  return repWrap(title, `<span><b>Period:</b> ${escHtml(rangeLabel)}</span><span><b>${seg === 'paid' ? 'Students Cleared' : 'Receipts'}:</b> ${seg === 'paid' ? kpi.students : kpi.receipts}</span><span><b>Grand Total:</b> Rs. ${fmt(kpi.recv)}</span>`, `<div class="kpi-row">
