function buildRepHeadwiseHTML({
  kind,
  c,
  s,
  rows,
  from,
  to,
  head,
  isBW = false,
  school = null
}) {
  if (kind === 'student') {
    const sum = rows.reduce((a, r) => ({
      total: a.total + r.total,
      disc: a.disc + r.disc,
      recv: a.recv + r.recv,
      pend: a.pend + r.pend
    }), {
      total: 0,
      disc: 0,
      recv: 0,
      pend: 0
    });
    return repWrap(`Head-Wise Collection — ${s.name}`, `<span><b>Class:</b> ${escHtml(c.cls)} / ${escHtml(c.sec)}</span><span><b>Reg:</b> ${escHtml(s.reg)}</span><span><b>Head:</b> ${escHtml(head)}</span><span><b>Range:</b> ${escHtml(from)} → ${escHtml(to)}</span>`, `<table class="rep-tbl"><thead><tr><th>Sn.</th><th>Account Type</th><th>Fee Head</th><th class="r">Standard</th><th class="r">Discount</th><th class="r">Received</th><th class="r">Pending</th></tr></thead>
        <tbody>${rows.map((r, j) => `<tr><td>${j + 1}</td><td>${escHtml(r.head)}</td><td><b>${escHtml(headLabel(r.sub))}</b></td><td class="r">${r.total.toLocaleString('en-PK')}</td><td class="r">${r.disc.toLocaleString('en-PK')}</td><td class="r pos">${r.recv.toLocaleString('en-PK')}</td><td class="r ${r.pend !== 0 ? 'neg' : ''}">${r.pend.toLocaleString('en-PK')}</td></tr>`).join('')}</tbody>
        <tfoot><tr class="rep-tot"><td colspan="3">Total</td><td class="r">${sum.total.toLocaleString('en-PK')}</td><td class="r">${sum.disc.toLocaleString('en-PK')}</td><td class="r">${sum.recv.toLocaleString('en-PK')}</td><td class="r">${sum.pend.toLocaleString('en-PK')}</td></tr></tfoot>
      </table>`, isBW, school);
  }
  /* class — on-screen table ke bilkul barabar: Advance column + "All Heads" par
     pura student ka SAHI outstanding (m.remaining, de-duped) aur advance; kisi khaas
     head par us head ka apna sum. Pehle PDF me Advance column hi nahi tha aur pending
     sum.pend (carry-forward double-count) dikhata tha — Preview se match nahi karta tha. */
  const allHeadsSel = head === 'All Heads';
  const rowPend = (m, sum) => allHeadsSel ? (m === null || m === void 0 ? void 0 : m.remaining) || 0 : sum.pend;
  const rowAdv = m => allHeadsSel ? (m === null || m === void 0 ? void 0 : m.advance) || 0 : 0;
  const trs = (rows || []).map(({
    s,
    m,
    heads
  }, j) => {
    const sum = heads.reduce((a, r) => ({
      total: a.total + r.total,
      disc: a.disc + r.disc,
      recv: a.recv + r.recv,
      pend: a.pend + r.pend
    }), {
      total: 0,
      disc: 0,
      recv: 0,
      pend: 0
    });
    const adv = rowAdv(m),
      pend = rowPend(m, sum);
    return `<tr><td>${j + 1}</td><td><b>${escHtml(s.name)}</b><br><small>s/o ${escHtml(s.father || '—')}</small></td><td>${escHtml(s.reg)}</td><td class="r">${sum.total.toLocaleString('en-PK')}</td><td class="r">${sum.disc.toLocaleString('en-PK')}</td><td class="r pos">${sum.recv.toLocaleString('en-PK')}</td><td class="r ${adv > 0 ? 'neg' : ''}">${(adv > 0 ? -adv : 0).toLocaleString('en-PK')}</td><td class="r ${pend !== 0 ? 'neg' : ''}">${pend.toLocaleString('en-PK')}</td></tr>`;
  }).join('');
  const foot = (rows || []).reduce((a, {
    m,
    heads
  }) => {
    const sum = heads.reduce((b, r) => ({
      total: b.total + r.total,
      disc: b.disc + r.disc,
      recv: b.recv + r.recv,
      pend: b.pend + r.pend
    }), {
      total: 0,
      disc: 0,
      recv: 0,
      pend: 0
    });
    return {
      total: a.total + sum.total,
      disc: a.disc + sum.disc,
      recv: a.recv + sum.recv,
      adv: a.adv + rowAdv(m),
      pend: a.pend + rowPend(m, sum)
    };
  }, {
    total: 0,
    disc: 0,
    recv: 0,
    adv: 0,
    pend: 0
  });
  return repWrap(`Class Head-Wise Collection — ${c.cls} (${c.sec})`, `<span><b>Class:</b> ${escHtml(c.cls)} — ${escHtml(c.sec)}</span><span><b>Head:</b> ${escHtml(head)}</span><span><b>Range:</b> ${escHtml(from)} → ${escHtml(to)}</span>`, `<table class="rep-tbl"><thead><tr><th>Sn.</th><th>Student</th><th>Reg No</th><th class="r">Standard</th><th class="r">Discount</th><th class="r">Received</th><th class="r">Advance</th><th class="r">Pending</th></tr></thead><tbody>${trs}</tbody>
      <tfoot><tr class="rep-tot"><td colspan="3">Total</td><td class="r">${foot.total.toLocaleString('en-PK')}</td><td class="r">${foot.disc.toLocaleString('en-PK')}</td><td class="r">${foot.recv.toLocaleString('en-PK')}</td><td class="r">${(foot.adv > 0 ? -foot.adv : 0).toLocaleString('en-PK')}</td><td class="r">${foot.pend.toLocaleString('en-PK')}</td></tr></tfoot>
    </table>`, isBW, school);
}
