  font-size: 12.5px;
  color: var(--text-primary);
  display: flex;
  align-items: center;
}
.fee-td.fee-name { font-weight: 700; }
.fee-row-icon {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, rgba(30,58,138,.12), rgba(37,99,235,.06));
