  border-color: rgba(239,68,68,.3);
  color: #FCA5A5;
}
[data-theme="dark"] .fee-confirm-hint--danger i { color: #FCA5A5; }
[data-theme="dark"] .fee-confirm-hint--primary {
  background: rgba(59,130,246,.10);
  border-color: rgba(59,130,246,.3);
  color: #BFD2F8;
}
