            <label className="fee-label">Registration Number</label>
            <input
              className="fee-input"
              value={regNo}
              placeholder="e.g. LEA-4021"
              onChange={e => setRegNo(e.target.value)}
            />
          </div>
          <div className="fee-field-stack">
            <label className="fee-label">Assigned Route</label>
            <input
              className="fee-input"
