/* ═══════════════════════════════════════════════════════════════════
   FEE CHALLANS TAB — month/year filter + smart search + class table
   + per-class expandable student-level challan list.

   Step 6a (this turn): sub-segments shell, filters, table, student
   rows, delete confirms, tooltips, dark mode.
   Step 6b (next): Generate / Discount / Download / Preview modals.
   Step 6c: Family Tree Challans.
   ═══════════════════════════════════════════════════════════════════ */

const FEE_MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

/* Fee Challan Settings gate the month either side of the current one.
   The API's previousMonthFeeChallan / nextMonthFeeChallan are ON = allowed:
   turning "Previous Month Challan Receiving" on lets last month's challans be
   generated and received, and likewise for next month. When a toggle is off,
   that adjacent month is barred.

   "Previous"/"next" are measured against today's real month, not the month
   picker, so changing the filter can't shift what the gate means. Returns the
   reason a month is barred, or null when it's fine. */
/* Sirf in branches ko previous-month challan CREATE karne ki ijazat hai.
   Receiving isPastView se band rehti hai. */
const PREV_MONTH_CHALLAN_BRANCHES = new Set([210780]);

function challanMonthLock(monthIdx, year, settings) {
  if (!settings || monthIdx < 0) return null;
  const now = new Date();
  const diff = (Number(year) * 12 + monthIdx) - (now.getFullYear() * 12 + now.getMonth());
  const branchId = Number(sessionStorage.getItem('branchID')) || 0;
  if (diff === -1 && !settings.prevMonthChallan && !PREV_MONTH_CHALLAN_BRANCHES.has(branchId)) {
    /* Toggle UI se comment-out hai — message usay point na kare. */
    return 'Previous month is locked — receive its pending dues from the current month (Receive Pending).';
  }
  /* Next month lock HATA diya — "Next Month Challan Receiving" toggle comment-out hai; har
     mahine (aage ka bhi) receiving/generation allowed, shart sirf pending amount. */
  return null;
}

function FeeChallansTab({ toast }) {
  const [seg, setSeg] = useState('challan');

  return (
    <>
      {/* Sub-segments: Fee Challans / Family Tree Challans */}
      <div className="fee-seg">
        <Tooltip text="Single-student challans grouped by class">
          <button
            className={`fee-seg-btn${seg === 'challan' ? ' active' : ''}`}
            onClick={() => setSeg('challan')}
          >
            <i className="fa-solid fa-file-invoice"></i> Fee Challans
          </button>
        </Tooltip>
        <Tooltip text="Combine siblings into a single guardian challan">
          <button
            className={`fee-seg-btn${seg === 'family' ? ' active' : ''}`}
            onClick={() => setSeg('family')}
          >
            <i className="fa-solid fa-people-roof"></i> Family Tree Challans
          </button>
        </Tooltip>
      </div>

      {seg === 'challan'
        ? <FeeChallansList toast={toast} />
        : <FamilyTreeChallansList toast={toast} />}
    </>
  );
}

/* Aggregate carry line only ("Previous Pending" / "Arrear").
   Launch-setup "Previous Due" / "Previous Dues" and the migrated
   "Pending Due" / "Old Dues Till Date" head are real fee heads — a broad
   /previous|pending|arrear/ test used to skip their balance on the next
   month's challan list while the printed challan still showed it. */
function isAggregateCarryRow(r) {
  return /previous\s*pending|arrears?/i.test(String((r && (r.subHead || r.head || r.name)) || ''));
}

/* Heads still open for an installment. Receiving is taken off previous first,
   then off this month's net — same order as the challan list. A head whose
   remaining balance is 0 is left out, so a fully received amount is not shown. */
function installmentHeadsOf(rec) {
  return ((rec && rec.detailRows) || [])
    .filter(r => !isAggregateCarryRow(r) && !feeService.isLateFineRow(r))
    .map(r => {
      const billed = Math.max(0, Math.round(Number(r.challanAmount) || 0));
      const discount = Math.min(Math.max(0, Math.round(Number(r.discount) || 0)), billed);
      const prevRaw = r.previousPendingorAdv ?? r.previousPendingOrAdv
        ?? r.previousAmount ?? r.previousBalance ?? r.prevAmount ?? r.prevBalance
        ?? r.previousPending ?? r.prevPending ?? r.previousDue ?? r.previousDues
        ?? r.openingBalance ?? r.arrearAmount;
      const prevGross = Math.max(0, Math.round(Number(prevRaw) || 0));
      const recv = Math.max(0, Math.round(Number(r.receivedAmount) || 0));
      const curNet = Math.max(0, billed - discount);
      const againstPrev = Math.min(recv, prevGross);
      const againstCur = Math.max(0, recv - againstPrev);
      const prev = Math.max(0, prevGross - againstPrev);
      const curLeft = Math.max(0, curNet - againstCur);
      /* Challan column follows the unpaid current bill, so received rupees
         are not still sitting in the row. Discount stays on that unpaid part. */
      const challanAmount = curLeft > 0 ? curLeft + discount : 0;
      return {
        name: String(r.subHead || r.head || ''),
        challanAmount,
        discount: curLeft > 0 ? discount : 0,
        prev,
        afterDiscount: curLeft + prev,
      };
    })
    .filter(h => h.name && h.afterDiscount > 0);
}

/* Split a BranchLedger challan record into the family-table figures:
   transport heads → Transport, the aggregate carry line → dues/advance,
   everything else → Fee. A real previous/old-dues head's previousPendingorAdv
   is added to Total Dues (same as the printed challan). */
function familyChildFigures(rec) {
  const rows = (rec && rec.detailRows) || [];
  let fee = 0, transport = 0, discount = 0, dues = 0, advance = 0;
  let totalNet = 0, totalRecv = 0;
  rows.forEach(r => {
    const amt = Number(r.challanAmount) || 0;
    const disc = Number(r.discount) || 0;
    const recv = Number(r.receivedAmount) || 0;
    const net = amt - disc;
    const out = Math.max(0, net - recv);   // wasooli ke baad bacha hua
    const hp = Math.max(0, Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0);
    totalNet += net;
    totalRecv += recv;
    const label = String(r.subHead || r.head || '').toLowerCase().trim();
    /* Fee / Transport / Dues ab BAQAYA dikhate hain — poora receive ho jaye to 0.
       Discount billed hi rehta hai (sirf information ke liye). */
    if (isAggregateCarryRow(r)) {
      if (amt >= 0) dues += out; else advance += Math.abs(amt);
    } else if (label === 'transport') {
      /* SIRF Transport Fee Setup se auto-add hone wali row ka subHead exactly
         "Transport" hota hai. Class ke apne fee heads (jaise "Transport Fee")
         Fee column me hi ginne chahiyein — warna wo galti se Transport dikhte the. */
      transport += out; discount += disc;
      dues += hp;
    } else {
      fee += out; discount += disc;
      /* Head ka previous (Pending Due 1,200) list ke Total Dues me — challan jaisa.
         Received pehle is mahine ke bill par lag chuka (out), is liye yahan poora hp. */
      dues += hp;
    }
  });
  /* Over-receiving (total se zyada wasool) → extra raqam ADVANCE. */
  advance += Math.max(0, totalRecv - totalNet);
  /* fee/transport/dues pehle se discount-ke-baad hain, is liye yahan discount dobara
     minus NAHI hota. Over-payment par ye MINUS me jaata hai = student ka credit. */
  return { fee, transport, discount, dues, advance, payable: fee + transport + dues - advance };
}

/* familyChildFigures + LIVE prior-outstanding override. Challan me stored "Previous
   Pending" generation-time snapshot hai; pichhle mahine ki receiving baad me ho to stale
   ho jaata hai. prevLive ({ dues, advance }, running-ledger se) mile to dues/advance usse
   badal do — warna stored hi. */
function famFigWithPrev(rec, prevLive) {
  const fig = familyChildFigures(rec);
  /* Poora settle (credit head/advance samet) → sab 0 dikhao (phantom −550 / net-0 nahi). */
  if (challanFullyPaid(rec)) return { ...fig, dues: 0, advance: 0, fee: 0, transport: 0, payable: 0 };
  if (!prevLive) return fig;
  /* prevLive.advance sirf pichhle mahino ka — is challan me consume ho chuka advance ghata do
     (warna fully-received par bhi phantom −550 baqaya reh jaata tha). */
  const advance = Math.max(0, prevLive.advance - advConsumedOf(rec));
  return {
    ...fig, dues: prevLive.dues, advance,
    payable: fig.fee + fig.transport + prevLive.dues - advance
  };
}

/* ═══════════════════════════════════════════════════════════════════
   FAMILY TREE CHALLANS — combines siblings under one guardian. Mirrors
   FeeChallansList structurally: filters, smart search, table, per-row
   expand with children list, status-based per-child actions, and bulk
   generate (the BulkGenerateModal in 'family' mode), plus dedicated
   family-slip Preview/Download flows.
   ═══════════════════════════════════════════════════════════════════ */
function FamilyTreeChallansList({ toast }) {
  const { data: serverFams = [], loading: famsLoading } = useAsync(feeService.getFamilies, []);
  const { data: settings = {} } = useAsync(feeService.getFeeSettings, []);
  /* Class-wise fee heads (headName) — powers the Generate Family Challans
     "Select Fee Heads" dropdown, keyed by class/grade id. */
  const { data: classFeeHeads = {} } = useAsync(feeService.getClassFeeHeadsMap, []);
  /* Full fee heads WITH amounts per grade — so a SEPARATE (single) family-child
     challan can be generated per-head exactly like an Individual student. */
  const { data: feeGrades = [] } = useAsync(feeService.getFeeGrades, []);
  /* Branch header (name / address / logo) for the separate child slip. */
  const { data: branchHeader = null } = useAsync(feeService.getReportHeader, [], null);
  const headsForChildGrade = useCallback(
    (gradeID) => (feeGrades.find(g => String(g._gradeId) === String(gradeID))?.heads) || [],
    [feeGrades],
  );

  /* Har bachche ke SAVED discounts (Fee Challans wale Discount Manager se) server se
     laao aur family challan ke liye { [famKey]: { [reg]: { [headName]: amt } } } shape
     me do — warna family tree ka challan hamesha 0 discount ke saath banta tha.
     Discount API sirf headID deta hai, is liye bachche ke apne grade heads ke
     feeStructureID se match karke head ka naam nikala jaata hai. Ek head ke ek se
     zyada active record hon to SABSE NAYA (bada id) jeetta hai. */
  const fetchFamilyDiscounts = useCallback(async (classMeta, studs) => {
    const perReg = {};
    await Promise.all((studs || []).map(async (s) => {
      const gHeads = headsForChildGrade(s.gradeID) || [];
      const map = {};
      try {
        const rows = await feeService.getFeeDiscountsByStudent(s.studentID);
        const newestByHead = new Map();
        (rows || []).filter(r => r.isActive !== false).forEach(r => {
          const k = String(r.headID);
          const rank = Number(r.id) || 0;
          const cur = newestByHead.get(k);
          if (!cur || rank >= cur.rank) newestByHead.set(k, { rank, row: r });
        });
        newestByHead.forEach(({ row: r }) => {
          const head = gHeads.find(h => Number(h.feeStructureID) === Number(r.headID));
          const amt = Number(r.discountAmount) || 0;
          if (head && amt > 0) map[head.name] = amt;
        });
      } catch (e) { /* discount na mile to 0 hi rahega */ }
      if (Object.keys(map).length) perReg[s.reg] = map;
    }));
    return { [classMeta.key]: perReg };
  }, [headsForChildGrade]);

  /* Build deduped fee-head options (by name, case-insensitive) across the
     given class/grade ids. Family challans carry no per-head amount, so we
     surface names only. */
  const feeHeadsFor = (gradeIds) => {
    const seen = new Set();
    const out = [];
    (gradeIds || []).forEach(gid => {
      (classFeeHeads[gid] || []).forEach(name => {
        const k = String(name).trim().toLowerCase();
        if (!k || seen.has(k)) return;
        seen.add(k);
        out.push({ name });
      });
    });
    return out;
  };

  /* Local mirror of families (mutable: remove-child support) */
  const [families, setFamilies] = useState(null);
  useEffect(() => {
    if (serverFams.length && families == null) setFamilies(serverFams);
  }, [serverFams, families]);
  const list = useMemo(() => families || [], [families]);

  /* Filters */
  const today = new Date();
  const [month, setMonth] = useState(FEE_MONTHS[today.getMonth()]);
  const [year, setYear] = useState(String(today.getFullYear()));
  const [appliedMonth, setAppliedMonth] = useState(month);
  const [appliedYear, setAppliedYear] = useState(year);

  /* Smart search */
  const [searchQ, setSearchQ] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);
  const [highlightKey, setHighlightKey] = useState(null);
  const searchAnchorRef = useRef(null);
  useEffect(() => {
    if (!searchOpen) return undefined;
    const onDown = (e) => {
      if (searchAnchorRef.current && !searchAnchorRef.current.contains(e.target)) setSearchOpen(false);
    };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('touchstart', onDown);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('touchstart', onDown);
    };
  }, [searchOpen]);
  useEffect(() => {
    if (!searchOpen) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') setSearchOpen(false); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [searchOpen]);

  /* Generation state — driven live from BranchLedger (loadLedgers below). */
  const [genSet, setGenSet] = useState(null);
  const monthIdx = FEE_MONTHS.indexOf(appliedMonth);
  const keyOf = (famKey, reg) => `${famKey}|${reg}|${monthIdx}`;

  /* Per-child fee figures from BranchLedger, keyed by keyOf(fam,reg). For
     every student in every family we hit /api/BranchLedger/get-all with the
     student's applicantsID as `studentId` (+ branch + applied month/year).
     Runs on mount (i.e. when the Family Tree Challans tab opens) and whenever
     the family list or the applied month/year changes. A child that has a
     ledger row for the month is marked generated. */
  const [figMap, setFigMap] = useState({});
  /* BranchLedger record id per child challan — used to delete via
     /api/BranchLedger/delete/{id}. Keyed by keyOf(fam, reg). */
  const [idMap, setIdMap] = useState({});
  /* Poora BranchLedger record per child (keyOf(fam, reg)) — is se challan ki ASLI
     Issue/Due date (dateofCreattion / dueDate) print par jaati hai, warna slip par
     hamesha "aaj + 10 din" chhap jaata tha. */
  const [recMap, setRecMap] = useState({});
  /* Pichhle mahino ka baqaya / advance — { [studentID]: { dues, advance } }.
     Isse naya challan banane se PEHLE hi bachche ke dues nazar aa jaate hain. */
  const [prevOutMap, setPrevOutMap] = useState({});
  /* Is mahine ka challan data load ho chuka? Na ho to list ki jagah LOADER (class/row ke
     0 / khali figures nahi). Save/delete ke baad refresh par list chhupti nahi. */
  const [loadedKey, setLoadedKey] = useState('');
  const viewKey = `${appliedMonth}|${appliedYear}`;
  const loadLedgers = useCallback(async () => {
    const fams = families;
    if (!fams || !fams.length) { setFigMap({}); setIdMap({}); setRecMap({}); setGenSet(new Set()); setLoadedKey(`${appliedMonth}|${appliedYear}`); return; }
    const mIdx = FEE_MONTHS.indexOf(appliedMonth);
    const pairs = fams
      .flatMap(f => (f.children || []).map(ch => ({ f, ch })))
      .filter(({ ch }) => ch.applicantsID != null);
    try {
      const results = await Promise.all(pairs.map(async ({ f, ch }) => {
        const key = `${f.key}|${ch.reg}|${mIdx}`;
        try {
          const rows = await feeService.getStudentChallans(ch.applicantsID, mIdx + 1, appliedYear);
          const rec = pickMonthChallan(rows, mIdx + 1, Number(appliedYear));
          return { key, fig: rec ? familyChildFigures(rec) : null, id: rec?.id ?? null, rec };
        } catch (e) {
          return { key, fig: null, id: null, rec: null };
        }
      }));
      const fmap = {};
      const imap = {};
      const rmap = {};
      const gset = new Set();
      results.forEach(({ key, fig, id, rec }) => {
        if (!fig) return;
        fmap[key] = fig;
        if (rec) rmap[key] = rec;
        /* Pichhle mahine se shuru hua multi-month challan (Sep–Nov ka Oct) — is mahine ko
           "generated" NAHI ginte, taake Oct me naya challan Create ho sake (Individual
           jaisa). Figures (fmap/rmap) dikhte rahein; id map me NAHI — warna Oct ka Delete
           September wala challan mita deta. */
        if (rec && isMultiMonthNonStartView(rec, mIdx + 1, Number(appliedYear))) return;
        gset.add(key);
        if (id != null) imap[key] = id;
      });
      setFigMap(fmap);
      setIdMap(imap);
      setRecMap(rmap);
      setGenSet(gset);

      /* ── Pichhle mahino ka baqaya, RUN TIME par ──
         Har bachche ka SABSE RECENT purana challan liya jaata hai (usme pehle ka
         carry-forward already shamil hota hai → double-count nahi), phir uska
         unpaid remainder: Σ (challanAmount − discount − receivedAmount).
         > 0 → Total Dues | < 0 → Advance. */
      let prevOut = {};
      try {
        let toM = mIdx, toY = appliedYear;                 // applied month se ek pehle
        if (toM === 0) { toM = 12; toY = appliedYear - 1; }
        let fromM = toM - 11, fromY = toY;                 // 12-month window
        while (fromM <= 0) { fromM += 12; fromY -= 1; }
        const prevRows = await feeService.getLedgerRange(fromM, fromY, toM, toY);
        /* Running-ledger — stale stored Previous Pending se bachne ke liye (jaise
           September ki receiving October ke baad hui to October ka stored 13,850 galat). */
        prevOut = prevOutFromLedgerRows(prevRows, mIdx + 1, appliedYear);
      } catch (e) { /* optional — na mile to 0 hi rahenge */ }
      setPrevOutMap(prevOut);
    } catch (e) {
      toast(e.message || 'Could not load family ledgers', 'error');
      setFigMap({});
      setIdMap({});
      setRecMap({});
      setGenSet(new Set());
      setPrevOutMap({});
    } finally {
      setLoadedKey(`${appliedMonth}|${appliedYear}`);
    }
  }, [families, appliedMonth, appliedYear, toast]);
  useEffect(() => { loadLedgers(); }, [loadLedgers]);

  /* A child's displayed figures: real ledger data when a challan exists for
     the month, else the family-tree defaults (zeros until one is generated). */
  const childFig = (f, ch) => {
    const real = figMap[keyOf(f.key, ch.reg)];
    const prevLive = prevOutMap[String(ch.applicantsID)] || null;
    const chRec = recMap[keyOf(f.key, ch.reg)] || null;
    const viewM = FEE_MONTHS.indexOf(appliedMonth) + 1;
    const viewY = Number(appliedYear);
    if (real) {
      /* Poora settle (credit head/advance samet) → sab 0 dikhao (phantom −550 nahi). */
      /* Owed se zyada liya ho to wo advance (−3,500) dikhe — Sep–Oct challan ke Oct me bhi. */
      if (challanFullyPaid(chRec || real)) {
        const overAdv = challanOverpaid(chRec);
        return { ...real, dues: 0, advance: overAdv, fee: 0, transport: 0, payable: -overAdv };
      }
      let dues = Number(real.dues) || 0;
      let fee = Number(real.fee) || 0;
      let transport = Number(real.transport) || 0;
      let advance = Number(real.advance) || 0;
      /* Generated challan ka stored "Previous Pending" GENERATION ke waqt ka snapshot hai;
         agar us ke baad kisi pichhle mahine ki fee receive ho gayi to stale ho jaata hai.
         Live prevOut (running-ledger) se dues/advance override — October ka 13,850 → 6,850. */
      if (prevLive) {
        /* prevLive.advance sirf pichhle mahino ka — is challan me consume ho chuka advance ghata do. */
        advance = Math.max(0, prevLive.advance - advConsumedOf(chRec || real));
        dues = Number(prevLive.dues) || 0;
      }
      /* Two Months+: start month → Fee; covered later month (dropdown) → Dues. */
      if (chRec && isMultiMonthNonStartView(chRec, viewM, viewY)) {
        dues = dues + fee + transport;
        fee = 0;
        transport = 0;
      }
      return {
        ...real, dues, fee, transport, advance,
        payable: fee + transport + dues - advance,
      };
    }
    /* Challan abhi nahi bana → pichhle mahino ka LIVE baqaya dikhao (0 ki jagah). */
    const prev = prevLive;
    const dues = prev ? prev.dues : (+ch.dues || 0);
    const adv = prev ? prev.advance : (+ch.advance || 0);
    return {
      fee: +ch.fee || 0, transport: +ch.transport || 0, discount: +ch.discount || 0,
      dues, advance: adv,
      payable: (+ch.fee || 0) + (+ch.transport || 0) - (+ch.discount || 0),
    };
  };

  /* Challan HTML builders har child ke FLAT fee/transport/discount padhte hain, magar
     asli figures ledger se childFig() me compute hote hain. Preview/download se pehle
     family ko un computed figures ke saath enrich karo — warna challan me sab 0 aata hai. */
  const famWithFigs = (f) => ({
    ...f,
    children: (f.children || []).map(ch => {
      const g = childFig(f, ch);
      /* `_challan` bhi saath bhejo — slip is se challan ki asli Issue/Due date leta hai. */
      return {
        ...ch, fee: g.fee, transport: g.transport, discount: g.discount, dues: g.dues, advance: g.advance,
        _challan: ch._challan || recMap[keyOf(f.key, ch.reg)] || null,
      };
    }),
  });

  /* Expanded row */
  const [openKey, setOpenKey] = useState(null);
  const [confirm, setConfirm] = useState(null);
  const [busyMsg, setBusyMsg] = useState('');    // delete chal raha ho to center loader + screen lock
  const [bulkGen, setBulkGen] = useState(null);
  const [challanPreview, setChallanPreview] = useState(null);
  const [downloadCtx, setDownloadCtx] = useState(null);
  /* Installment challan modal — { classMeta, student, rec, heads } */
  const [installmentCtx, setInstallmentCtx] = useState(null);
  /* Installment challan ka Colorful / Colorless picker */
  const [instPrintCtx, setInstPrintCtx] = useState(null);
  const apply = () => {
    setAppliedMonth(month); setAppliedYear(year);
    toast(`Loaded ${month} ${year} family challans`, 'info');
  };
  const resetFilters = () => {
    setMonth(FEE_MONTHS[today.getMonth()]);
    setYear(String(today.getFullYear()));
    setAppliedMonth(FEE_MONTHS[today.getMonth()]);
    setAppliedYear(String(today.getFullYear()));
    setSearchQ('');
    setHighlightKey(null);
  };

  const genCountFor = (famKey, children) => (children || []).reduce(
    (a, ch) => a + (genSet && genSet.has(keyOf(famKey, ch.reg)) ? 1 : 0), 0,
  );
  const isGen = (famKey, reg) => !!genSet && genSet.has(keyOf(famKey, reg));

  /* ── Bulk generate (family mode) ── */
  const openBulkGen = (f) => {
    const lock = challanMonthLock(monthIdx, appliedYear, settings);
    if (lock) { toast(lock, 'warning'); return; }
    if (!f.children.length) { toast('No children in this family', 'warning'); return; }
    /* Only children who don't already have a challan for the applied month.
       A sibling whose challan is already generated/received is dropped here so
       the bulk modal loads heads for — and generates challans for — just the
       remaining children, never re-billing the one that's already done. */
    const remaining = f.children.filter(ch => !isGen(f.key, ch.reg));
    if (!remaining.length) {
      toast(`All children already have ${appliedMonth} ${appliedYear} challans`, 'info');
      return;
    }
    /* Build pseudo-students for BulkGenerateModal — re-use that infra. IDs
       (studentID = applicantsID, gradeID, sectionID) + the child's own
       fee/transport/discount travel through so the create-challan payload is
       correct per child. */
    const pseudoStudents = remaining.map(ch => {
      const fig = childFig(f, ch);
      return {
        reg: ch.reg, name: ch.name, father: ch.father,
        studentID: ch.applicantsID, gradeID: ch.gradeID, sectionID: ch.sectionID,
        fee: fig.fee, transport: fig.transport, discount: fig.discount,
        dues: fig.dues || 0, advance: fig.advance || 0, current: fig.payable,
        /* Each child's OWN grade fee heads (with amounts) so a common head
           selected in bulk sends this student's own amount to the API. */
        heads: headsForChildGrade(ch.gradeID),
      };
    });
    /* Dropdown heads = the union (deduped by name) of each child's OWN grade
       heads — the exact source used for generation (getFeeGrades). This keeps
       the picker in sync with what actually gets billed, and never comes back
       empty due to getClassFeeHeadsMap / employee_ID, which is what made the
       heads disappear once a child already had a challan. */
    const seen = new Set();
    const familyHeads = [];
    pseudoStudents.forEach(s => (s.heads || []).forEach(h => {
      const k = String(h.name || '').trim().toLowerCase();
      if (!k || seen.has(k)) return;
      seen.add(k);
      familyHeads.push({ name: h.name });
    }));
    setBulkGen({
      classMeta: { key: f.key, cls: f.name, sec: f.guardian },
      students: pseudoStudents,
      heads: familyHeads,
    });
  };
  const handleBulkGenerated = (famKey, regs) => {
    setGenSet(prev => {
      const n = new Set(prev);
      regs.forEach(reg => n.add(keyOf(famKey, reg)));
      return n;
    });
  };
  const openIndivGen = (f, ch) => {
    const lock = challanMonthLock(monthIdx, appliedYear, settings);
    if (lock) { toast(lock, 'warning'); return; }
    /* Roll-up child's family-level fee into `current` so the modal's
       student card can display Total Fee + Pending Amount via the same
       (current − dues − advance) calculation used in class single-mode. */
    const fig = childFig(f, ch);
    const totalFee = fig.fee + fig.transport - fig.discount;
    const pseudo = {
      reg: ch.reg, name: ch.name, father: ch.father,
      studentID: ch.applicantsID, gradeID: ch.gradeID, sectionID: ch.sectionID,
      fee: fig.fee, transport: fig.transport, discount: fig.discount,
      dues: fig.dues || 0,
      advance: fig.advance || 0,
      current: totalFee,
      /* This child's own grade fee heads (with amounts) → per-head challan. */
      heads: headsForChildGrade(ch.gradeID),
    };
    /* Per-head fee heads (with amounts) for this child's own class, so the
       separate challan is built head-by-head like an Individual student.
       Falls back to name-only heads if the grade has no fee setup. */
    const perHead = headsForChildGrade(ch.gradeID);
    const familyHeads = perHead.length ? perHead : feeHeadsFor([ch.gradeID]);
    setBulkGen({
      /* Pass the child's actual class/section to the card, but keep the
         family key so the genSet keys roll up under the family. */
      classMeta: { key: f.key, cls: ch.cls, sec: ch.sec, familyName: f.name, guardian: f.guardian },
      students: [pseudo],
      heads: familyHeads,
      mode: 'single',
    });
  };

  /* Installment challan — same slip as Individual, against this child's ledger. */
  const openInstallment = (f, ch) => {
    const rec = recMap[keyOf(f.key, ch.reg)];
    if (!rec) { toast('Generate the challan first', 'warning'); return; }
    if (challanFullyPaid(rec)) { toast('This challan is fully received', 'warning'); return; }
    const heads = installmentHeadsOf(rec);
    if (!heads.length) { toast('This challan is fully received', 'warning'); return; }
    setInstallmentCtx({
      classMeta: { key: `g${ch.gradeID}-s${ch.sectionID}`, cls: ch.cls, sec: ch.sec },
      student: ch,
      rec,
      heads,
    });
  };

  const createInstallmentChallan = async (cfg, perHead, bw = false, size = 'a4') => {
    const { classMeta: c, student: s, rec, heads } = cfg;
    const billed = heads
      .map(h => ({ ...h, amt: Math.max(0, Math.round(Number(perHead?.[h.name]) || 0)) }))
      .filter(h => h.amt > 0 && h.amt <= h.afterDiscount);
    const totalInstallment = billed.reduce((a, h) => a + h.amt, 0);
    if (!totalInstallment) throw new Error('Enter an installment amount on at least one fee head');
    const branchID = Number(sessionStorage.getItem('branchID')) || Number(rec.branchID) || 1;
    const userID = Number(sessionStorage.getItem('UserID')) || 0;
    const mo = Number(rec.month) || (monthIdx + 1);
    const yr = Number(rec.year) || Number(appliedYear) || new Date().getFullYear();
    const dueISO = (() => {
      const d = new Date(rec.dueDate || Date.now());
      return Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
    })();
    const res = await feeService.generatePsid({
      studentID: Number(rec.studentID || s.applicantsID || s.studentID) || 0,
      branchID,
      month: mo,
      year: yr,
      amount: totalInstallment,
      fullName: String(s.name || rec.fullName || ''),
      mobileNo: String(s.mobile || s.phone || ''),
      dueDate: dueISO,
      ledgerId: Number(rec.id) || 0,
      forceNew: true,
      modifiedBy: userID,
    });
    let psid = feeService.psidFromResponse(res);
    if (!psid) {
      try {
        const list = await feeService.getWithInstallments({
          branchId: branchID,
          studentId: Number(rec.studentID || s.applicantsID || s.studentID) || 0,
          month: mo,
          year: yr,
        });
        const latest = Array.isArray(list) && list.length ? list[list.length - 1] : null;
        psid = latest ? feeService.psidOf(latest) : '';
      } catch (e) { /* best-effort */ }
    }
    try {
      const instChallan = {
        ...rec,
        plpsid: psid,
        detailRows: billed.map(h => ({
          head: 'Account Payable', subHead: String(h.name || ''),
          challanAmount: h.amt, discount: 0, receivedAmount: 0,
        })),
      };
        const html = buildChallanHTML({
        classMeta: c,
        students: [{ ...s, dues: 0, advance: 0, prevByHead: null, _challan: instChallan }],
        installmentSlip: true,
        heads: headsForChildGrade(s.gradeID),
        settings, discountMap: {}, bw, size: size === 'thermal' ? 'thermal' : 'a4', school: branchHeader,
      });
      const w = window.open('', '_blank');
      if (w) {
        w.document.write(html);
        w.document.close();
        w.onload = () => { try { w.focus(); w.print(); } catch (err) { /* ignore */ } };
      } else {
        toast('Please allow pop-ups to download the challan', 'error');
      }
    } catch (e) { /* PSID already generated */ }
    toast(`Installment ${psid || 'challan'} challan created`, 'success');
    setInstallmentCtx(null);
    loadLedgers();
  };

  /* ── Preview / Download ── */
  const openPreview = (f) => {
    if (!f.children.length) { toast('No children to preview', 'info'); return; }
    setChallanPreview({
      title: 'Family Challan Preview',
      sub: `${f.name} — ${f.guardian} · ${f.children.length} child${f.children.length === 1 ? '' : 'ren'} · Parent · Bank · School copies`,
      family: f,
      innerHtml: buildFamilyChallanInner({ family: famWithFigs(f), settings, bw: false, school: branchHeader }),
    });
  };
  const openDownload = (f) => {
    if (!f.children.length) { toast('Nothing to download', 'info'); return; }
    setDownloadCtx({
      family: f,
      sub: `${f.name} — ${f.guardian} · ${f.children.length} children`,
      defaultSize: settings.printSize || 'a4',
    });
  };

  /* SEPARATE (single-child) download — produces an individual challan slip for
     that one child, exactly like the Individual tab (buildChallanHTML with the
     child's real BranchLedger challan), instead of the combined family slip. */
  /* Sirf ISI bachche ka challan preview (family combined nahi) — per-child 👁 button. */
  const openChildPreview = async (f, ch) => {
    if (ch.applicantsID == null) { toast(`Generate ${ch.name}'s challan first`, 'warning'); return; }
    let rec = null;
    try {
      const rows = await feeService.getStudentChallans(ch.applicantsID, monthIdx + 1, appliedYear);
      rec = pickMonthChallan(rows, monthIdx + 1, Number(appliedYear));
    } catch (e) { /* ignore */ }
    if (!rec) { toast(`No ${appliedMonth} challan for ${ch.name} — generate it first`, 'warning'); return; }
    const student = {
      reg: ch.reg, name: ch.name, father: ch.father,
      studentID: ch.applicantsID, gradeID: ch.gradeID, sectionID: ch.sectionID,
      _challan: rec,
    };
    setChallanPreview({
      title: 'Challan Preview',
      sub: `${ch.name} — ${ch.cls} (${ch.sec}) · Parent · Bank · School copies`,
      family: f,
      child: ch,          /* Download button ko child-mode par bhejne ke liye */
      innerHtml: buildChallanInner({
        classMeta: { key: `g${ch.gradeID}-s${ch.sectionID}`, cls: ch.cls, sec: ch.sec },
        students: [student],
        heads: headsForChildGrade(ch.gradeID),
        settings, discountMap: {}, bw: false, school: branchHeader,
      }),
    });
  };
  const openChildDownload = async (f, ch) => {
    if (ch.applicantsID == null) { toast(`Generate ${ch.name}'s challan first`, 'warning'); return; }
    let rec = null;
    try {
      const rows = await feeService.getStudentChallans(ch.applicantsID, monthIdx + 1, appliedYear);
      rec = pickMonthChallan(rows, monthIdx + 1, Number(appliedYear));
    } catch (e) { /* ignore */ }
    if (!rec) { toast(`No ${appliedMonth} challan for ${ch.name} — generate it first`, 'warning'); return; }
    setDownloadCtx({
      kind: 'child',
      classMeta: { key: `g${ch.gradeID}-s${ch.sectionID}`, cls: ch.cls, sec: ch.sec },
      student: {
        reg: ch.reg, name: ch.name, father: ch.father,
        studentID: ch.applicantsID, gradeID: ch.gradeID, sectionID: ch.sectionID,
        _challan: rec,
      },
      heads: headsForChildGrade(ch.gradeID),
      sub: `${ch.name} · child of ${ch.father || '—'}`,
      defaultSize: settings.printSize || 'a4',
    });
  };
  const runChildDownload = (ctx, { theme, fmt, size = 'a4' }) => {
    const bw = theme === 'bw';
    const html = buildChallanHTML({
      classMeta: ctx.classMeta, students: [ctx.student], heads: ctx.heads,
      settings, discountMap: {}, bw, size, school: branchHeader,
    });
    const sizeT = size === 'thermal' ? 'Thermal 80mm' : 'A4';
    toast(`Generating ${sizeT} · ${bw ? 'B&W' : 'Color'} ${fmt === 'word' ? 'Word' : 'PDF'} — challan…`, 'info');
    /* Word needs no pop-up — the .docx is built and downloaded in place. */
    if (fmt === 'word') {
      downloadDocxFromHtml(html, `${(ctx.student.name || 'student').replace(/\s+/g, '-')}-challan`);
      toast('Challan Word file downloaded.', 'success');
      return;
    }
    const w = window.open('', '_blank');
    if (!w) { toast('Please allow pop-ups to download the challan', 'error'); return; }
    w.document.write(html);
    w.document.close();
    w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    setTimeout(() => toast('Challan ready — use your browser\'s Save as PDF.', 'success'), 1100);
  };
  const runDownload = (family, { theme, fmt, size = 'a4' }) => {
    const bw = theme === 'bw';
    const html = buildFamilyChallanHTML({ family: famWithFigs(family), settings, bw, size, school: branchHeader });
    const sizeT = size === 'thermal' ? 'Thermal 80mm' : 'A4';
    toast(`Generating ${sizeT} · ${bw ? 'B&W' : 'Color'} ${fmt === 'word' ? 'Word' : 'PDF'} — family challan…`, 'info');
    /* Word needs no pop-up — the .docx is built and downloaded in place. */
    if (fmt === 'word') {
      downloadDocxFromHtml(html, `${family.name.replace(/\s+/g, '-')}-family-challan`);
      toast('Family challan Word file downloaded.', 'success');
      return;
    }
    const w = window.open('', '_blank');
    if (!w) { toast('Please allow pop-ups to download the challan', 'error'); return; }
    w.document.write(html);
    w.document.close();
    w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    setTimeout(() => toast('Family challan ready — use your browser\'s Save as PDF.', 'success'), 1100);
  };

  /* ── Confirm-driven actions ── */
  const requestDeleteChildChallan = (f, ch) => {
    const rec = recMap[keyOf(f.key, ch.reg)];
    if (challanHasReceiving(rec)) { toast(DEL_LOCKED_TIP, 'warning'); return; }
    const hasReceived = (rec?.detailRows || []).some(r => (Number(r.receivedAmount) || 0) > 0);
    setConfirm({
      title: 'Delete child challan?',
      message: `${ch.name}'s ${appliedMonth} ${appliedYear} challan will be deleted.`,
      hint: hasReceived
        ? 'Warning: this challan already has received amounts. Deleting will remove those payments from the ledger. This cannot be undone.'
        : 'This action cannot be undone.',
      onConfirm: async () => {
        /* Real API: delete the BranchLedger challan record by its id. */
        const id = idMap[keyOf(f.key, ch.reg)] ?? rec?.id;
        if (id == null) { toast('No challan found to delete', 'warning'); return; }
        setBusyMsg('Deleting challan…');
        try {
          await feeService.deleteChallanById(id);
          toast(`Challan removed for ${ch.name}`, 'success');
        } catch (e) {
          toast(e.message || 'Could not delete challan', 'error');
        } finally {
          await loadLedgers();
          setBusyMsg('');
        }
      },
    });
  };
  const requestRemoveChild = (f, ch) => {
    setConfirm({
      title: 'Remove child from family challan?',
      message: <span><strong>{ch.name}</strong> will be removed from the combined challan for <strong>{f.name}</strong>.</span>,
      hint: 'The child stays in the regular student roster — only the family link is removed.',
      confirmLabel: 'Yes, Remove',
      icon: 'fa-user-minus',
      onConfirm: async () => {
        /* Real API: delete the family-tree detail record by its id. */
        try {
          await feeService.deleteFamilyTreeDetail({
            id: ch.detailID,
            treeID: f.id,
            applicantsID: ch.applicantsID,
            gradeID: ch.gradeID,
            sectionID: ch.sectionID,
          });
        } catch (err) {
          toast(err.message || 'Could not remove child from family', 'error');
          return;
        }
        setFamilies(prev => prev.map(x => x.key === f.key ? {
          ...x,
          children: x.children.filter(c => c.reg !== ch.reg),
        } : x));
        setGenSet(prev => { const n = new Set(prev); n.delete(keyOf(f.key, ch.reg)); return n; });
        toast('Child removed from family challan', 'success');
      },
    });
  };

  /* ── Smart search ── */
  const matches = useCallback(() => {
    const q = searchQ.trim().toLowerCase();
    if (!q) return [];
    return list.filter(f => `${f.name} ${f.guardian}`.toLowerCase().includes(q)).slice(0, 8);
  }, [searchQ, list])();

  const clearSearch = () => { setSearchQ(''); setSearchOpen(false); setHighlightKey(null); };

  const focusOnFamily = (f) => {
    setOpenKey(f.key);
    setSearchOpen(false);
    setHighlightKey(f.key);
    toast('Jumped to family', 'info');
    setTimeout(() => {
      const el = document.getElementById(`fam-row-${f.key}`);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 380);
  };

  return (
    <>
      {/* Filters + smart search */}
      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field">
              <span className="fee-label">Month</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={month} onChange={e => setMonth(e.target.value)}>
                  {FEE_MONTHS.map(m => <option key={m}>{m}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Year</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={year} onChange={e => setYear(e.target.value)}>
                  <option>2025</option><option>2026</option><option>2027</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <Tooltip text="Load family challan data for the selected month and year">
              <button className="fee-btn fee-btn-primary" onClick={apply}>
                <i className="fa-solid fa-filter"></i> Get Families
              </button>
            </Tooltip>
            <Tooltip text="Reset filters and search to defaults">
              <button className="fee-btn fee-btn-ghost" onClick={resetFilters}>
                <i className="fa-solid fa-rotate-left"></i> Reset
              </button>
            </Tooltip>
          </div>

          <div className="fee-searchrow">
            <div className="fee-field" style={{ width: '100%' }}>
              <span className="fee-label">Search Family</span>
              <div className="fee-search-anchor" ref={searchAnchorRef}>
                <div className="fee-search-box">
                  <i className="fa-solid fa-magnifying-glass"></i>
                  <input
                    value={searchQ}
                    autoComplete="off"
                    onChange={e => { const v = e.target.value; setSearchQ(v); setSearchOpen(true); if (!v.trim()) setHighlightKey(null); }}
                    onFocus={() => setSearchOpen(true)}
                    placeholder="Search by Family Name or Guardian"
                  />
                  {searchQ && (
                    <Tooltip text="Clear search">
                      <button type="button" className="fee-search-clear" onClick={clearSearch} aria-label="Clear search">
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </Tooltip>
                  )}
                </div>
                <div className={`fee-search-results${searchOpen && searchQ ? ' open' : ''}`}>
                  {matches.length === 0 ? (
                    <div className="fee-sr-empty">No families found for "<b>{searchQ}</b>"</div>
                  ) : matches.map(f => {
                    const initial = (f.name.match(/\d+/) || [f.name[0]])[0];
                    return (
                      <button type="button" key={f.key} className="fee-sr-item" onClick={() => focusOnFamily(f)}>
                        <div className="fee-sr-av">{initial}</div>
                        <div className="fee-sr-main">
                          <div className="fee-sr-name">{f.name}</div>
                          <div className="fee-sr-meta">
                            <span><b>Guardian:</b> {f.guardian}</span>
                            <span><b>Children:</b> {f.children.length}</span>
                          </div>
                        </div>
                        <div className="fee-sr-go"><i className="fa-solid fa-arrow-right"></i></div>
                      </button>
                    );
                  })}
                </div>
              </div>
              <div className="fee-hint">
                <i className="fa-solid fa-circle-info"></i>
                <span>Search any family by family name or guardian name.</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span>
          Family challans combine all siblings under one guardian into a single payable challan.
          The <strong>Children</strong> count shows how many of the family's children have a challan generated.
        </span>
      </div>

      <div className="fee-section">
        <div className="fee-table-head fee-family-row">
          <div className="fee-th">#</div>
          <div className="fee-th">Family / Guardian</div>
          <div className="fee-th fee-center">Children</div>
          <div className="fee-th fee-center">Download</div>
          <div className="fee-th fee-center">Bulk</div>
          <div className="fee-th fee-center">Details</div>
        </div>

        {famsLoading ? (
          <div className="fee-empty"><i className="fa-solid fa-spinner fa-spin"></i> Loading families…</div>
        ) : (list.length > 0 && loadedKey !== viewKey) ? (
          <div className="fee-empty"><i className="fa-solid fa-spinner fa-spin"></i> Loading challans…</div>
        ) : list.length === 0 ? (
          <div className="fee-empty">No families configured.</div>
        ) : list.map((f, i) => {
          const isOpen = openKey === f.key;
          const gen = genCountFor(f.key, f.children);
          const tot = f.children.length;
          /* Column totals for the table footer — summed from each child's figures. */
          const sums = f.children.reduce((a, ch) => {
            const fig = childFig(f, ch);
            const d = Number(fig.dues) || 0;
            const v = Number(fig.advance) || 0;
            /* Row jaisa hi hisaab (discount already fee/transport me shamil). */
            const p = (Number(fig.fee) || 0) + (Number(fig.transport) || 0) + d - v;
            /* PROJECTED late fine ko Total Payable me NAHI jodte — challan amount asal
               fee hi rahe. Sirf bill ho chuki (receive ke waqt lagi) fine, jo pehle se
               `fee` me baqaya ke taur par shamil hai, count hoti hai. */
            const chRec = recMap[keyOf(f.key, ch.reg)];
            const billedFine = billedFineOf(chRec) > 0 ? challanAccruedFine(chRec, settings) : 0;
            return {
              fee: a.fee + (Number(fig.fee) || 0),
              transport: a.transport + (Number(fig.transport) || 0),
              discount: a.discount + (Number(fig.discount) || 0),
              dues: a.dues + d,
              advance: a.advance + v,
              fine: a.fine + billedFine,
              payable: a.payable + p,
            };
          }, { fee: 0, transport: 0, discount: 0, dues: 0, advance: 0, fine: 0, payable: 0 });
          const total = sums.payable;
          return (
            <div key={f.key} className={`fee-rowwrap${highlightKey === f.key ? ' fee-st-highlight' : ''}`} id={`fam-row-${f.key}`}>
              <div
                className={`fee-row fee-family-row${isOpen ? ' open' : ''}`}
                onClick={() => setOpenKey(isOpen ? null : f.key)}
              >
                <div className="fee-td" data-label="#"><span className="fee-row-icon">{i + 1}</span></div>
                <div className="fee-td fee-name" data-label="Family / Guardian">
                  {f.name} <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>— {f.guardian}</span>
                </div>
                <div className="fee-td fee-center" data-label="Children">
                  <span className="fee-count">{gen} <small>/ {tot}</small></span>
                </div>
                <div className="fee-td fee-center" data-label="Download" onClick={e => e.stopPropagation()}>
                  <Tooltip text={`Download combined challan for ${f.name}`}>
                    <button className="fee-iconbtn" onClick={() => openDownload(f)}>
                      <i className="fa-solid fa-file-arrow-down"></i>
                    </button>
                  </Tooltip>
                </div>
                <div className="fee-td fee-center" data-label="Bulk" onClick={e => e.stopPropagation()}>
                  <Tooltip text={tot - gen > 0
                    ? `Generate challans for the ${tot - gen} remaining child${tot - gen === 1 ? '' : 'ren'} (already-generated ones are skipped)`
                    : `All ${tot} children already have challans`}>
                    <button className="fee-btn fee-btn-primary fee-btn-xs" onClick={() => openBulkGen(f)}>
                      <i className="fa-solid fa-people-roof"></i> Bulk Challans
                    </button>
                  </Tooltip>
                </div>
                <div className="fee-td fee-center" data-label="Details">
                  <Tooltip text={isOpen ? 'Hide children list' : 'Show children list'}>
                    <span className={`fee-chevbtn${isOpen ? ' open' : ''}`}>
                      <i className="fa-solid fa-chevron-down fee-chev"></i>
                    </span>
                  </Tooltip>
                </div>
              </div>

              <div className={`fee-detail${isOpen ? ' open' : ''}`}>
                <div className="fee-detail-inner">
                  <div className="fee-detail-title">
                    <i className="fa-solid fa-children"></i> Children in {f.name}
                  </div>

                  <div className="fee-stbl-wrap">
                    <table className="fee-stbl">
                      <thead>
                        <tr>
                          <th>#</th>
                          <th>Reg No</th>
                          <th>Name</th>
                          <th>Class</th>
                          <th>Sec</th>
                          <th className="fee-right">Total Dues</th>
                          <th className="fee-right">Advance</th>
                          <th className="fee-right">Transport</th>
                          <th className="fee-right">Discount</th>
                          <th className="fee-right">Fee</th>
                          <th className="fee-right">Total Payable</th>
                          <th className="fee-center">Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {f.children.length === 0 ? (
                          <tr><td colSpan="12" className="fee-stbl-empty">No children in this family.</td></tr>
                        ) : f.children.map((ch, j) => {
                          const fig = childFig(f, ch);
                          /* Fee/Transport/Dues ab baqaya (received ke baad) hain aur discount
                             unme already shamil — is liye yahan discount dobara minus nahi.
                             Over-payment par pay MINUS me jaata hai = student ka credit. */
                          const dues = Number(fig.dues) || 0;
                          const adv = Number(fig.advance) || 0;
                          const pay = (Number(fig.fee) || 0) + (Number(fig.transport) || 0) + dues - adv;
                          const generated = isGen(f.key, ch.reg);
                          /* Total Payable = asal challan fee. PROJECTED late fine yahan
                             NAHI jodte — wo challan print/receiving par lagti hai. Sirf
                             bill ho chuki fine (jo `fig.fee` me pehle se hai) note me. */
                          const chRec = recMap[keyOf(f.key, ch.reg)];
                          const billedFine = billedFineOf(chRec) > 0 ? challanAccruedFine(chRec, settings) : 0;
                          return (
                            <tr key={ch.reg}>
                              <td className="fee-num">{j + 1}</td>
                              <td>{ch.reg}</td>
                              <td><b>{ch.name}</b></td>
                              <td>{ch.cls}</td>
                              <td>{ch.sec}</td>
                              <td className="fee-right">{money(dues)}</td>
                              {/* Advance student ke haq me hai → MINUS me dikhao. */}
                              <td className={`fee-right${adv > 0 ? ' fee-neg' : ''}`}>{money(adv > 0 ? -adv : 0)}</td>
                              <td className="fee-right">{money(fig.transport)}</td>
                              <td className="fee-right">{money(fig.discount)}</td>
                              <td className="fee-right">{money(fig.fee)}</td>
                              <td className={`fee-right${pay < 0 ? ' fee-neg' : ''}`}>
                                <b>{money(pay)}</b>
                                {billedFine > 0 && <span className="fee-sub-eq fee-fine">incl. fine {money(billedFine)}</span>}
                              </td>
                              <td className="fee-center fee-st-actions">
                                {generated && settings.installmentChallan === true && (
                                  challanFullyPaid(chRec) ? (
                                    <Tooltip text="Fully received">
                                      <button className="fee-iconbtn" disabled aria-disabled="true" style={{ opacity: .4, cursor: 'not-allowed' }}>
                                        <i className="fa-solid fa-money-check-dollar"></i>
                                      </button>
                                    </Tooltip>
                                  ) : (
                                    <Tooltip text={`Create installment challan for ${ch.name}`}>
                                      <button className="fee-iconbtn" onClick={() => openInstallment(f, ch)}>
                                        <i className="fa-solid fa-money-check-dollar"></i>
                                      </button>
                                    </Tooltip>
                                  )
                                )}
                                {generated ? (
                                  <Tooltip text={challanHasReceiving(chRec) ? DEL_LOCKED_TIP : `Delete ${appliedMonth} challan for ${ch.name}`}>
                                    <button
                                      className="fee-iconbtn danger"
                                      aria-disabled={challanHasReceiving(chRec)}
                                      style={challanHasReceiving(chRec) ? { opacity: .4, cursor: 'not-allowed' } : undefined}
                                      onClick={() => { if (!challanHasReceiving(chRec)) requestDeleteChildChallan(f, ch); }}
                                    >
                                      <i className="fa-solid fa-trash-can"></i>
                                    </button>
                                  </Tooltip>
                                ) : chRec ? (
                                  /* Pichhle mahine ka multi-month challan is mahine ko cover karta hai —
                                     Delete nahi (wo us mahine ka challan hai), sirf Regenerate. */
                                  <Tooltip text={`Regenerate ${appliedMonth} challan for ${ch.name} (currently covered by ${ledgerMonthLabel(chRec)} challan)`}>
                                    <button className="fee-iconbtn" style={REGEN_BTN_STYLE} onClick={() => openIndivGen(f, ch)}>
                                      <i className="fa-solid fa-rotate"></i>
                                    </button>
                                  </Tooltip>
                                ) : (
                                  <Tooltip text={`Generate family challan for ${ch.name}`}>
                                    <button className="fee-iconbtn green" onClick={() => openIndivGen(f, ch)}>
                                      <i className="fa-solid fa-file-circle-plus"></i>
                                    </button>
                                  </Tooltip>
                                )}
                                <Tooltip text={`Download ${ch.name}'s separate challan`}>
                                  <button className="fee-iconbtn" onClick={() => openChildDownload(f, ch)}>
                                    <i className="fa-solid fa-download"></i>
                                  </button>
                                </Tooltip>
                                <Tooltip text={`View ${ch.name}'s challan`}>
                                  <button className="fee-iconbtn" onClick={() => openChildPreview(f, ch)}>
                                    <i className="fa-solid fa-eye"></i>
                                  </button>
                                </Tooltip>
                                <Tooltip text="Remove child from family">
                                  <button className="fee-iconbtn danger" onClick={() => requestRemoveChild(f, ch)}>
                                    <i className="fa-solid fa-user-minus"></i>
                                  </button>
                                </Tooltip>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                      {/* Column-wise total row hata diya — neeche right corner wala
                          "Total Family Payable" hi kaafi hai. */}
                    </table>
                  </div>

                  <div className="fee-family-total">
                    {sums.fine > 0 && (
                      <>
                        Total Fine: <span className="fee-fine">{money(sums.fine)}</span>
                        <span style={{ margin: '0 10px', opacity: 0.4 }}>|</span>
                      </>
                    )}
                    Total Family Payable: <span>{money(total)}</span>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <FeeConfirmDialog cfg={confirm} onClose={() => setConfirm(null)} />
      <FeeBusyOverlay message={busyMsg} />

      <BulkGenerateModal
        open={!!bulkGen}
        classMeta={bulkGen?.classMeta}
        students={bulkGen?.students || []}
        heads={bulkGen?.heads || []}
        defaultMonth={appliedMonth}
        defaultYear={appliedYear}
        genSet={genSet}
        keyOf={keyOf}
        onClose={() => setBulkGen(null)}
        onGenerated={handleBulkGenerated}
        toast={toast}
        familyMode
        singleMode={bulkGen?.mode === 'single'}
        /* Student ka saved discount family challan me bhi map ho. */
        fetchDiscounts={fetchFamilyDiscounts}
      />

      <ChallanPreviewModal
        cfg={challanPreview}
        onClose={() => setChallanPreview(null)}
        onDownload={() => {
          const f = challanPreview?.family;
          const ch = challanPreview?.child;
          setChallanPreview(null);
          /* Child preview tha to usi bachche ka download, warna poori family ka. */
          if (ch && f) openChildDownload(f, ch);
          else if (f) openDownload(f);
        }}
      />

      <DownloadPickerModal
        cfg={downloadCtx}
        onClose={() => setDownloadCtx(null)}
        onSubmit={(picks) => {
          const ctx = downloadCtx;
          setDownloadCtx(null);
          if (!ctx) return;
          if (ctx.kind === 'child') runChildDownload(ctx, picks);   // separate child slip
          else if (ctx.family) runDownload(ctx.family, picks); // combined family slip
        }}
      />

      <InstallmentChallanModal
        cfg={installmentCtx}
        onClose={() => setInstallmentCtx(null)}
        onCreate={createInstallmentChallan}
        toast={toast}
        defaultSize={settings.printSize || 'a4'}
      />
    </>
  );
}

/* Split a challan's detailRows into the screen figures: a "previous pending"
   head becomes Total Dues when positive, or Advance (as a positive number) when
   negative; every other head sums into Current Fee. Total Payable = Current Fee
   + Total Dues − Advance.
   `byHead` (optional): live prior remaining per head (billed−disc−recv). Raw
   previousPendingorAdv kabhi GROSS hota hai (3000); byHead discount-ke-baad
   (2500) — wasooli attribution / fully-paid ke liye yahi cap use karo warna
   5000 receive ke baad bhi Current pe phantom 500 reh jata tha. */
function challanFigures(rec, byHead = null) {
  const rows = (rec && rec.detailRows) || [];
  /* Sirf aggregate "Previous Pending" / Arrear. "Previous Due" aur "Pending Due"
     asli heads hain — unka previous list se skip nahi hona. */
  const isPrevRow = (r) => isAggregateCarryRow(r);
  /* Head-wise: kisi non-prev head par per-head previousPendingorAdv ho to previous PER-HEAD me
     hai — aise me aggregate "Previous Pending" rows ko SKIP karte hain (warna previous DO baar
     ginta: ek per-head, ek aggregate row → fully-paid par bhi Total Dues 1,500 dikhता tha). */
  const hasHeadPrev = rows.some(r => !isPrevRow(r) && (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0);
  const byHeadLookup = (name) => {
    if (!byHead || typeof byHead !== 'object') return null;
    const norm = String(name || '').toLowerCase().trim();
    const key = Object.keys(byHead).find(k => String(k).toLowerCase().trim() === norm);
    if (key == null) return null;
    const n = Number(byHead[key]);
    return Number.isFinite(n) ? n : null;
  };
  let dues = 0, advance = 0, current = 0;
  let totalNet = 0, totalRecv = 0;
  rows.forEach(r => {
    const amt = Number(r.challanAmount) || 0;
    const disc = Number(r.discount) || 0;
    const recv = Number(r.receivedAmount) || 0;
    const isPrev = isPrevRow(r);
    if (hasHeadPrev && isPrev) return;   // head-wise: aggregate prev row skip (per-head me hai)
    const hpRaw = hasHeadPrev ? (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) : 0;
    const live = byHeadLookup(r.subHead || r.head);
    /* byHead > 0 ho to usse cap (gross 3000 → 2500); byHead 0/absent ho to challan hp. */
    let prevPart = Math.max(0, hpRaw);
    if (live != null && live > 0) prevPart = Math.min(prevPart, live);
    const curNet = amt - disc;
    totalNet += curNet + prevPart;
    totalRecv += recv;
    /* Dues/Current ab WASOOLI KE BAAD ka baqaya hai — challan poora receive ho jaye to
       ye 0 ho jaate hain (pehle full amount hi dikhta rehta tha). */
    if (isPrev) {
      if (amt >= 0) dues += Math.max(0, curNet - recv);
      else advance += Math.abs(amt);
    } else if (hasHeadPrev) {
      const againstPrev = Math.min(recv, prevPart);
      const againstCur = Math.max(0, recv - againstPrev);
      dues += Math.max(0, prevPart - againstPrev);
      current += Math.max(0, curNet - againstCur);
    } else {
      current += Math.max(0, curNet - recv);
    }
  });
  /* Challan ke total se ZYADA wasool ho gaya (over-receiving) → extra raqam student ka
     ADVANCE hai. Isay bhi advance me jodo, warna Fee Challans list par 0 dikhta tha. */
  advance += Math.max(0, totalRecv - totalNet);
  return { dues, advance, current, payable: current + dues - advance };
}

/* IS challan me PEHLE SE consume ho chuka advance — negative "Previous Pending"/advance rows
   ke received (minus) ka jama. running-ledger ka prevOut.advance sirf PICHHLE mahino ka hai,
   is mahine ki consumption nahi jaanta — is liye card use karta hai (warna −550 phantom). */
function advConsumedOf(rec) {
  if (!rec || !Array.isArray(rec.detailRows)) return 0;
  return rec.detailRows
    .filter(r => isAggregateCarryRow(r) && (Number(r.challanAmount) || 0) < 0)
    .reduce((a, r) => a + Math.abs(Number(r.receivedAmount) || 0), 0);
}

/* Kya ye challan POORA settle ho chuka — har head ka (challanAmount − discount +
   previousPendingorAdv) − received ka jama <= 0 aur koi receiving hui ho. Advance jab head
   ki fee se zyada ho to Others net minus (−550) reh jaata tha "Fully Received" ke bawajood;
   aise settled challan par card sab (Dues/Advance/Current/Payable) 0 dikhata hai — clean. */
/* IS challan par owed se ZYADA wasool (over-receiving) = student ka advance (musbat).
   challanFullyPaid ka hi hisaab — outstanding MINUS ho to utna advance. Fully-paid /
   prevOut override branches isay alag rakhte hain, warna −3,500 advance 0 ho jaata tha. */
function challanOverpaid(rec, byHead = null) {
  if (!rec || !Array.isArray(rec.detailRows) || !rec.detailRows.length) return 0;
  const isPrevRow = (r) => isAggregateCarryRow(r);
  const hasHeadPrev = rec.detailRows.some(r => !isPrevRow(r) && (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0);
  const norm = (s) => String(s || '').toLowerCase().trim();
  let outstanding = 0;
  rec.detailRows.forEach(r => {
    if (hasHeadPrev && isPrevRow(r)) return;
    /* Negative advance rows (credit) consume ho kar received −X — un ka net 0 rakho. */
    if (isPrevRow(r) && (Number(r.challanAmount) || 0) < 0) return;
    let hp = Math.max(0, Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0);
    if (byHead && typeof byHead === 'object') {
      const key = Object.keys(byHead).find(k => norm(k) === norm(r.subHead || r.head));
      const live = key != null ? Number(byHead[key]) : null;
      if (live != null && Number.isFinite(live) && live > 0) hp = Math.min(hp, live);
    }
    outstanding += (Number(r.challanAmount) || 0) - (Number(r.discount) || 0) + hp - (Number(r.receivedAmount) || 0);
  });
  return Math.max(0, -Math.round(outstanding));
}

function challanFullyPaid(rec, byHead = null) {
  if (!rec || !Array.isArray(rec.detailRows) || !rec.detailRows.length) return false;
  const isPrevRow = (r) => isAggregateCarryRow(r);
  /* Head-wise: previous per-head hai to aggregate "Previous Pending" row SKIP (double-count na
     ho — warna fully-paid ke bawajood us row ki wajah se outstanding 1,500 reh jaata tha). */
  const hasHeadPrev = rec.detailRows.some(r => !isPrevRow(r) && (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0);
  const byHeadLookup = (name) => {
    if (!byHead || typeof byHead !== 'object') return null;
    const norm = String(name || '').toLowerCase().trim();
    const key = Object.keys(byHead).find(k => String(k).toLowerCase().trim() === norm);
    if (key == null) return null;
    const n = Number(byHead[key]);
    return Number.isFinite(n) ? n : null;
  };
  let outstanding = 0, anyRecv = 0, billed = 0;
  rec.detailRows.forEach(r => {
    if (hasHeadPrev && isPrevRow(r)) return;   // head-wise: aggregate prev row skip
    const hpRaw = Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0;
    const live = byHeadLookup(r.subHead || r.head);
    let hp = Math.max(0, hpRaw);
    if (live != null && live > 0) hp = Math.min(hp, live);
    const net = (Number(r.challanAmount) || 0) - (Number(r.discount) || 0) + hp;
    const recv = Number(r.receivedAmount) || 0;
    billed += Math.max(0, net);
    outstanding += net - recv;
    anyRecv += recv;
  });
  /* outstanding <= 0 = settle (wasooli YA poora discount). anyRecv zaroori nahi —
     warna 100% discount / give-disc par bhi purana byHead 2500 list me wapas aa jata tha. */
  return Math.round(outstanding) <= 0 && (anyRecv !== 0 || billed > 0);
}

function FeeChallansList({ toast }) {
  /* Classes API ke fee heads (feeStructureID + name) — Discount Manager ke
     heads render + saved-discount ko headID se resolve karne ke liye. */
  const { data: classFeeStruct = {} } = useAsync(feeService.getClassFeeStructureMap, []);
  /* Existing discount record ids: { [studentID]: { [headID]: recordId } } — save
     par bheja jaata hai taake already-added discount update ho (na ke naya insert). */
  const discountIdRef = useRef({});
  const { can } = usePermissions();
  const canChCreate = can('Fee', 'Fee Challans', 'Create');
  const canChDelete = can('Fee', 'Fee Challans', 'Delete');
  const canChDownload = can('Fee', 'Fee Challans', 'Download');
  const { data: classes = [], loading: classesLoading } = useAsync(feeService.getFeeClasses, []);
  const { data: studentsMap = {} } = useAsync(feeService.getTransportFee, []);
  const { data: headsMap = {} } = useAsync(feeService.getFeeHeads, []);
  const { data: settings = {} } = useAsync(feeService.getFeeSettings, []);
  /* Branch header (name / address / logo / session / date) for challan slips. */
  const { data: branchHeader = null } = useAsync(feeService.getReportHeader, [], null);

  /* Filters */
  const today = new Date();
  const [month, setMonth] = useState(FEE_MONTHS[today.getMonth()]);
  const [year, setYear] = useState(String(today.getFullYear()));
  const [appliedMonth, setAppliedMonth] = useState(month);
  const [appliedYear, setAppliedYear] = useState(year);

  /* Smart search */
  const [searchQ, setSearchQ] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);
  const [highlightKey, setHighlightKey] = useState(null);
  const searchAnchorRef = useRef(null);

  /* Close on outside click (mousedown so it fires before a focus-blur race) */
  useEffect(() => {
    if (!searchOpen) return undefined;
    const onDown = (e) => {
      if (searchAnchorRef.current && !searchAnchorRef.current.contains(e.target)) {
        setSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('touchstart', onDown);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('touchstart', onDown);
    };
  }, [searchOpen]);

  /* Close on Escape */
  useEffect(() => {
    if (!searchOpen) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') setSearchOpen(false); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [searchOpen]);

  /* Generated challans, loaded live from get-with-installments for the
     applied month/year. `genSet` marks which class|reg|month challans exist;
     `challanMap` holds the full challan record (incl. id + detailRows +
     installments) per key so deletes can target the real BranchLedger id. */
  const [genSet, setGenSet] = useState(null);
  const [challanMap, setChallanMap] = useState({});
  /* Pichle mahino ka baqaya (dues) / advance — { [studentID]: { dues, advance } }.
     Isse current month me challan banane se PEHLE hi total dues dikh jaate hain. */
  const [prevOutMap, setPrevOutMap] = useState({});
  /* Covering multi-month challans (Sep–Nov ka Oct view) — generated nahi, sirf display. */
  const [coverMap, setCoverMap] = useState({});
  const monthIdx = FEE_MONTHS.indexOf(appliedMonth);
  const keyOf = (classKey, reg) => `${classKey}|${reg}|${monthIdx}`;

  /* Pull the month's challans and index them onto the class|reg keys. Matches
     each challan to a student by studentID (falling back to the challan's own
     grade/section/registration), so the list reflects real generated data. */
  /* Is mahine ka challan data load ho chuka? Na ho to list ki jagah LOADER (class/row ke
     0 / khali figures nahi). Save/delete ke baad refresh par list chhupti nahi. */
  const [loadedKey, setLoadedKey] = useState('');
  const viewKey = `${appliedMonth}|${appliedYear}`;
  const loadChallans = useCallback(async () => {
    if (!studentsMap || Object.keys(studentsMap).length === 0) return;
    const mIdx = FEE_MONTHS.indexOf(appliedMonth);
    try {
      const rows = await feeService.getMonthChallans(mIdx + 1, appliedYear);
      const byStudentId = new Map();
      Object.entries(studentsMap).forEach(([ck, studs]) => {
        (studs || []).forEach(s => byStudentId.set(String(s.studentID), { classKey: ck, reg: s.reg }));
      });
      const set = new Set();
      const map = {};
      /* Multi-month challan jo PICHHLE mahine se shuru hua (Sep–Nov ka Oct) — is mahine ko
         "generated" NAHI ginte, taake Oct me naya challan Create ho sake (user ki marzi).
         Us ke figures (advance waghera) phir bhi row me dikhein — coverMap se. */
      const cover = {};
      rows.forEach(ch => {
        const loc = byStudentId.get(String(ch.studentID));
        const classKey = loc ? loc.classKey : `g${ch.gradeID}-s${ch.sectionID}`;
        const reg = loc ? loc.reg : String(ch.registrationNumber || '');
        const k = `${classKey}|${reg}|${mIdx}`;
        if (isMultiMonthNonStartView(ch, mIdx + 1, Number(appliedYear))) {
          cover[k] = feeService.withPersistedGiveDisc(ch);
          return;
        }
        set.add(k);
        map[k] = feeService.withPersistedGiveDisc(ch);
      });
      setGenSet(set);
      setChallanMap(map);
      setCoverMap(cover);

      /* ── Pichhle mahino ka baqaya, RUN TIME par ──
         Har student ka SABSE RECENT purana challan liya jaata hai (usi me pehle ka
         carry-forward already shamil hota hai, is liye double-count nahi hota), phir
         uska unpaid remainder nikaala jaata hai:
           remainder = Σ (challanAmount − discount − receivedAmount)
         remainder > 0 → Total Dues | remainder < 0 → Advance.
         Isse current month ka challan banane se PEHLE hi dues/advance dikh jaate hain. */
      let prevOut = {};
      try {
        let toM = mIdx, toY = appliedYear;                 // applied month se ek pehle
        if (toM === 0) { toM = 12; toY = appliedYear - 1; }
        let fromM = toM - 11, fromY = toY;                 // 12-month window
        while (fromM <= 0) { fromM += 12; fromY -= 1; }
        const prevRows = await feeService.getLedgerRange(fromM, fromY, toM, toY);
        /* Running-ledger — stale stored Previous Pending se bachne ke liye. */
        prevOut = prevOutFromLedgerRows(prevRows, mIdx + 1, appliedYear);
        /* Covering (Sep–Nov ka Nov) challan jis ka baqaya baad wala (Oct) challan pehle hi
           CARRY kar chuka — row me us ke figures mat dikhao (dues double: 16,000 + advance
           −4,000). Row pichhle baqaye (prevOut: 12,000) par chale. */
        const prior = priorChallansByStudent(prevRows, mIdx + 1, appliedYear);
        const cover2 = { ...cover };
        let coverDropped = false;
        Object.keys(cover2).forEach(k => {
          const cr = cover2[k];
          const latest = (prior[String(cr.studentID)] || [])[0];
          if (!latest) return;
          const ls = Number(latest.startYear || latest.year) * 12 + Number(latest.startMonth || latest.month);
          const cs = Number(cr.startYear || cr.year) * 12 + Number(cr.startMonth || cr.month);
          if (ls > cs && challanCarriesPrev(latest)) { delete cover2[k]; coverDropped = true; }
        });
        if (coverDropped) setCoverMap(cover2);
      } catch (e) { /* previous dues optional — na mile to 0 hi rahenge */ }
      setPrevOutMap(prevOut);
    } catch (e) {
      toast(e.message || 'Could not load challans', 'error');
      setGenSet(new Set());
      setChallanMap({});
      setCoverMap({});
      setPrevOutMap({});
    } finally {
      setLoadedKey(`${appliedMonth}|${appliedYear}`);
    }
  }, [studentsMap, appliedMonth, appliedYear, toast]);

  /* Load on mount and whenever the student roster or applied month/year change. */
  useEffect(() => { loadChallans(); }, [loadChallans]);

  /* Expanded row */
  const [openKey, setOpenKey] = useState(null);
  const [confirm, setConfirm] = useState(null);
  const [busyMsg, setBusyMsg] = useState('');    // delete chal raha ho to center loader + screen lock
  const [bulkGen, setBulkGen] = useState(null);          // { classMeta, students, heads }
  const [challanPreview, setChallanPreview] = useState(null); // { title, sub, ctx, innerHtml }
  const [downloadCtx, setDownloadCtx] = useState(null);  // { type, classKey, reg?, sub }
  const [discountCtx, setDiscountCtx] = useState(null);  // { classMeta, student, heads, initial }
  /* Installment challan modal — { classMeta, student, rec, heads } */
  const [installmentCtx, setInstallmentCtx] = useState(null);
  /* Per-class per-student discount map: { [classKey]: { [reg]: { [headName]: amount } } } */
  const [discountMap, setDiscountMap] = useState({});
  /* Student-specific discounts jo abhi approval ka intezaar kar rahe hain. save-fee-discount
     ke `PendingApproval:true` response par set hota hai — ACTION column me "Pending Approval"
     badge (ApprovalID ke saath) + Withdraw icon isi se render hota hai.
     keyOf(classKey, reg) -> { approvalId, requestNo } */
  const [pendingDiscounts, setPendingDiscounts] = useState({});
  /* List open par server se aayi pending FeeDiscount requests (page reload ke baad bhi
     badge dikhe). approvals_by_user se filter: module=FeeDiscount, status=Pending.
     studentID -> { approvalId, requestNo }. Render dono (session + server) ko dekhta hai. */
  const [pendingByStudent, setPendingByStudent] = useState({});
  const loadPendingDiscountApprovals = useCallback(async () => {
    try {
      const rows = await feeService.getUserApprovalRequests();
      const map = {};
      rows
        .filter(r => String(r.module) === 'FeeDiscount'
          && String(r.status).toLowerCase() === 'pending'
          && r.studentID != null)
        .forEach(r => {
          const sid = String(r.studentID);
          /* Ek student ke multiple pending heads — sab se naya (bada id) badge me. */
          const prev = map[sid];
          if (!prev || Number(r.id) > Number(prev.approvalId)) {
            map[sid] = { approvalId: r.id, requestNo: r.requestNo };
          }
        });
      setPendingByStudent(map);
    } catch (e) { /* optional — na mile to sirf session-saved badges dikhenge */ }
  }, []);
  /* Mount par aur roster badalne par (tab/branch switch) refresh. */
  useEffect(() => { loadPendingDiscountApprovals(); }, [loadPendingDiscountApprovals, studentsMap]);

  const apply = () => {
    setAppliedMonth(month);
    setAppliedYear(year);
    toast(`Loaded ${month} ${year} challans`, 'info');
  };

  const resetFilters = () => {
    setMonth(FEE_MONTHS[today.getMonth()]);
    setYear(String(today.getFullYear()));
    setAppliedMonth(FEE_MONTHS[today.getMonth()]);
    setAppliedYear(String(today.getFullYear()));
    setSearchQ('');
    setHighlightKey(null);
  };

  /* Compute generated counts per class against the applied month */
  const genCountFor = (classKey) => {
    if (!genSet) return 0;
    const studs = studentsMap[classKey] || [];
    return studs.reduce((acc, s) => acc + (genSet.has(keyOf(classKey, s.reg)) ? 1 : 0), 0);
  };
  const isGenerated = (classKey, reg) => !!genSet && genSet.has(keyOf(classKey, reg));

  /* Export Excel — selected MONTH/YEAR ke SAARAY generated challans.
     Dropdown ki values use hoti hain (Fetch Details ke baghair bhi); data
     seedha API se fresh pull — genSet/search filter par depend nahi. */
  const [exportingExcel, setExportingExcel] = useState(false);
  const handleExportExcel = async () => {
    const exportMonth = month;
    const exportYear = String(year);
    const mIdx = FEE_MONTHS.indexOf(exportMonth);
    if (mIdx < 0) {
      toast('Please select a valid month', 'warning');
      return;
    }

    const isoOrNull = (v) => {
      const s = v ? String(v).slice(0, 10) : '';
      return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null;
    };

    setExportingExcel(true);
    try {
      const challanRows = await feeService.getMonthChallans(mIdx + 1, exportYear);
      if (!Array.isArray(challanRows) || challanRows.length === 0) {
        toast(`No generated challans found for ${exportMonth} ${exportYear}.`, 'warning');
        return;
      }

      /* Reliable name resolution — load the FULL branch roster once and build
         lookup maps (class/section names by id; students by studentID,
         applicantsID and registrationNumber). This does not depend on which
         classes the user expanded and is not limited to active students, so
         every generated challan resolves its class/section/student names. */
      let classNameById = {}, sectionNameById = {}, studentById = {};
      try {
        ({ classNameById, sectionNameById, studentById } = await feeService.getBranchRosterMaps());
      } catch (e) { /* roster optional — falls back to component classes / challan fields */ }
      const classByKey = new Map((classes || []).map(c => [c.key, c]));

      /* Payable ke liye live previous (byHead) — list jaisa. */
      let prevOut = {};
      try {
        let toM = mIdx;
        let toY = Number(exportYear);
        if (toM === 0) { toM = 12; toY -= 1; }
        let fromM = toM - 11;
        let fromY = toY;
        while (fromM <= 0) { fromM += 12; fromY -= 1; }
        const prevRows = await feeService.getLedgerRange(fromM, fromY, toM, toY);
        prevOut = prevOutFromLedgerRows(prevRows, mIdx + 1, Number(exportYear));
      } catch (e) { /* optional — bina prev ke bhi export chalega */ }

      const rows = [];
      challanRows.forEach(ch => {
        const rec = feeService.withPersistedGiveDisc(ch);

        /* Resolve the student from the roster maps — match on studentID, then
           applicantsID, then registrationNumber (challans may reference any). */
        const resolved = studentById[String(ch.studentID)]
          || studentById[String(ch.applicantsID ?? '')]
          || studentById[String(ch.registrationNumber ?? ch.regNo ?? '')]
          || null;

        const classKey = `g${ch.gradeID}-s${ch.sectionID}`;
        const fromClasses = classByKey.get(classKey);
        const c = {
          key: classKey,
          cls: classNameById[String(ch.gradeID)]
            || fromClasses?.cls
            || ch.gradeName || ch.className || ch.class || `Class ${ch.gradeID || ''}`,
          sec: sectionNameById[String(ch.sectionID)]
            || fromClasses?.sec
            || ch.sectionName || ch.section || String(ch.sectionID || '—'),
        };
        const s = {
          studentID: ch.studentID,
          applicantsID: ch.applicantsID,
          reg: String(resolved?.reg || ch.registrationNumber || ch.regNo || ''),
          name: resolved?.name || ch.studentName || ch.name || '—',
          father: resolved?.father || ch.fatherName || ch.father || '—',
          /* Contact from the roster (studentPhone() reads s.phone); fall back to
             any phone on the challan record, else studentPhone() prints '—'. */
          phone: resolved?.phone || ch.phone || ch.mobile || ch.contactNumber || '',
          /* Address from the branch roster; '—' when the endpoint has none. */
          address: resolved?.address || ch.address || '',
        };

        /* Per-head net (challanAmount − discount) from the challan's own
           detailRows — same source the printed challan/slip uses. Previous/
           pending/arrear rows are folded into a single "Arrears" bucket; every
           other head keeps its subHead name. The builder discovers the dynamic
           head columns from the union of these keys, so it stays a pure
           formatter. */
        const isPrevDetail = (r) => /previous|pending|arrear/i.test(String(r.subHead || r.head || ''));
        const headAmounts = {};
        let arrears = 0;
        (rec.detailRows || []).forEach(r => {
          const name = String(r.subHead || r.head || '').trim();
          if (!name) return;
          const net = (Number(r.challanAmount) || 0) - (Number(r.discount) || 0);
          if (isPrevDetail(r)) { arrears += net; return; }
          headAmounts[name] = (headAmounts[name] || 0) + net;
        });
        s.headAmounts = headAmounts;
        s.arrears = arrears;

        const p = prevOut[String(s.studentID)]
          || prevOut[String(ch.studentID)]
          || prevOut[String(s.applicantsID || '')]
          || null;
        const byHead = p?.byHead || null;
        const fig = challanFigures(rec, byHead);
        let payable = 0;
        if (challanFullyPaid(rec, byHead)) {
          payable = 0;
        } else if (p) {
          const consumed = advConsumedOf(rec);
          const detail = rec.detailRows || [];
          const hasHeadPrev = detail.some(r =>
            !isAggregateCarryRow(r)
            && (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0
          );
          const byHeadSum = byHead
            ? Object.values(byHead).reduce((a, v) => a + Math.max(0, Number(v) || 0), 0)
            : 0;
          const dues = hasHeadPrev
            ? (fig.dues || 0)
            : (byHeadSum > 0 ? byHeadSum : (+p.dues || 0));
          const advance = Math.max(0, (+p.advance || 0) - consumed);
          payable = (fig.current || 0) + dues - advance;
        } else {
          payable = fig.payable;
        }

        rows.push({
          c, s, payable,
          genISO: isoOrNull(rec.dateofCreattion),
          dueISO: isoOrNull(rec.dueDate),
        });
      });

      rows.sort((a, b) => {
        const cls = String(a.c.cls || '').localeCompare(String(b.c.cls || ''));
        if (cls) return cls;
        const sec = String(a.c.sec || '').localeCompare(String(b.c.sec || ''));
        if (sec) return sec;
        return String(a.s.name || '').localeCompare(String(b.s.name || ''));
      });

      const wb = buildGeneratedChallansWorkbook({
        rows,
        monthIdx: mIdx,
        appliedMonth: exportMonth,
        appliedYear: exportYear,
        school: feeReportSchool(branchHeader),
      });
      await feeDownloadWorkbook(
        wb,
        `${reportFileName('Generated-Fee-Challans')}-${exportMonth}-${exportYear}.xlsx`,
      );
      toast(
        `Exported ${rows.length} generated challan${rows.length === 1 ? '' : 's'} (${exportMonth} ${exportYear})`,
        'success',
      );
    } catch (e) {
      toast(e?.message || 'Unable to export report. Please try again.', 'error');
    } finally {
      setExportingExcel(false);
    }
  };

  const openBulkGen = (c) => {
    const lock = challanMonthLock(monthIdx, appliedYear, settings);
    if (lock) { toast(lock, 'warning'); return; }
    const students = studentsMap[c.key] || [];
    const heads = headsMap[c.key] || [];
    if (students.length === 0) {
      toast('No students enrolled in this class', 'warning');
      return;
    }
    setBulkGen({ classMeta: c, students, heads });
  };
  const handleBulkGenerated = (classKey, regs) => {
    setGenSet(prev => {
      const n = new Set(prev);
      regs.forEach(reg => n.add(keyOf(classKey, reg)));
      return n;
    });
    /* Re-pull from the API so the new challans carry their real ids (needed for delete). */
    loadChallans();
  };
  const openIndivGen = (c, s) => {
    const lock = challanMonthLock(monthIdx, appliedYear, settings);
    if (lock) { toast(lock, 'warning'); return; }
    setBulkGen({
      classMeta: c,
      students: [s],
      heads: headsMap[c.key] || [],
      mode: 'single',
    });
  };

  /* Attach the real generated challan (with its detailRows) to a student so the
     slip renders exactly the heads the API returned, incl. "Previous Pending". */
  const withChallan = (c, s) => ({ ...s, _challan: challanMap[keyOf(c.key, s.reg)] || null });

  const resolveCtx = (ctx) => {
    const c = classes.find(x => x.key === ctx.classKey);
    if (!c) return null;
    const heads = headsMap[ctx.classKey] || [];
    if (ctx.type === 'student') {
      const s = (studentsMap[ctx.classKey] || []).find(x => x.reg === ctx.reg);
      if (!s) return null;
      return { classMeta: c, students: [withChallan(c, s)], heads, sub: `${s.name} · child of ${s.father || '—'}` };
    }
    if (ctx.type === 'bulk') {
      const all = studentsMap[ctx.classKey] || [];
      const list = all.filter(s => genSet && genSet.has(keyOf(c.key, s.reg)));
      if (list.length === 0) return null;
      return { classMeta: c, students: list.map(s => withChallan(c, s)), heads, sub: `${c.cls} — Section ${c.sec} · ${list.length} student${list.length === 1 ? '' : 's'}` };
    }
    return null;
  };

  /* Saved discounts for the students about to be printed, in the
     { [classKey]: { [reg]: { [headName]: amt } } } shape the slip builders read.

     They have to come from /api/Student/get-fee-discounts-by-student: the local
     discountMap only holds this session's edits, so on a fresh page the Disc
     column would print blank even though a discount exists. The API's headName
     is always empty, so rows are matched to heads by headID → feeStructureID. */
  const fetchStudentDiscounts = useCallback(async (classMeta, students) => {
    const perReg = {};
    await Promise.all((students || []).map(async (s) => {
      const gradeId = s.gradeID || classMeta._gradeId;
      const gHeads = (classFeeStruct[gradeId] && classFeeStruct[gradeId].length)
        ? classFeeStruct[gradeId]
        : (headsMap[classMeta.key] || []);
      let fromApi = {};
      try {
        const rows = await feeService.getFeeDiscountsByStudent(s.studentID);
        /* Ek hi head ke khilaf agar EK SE ZYADA active record hon (purana + naya),
           to SABSE NAYA (sabse bada id) jeetna chahiye — warna purana discount
           (e.g. 600) naye (100) ki jagah print/challan me chala jata hai. */
        const newestByHead = new Map();
        (rows || []).filter(r => r.isActive !== false).forEach(r => {
          const k = String(r.headID);
          const rank = Number(r.id) || 0;
          const cur = newestByHead.get(k);
          if (!cur || rank >= cur.rank) newestByHead.set(k, { rank, row: r });
        });
        newestByHead.forEach(({ row: r }) => {
          const head = gHeads.find(h => Number(h.feeStructureID) === Number(r.headID));
          const amt = Number(r.discountAmount) || 0;
          if (head && amt > 0) fromApi[head.name] = amt;
        });
      } catch (e) { fromApi = {}; }   /* no discounts → Disc stays blank */
      /* This session's just-saved edits win over what the server returned. */
      const local = (discountMap[classMeta.key] || {})[s.reg] || {};
      const merged = { ...fromApi, ...local };
      if (Object.keys(merged).length) perReg[s.reg] = merged;
    }));
    return { [classMeta.key]: perReg };
  }, [classFeeStruct, headsMap, discountMap]);

  const openPreview = async (ctx) => {
    const r = resolveCtx(ctx);
    if (!r) { toast('Nothing to preview', 'info'); return; }
    const dMap = await fetchStudentDiscounts(r.classMeta, r.students);
    /* Running-ledger dues/advance/byHead students par lagao — challan ka previous card ke
       barabar rahe aur advance Net me sahi minus ho. */
    const students = r.students.map(s => {
      const p = prevOutMap[String(s.studentID)] || prevOutMap[String(s.applicantsID)] || null;
      return p ? { ...s, dues: p.dues, advance: p.advance, prevByHead: p.byHead || null } : s;
    });
    const inner = buildChallanInner({
      classMeta: r.classMeta, students, heads: r.heads,
      settings, discountMap: dMap, bw: false, school: branchHeader,
    });
    setChallanPreview({
      title: ctx.type === 'bulk' ? 'Bulk Challan Preview' : 'Challan Preview',
      sub: `${r.sub} · Parent · Bank · School copies`,
      ctx,
      innerHtml: inner,
    });
  };
  const openDownload = (ctx) => {
    const r = resolveCtx(ctx);
    if (!r) { toast('Nothing to download', 'info'); return; }
    setDownloadCtx({ ...ctx, sub: r.sub, defaultSize: settings.printSize || 'a4' });
  };
  const runDownload = async (ctx, { theme, fmt, size = 'a4' }) => {
    const r = resolveCtx(ctx);
    if (!r) { toast('Nothing to download', 'info'); return; }
    const bw = theme === 'bw';
    const dMap = await fetchStudentDiscounts(r.classMeta, r.students);
    const students = r.students.map(s => {
      const p = prevOutMap[String(s.studentID)] || prevOutMap[String(s.applicantsID)] || null;
      return p ? { ...s, dues: p.dues, advance: p.advance, prevByHead: p.byHead || null } : s;
    });
    const html = buildChallanHTML({
      classMeta: r.classMeta, students, heads: r.heads,
      settings, discountMap: dMap, bw, size, school: branchHeader,
    });
    const cnt = r.students.length;
    const sizeT = size === 'thermal' ? 'Thermal 80mm' : 'A4';
    const label = `${sizeT} · ${bw ? 'B&W' : 'Color'} ${fmt === 'word' ? 'Word' : 'PDF'}`;
    toast(`Generating ${label} — ${cnt} challan${cnt === 1 ? '' : 's'}…`, 'info');
    /* Word needs no pop-up — the .docx is built and downloaded in place. */
    if (fmt === 'word') {
      downloadDocxFromHtml(html, `${r.classMeta.cls}-${r.classMeta.sec}-challans`);
      toast(`${cnt} challan${cnt === 1 ? '' : 's'} downloaded as Word.`, 'success');
      return;
    }
    const w = window.open('', '_blank');
    if (!w) { toast('Please allow pop-ups to download the challan', 'error'); return; }
    w.document.write(html);
    w.document.close();
    w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    setTimeout(() => toast('Challan ready — use your browser\'s Save as PDF.', 'success'), 1100);
  };

  /* ── Installment challan ────────────────────────────────────────────
     Open the modal for an ALREADY-generated challan: build the per-head
     grid (Challan Amount / Discount / After-Discount, all fixed) from the
     saved BranchLedger record's detailRows. Aggregate "Previous Pending"
     and late-fine rows are excluded — an installment is billed against the
     current fee heads only. */
  const openInstallment = (c, s) => {
    const rec = challanMap[keyOf(c.key, s.reg)];
    if (!rec) { toast('Generate the challan first', 'warning'); return; }
    if (challanFullyPaid(rec)) { toast('This challan is fully received', 'warning'); return; }
    const heads = installmentHeadsOf(rec);
    if (!heads.length) { toast('This challan is fully received', 'warning'); return; }
    setInstallmentCtx({ classMeta: c, student: s, rec, heads });
  };

  /* Each head has its own installment amount. PSID total = the sum of those amounts.
     The slip prints each typed amount as Standard and Net — no discount, no previous. */
  const createInstallmentChallan = async (cfg, perHead, bw = false, size = 'a4') => {    const { classMeta: c, student: s, rec, heads } = cfg;
    const billed = heads
      .map(h => ({ ...h, amt: Math.max(0, Math.round(Number(perHead?.[h.name]) || 0)) }))
      .filter(h => h.amt > 0 && h.amt <= h.afterDiscount);
    const totalInstallment = billed.reduce((a, h) => a + h.amt, 0);
    if (!totalInstallment) throw new Error('Enter an installment amount on at least one fee head');
    const branchID = Number(sessionStorage.getItem('branchID')) || Number(rec.branchID) || 1;
    const userID = Number(sessionStorage.getItem('UserID')) || 0;
    const mo = Number(rec.month) || (monthIdx + 1);
    const yr = Number(rec.year) || Number(appliedYear) || new Date().getFullYear();
    const dueISO = (() => {
      const d = new Date(rec.dueDate || Date.now());
      return Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
    })();

    const payload = {
      studentID: Number(rec.studentID || s.studentID) || 0,
      branchID,
      month: mo,
      year: yr,
      amount: totalInstallment,
      fullName: String(s.name || rec.fullName || ''),
      mobileNo: String(s.mobile || s.phone || ''),
      dueDate: dueISO,
      ledgerId: Number(rec.id) || 0,
      forceNew: true,
      modifiedBy: userID,
    };

    /* 1) Generate the installment PSID for this ledger. */
    const res = await feeService.generatePsid(payload);

    /* 2) New PSID — response se, warna branch-ledger (get-with-installments) se. */
    let psid = feeService.psidFromResponse(res);
    if (!psid) {
      try {
        const list = await feeService.getWithInstallments({ branchId: branchID, studentId: payload.studentID, month: mo, year: yr });
        const latest = Array.isArray(list) && list.length ? list[list.length - 1] : null;
        psid = latest ? feeService.psidOf(latest) : '';
      } catch (e) { /* best-effort */ }
    }

    /* 3) Installment slip download — har head par installment amount + naya PSID. */
    try {
      const instChallan = {
        ...rec,
        plpsid: psid,   // psidOf() isay slip par naya PSID/QR banane ke liye padhta hai
        detailRows: billed.map(h => ({
          head: 'Account Payable', subHead: String(h.name || ''),
          challanAmount: h.amt, discount: 0, receivedAmount: 0,
        })),
      };
          const student = { ...s, dues: 0, advance: 0, prevByHead: null, _challan: instChallan };
           const html = buildChallanHTML({
        classMeta: c, students: [student], heads: headsMap[c.key] || [],
        settings, discountMap: {}, bw, size: size === 'thermal' ? 'thermal' : 'a4', school: branchHeader,
        installmentSlip: true,
      });
      const w = window.open('', '_blank');
      if (w) {
        w.document.write(html);
        w.document.close();
        w.onload = () => { try { w.focus(); w.print(); } catch (err) { /* ignore */ } };
      } else {
        toast('Please allow pop-ups to download the challan', 'error');
      }
    } catch (e) { /* download failure not fatal — PSID is already generated */ }

    /* 4) Toast + close + list refresh. */
    toast(`Installment ${psid || 'challan'} challan created`, 'success');
    setInstallmentCtx(null);
    loadChallans();
  };

  const openDiscount = async (c, s) => {
    const gradeId = s.gradeID || c._gradeId;
    /* Heads classes API (get-classlist-…) se — inme feeStructureID + headName
       hota hai jo discount ke headID se match karta hai. Fallback: headsMap. */
    const heads = (classFeeStruct[gradeId] && classFeeStruct[gradeId].length)
      ? classFeeStruct[gradeId]
      : (headsMap[c.key] || []);
    if (heads.length === 0) { toast('Configure fee heads for this class first', 'warning'); return; }
    /* Is session ke local edits (jinme clear kiya hua 0 bhi shamil) — ye API ki
       purani value par JEETENGE, warna clear kiya hua discount reopen par phir purana
       dikhta tha (backend 0 par clear nahi karta). Challan generation bhi isi tarah
       edits ko preference deti hai, so UI aur challan consistent rehte hain. */
    const localMirror = (discountMap[c.key] && discountMap[c.key][s.reg]) || {};
    let initial = { ...localMirror };
    try {
      const rows = await feeService.getFeeDiscountsByStudent(s.studentID);
      const active = (rows || []).filter(r => r.isActive !== false);
      /* headID → { id, amt } yaad rakho — save par update ke liye id chahiye. */
      const idMap = {};
      active.forEach(r => { idMap[String(r.headID)] = { id: r.id, amt: Number(r.discountAmount) || 0 }; });
      discountIdRef.current[String(s.studentID)] = idMap;
      if (active.length) {
        const fromApi = {};
        active.forEach(r => {
          /* headName API me khaali aata hai — headID ko head.feeStructureID se match karo. */
          const head = heads.find(h => Number(h.feeStructureID) === Number(r.headID));
          if (head) fromApi[head.name] = Number(r.discountAmount) || 0;
        });
        /* API base, phir is session ke edits (0 clear samet) overlay — edits jeetein. */
        initial = { ...fromApi, ...localMirror };
      }
    } catch (e) { /* API fail → local mirror hi use hoga */ }
    setDiscountCtx({ classMeta: c, student: s, heads, initial });
  };
  const saveDiscount = async (classKey, reg, perHead, changedHeads) => {
    const pendKey = keyOf(classKey, reg);
    /* changedHeads diya ho to SIRF un heads ka API call jaata hai (jo add/change hue).
       Na diya ho (purane callers) to sab heads — backward compatible. */
    const changedSet = Array.isArray(changedHeads) ? new Set(changedHeads) : null;
    /* Mirror ki purani value — agar response "Pending Approval" aaye to yahin wapas
       laut jaate hain (discount abhi lagा nahi, approval ka intezaar hai). */
    const prevMirror = (discountMap[classKey] || {})[reg];

    /* Local mirror (drives the challan discount figures). */
    setDiscountMap(prev => {
      const next = { ...prev };
      next[classKey] = { ...(next[classKey] || {}) };
      next[classKey][reg] = { ...perHead };
      return next;
    });

    /* Real API: POST /api/Student/save-fee-discount — ek record per fee head. */
    const cls = classes.find(x => x.key === classKey);
    const student = (studentsMap[classKey] || []).find(x => x.reg === reg);
    const gradeId = student?.gradeID || cls?._gradeId;
    /* feeStructureID classes API se (modal heads jaisi hi source), fallback headsMap. */
    const heads = (classFeeStruct[gradeId] && classFeeStruct[gradeId].length)
      ? classFeeStruct[gradeId]
      : (headsMap[classKey] || []);
    const entries = Object.entries(perHead || {})
      .filter(([name]) => !changedSet || changedSet.has(name));
    const idMap = discountIdRef.current[String(student?.studentID)] || {};
    /* Agar koi head approval-gated nikla to uska ApprovalID/RequestNo yahan. */
    let pending = null;
    /* Jo bhi message API response me aaye (save/approval) wahi toast me dikhao. */
    let apiMessage = '';
    if (student && entries.length) {
      try {
        for (const [headName, discountAmount] of entries) {
          const head = heads.find(h => h.name === headName);
          /* Already-added discount ka { id, amt } — id se update. */
          const existing = idMap[String(head?.feeStructureID)] || {};
          const existingId = existing.id || 0;
          const num = Number(discountAmount) || 0;
          /* Sirf > 0 discount server par save/update hota hai. 0 (clear) backend par
             persist NAHI hota — backend 0 reject karta hai aur isActive:false ko ignore
             kar ke record active + purana amount rakh deta hai (koi delete endpoint nahi).
             Is liye 0 par koi call nahi bhejte; clear sirf is session ke local mirror se
             chalta hai (challan generation aur discount box dono use karte hain). */
          if (num > 0) {
            const resp = await feeService.saveFeeDiscount({
              id: existingId,
              gradeID: student.gradeID || cls?._gradeId,
              sectionID: student.sectionID || cls?._sectionId,
              headID: head?.feeStructureID,
              headName,
              discountAmount: num,
              studentID: student.studentID,
              studentName: student.name,
              isActive: true,
            });
            /* Server ka message (har head ka) — aakhri wala toast me dikhega. */
            if (resp?.message || resp?.Message) apiMessage = resp.message || resp.Message;
            /* Approval ON ho to backend save nahi karta — { PendingApproval, ApprovalID,
               RequestNo } lauta deta hai. Casing backend ke hisaab se badalti hai. */
            const d = resp?.data || resp?.Data || {};
            const isPending = d.PendingApproval ?? d.pendingApproval ?? d.isPending;
            if (isPending) {
              pending = {
                approvalId: d.ApprovalID ?? d.approvalID ?? d.approvalId ?? null,
                requestNo:  d.RequestNo ?? d.requestNo ?? '',
                message:    resp?.message || resp?.Message || 'Request sent for approval',
              };
            }
          }
        }
        if (pending) {
          /* Discount lagा nahi — mirror ko wapas purani value par le jaao. */
          setDiscountMap(prev => {
            const next = { ...prev };
            next[classKey] = { ...(next[classKey] || {}) };
            if (prevMirror === undefined) delete next[classKey][reg];
            else next[classKey][reg] = prevMirror;
            return next;
          });
          setPendingDiscounts(prev => ({
            ...prev,
            [pendKey]: { approvalId: pending.approvalId, requestNo: pending.requestNo },
          }));
          toast(pending.message, 'info');
        } else {
          /* Seedha save ho gaya — koi purani pending request thi to hata do. */
          setPendingDiscounts(prev => {
            if (!prev[pendKey]) return prev;
            const next = { ...prev }; delete next[pendKey]; return next;
          });
          toast(apiMessage || 'Discount saved', 'success');
        }
      } catch (e) {
        toast(e.message || 'Could not save discount', 'error');
      }
    } else {
      toast('Discount saved', 'success');
    }
    setDiscountCtx(null);
  };

  /* ACTION column ke "Withdraw this discount request" icon se — pending request
     wapas lene se pehle confirm modal (FeeConfirmDialog, primary/undo style). */
  const requestWithdrawDiscount = (c, s) => {
    const key = keyOf(c.key, s.reg);
    const sid = String(s.studentID);
    const aid = String(s.applicantsID);
    const pend = pendingDiscounts[key] || pendingByStudent[sid] || pendingByStudent[aid];
    if (!pend) return;
    setConfirm({
      title: 'Withdraw this request?',
      message: 'The change will not be applied.',
      confirmStyle: 'primary',
      icon: 'fa-rotate-left',
      iconBg: 'rgba(30,58,138,.1)',
      iconColor: '#1E40AF',
      confirmLabel: 'Yes, Withdraw',
      onConfirm: async () => {
        setBusyMsg('Withdrawing request…');
        try {
          if (pend.approvalId) await feeService.withdrawFeeDiscount(pend.approvalId);
          setPendingDiscounts(prev => {
            const next = { ...prev }; delete next[key]; return next;
          });
          setPendingByStudent(prev => {
            if (!prev[sid] && !prev[aid]) return prev;
            const next = { ...prev }; delete next[sid]; delete next[aid]; return next;
          });
          toast('Discount request withdrawn', 'success');
        } catch (e) {
          toast(e.message || 'Could not withdraw request', 'error');
        } finally {
          setBusyMsg('');
        }
      },
    });
  };

  /* Confirm-driven delete — DELETE /delete-challan-installment/{ledgerId}.
     README §3.3: warn when any head has receivedAmount > 0. */
  const requestDeleteClassChallans = (c) => {
    const gen = genCountFor(c.key);
    if (gen === 0) { toast('No challans to delete for this class', 'warning'); return; }
    const studs = studentsMap[c.key] || [];
    const recs = studs.map(s => challanMap[keyOf(c.key, s.reg)]).filter(Boolean);
    const hasReceived = recs.some(rec =>
      (rec.detailRows || []).some(r => (Number(r.receivedAmount) || 0) > 0),
    );
    setConfirm({
      title: 'Delete generated challans?',
      message: `All ${gen} challan${gen === 1 ? '' : 's'} for ${c.cls} (${c.sec}) in ${appliedMonth} ${appliedYear} will be removed.`,
      hint: hasReceived
        ? 'Warning: one or more challans already have received amounts. Deleting will remove those payments from the ledger. This cannot be undone.'
        : 'This action cannot be undone.',
      onConfirm: async () => {
        setBusyMsg('Deleting challans…');
        try {
          /* EK call me poori class/section ke is mahine ke challans — bulk-delete-by-class
             (pehle har challan ki alag DELETE call jaati thi). */
          const res = await feeService.bulkDeleteChallansByClass({
            gradeId: c._gradeId, sectionId: c._sectionId, month: monthIdx + 1, year: Number(appliedYear),
          });
          toast(res?.message || 'Generated challans removed', 'success');
        } catch (e) {
          toast(e.message || 'Could not delete challans', 'error');
        } finally {
          await loadChallans();
          setBusyMsg('');
        }
      },
    });
  };

  const requestDeleteStudentChallan = (c, s) => {
    const rec = challanMap[keyOf(c.key, s.reg)];
    if (challanHasReceiving(rec)) { toast(DEL_LOCKED_TIP, 'warning'); return; }
    const hasReceived = (rec?.detailRows || []).some(r => (Number(r.receivedAmount) || 0) > 0);
    setConfirm({
      title: 'Delete this challan?',
      message: `The ${appliedMonth} ${appliedYear} challan for ${s.name} will be deleted.`,
      hint: hasReceived
        ? 'Warning: this challan already has received amounts. Deleting will remove those payments from the ledger. This cannot be undone.'
        : 'This action cannot be undone.',
      onConfirm: async () => {
        if (!rec?.id) { toast('No challan found to delete', 'warning'); return; }
        setBusyMsg('Deleting challan…');
        try {
          await feeService.deleteChallanById(rec.id);
          toast(`Challan removed for ${s.name}`, 'success');
        } catch (e) {
          toast(e.message || 'Could not delete challan', 'error');
        } finally {
          await loadChallans();
          setBusyMsg('');
        }
      },
    });
  };

  /* Smart-search results — name + father + reg, ranked so an exact
     GR/registration number is always the first of the 8 rows shown. */
  const allMatches = useCallback(() => {
    if (!searchQ.trim()) return [];
    const rows = [];
    classes.forEach(c => (studentsMap[c.key] || []).forEach(s => rows.push({ c, s })));
    return rankedMatches(searchQ, rows, ({ c, s }) => ({
      ids:  [s.reg, s.adm],
      text: `${s.name} ${s.father || ''} ${c.cls} ${c.sec}`,
    }), 8);
  }, [searchQ, classes, studentsMap]);
  const matches = allMatches();

  const clearSearch = () => { setSearchQ(''); setSearchOpen(false); setHighlightKey(null); };

  const focusOnStudent = (c, s) => {
    const key = `${c.key}-${s.reg}`;
    setOpenKey(c.key);
    setSearchOpen(false);
    setHighlightKey(key);
    toast('Jumped to student', 'info');
    setTimeout(() => {
      const el = document.getElementById(`fee-st-${key}`);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 380);
  };

  return (
    <>
      {/* Filters + smart search */}
      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field">
              <span className="fee-label">Month</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={month} onChange={e => setMonth(e.target.value)}>
                  {FEE_MONTHS.map(m => <option key={m}>{m}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Year</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={year} onChange={e => setYear(e.target.value)}>
                  <option>2025</option><option>2026</option><option>2027</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <Tooltip text="Load challan data for the selected month and year">
              <button className="fee-btn fee-btn-primary" onClick={apply}>
                <i className="fa-solid fa-filter"></i> Fetch Details
              </button>
            </Tooltip>
            <Tooltip text="Reset filters and search to defaults">
              <button className="fee-btn fee-btn-ghost" onClick={resetFilters}>
                <i className="fa-solid fa-rotate-left"></i> Reset
              </button>
            </Tooltip>
          </div>

          <div className="fee-searchrow fee-searchrow--export">
            <div className="fee-field">
              <span className="fee-label">Search Student</span>
              <div className="fee-search-anchor" ref={searchAnchorRef}>
                <div className="fee-search-box">
                  <i className="fa-solid fa-magnifying-glass"></i>
                  <input
                    value={searchQ}
                    autoComplete="off"
                    onChange={e => { const v = e.target.value; setSearchQ(v); setSearchOpen(true); if (!v.trim()) setHighlightKey(null); }}
                    onFocus={() => setSearchOpen(true)}
                    placeholder="Search by Name, Father Name or Registration Number"
                  />
                  {searchQ && (
                    <Tooltip text="Clear search">
                      <button
                        type="button"
                        className="fee-search-clear"
                        onClick={clearSearch}
                        aria-label="Clear search"
                      >
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </Tooltip>
                  )}
                </div>
                <div className={`fee-search-results${searchOpen && searchQ ? ' open' : ''}`}>
                  {matches.length === 0 ? (
                    <div className="fee-sr-empty">No students found for "<b>{searchQ}</b>"</div>
                  ) : matches.map(({ c, s }) => {
                    const gen = !!genSet && genSet.has(keyOf(c.key, s.reg));
                    const initial = (s.name || '').trim()[0] || '?';
                    return (
                      <button
                        type="button"
                        key={`${c.key}-${s.reg}`}
                        className="fee-sr-item"
                        onClick={() => focusOnStudent(c, s)}
                      >
                        <div className="fee-sr-av">{initial.toUpperCase()}</div>
                        <div className="fee-sr-main">
                          <div className="fee-sr-name">
                            {s.name}
                            {gen
                              ? <span className="fee-chip fee-chip-active"><i className="fa-solid fa-circle-check"></i> Generated</span>
                              : <span className="fee-chip fee-chip-due"><i className="fa-solid fa-circle-exclamation"></i> Pending</span>}
                          </div>
                          <div className="fee-sr-meta">
                            <span><b>Father:</b> {s.father || '—'}</span>
                            <span><b>Class:</b> {c.cls}</span>
                            <span><b>Section:</b> {c.sec}</span>
                            <span><b>Reg:</b> {s.reg}</span>
                          </div>
                        </div>
                        <div className="fee-sr-go"><i className="fa-solid fa-arrow-right"></i></div>
                      </button>
                    );
                  })}
                </div>
              </div>
              <div className="fee-hint">
                <i className="fa-solid fa-circle-info"></i>
                <span>Search any student by name, father name, or registration number.</span>
              </div>
            </div>

            <div className="fee-searchrow-export">
              <Tooltip text={`Download Excel of every generated challan for the selected month (${month} ${year})`}>
                <button
                  type="button"
                  className="fee-btn fee-btn-primary fee-btn-excel"
                  onClick={handleExportExcel}
                  disabled={exportingExcel}
                  style={exportingExcel ? { opacity: .7, cursor: 'wait' } : undefined}
                >
                  <i className={`fa-solid ${exportingExcel ? 'fa-spinner fa-spin' : 'fa-file-excel'}`}></i>
                  {exportingExcel ? 'Exporting…' : 'Export Excel'}
                </button>
              </Tooltip>
            </div>
          </div>
        </div>
      </div>

      {/* Header + class table */}
      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span>
          Bulk generation will create challans for all students in this class. The
          <strong> Generated</strong> count shows how many challans are created out of total students.
        </span>
      </div>

      <div className="fee-section">
        <div className="fee-table-head fee-challan-row">
          <div className="fee-th">#</div>
          <div className="fee-th">Class</div>
          <div className="fee-th">Section</div>
          <div className="fee-th fee-center">Download</div>
          <div className="fee-th fee-center">Generated</div>
          <div className="fee-th fee-center">Bulk</div>
          <div className="fee-th fee-center">Delete</div>
          <div className="fee-th fee-center">Details</div>
        </div>

        {classesLoading ? (
          <div className="fee-empty"><i className="fa-solid fa-spinner fa-spin"></i> Loading classes…</div>
        ) : (Object.keys(studentsMap || {}).length > 0 && loadedKey !== viewKey) ? (
          <div className="fee-empty"><i className="fa-solid fa-spinner fa-spin"></i> Loading challans…</div>
        ) : classes.length === 0 ? (
          <div className="fee-empty">No classes available.</div>
        ) : classes.map((c, i) => {
          const students = studentsMap[c.key] || [];
          const isOpen = openKey === c.key;
          const gen = genCountFor(c.key);
          const total = students.length;
          const pct = total ? Math.round(gen / total * 100) : 0;
          return (
            <div key={c.key} className="fee-rowwrap">
              <div
                className={`fee-row fee-challan-row${isOpen ? ' open' : ''}`}
                onClick={() => setOpenKey(isOpen ? null : c.key)}
              >
                <div className="fee-td" data-label="#"><span className="fee-row-icon">{i + 1}</span></div>
                <div className="fee-td fee-name" data-label="Class">{c.cls}</div>
                <div className="fee-td" data-label="Section"><span className="fee-tag">{c.sec}</span></div>
                <div className="fee-td fee-center" data-label="Download" onClick={e => e.stopPropagation()}>
                  {canChDownload && (
                    <Tooltip text={`Download all generated challans for ${c.cls} (${c.sec})`}>
                      <button className="fee-iconbtn" onClick={() => openDownload({ type: 'bulk', classKey: c.key })}>
                        <i className="fa-solid fa-file-arrow-down"></i>
                      </button>
                    </Tooltip>
                  )}
                </div>
                <div className="fee-td fee-center" data-label="Generated">
                  <div className="fee-gen-block">
                    <span className="fee-count">{gen} <small>/ {total}</small></span>
                    <div className="fee-gen-bar">
                      <span style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                </div>
                <div className="fee-td fee-center" data-label="Bulk" onClick={e => e.stopPropagation()}>
                  {canChCreate && (
                    <Tooltip text={`Generate challans for all ${total} students in ${c.cls} (${c.sec})`}>
                      <button className="fee-btn fee-btn-primary fee-btn-xs" onClick={() => openBulkGen(c)}>
                        <i className="fa-solid fa-layer-group"></i> Bulk Challans
                      </button>
                    </Tooltip>
                  )}
                </div>
                <div className="fee-td fee-center" data-label="Delete" onClick={e => e.stopPropagation()}>
                  {canChDelete && (
                    <Tooltip text={gen > 0 ? `Delete all ${gen} generated challan${gen === 1 ? '' : 's'} for this class` : 'No challans to delete'}>
                      <button
                        className="fee-iconbtn danger"
                        onClick={() => requestDeleteClassChallans(c)}
                        disabled={gen === 0}
                        style={gen === 0 ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                      >
                        <i className="fa-solid fa-trash-can"></i>
                      </button>
                    </Tooltip>
                  )}
                </div>
                <div className="fee-td fee-center" data-label="Details">
                  <Tooltip text={isOpen ? 'Hide student challan list' : 'Show student challan list'}>
                    <span className={`fee-chevbtn${isOpen ? ' open' : ''}`}>
                      <i className="fa-solid fa-chevron-down fee-chev"></i>
                    </span>
                  </Tooltip>
                </div>
              </div>

              <div className={`fee-detail${isOpen ? ' open' : ''}`}>
                <div className="fee-detail-inner">
                  <div className="fee-detail-title">
                    <i className="fa-solid fa-users"></i> {appliedMonth} {appliedYear} — Challan List
                  </div>

                  <div className="fee-stbl-wrap">
                    <table className="fee-stbl">
                      <thead>
                        <tr>
                          <th>#</th>
                          <th>Reg No</th>
                          <th>Name</th>
                          <th>Father</th>
                          <th className="fee-right">Total Dues</th>
                          <th className="fee-right">Advance</th>
                          <th className="fee-right">Current Fee</th>
                          <th className="fee-right">Total Payable</th>
                          <th className="fee-center">Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {students.length === 0 ? (
                          <tr><td colSpan="9" className="fee-stbl-empty">No students in this section.</td></tr>
                        ) : students.map((s, j) => {
                          const generated = isGenerated(c.key, s.reg);
                          /* Generated → figures from the real challan detailRows;
                             otherwise fall back to the student roster values. */
                          /* Covering (Sep–Nov ka Oct) challan: generated nahi (Create khula), magar figures dikhein. */
                          const rec = generated ? challanMap[keyOf(c.key, s.reg)] : (coverMap[keyOf(c.key, s.reg)] || null);
                          /* Challan abhi nahi bana → pichhle mahino ka live baqaya dikhao
                             (roster ke stale 0 ki jagah), taake dues turant nazar aayein. */
                          const prevOut = prevOutMap[String(s.studentID)] || null;
                          /* byHead = har head ka (billed − discount − received) — yahi challan
                             Prev column use karta hai. raw previousPendingorAdv / running.dues
                             kabhi GROSS (3000) ya undercount (2000) de dete hain. */
                          const byHeadSum = prevOut && prevOut.byHead
                            ? Object.values(prevOut.byHead).reduce((a, v) => a + Math.max(0, Number(v) || 0), 0)
                            : 0;
                          const byHeadNeg = prevOut && prevOut.byHead
                            ? Object.values(prevOut.byHead).reduce((a, v) => a + Math.min(0, Number(v) || 0), 0)
                            : 0;
                          const fbDues = prevOut
                            ? (byHeadSum > 0 ? byHeadSum : (+prevOut.dues || 0))
                            : (+s.dues || 0);
                          /* byHead ho to Advance bhi usi ke negative nets se — running.advance
                             mat lo. Setup "Previous Due" partial receive ke baad running galat
                             −ve ho kar Advance column me aa jata tha; baqaya Dues me hona chahiye. */
                          const fbAdv = prevOut
                            ? (prevOut.byHead && Object.keys(prevOut.byHead).length
                                ? Math.max(0, -byHeadNeg)
                                : (+prevOut.advance || 0))
                            : (+s.advance || 0);
                          const fig = rec ? challanFigures(rec, prevOut?.byHead || null) : {
                            dues: fbDues,
                            advance: fbAdv,
                            current: +s.current || 0,
                            payable: (+s.current || 0) + fbDues - fbAdv,
                          };
                          /* Generated challan ka stored "Previous Pending" GENERATION ke
                             waqt ka snapshot hai — agar us ke baad kisi pichhle mahine ki
                             fee receive ho gayi to stale ho jaata hai. Live prevOut se
                             override (October ka 13,850 → sahi 6,850). */
                          /* Is challan par zyada wasooli (advance) — neeche ke override isay na mitayein. */
                          const overAdv = rec ? challanOverpaid(rec, prevOut?.byHead || null) : 0;
                          if (rec && challanFullyPaid(rec, prevOut?.byHead || null)) {
                            /* Poora settle — credit head (advance > fee) bhi consume ho chuka.
                               Sab 0 (Current 1,220 / Advance −1,220 ka phantom net-0 nahi).
                               Magar owed se ZYADA liya ho to wo advance (−3,500) dikhe. */
                            fig.dues = 0; fig.advance = overAdv; fig.current = 0; fig.payable = -overAdv;
                          } else if (rec && prevOut) {
                            /* prevOut.advance sirf pichhle mahino ka — is challan me consume ho
                               chuka advance ghata do (warna fully-received par −550 phantom). */
                            const consumed = advConsumedOf(rec);
                            const rows = rec.detailRows || [];
                            const hasHeadPrev = rows.some(r =>
                              !isAggregateCarryRow(r)
                              && (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0
                            );
                            /* Head-wise: previous IS challan par bill / receive ho chuka —
                               purane mahine ka byHead yahan mat chipkao (warna fully-received
                               ke baad bhi Total Dues 2500 zombie reh jata tha). */
                            if (!hasHeadPrev) {
                              fig.dues = byHeadSum > 0 ? byHeadSum : (+prevOut.dues || 0);
                            }
                            fig.advance = Math.max(0, prevOut.advance - consumed) + overAdv;
                            fig.payable = (fig.current || 0) + fig.dues - fig.advance;
                          }
                          /* Two Months+: jis month me challan bana → Current Fee;
                             dropdown se agla covered month → wahi amount Total Dues me. */
                          if (rec && isMultiMonthNonStartView(rec, monthIdx + 1, Number(appliedYear))) {
                            fig.dues = (Number(fig.dues) || 0) + (Number(fig.current) || 0);
                            fig.current = 0;
                            fig.payable = fig.current + fig.dues - (Number(fig.advance) || 0);
                          }
                          /* Total Payable = asal challan fee. PROJECTED late fine yahan
                             NAHI jodte — wo challan print/receiving par lagti hai. Sirf
                             bill ho chuki fine (jo `current` me baqaya ke taur par pehle se
                             hai) "incl. fine" note me dikhate hain. */
                          const billedFine = billedFineOf(rec) > 0 ? challanAccruedFine(rec, settings) : 0;
                          return (
                            <tr
                              key={s.reg}
                              id={`fee-st-${c.key}-${s.reg}`}
                              className={highlightKey === `${c.key}-${s.reg}` ? 'fee-st-highlight' : undefined}
                            >
                              <td className="fee-num">{j + 1}</td>
                              <td>
                                <Tooltip text={'Std_ID: ' + s.studentID}>
                                  <span>{s.reg}</span>
                                </Tooltip>
                              </td>
                              <td><b>{s.name}</b></td>
                              <td>{s.father}</td>
                              <td className="fee-right">{money(fig.dues)}</td>
                              {/* Advance student ke haq me hai → MINUS me dikhao. */}
                              <td className={`fee-right${fig.advance > 0 ? ' fee-neg' : ''}`}>
                                {money(fig.advance > 0 ? -fig.advance : 0)}
                              </td>
                              <td className="fee-right">{money(fig.current)}</td>
                              <td className={`fee-right${fig.payable < 0 ? ' fee-neg' : ''}`}>
                                {money(fig.payable)}
                                {billedFine > 0 && (
                                  <span className="fee-sub-eq fee-fine">incl. fine {money(billedFine)}</span>
                                )}
                              </td>
                              <td className="fee-center fee-st-actions">
                                {generated && settings.installmentChallan === true && (
                                  challanFullyPaid(rec) ? (
                                    <Tooltip text="Fully received">
                                      <button className="fee-iconbtn" disabled aria-disabled="true" style={{ opacity: .4, cursor: 'not-allowed' }}>
                                        <i className="fa-solid fa-money-check-dollar"></i>
                                      </button>
                                    </Tooltip>
                                  ) : (
                                    <Tooltip text={`Create installment challan for ${s.name}`}>
                                      <button className="fee-iconbtn" onClick={() => openInstallment(c, s)}>
                                        <i className="fa-solid fa-money-check-dollar"></i>
                                      </button>
                                    </Tooltip>
                                  )
                                )}
                                {generated ? (
                                  <Tooltip text={challanHasReceiving(rec) ? DEL_LOCKED_TIP : `Delete ${appliedMonth} challan for ${s.name}`}>
                                    <button
                                      className="fee-iconbtn danger"
                                      aria-disabled={challanHasReceiving(rec)}
                                      style={challanHasReceiving(rec) ? { opacity: .4, cursor: 'not-allowed' } : undefined}
                                      onClick={() => { if (!challanHasReceiving(rec)) requestDeleteStudentChallan(c, s); }}
                                    >
                                      <i className="fa-solid fa-trash-can"></i>
                                    </button>
                                  </Tooltip>
                                ) : rec ? (
                                  /* Pichhle mahine ka multi-month challan (Sep–Nov) is mahine ko cover
                                     karta hai — Delete nahi (wo September ka challan hai), sirf Regenerate. */
                                  <Tooltip text={`Regenerate ${appliedMonth} challan for ${s.name} (currently covered by ${ledgerMonthLabel(rec)} challan)`}>
                                    <button className="fee-iconbtn" style={REGEN_BTN_STYLE} onClick={() => openIndivGen(c, s)}>
                                      <i className="fa-solid fa-rotate"></i>
                                    </button>
                                  </Tooltip>
                                ) : (
                                  <Tooltip text={`Generate ${appliedMonth} challan for ${s.name}`}>
                                    <button className="fee-iconbtn green" onClick={() => openIndivGen(c, s)}>
                                      <i className="fa-solid fa-file-circle-plus"></i>
                                    </button>
                                  </Tooltip>
                                )}
                                <Tooltip text="Download this student's challan">
                                  <button
                                    className="fee-iconbtn"
                                    disabled={!generated}
                                    style={!generated ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                                    onClick={() => openDownload({ type: 'student', classKey: c.key, reg: s.reg })}
                                  >
                                    <i className="fa-solid fa-download"></i>
                                  </button>
                                </Tooltip>
                                <Tooltip text="View challan preview">
                                  <button
                                    className="fee-iconbtn"
                                    disabled={!generated}
                                    style={!generated ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                                    onClick={() => openPreview({ type: 'student', classKey: c.key, reg: s.reg })}
                                  >
                                    <i className="fa-solid fa-eye"></i>
                                  </button>
                                </Tooltip>
                                <Tooltip text="Apply student-specific fee discounts">
                                  <button className="fee-iconbtn" onClick={() => openDiscount(c, s)}>
                                    <i className="fa-solid fa-percent"></i>
                                  </button>
                                </Tooltip>
                                {(() => {
                                  /* Session (abhi save hua) ya server (approvals_by_user) — dono me se jo mile.
                                     Server match studentID YA applicantsID par (roster me id field
                                     kabhi studentID, kabhi applicantsID se aati hai). */
                                  const pend = pendingDiscounts[keyOf(c.key, s.reg)]
                                    || pendingByStudent[String(s.studentID)]
                                    || pendingByStudent[String(s.applicantsID)];
                                  if (!pend) return null;
                                  return (
                                    <>
                                      <Tooltip text={`Discount request ${pend.requestNo || ''} awaiting approval`.trim()}>
                                        <span className="fee-pending-badge" role="status">
                                          <i className="fa-solid fa-hourglass-half"></i>
                                          <span>Pending Approval</span>
                                          {pend.approvalId != null && (
                                            <b className="fee-pending-id">#{pend.approvalId}</b>
                                          )}
                                        </span>
                                      </Tooltip>
                                      <Tooltip text="Withdraw this discount request">
                                        <button
                                          className="fee-iconbtn fee-withdraw-btn"
                                          onClick={() => requestWithdrawDiscount(c, s)}
                                        >
                                          <i className="fa-solid fa-rotate-left"></i>
                                        </button>
                                      </Tooltip>
                                    </>
                                  );
                                })()}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <FeeConfirmDialog cfg={confirm} onClose={() => setConfirm(null)} />
      <FeeBusyOverlay message={busyMsg} />

      <BulkGenerateModal
        open={!!bulkGen}
        classMeta={bulkGen?.classMeta}
        students={bulkGen?.students || []}
        heads={bulkGen?.heads || []}
        defaultMonth={appliedMonth}
        defaultYear={appliedYear}
        discountMap={discountMap}
        genSet={genSet}
        keyOf={keyOf}
        onClose={() => setBulkGen(null)}
        onGenerated={handleBulkGenerated}
        toast={toast}
        singleMode={bulkGen?.mode === 'single'}
        /* Generate se pehle live saved discounts (server + session edits) resolve karo. */
        fetchDiscounts={fetchStudentDiscounts}
      />

      <ChallanPreviewModal
        cfg={challanPreview}
        onClose={() => setChallanPreview(null)}
        onDownload={() => {
          const ctx = challanPreview?.ctx;
          setChallanPreview(null);
          if (ctx) openDownload(ctx);
        }}
      />

      <DownloadPickerModal
        cfg={downloadCtx}
        onClose={() => setDownloadCtx(null)}
        onSubmit={(picks) => {
          const ctx = downloadCtx;
          setDownloadCtx(null);
          if (ctx) runDownload(ctx, picks);
        }}
      />

      <DiscountManagerModal
        cfg={discountCtx}
        onClose={() => setDiscountCtx(null)}
        onSave={saveDiscount}
        toast={toast}
      />

      <InstallmentChallanModal
        cfg={installmentCtx}
        onClose={() => setInstallmentCtx(null)}
        onCreate={createInstallmentChallan}
        toast={toast}
        defaultSize={settings.printSize || 'a4'}
      />

      {/* <DownloadPickerModal
        cfg={instPrintCtx}
        onClose={() => setInstPrintCtx(null)}
        onSubmit={(picks) => {
          const ctx = instPrintCtx;
          setInstPrintCtx(null);
          if (ctx && ctx.print) ctx.print(picks.theme === 'bw');
        }}
      /> */}
    </>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   BULK GENERATE MODAL — bulk-generates challans for every student of
   the picked class for the chosen month. Mirrors the reference HTML:
   Month + Multi-select Fee Heads + Issue/Due dates;
   then a footer "Generate Challans" CTA that swaps to an animated
   progress bar (batch increments at 55 ms intervals). At 100%, label
   flips to "Completed", a final toast fires, the modal closes.
   ═══════════════════════════════════════════════════════════════════ */
function BulkGenerateModal({
  open, classMeta, students, heads, defaultMonth, defaultYear,
  discountMap = {},
  /* Generate se THEEK PEHLE server ke saved discounts (+ is session ki edits) laata hai —
     sirf local state par bharosa karna galat discount bhej deta tha. */
  fetchDiscounts = null,
  genSet, keyOf, onClose, onGenerated, toast,
  familyMode = false, singleMode = false,
}) {
  /* Issue/Due date bhi LOCAL calendar par — challan ki due date hi late fine ka
     base hai, aur toISOString() (UTC) Pakistan me subah 5 baje se pehle dono ko
     ek din peechhe kar deta tha. */
  const todayISO = localTodayISO;
  const plusDays = (n) => {
    const d = new Date(); d.setDate(d.getDate() + n);
    return localDateISO(d);
  };

  const [month, setMonth] = useState(defaultMonth || FEE_MONTHS[0]);
  /* Challan Type — '1' = One Month (default), '2' = Two Months. Two Months par
     start/end month range bheji jaati hai; server amounts multiply karta hai
     (feeService.generateChallan → buildLedgerChallanPayload, options.type). */
  const [type, setType] = useState('1');
  const [picked, setPicked] = useState([]);      // selected fee head names
  const [msOpen, setMsOpen] = useState(false);
  const [issueDate, setIssueDate] = useState(todayISO());
  const [dueDate, setDueDate] = useState(plusDays(10));

  const [progress, setProgress] = useState(null);    // null | { done, total, label }
  const cancelRef = useRef(false);
  const msAnchorRef = useRef(null);
  /* Challan Type — custom dropdown (native <select> jagah kam ho to UPAR khulta tha);
     ye hamesha NEECHE khulta hai, lambi list scroll. */
  const [typeOpen, setTypeOpen] = useState(false);
  const typeAnchorRef = useRef(null);
  useEffect(() => {
    if (!typeOpen) return undefined;
    const onDown = (e) => { if (typeAnchorRef.current && !typeAnchorRef.current.contains(e.target)) setTypeOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') { e.stopPropagation(); setTypeOpen(false); } };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey, true);
    return () => { document.removeEventListener('mousedown', onDown); document.removeEventListener('keydown', onKey, true); };
  }, [typeOpen]);

  /* Reset state every time the modal opens. Heads ab KOI pre-selected nahi (user request) —
     user "Select Fee Heads" se khud chune kaunse heads challan me jayen; khali par validate()
     "Select at least one fee head" rok deta hai. */
  useEffect(() => {
    if (!open) return;
    cancelRef.current = false;
    setMonth(defaultMonth || FEE_MONTHS[0]);
    setType('1');
    setTypeOpen(false);
    setPicked([]);   // koi head pehle se tick nahi — user khud chune
    setMsOpen(false);
    setIssueDate(todayISO());
    setDueDate(plusDays(10));
    setProgress(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, defaultMonth]);

  /* Esc + body-scroll lock */
  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape' && !progress) onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [open, onClose, progress]);

  /* Close multi-select on outside click */
  useEffect(() => {
    if (!msOpen) return undefined;
    const onDown = (e) => {
      if (msAnchorRef.current && !msAnchorRef.current.contains(e.target)) {
        setMsOpen(false);
      }
    };
    document.addEventListener('mousedown', onDown);
    return () => document.removeEventListener('mousedown', onDown);
  }, [msOpen]);

  if (!open || !classMeta) return null;

  const toggleHead = (name) => {
    setPicked(prev => prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name]);
  };
  const headsLabel = picked.length === 0
    ? 'Select Heads'
    : `${picked.length} head${picked.length === 1 ? '' : 's'} selected`;

  const validate = () => {
    if (!heads.length) {
      toast('No fee heads are defined for this class — add them in Fee Setup first', 'error');
      return false;
    }
    /* A challan with no head picked used to silently bill every head. */
    if (!picked.length) { toast('Select at least one fee head', 'error'); return false; }
    if (!issueDate) { toast('Pick an issue date', 'error'); return false; }
    const issueChk = validateSessionDateFromStorage(issueDate, 'issue date');
    if (!issueChk.ok) { toast(issueChk.message, 'error'); return false; }
    /* Due Date sirf One Month par — Two Months+ pe field hide, validate nahi. */
    if (String(type) === '1') {
      if (!dueDate) { toast('Pick a due date', 'error'); return false; }
      if (dueDate < issueDate) {
        toast('Due date cannot be before issue date', 'error');
        return false;
      }
      const dueChk = validateSessionDateFromStorage(dueDate, 'due date');
      if (!dueChk.ok) { toast(dueChk.message, 'error'); return false; }
    }
    return true;
  };

  /* Animated batch run — Math.max(1, ceil(total/24)) per tick, 55 ms apart */
  const runBatch = () => {
    if (!validate()) return;
    const total = students.length;
    if (total === 0) { toast('No students to generate for', 'warning'); onClose(); return; }

    /* Filter out already-generated for the picked month */
    const monthIdx = FEE_MONTHS.indexOf(month);
    const targets = students.filter(s => !(genSet && genSet.has(keyOf(classMeta.key, s.reg))));
    const skipCount = total - targets.length;

    if (targets.length === 0) {
      toast(`All ${total} challan${total === 1 ? '' : 's'} are already generated for ${month}`, 'info');
      onClose();
      return;
    }

    setProgress({ done: 0, total: targets.length, label: 'Generating challans...' });

    let done = 0;
    const step = () => {
      if (cancelRef.current) return;
      const batch = Math.max(1, Math.ceil(targets.length / 24));
      for (let k = 0; k < batch && done < targets.length; k++) done++;
      setProgress({ done, total: targets.length, label: 'Generating challans...' });
      if (done < targets.length) {
        setTimeout(step, 55);
      } else {
        setProgress({ done, total: targets.length, label: 'Saving challans...' });
        const regs = targets.map(s => s.reg);
        /* validate() guarantees picked is non-empty — never fall back to all heads. */
        const selectedHeads = heads.filter(h => picked.includes(h.name));
        /* Discount hamesha LIVE lo (server ke saved + is session ki edits, jisme
           edits jeette hain). Sirf local map bhejne se purana/khaali discount
           challan me chala jata tha. */
        const resolveDiscounts = async () => {
          if (!fetchDiscounts) return discountMap;
          try { return await fetchDiscounts(classMeta, targets); }
          catch (e) { return discountMap; }
        };
        resolveDiscounts().then(dMap => feeService.generateChallan(classMeta.key, regs, monthIdx, {
          classMeta,
          students: targets,
          heads: selectedHeads,
          selectedHeadNames: picked,
          discountMap: dMap,
          issueDate,
          /* Two Months+: Due Date hide — API ko mat bhejo / khaali. */
          dueDate: String(type) === '1' ? dueDate : '',
          /* Challan Type — '2' (Two Months) → start/end month range; server
             per-month amounts ko ×2 karta hai (FE multiply nahi). */
          type,
          year: defaultYear,
          familyMode,
          singleMode,
        }).then((result) => {
          setProgress({ done, total: targets.length, label: 'Completed' });
          onGenerated(classMeta.key, regs);
          /* README §3.2 — toast: Created X, already generated Y, failed Z. */
          const created = Number(result?.created) || 0;
          const already = Number(result?.alreadyGenerated) || 0;
          const failed = Array.isArray(result?.failed) ? result.failed : [];
          const failN = failed.length;
          const parts = [];
          if (created > 0) parts.push(`Created ${created}`);
          if (already > 0) parts.push(`already generated ${already}`);
          if (failN > 0) parts.push(`failed ${failN}`);
          if (skipCount > 0 && already === 0) parts.push(`${skipCount} skipped — already existed`);
          const msg = parts.length
            ? parts.join(', ')
            : 'No challans generated';
          const kind = failN > 0 && created === 0 && already === 0 ? 'error'
            : failN > 0 ? 'warning'
            : 'success';
          toast(msg, kind);
          if (failN > 0 && failed[0]?.message) {
            toast(failed.slice(0, 3).map(f => `${f.student || 'Student'}: ${f.message}`).join(' · '), 'warning');
          }
          setTimeout(onClose, 500);
        }).catch((err) => {
          setProgress(null);
          toast(err.message || 'Could not generate challans', 'error');
        }));
      }
    };
    setTimeout(step, 150);
  };

  const requestClose = () => {
    if (progress && progress.done < progress.total) {
      cancelRef.current = true;
    }
    onClose();
  };

  const pct = progress ? Math.round(progress.done / progress.total * 100) : 0;

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget && !progress) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon">
              <i className={`fa-solid ${familyMode && !singleMode ? 'fa-people-roof' : 'fa-file-circle-plus'}`}></i>
            </div>
            <div>
              <div className="fee-modal-title">
                {singleMode
                  ? (familyMode ? 'Generate Family Challan' : 'Generate Challan')
                  : familyMode ? 'Generate Family Challans' : 'Generate Bulk Challans'}
              </div>
              <div className="fee-modal-sub">
                {singleMode
                  ? `${students[0]?.name} · child of ${students[0]?.father || '—'}`
                  : familyMode
                    ? `${classMeta.cls} — ${classMeta.sec} · ${students.length} child${students.length === 1 ? '' : 'ren'}`
                    : `${classMeta.cls} — Section ${classMeta.sec} · ${students.length} student${students.length === 1 ? '' : 's'}`}
              </div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={requestClose} disabled={!!(progress && progress.done < progress.total)} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          {singleMode && students[0] && (() => {
            const s = students[0];
            const pending = (+s.current || 0) - (+s.dues || 0) - (+s.advance || 0);
            const totalHeads = heads.reduce((a, h) => a + (+h.amt || 0), 0);
            /* In family mode the heads carry no amount — show the child's
               rolled-up Total Fee (passed via s.current) as the "Standard
               Fee" line instead, so the card reflects what's billable. */
            const standard = familyMode ? (+s.current || 0) : totalHeads;
            const initials = (s.name || '?').trim().split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase() || '?';
            return (
              <div className="fee-stud-card">
                <div className="fee-stud-logo">{initials}</div>
                <div className="fee-stud-meta">
                  <div><b>Name</b> {s.name}</div>
                  <div><b>Father Name</b> {s.father || '—'}</div>
                  <div><b>Class</b> {classMeta.cls} ({classMeta.sec})</div>
                  <div><b>Reg No</b> {s.reg}</div>
                  {familyMode && classMeta.familyName && (
                    <div><b>Family</b> {classMeta.familyName} — {classMeta.guardian}</div>
                  )}
                  <div>
                    <b>Pending Amount</b>
                    {' '}
                    <span className={pending < 0 ? 'fee-neg' : ''}>{money(pending)}</span>
                  </div>
                  <div><b>{familyMode ? 'Total Fee' : 'Standard Fee'}</b> {money(standard)}</div>
                </div>
              </div>
            );
          })()}

          <div className="fee-filters" style={{ alignItems: 'flex-start', marginTop: singleMode ? 18 : 0 }}>
            <div className="fee-field">
              <span className="fee-label">Month</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={month} onChange={e => setMonth(e.target.value)} disabled={!!progress}>
                  {FEE_MONTHS.map(m => <option key={m}>{m}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Challan Type</span>
              {/* 1 se 12 mahine tak — server amounts ko months se multiply karta hai. List hamesha
                  NEECHE khulti hai (fee-ms menu: top 100%, max-height + scroll). */}
              <div className={`fee-ms${typeOpen ? ' open' : ''}`} ref={typeAnchorRef} style={{ minWidth: 170 }}>
                <button
                  type="button"
                  id="gen-challan-type"
                  className="fee-ms-toggle"
                  aria-haspopup="listbox"
                  aria-expanded={typeOpen}
                  onClick={() => !progress && setTypeOpen(o => !o)}
                  disabled={!!progress}
                >
                  <span>{CHALLAN_TYPE_LABELS[(Number(type) || 1) - 1]}</span>
                  <i className="fa-solid fa-chevron-down"></i>
                </button>
                {typeOpen && (
                  <div className="fee-ms-menu" role="listbox" style={{ minWidth: 0 }}>
                    {CHALLAN_TYPE_LABELS.map((lbl, i) => {
                      const v = String(i + 1);
                      return (
                        <button
                          type="button"
                          key={v}
                          role="option"
                          aria-selected={type === v}
                          className={`fee-ms-opt${type === v ? ' sel' : ''}`}
                          style={type === v ? { background: 'var(--bg-muted)', color: '#1E3A8A' } : undefined}
                          onClick={() => { setType(v); setTypeOpen(false); }}
                        >
                          {lbl}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
            <div className="fee-field fee-field--grow">
              <span className="fee-label">Select Fee Heads</span>
              <div
                className={`fee-ms${msOpen ? ' open' : ''}`}
                ref={msAnchorRef}
              >
                <button
                  type="button"
                  className="fee-ms-toggle"
                  onClick={() => !progress && setMsOpen(o => !o)}
                  disabled={!!progress}
                >
                  <span>{headsLabel}</span>
                  <i className="fa-solid fa-chevron-down"></i>
                </button>
                {msOpen && (
                  <div className="fee-ms-menu">
                    {heads.length === 0 ? (
                      <div className="fee-ms-empty">No fee heads configured for this class.</div>
                    ) : heads.map(h => {
                      const sel = picked.includes(h.name);
                      const hasAmt = h.amt !== undefined && h.amt !== null;
                      return (
                        <button
                          type="button"
                          key={h.name}
                          className={`fee-ms-opt${sel ? ' sel' : ''}`}
                          onClick={() => toggleHead(h.name)}
                        >
                          <span className="fee-ms-check"><i className="fa-solid fa-check"></i></span>
                          <span className="fee-ms-name">{h.name}</span>
                          {hasAmt && <span className="fee-ms-amt">{money(h.amt)}</span>}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="fee-filters" style={{ marginTop: 14 }}>
            <div className="fee-field fee-field--grow">
              <span className="fee-label">Issue Date</span>
              <input
                className="fee-input"
                type="date"
                value={issueDate}
                /* One Month: due se aage nahi; multi-month: koi max nahi. */
                max={String(type) === '1' ? (dueDate || undefined) : undefined}
                onChange={e => setIssueDate(e.target.value)}
                disabled={!!progress}
              />
            </div>
            {String(type) === '1' && (
              <div className="fee-field fee-field--grow">
                <span className="fee-label">Due Date</span>
                <input
                  className="fee-input"
                  type="date"
                  value={dueDate}
                  min={issueDate || undefined}
                  onChange={e => setDueDate(e.target.value)}
                  disabled={!!progress}
                />
              </div>
            )}
          </div>

          <div className="fee-info" style={{ marginTop: 16, marginBottom: 0 }}>
            <i className="fa-solid fa-circle-info"></i>
            <span>
              {familyMode
                ? <>Combined family challan pulls each child's <strong>fee + transport − discount</strong> from the family roster automatically.</>
                : <>Fee heads are loaded from the class fee structure. <strong>Select the fee heads</strong> to include in this challan — at least one is required.</>}
            </span>
          </div>

          {progress && (
            <div className="fee-gen-progress">
              <div className="fee-prog-label">
                <span>{progress.label}</span>
                <span>{progress.done} / {progress.total}</span>
              </div>
              <div className="fee-prog-track">
                <div
                  className={`fee-prog-fill${progress.label === 'Completed' ? ' done' : ''}`}
                  style={{ width: `${pct}%` }}
                />
              </div>
            </div>
          )}
        </div>

        {!progress && (
          <div className="fee-modal-foot">
            <Tooltip text="Close without generating">
              <button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button>
            </Tooltip>
            <Tooltip text={singleMode
              ? `Generate challan for ${students[0]?.name}`
              : `Generate challans for ${students.length} student${students.length === 1 ? '' : 's'}`}
            >
              <button className="fee-btn fee-btn-primary" onClick={runBatch}>
                <i className="fa-solid fa-bolt"></i> {singleMode ? 'Generate Challan' : 'Generate Challans'}
              </button>
            </Tooltip>
          </div>
        )}

        {progress && progress.label === 'Completed' && (
          <div className="fee-modal-foot">
            <Tooltip text="Close">
              <button className="fee-btn fee-btn-primary" onClick={onClose}>
                <i className="fa-solid fa-check"></i> Done
              </button>
            </Tooltip>
          </div>
        )}
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   CHALLAN PREVIEW MODAL — fee-modal.lg with the 3-copy challan
   rendered inline (scoped CSS). Footer: Close + Download (jumps to
   the Download picker, preserving the challan context).
   ═══════════════════════════════════════════════════════════════════ */
function ChallanPreviewModal({ cfg, onClose, onDownload }) {
  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal lg">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon"><i className="fa-solid fa-eye"></i></div>
            <div>
              <div className="fee-modal-title">{cfg.title}</div>
              <div className="fee-modal-sub">{cfg.sub}</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body fee-preview-body">
          <style>{FEE_CHALLAN_CSS_SCOPED}</style>
          <div dangerouslySetInnerHTML={{ __html: cfg.innerHtml }} />
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Close preview">
            <button className="fee-btn fee-btn-ghost" onClick={onClose}>Close</button>
          </Tooltip>
          <Tooltip text="Pick theme &amp; format and download">
            <button className="fee-btn fee-btn-primary" onClick={onDownload}>
              <i className="fa-solid fa-download"></i> Download
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   DOWNLOAD PICKER MODAL — choose Color/B&W theme + PDF/Word format,
   then trigger the actual print/download via the parent's onSubmit.
   ═══════════════════════════════════════════════════════════════════ */
function DownloadPickerModal({ cfg, onClose, onSubmit }) {
  const [theme, setTheme] = useState('color');
  const [fmt, setFmt] = useState('pdf');
  const [size, setSize] = useState('a4');

  useEffect(() => {
    if (!cfg) return;
    setTheme('color'); setFmt('pdf');
    setSize(cfg.defaultSize || 'a4');
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  /* Keyboard nav for the radio-style picker cards (matches Modules 2–6). */
  const onThemeKey = (e, value) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); setTheme('color'); }
    else if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); setTheme('bw'); }
    /* Space/Enter handled natively because the cards are real <button>s. */
  };

  return createPortal(
    <div
      className="fee-overlay open"
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="fee-dl-title"
    >
      <div className="fee-modal sm">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon"><i className="fa-solid fa-download"></i></div>
            <div>
              <div className="fee-modal-title" id="fee-dl-title">Download Challan</div>
              <div className="fee-modal-sub">{cfg.sub || 'Choose a report theme & format'}</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close download dialog">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-dl-label" id="fee-dl-theme-lbl">Report Theme</div>
          <div className="fee-dl-grid" role="radiogroup" aria-labelledby="fee-dl-theme-lbl">
            <button
              type="button"
              className={`fee-dl-card${theme === 'color' ? ' sel' : ''}`}
              onClick={() => setTheme('color')}
              role="radio"
              aria-checked={theme === 'color'}
              tabIndex={theme === 'color' ? 0 : -1}
              onKeyDown={(e) => onThemeKey(e, 'color')}
            >
              <div className="fee-dl-prev fee-dl-prev--color" aria-hidden="true">
                <span className="fee-dl-orb"></span>
                <span className="fee-dl-line lg"></span>
                <span className="fee-dl-line md"></span>
                <div className="fee-dl-pills">
                  <span className="fee-dl-pill blue"></span>
                  <span className="fee-dl-pill amber"></span>
                </div>
              </div>
              <div className="fee-dl-meta">
                <div className="fee-dl-name"><i className="fa-solid fa-palette" style={{ color: '#1E3A8A', marginRight: 6 }} aria-hidden="true"></i>Colorful Report</div>
                <div className="fee-dl-desc">Brand-colour challan with summary highlights</div>
              </div>
            </button>
            <button
              type="button"
              className={`fee-dl-card${theme === 'bw' ? ' sel' : ''}`}
              onClick={() => setTheme('bw')}
              role="radio"
              aria-checked={theme === 'bw'}
              tabIndex={theme === 'bw' ? 0 : -1}
              onKeyDown={(e) => onThemeKey(e, 'bw')}
            >
              <div className="fee-dl-prev fee-dl-prev--bw" aria-hidden="true">
                <span className="fee-dl-orb bw"></span>
                <span className="fee-dl-line lg bw"></span>
                <span className="fee-dl-line md bw"></span>
                <div className="fee-dl-pills">
                  <span className="fee-dl-pill bw"></span>
                  <span className="fee-dl-pill bw"></span>
                </div>
              </div>
              <div className="fee-dl-meta">
                <div className="fee-dl-name"><i className="fa-solid fa-circle-half-stroke" style={{ color: '#374151', marginRight: 6 }} aria-hidden="true"></i>Colorless Report</div>
                <div className="fee-dl-desc">Low-ink layout — white bg, light borders only</div>
              </div>
            </button>
          </div>

          {(!cfg.themeOnly || cfg.askSize) && (<>
          <div className="fee-dl-label" style={{ marginTop: 18 }}>Paper Size</div>
          <div className="fee-dl-fmt-grid">
            <button
              type="button"
              className={`fee-dl-fmt${size === 'a4' ? ' sel' : ''}`}
              onClick={() => setSize('a4')}
            >
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(30,58,138,.1)', color: '#1E3A8A' }}>
                <i className="fa-solid fa-file-lines"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">A4 Size</div>
                <div className="fee-dl-desc">Full page · 3-copy challan</div>
              </div>
            </button>
            <button
              type="button"
              className={`fee-dl-fmt${size === 'thermal' ? ' sel' : ''}`}
              onClick={() => setSize('thermal')}
            >
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(22,163,74,.1)', color: '#16A34A' }}>
                <i className="fa-solid fa-receipt"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">Thermal</div>
                <div className="fee-dl-desc">80mm receipt printer</div>
              </div>
            </button>
          </div>
          </>)}

          {!cfg.themeOnly && (<>
          <div className="fee-dl-label" style={{ marginTop: 18 }}>Report Format</div>
          <div className="fee-dl-fmt-grid">
            <button
              type="button"
              className={`fee-dl-fmt${fmt === 'pdf' ? ' sel' : ''}`}
              onClick={() => setFmt('pdf')}
            >
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(220,38,38,.1)', color: '#DC2626' }}>
                <i className="fa-solid fa-file-pdf"></i>
              </div>
              <div className="fee-dl-fmt-name">PDF</div>
            </button>
            <button
              type="button"
              className={`fee-dl-fmt${fmt === 'word' ? ' sel' : ''}`}
              onClick={() => setFmt('word')}
            >
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(2,132,199,.1)', color: '#0284C7' }}>
                <i className="fa-solid fa-file-word"></i>
              </div>
                      <div className="fee-dl-fmt-name">Word (.docx)</div>
            </button>
          </div>
          </>)}
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard and close">
            <button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button>
          </Tooltip>
          <Tooltip text={cfg.themeOnly
            ? `Generate ${cfg.askSize ? `${size === 'thermal' ? 'Thermal 80mm' : 'A4'} · ` : ''}${theme === 'bw' ? 'Colorless' : 'Colorful'} installment challan`
            : `Generate ${size === 'thermal' ? 'Thermal 80mm' : 'A4'} · ${theme === 'bw' ? 'Colorless' : 'Colorful'} ${fmt === 'word' ? 'Word' : 'PDF'} report`}>
            <button className="fee-btn fee-btn-primary" onClick={() => onSubmit({ theme, fmt, size })}>              <i className="fa-solid fa-file-arrow-down"></i> Generate Report
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   DISCOUNT MANAGER MODAL — per-student per-head discount editor.
   Each row: Fee Head | Standard Fee | Discount input | Net Payable.
   Discount is clamped to standard fee; totals recompute live.
   ═══════════════════════════════════════════════════════════════════ */
function DiscountManagerModal({ cfg, onClose, onSave, toast }) {
  const [discs, setDiscs] = useState({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!cfg) return;
    /* Initialise from existing saved discount (if any) */
    const init = {};
    cfg.heads.forEach(h => {
      init[h.name] = Number((cfg.initial || {})[h.name]) || 0;
    });
    setDiscs(init);
    setSaving(false);
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const setOne = (name, val, max) => {
    const v = Math.max(0, Math.min(Number(val) || 0, max));
    setDiscs(prev => ({ ...prev, [name]: v }));
  };

  let totalStd = 0, totalDisc = 0;
  const rows = cfg.heads.map(h => {
    const std = +h.amt || 0;
    const disc = Math.min(+discs[h.name] || 0, std);
    totalStd += std;
    totalDisc += disc;
    return { ...h, std, disc, net: std - disc };
  });
  const totalNet = totalStd - totalDisc;

  /* onSave posts one /api/Student/save-fee-discount per CHANGED head and closes the
     modal itself, so hold the spinner until it resolves. */
  const handleSave = async () => {
    if (saving) return;
    /* perHead = PURA state (local mirror/challan figures ke liye — sab heads).
       changed = sirf wahi heads jinki value modal khulne wali (initial) value se
       alag hai. Server par SIRF changed heads jaate hain — jo head user ne na add
       kiya na change kiya uska dobara save-fee-discount NAHI chalta. Clear (saved
       discount → 0) bhi ek change hai, is liye wo bhi bhejta hai. */
    const perHead = {};
    const changed = [];
    rows.forEach(r => {
      perHead[r.name] = r.disc;
      const initial = Number((cfg.initial || {})[r.name]) || 0;
      if (r.disc !== initial) changed.push(r.name);
    });
    if (!changed.length) { toast('No changes to save', 'info'); onClose(); return; }
    try {
      setSaving(true);
      await onSave(cfg.classMeta.key, cfg.student.reg, perHead, changed);
    } finally {
      setSaving(false);
    }
  };

  const handleClear = () => {
    const next = {};
    cfg.heads.forEach(h => { next[h.name] = 0; });
    setDiscs(next);
    toast('Discount cleared — click Save to persist', 'info');
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#0F766E,#0D9488)' }}>
              <i className="fa-solid fa-percent"></i>
            </div>
            <div>
              <div className="fee-modal-title">Discount Manager</div>
              <div className="fee-modal-sub">
                {cfg.student.name} S/O {cfg.student.father || '—'} — {cfg.classMeta.cls} ({cfg.classMeta.sec})
              </div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-info">
            <i className="fa-solid fa-circle-info"></i>
            <span>
              Enter a discount per fee head. Net Payable recalculates automatically.
              This is a <strong>student-specific</strong> adjustment.
            </span>
          </div>

          <div className="fee-stbl-wrap" style={{ border: 'none', marginTop: 14 }}>
            <table className="fee-dm-table">
              <thead>
                <tr>
                  <th>Fee Head</th>
                  <th className="fee-right">Standard Fee</th>
                  <th className="fee-right">Discount</th>
                  <th className="fee-right">Net Payable</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(r => (
                  <tr key={r.name}>
                    <td><b>{r.name}</b></td>
                    <td className="fee-right">{money(r.std)}</td>
                    <td className="fee-right">
                      <input
                        type="number"
                        min="0"
                        max={r.std}
                        /* 0 ki jagah field khaali dikhe (0 internally hi rehta hai). */
                        value={discs[r.name] || ''}
                        onChange={e => setOne(r.name, e.target.value, r.std)}
                      />
                    </td>
                    <td className="fee-right fee-dm-net">{money(r.net)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="fee-dm-total-row">
                  <td>Total</td>
                  <td className="fee-right">{money(totalStd)}</td>
                  <td className="fee-right">{money(totalDisc)}</td>
                  <td className="fee-right fee-dm-net">{money(totalNet)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Reset all discount inputs to zero">
            <button className="fee-btn fee-btn-ghost" onClick={handleClear} disabled={saving}>
              <i className="fa-solid fa-rotate-left"></i> Clear
            </button>
          </Tooltip>
          <Tooltip text="Discard changes and close">
            <button className="fee-btn fee-btn-ghost" onClick={onClose} disabled={saving}>Cancel</button>
          </Tooltip>
          <Tooltip text="Save discount for this student">
            <button
              className="fee-btn fee-btn-primary"
              onClick={handleSave}
              disabled={saving}
              style={saving ? { opacity: .7, cursor: 'wait' } : undefined}
            >
              {saving
                ? <><i className="fa-solid fa-spinner fa-spin"></i> Saving…</>
                : <><i className="fa-solid fa-floppy-disk"></i> Save Discount</>}
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   INSTALLMENT CHALLAN MODAL — each fee head has its own installment
   amount. Cap is that head's After Discount (unpaid challan after
   discount, plus head-wise previous still left). Create posts
   generate-psid for the sum, then prints each typed amount.
   ═══════════════════════════════════════════════════════════════════ */
function InstallmentChallanModal({ cfg, onClose, onCreate, toast, defaultSize = 'a4' }) {
  const [amounts, setAmounts] = useState({});
  const [creating, setCreating] = useState(false);

    /* Create Installment dabane par pehle Colorful / Colorless poocho */
  const [askTheme, setAskTheme] = useState(false);

  useEffect(() => {
    if (!cfg) return;
    setAmounts({});
    setCreating(false);
    setAskTheme(false);
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape' && !creating && !askTheme) onClose(); };
        window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [cfg, onClose, creating, askTheme]);

  if (!cfg) return null;

  const { classMeta, student, heads } = cfg;
  const rows = heads.map(h => {
    const amt = Math.max(0, Math.round(Number(amounts[h.name]) || 0));
    return { ...h, amt, over: amt > h.afterDiscount };
  });
  const overHead = rows.find(h => h.over) || null;
  const totalChallan = rows.reduce((a, h) => a + h.challanAmount, 0);
  const totalDiscount = rows.reduce((a, h) => a + h.discount, 0);
  const totalPrev = rows.reduce((a, h) => a + (h.prev || 0), 0);
  const totalAfter = rows.reduce((a, h) => a + h.afterDiscount, 0);
  const totalInstallment = rows.reduce((a, h) => a + h.amt, 0);
  const invalid = totalInstallment <= 0 || !!overHead;

  const handleCreate = async () => {
    if (creating) return;
    if (totalInstallment <= 0) { toast('Enter an installment amount on at least one fee head', 'warning'); return; }
    if (overHead) {
      toast(`Installment cannot exceed “${overHead.name}” after-discount amount (${money(overHead.afterDiscount)})`, 'error');
      return;
    }
    setAskTheme(true);   // pehle Colorful / Colorless picker
  };

  const runCreate = async (bw, size) => {
    setAskTheme(false);
    try {
      setCreating(true);
      const perHead = {};
      rows.forEach(h => { if (h.amt > 0) perHead[h.name] = h.amt; });
      await onCreate(cfg, perHead, bw, size === 'thermal' ? 'thermal' : 'a4');
    } catch (e) {
      toast(e.message || 'Could not create installment challan', 'error');
      setCreating(false);
    }
  };
  return createPortal(
     <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget && !creating) onClose(); }}>
      <DownloadPickerModal
        cfg={askTheme ? { sub: `${student.name} · Installment challan`, themeOnly: true, askSize: true, defaultSize } : null}
        onClose={() => setAskTheme(false)}
        onSubmit={(picks) => runCreate(picks.theme === 'bw', picks.size)}
      />
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#1D4ED8,#3B82F6)' }}>
              <i className="fa-solid fa-money-check-dollar"></i>
            </div>
            <div>
              <div className="fee-modal-title">Installment Challan</div>
              <div className="fee-modal-sub">
                {student.name} S/O {student.father || '—'} — {classMeta.cls} ({classMeta.sec}) · Reg {student.reg}
              </div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close" disabled={creating}>
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-info">
            <i className="fa-solid fa-circle-info"></i>
            <span>
              Enter an <strong>installment amount</strong> on any fee head. Each head can
              have its own amount. Amounts already received are taken off.
              Each amount must be at most that head's <strong>after-discount</strong> balance
              (after-discount already includes the previous still left).
            </span>
          </div>

          <div className="fee-stbl-wrap" style={{ border: 'none', marginTop: 14 }}>
            <table className="fee-dm-table">
              <thead>
                <tr>
                  <th>Fee Head</th>
                  <th className="fee-right">Previous Amount</th>
                  <th className="fee-right">Challan Amount</th>
                  <th className="fee-right">Discount</th>
                  <th className="fee-right">After Discount</th>
                  <th className="fee-right">Installment Amount</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(h => (
                    <tr key={h.name}>
                      <td><b>{h.name}</b></td>
                      <td className="fee-right">{h.prev ? money(h.prev) : '—'}</td>
                      <td className="fee-right">{h.challanAmount ? money(h.challanAmount) : '—'}</td>
                      <td className="fee-right">{h.discount ? money(h.discount) : '—'}</td>
                      <td className="fee-right">{money(h.afterDiscount)}</td>
                      <td className="fee-right">
                        <input
                          type="number"
                          min="0"
                          max={h.afterDiscount}
                          value={amounts[h.name] ?? ''}
                          onChange={e => setAmounts(prev => ({ ...prev, [h.name]: e.target.value }))}
                          style={h.over ? { borderColor: '#DC2626', color: '#DC2626' } : undefined}
                        />
                      </td>
                    </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="fee-dm-total-row">
                  <td>Total</td>
                  <td className="fee-right">{money(totalPrev)}</td>
                  <td className="fee-right">{money(totalChallan)}</td>
                  <td className="fee-right">{money(totalDiscount)}</td>
                  <td className="fee-right">{money(totalAfter)}</td>
                  <td className="fee-right fee-dm-net">{money(totalInstallment)}</td>
                </tr>
              </tfoot>
            </table>
          </div>

          {overHead && (
            <div className="fee-info" style={{ marginTop: 12, background: '#FEF2F2', color: '#B91C1C' }}>
              <i className="fa-solid fa-triangle-exclamation"></i>
              <span>
                “{overHead.name}” cannot exceed its after-discount amount ({money(overHead.afterDiscount)}).
              </span>
            </div>
          )}
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard and close">
            <button className="fee-btn fee-btn-ghost" onClick={onClose} disabled={creating}>Cancel</button>
          </Tooltip>
          <Tooltip text="Create the installment challan">
            <button
              className="fee-btn fee-btn-primary"
              onClick={handleCreate}
              disabled={creating || invalid}
              style={(creating || invalid) ? { opacity: .7, cursor: creating ? 'wait' : 'not-allowed' } : undefined}
            >
              {creating
                ? <><i className="fa-solid fa-spinner fa-spin"></i> Creating…</>
                : <><i className="fa-solid fa-file-circle-plus"></i> Create Installment</>}
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   EDIT INSTALLMENT MODAL — re-allocate ONE already-saved installment's
   per-head Received (and per-head Give Discount) WITHOUT touching the
   sibling installments of the same challan. Ported from the sibling
   front-end's EditPaymentModal; the ERP stores receiving-time discount
   as `giveDisc` (not `discPerHead`), so this reads/writes `giveDisc`.

   PERSISTENCE NOTE: the ERP's installments are session-state today
   (getReceipts() is a mock / returns []), so this SAVE updates the
   in-session receipts list only — the edit survives within the session
   but is lost on refresh. Real cross-refresh edit needs a backend
   "update-installment" API; the onSave handler below calls an OPTIONAL,
   guarded feeService.editInstallment(...) that is a no-op until such an
   endpoint exists. This is ADD-only UI: it never touches the
   generate/receive SAVE math (challanFigures/perHead/fine/receivePayment).
   ═══════════════════════════════════════════════════════════════════ */
function EditPaymentModal({ cfg, onClose, onSave, toast }) {
  const [date, setDate]     = useState('');
  const [method, setMethod] = useState('Cash');
  const [ref, setRef]       = useState('');
  const [remarks, setRemarks] = useState('');
  const [perHeadEdit, setPerHeadEdit] = useState({});
  const [discPerHeadEdit, setDiscPerHeadEdit] = useState({});

  useEffect(() => {
    if (!cfg) return;
    const p = cfg.payment;
    setDate(p.date || ''); setMethod(p.method || 'Cash');
    setRef(p.ref || p.txn || ''); setRemarks(p.remarks || '');
    const perSeed = {}, discSeed = {};
    (cfg.heads || []).forEach(h => {
      perSeed[h.name]  = +(p.perHead?.[h.name]) || 0;
      /* ERP stores per-head receiving-time discount under `giveDisc`. */
      discSeed[h.name] = +(p.giveDisc?.[h.name]) || 0;
    });
    setPerHeadEdit(perSeed);
    setDiscPerHeadEdit(discSeed);
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const { heads = [], payments = [], payment } = cfg;

  /* Per head: what every OTHER installment already received/discounted
     (this installment's own original contribution is excluded so it
     isn't double-subtracted while the user is actively editing it). */
  const rows = heads.map(h => {
    const otherReceived = payments.filter(p => p.id !== payment.id).reduce((a, p) => a + (+(p.perHead?.[h.name]) || 0), 0);
    const otherDiscount = payments.filter(p => p.id !== payment.id).reduce((a, p) => a + (+(p.giveDisc?.[h.name]) || 0), 0);
    const original       = h.net;
    const availableForThis = Math.max(0, original - otherReceived - otherDiscount);
    const receivedNow    = Math.max(0, +perHeadEdit[h.name] || 0);
    const discNow        = Math.max(0, Math.min(+discPerHeadEdit[h.name] || 0, availableForThis));
    return { name: h.name, original, otherReceived, otherDiscount, availableForThis, receivedNow, discNow };
  });
  const totalReceivedNow = rows.reduce((a, r) => a + r.receivedNow, 0);
  const totalDiscNow     = rows.reduce((a, r) => a + r.discNow, 0);

  const setReceived = (name, v) => setPerHeadEdit(prev => ({ ...prev, [name]: Math.max(0, Number(v) || 0) }));
  const setDisc     = (name, v) => setDiscPerHeadEdit(prev => ({ ...prev, [name]: Math.max(0, Number(v) || 0) }));

  const save = () => {
    if (!date) { toast('Paid date is required', 'error'); return; }
    if (totalReceivedNow <= 0) { toast('Received amount must be greater than 0', 'error'); return; }
    const perHead = {}, giveDisc = {};
    rows.forEach(r => {
      if (r.receivedNow > 0) perHead[r.name] = r.receivedNow;
      if (r.discNow > 0) giveDisc[r.name] = r.discNow;
    });
    const isReceiving = Object.keys(giveDisc).length > 0;
    onSave({ date, amount: totalReceivedNow, method, ref, remarks, perHead, giveDisc, isReceiving });
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal xl">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon"><i className="fa-solid fa-pen"></i></div>
            <div>
              <div className="fee-modal-title">Edit Installment</div>
              <div className="fee-modal-sub">{cfg.student?.name} · {cfg.period}</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button>
          </Tooltip>
        </div>
        <div className="fee-modal-body">
          {/* Subtle note: this edit lives in the session only until a backend
              update-installment API exists (see component header comment). */}
          <div className="fee-recv-note" style={{ marginBottom: 12, fontSize: 12, opacity: .8 }}>
            <i className="fa-solid fa-circle-info"></i> Re-allocates this installment only. Changes apply to the current session; persistent (cross-refresh) edit needs a backend update-installment API.
          </div>
          <div className="fee-recv-meta">
            <div className="fee-field">
              <span className="fee-label">Paid Date</span>
              <input className="fee-input" type="date" value={date} onChange={e => setDate(e.target.value)} />
            </div>
            <div className="fee-field">
              <span className="fee-label">Payment Method</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={method} onChange={e => setMethod(e.target.value)}>
                  <option>Cash</option>
                  <option>Bank Transfer</option>
                  <option>Cheque</option>
                  <option>Card</option>
                  <option>Online / App</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Reference #</span>
              <input className="fee-input" value={ref} onChange={e => setRef(e.target.value)} placeholder="Optional" />
            </div>
            {/* Remarks — backend not ready (README §10); hide until API stores it.
            <div className="fee-field">
              <span className="fee-label">Remarks</span>
              <input className="fee-input" value={remarks} onChange={e => setRemarks(e.target.value)} placeholder="Optional" />
            </div>
            */}
          </div>

          <div className="fee-stbl-wrap">
            <table className="fee-stbl fee-recv-table flow">
              <thead>
                <tr>
                  <th className="flow-head-col">Fee Head</th>
                  <th className="fee-right">Original Amount</th>
                  <th className="fee-right">Received by Other Installments</th>
                  <th className="fee-center">Edit Received Amount</th>
                  <th className="fee-center">Edit Discount</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(r => (
                  <tr key={r.name}>
                    <td className="flow-head-col"><b>{r.name}</b></td>
                    <td className="fee-right">{money(r.original)}</td>
                    <td className="fee-right">
                      {r.otherReceived > 0 ? <span className="fee-paid-amt">{money(r.otherReceived)}</span> : money(0)}
                      {r.otherDiscount > 0 && <span className="fee-sub-eq">disc {money(r.otherDiscount)}</span>}
                    </td>
                    <td className="fee-center">
                      <input
                        className="flow-input flow-input--pay"
                        type="number" min="0"
                        value={perHeadEdit[r.name] === 0 ? 0 : (perHeadEdit[r.name] || '')}
                        onChange={e => setReceived(r.name, e.target.value)}
                        placeholder="0"
                      />
                    </td>
                    <td className="fee-center">
                      <input
                        className="flow-input flow-input--disc"
                        type="number" min="0" max={r.availableForThis}
                        value={discPerHeadEdit[r.name] === 0 ? 0 : (discPerHeadEdit[r.name] || '')}
                        onChange={e => setDisc(r.name, e.target.value)}
                        placeholder="0"
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="fee-recv-total">
                  <td className="flow-head-col">Total</td>
                  <td className="fee-right">{money(rows.reduce((a, r) => a + r.original, 0))}</td>
                  <td className="fee-right">{money(rows.reduce((a, r) => a + r.otherReceived, 0))}</td>
                  <td className="fee-center">{money(totalReceivedNow)}</td>
                  <td className="fee-center">{money(totalDiscNow)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
        <div className="fee-modal-foot">
          <Tooltip text="Discard changes"><button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button></Tooltip>
          <Tooltip text="Save changes to this installment">
            <button className="fee-btn fee-btn-primary" onClick={save}><i className="fa-solid fa-check"></i> Save Changes</button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   FEE RECEIVING MODAL — record a payment against a generated challan.
   Meta inputs (Custom Ref / Date / Method / Txn#), info strip (Fine,
   Due Date, Fine After Due, Discount), per-head editable Received
   column with live total recompute, pay strip (Total / Already Paid
   / Receiving Now / Remaining After), payment history (if any), and
   a Receive CTA. viewOnly mode hides inputs and the receive button.
   ═══════════════════════════════════════════════════════════════════ */
/* "Old Dues Till Date" head — modal khulte hi Received me POORA baqaya
   pre-fill hota hai (Pending 0), magar cashier isay edit bhi kar sakta hai. */
const isOldDuesHead = (name) => /old\s*dues/i.test(String(name || ''));
/* Previous / old-dues head — challan amount aksar 0 hota hai, raqam previous me hoti hai.
   Paid ho jane par backend previousPendingorAdv 0 kar deta hai, is liye slip us wasooli
   ko advance (minus remaining) samajh leti thi. */
const isPreviousDuesHead = (name) => /old\s*dues|previous\s*dues?|pending\s*dues?|previous\s*pending|arrears?/i.test(String(name || ''));

function FeeReceivingModal({ cfg, onClose, onSave, toast, onDownloadPayment, onEditPayment }) {
  /* Receiving Date par late fine ka poora hisaab chalta hai — is liye LOCAL date
     (localTodayISO), toISOString() nahi: wo UTC me badal kar Pakistan (UTC+5) me
     subah 5 baje se pehle PICHHLI date deta tha. Us soorat me due-date wale din
     ki date aa jaati thi, daysLate 0 nikalta, fine 0 banti aur "Late Fine" row
     kabhi ledger me jaati hi nahi — jabke list aaj tak ki fine dikha rahi hoti. */
  const [date, setDate] = useState(localTodayISO());
  const [method, setMethod] = useState('Cash');
  const [ref, setRef] = useState('');
  const [txn, setTxn] = useState('');
  /* Optional note for THIS installment. receive-payment API me remarks field
     nahi hai, is liye ye session receipt (pay object) par store hoti hai — dekho
     handleReceive payload.remarks + parent handleSaveReceipt. */
  const [remarks, setRemarks] = useState('');
  const [perHeadInput, setPerHeadInput] = useState({});
  /* Fine ki WASOOLI ka apna input — baaki heads ke `perHeadInput` jaisa hi KUL
     wasooli (already + ab ki) rakhta hai. null = cashier ne abhi haath nahi
     lagaya, to already-paid par hi rehta hai (Received 0, fine Pending me). */
  const [fineRecvInput, setFineRecvInput] = useState(null);
  /* Fine par Give Discount (sirf is receiving ki) — Give Discount tick ho to fine row me input. */
  const [fineGiveInput, setFineGiveInput] = useState(0);
  /* Receiving-time EXTRA discount — checkbox ON par "Give Discount" column dikhti hai,
     values detailRows.discount me jati hain aur API isReceiving:true bhejti hai. */
  const [giveDiscInput, setGiveDiscInput] = useState({});
  const [showGiveDisc, setShowGiveDisc] = useState(false);

  useEffect(() => {
    if (!cfg) return;
    setDate(localTodayISO()); setMethod('Cash'); setRef(''); setTxn('');
    setRemarks('');
    setFineRecvInput(null);
    setFineGiveInput(0);
    /* "Received" input KUL wasooli (pehle jama + ab ki). Naya paisa = input − paid.
       Seed = paid + remaining → next installment ke Pay Now me baqaya auto-map. */
    const chRecv = {};
    (cfg.challan?.detailRows || []).forEach(r => {
      const n = r.subHead || r.head || '';
      chRecv[n] = (chRecv[n] || 0) + (+r.receivedAmount || 0);
    });
    /* Pehli receiving me Give Discount ON tha to Transaction Details / partial
       reopen par column wapas dikhao; viewOnly me amounts bhi seed karo.
       Server paymentMethod|#GD# marker + challan._giveDisc (logout/login safe). */
    const histGive = {};
    let priorGive = !!(cfg.challan?._isReceivingGive);
    Object.entries(cfg.challan?._giveDisc || {}).forEach(([n, v]) => {
      const g = Math.max(0, +v || 0);
      if (!g) return;
      histGive[n] = (histGive[n] || 0) + g;
      priorGive = true;
    });
    /* Marker sirf tab, jab row par receiving baqi ho — delete-receiving use
       paymentMethod par chhod jaata hai (withPersistedGiveDisc wahan se saaf
       kar deta hai; ye guard un raw records ke liye hai jo us se guzre nahi). */
    if (!priorGive && cfg.challan?.paymentMethod && feeService.hasLiveReceiving(cfg.challan)) {
      const parsed = feeService.parseGiveDiscFromPaymentMethod(cfg.challan.paymentMethod);
      Object.entries(parsed.giveDisc || {}).forEach(([n, v]) => {
        const g = Math.max(0, +v || 0);
        if (!g) return;
        histGive[n] = (histGive[n] || 0) + g;
        priorGive = true;
      });
    }
    if (!priorGive && cfg.challan?.id) {
      const stored = feeService.getStoredGiveDisc(cfg.challan.id);
      Object.entries(stored?.giveDisc || {}).forEach(([n, v]) => {
        const g = Math.max(0, +v || 0);
        if (!g) return;
        histGive[n] = (histGive[n] || 0) + g;
        priorGive = true;
      });
    }
    (cfg.payments || []).forEach(p => {
      if (p.isReceiving) priorGive = true;
      Object.entries(p.giveDisc || {}).forEach(([n, v]) => {
        const g = Math.max(0, +v || 0);
        if (!g) return;
        histGive[n] = (histGive[n] || 0) + g;
        priorGive = true;
      });
    });
    const useHeadPrevSeed = !!cfg.model.headWisePrev;
    const seed = {};
    const discSeed = {};
    (cfg.model.heads || []).forEach(h => {
      const hist = histGive[h.name] || 0;
      const fromPay = (cfg.payments || []).reduce((a, p) => a + (+(p.perHead?.[h.name]) || 0), 0);
      /* Negative received (Old Advance −3000) Math.max se 0 na bane. */
      const fromChSeed = +chRecv[h.name] || 0;
      const paidSeed = cfg.challan
        ? (Math.abs(fromChSeed) >= Math.abs(fromPay) ? fromChSeed : fromPay)
        : fromPay;
      const owedSeed = (+h.net || 0) + (useHeadPrevSeed ? (+h.prev || 0) : 0);
      /* Agar hist pehle se net/disc me fold hai to live input 0; warna hist dikhao
         taake Remaining/save pehli give ko dobara apply kar sake. */
      const remNo = owedSeed - paidSeed;
      const remWith = owedSeed - hist - paidSeed;
      const histFoldedSeed = hist > 0 && Math.abs(remNo) <= Math.abs(remWith);
      /* Pay Now (live) me Give Discount = SIRF is installment ki NAYI discount → 0 se
         shuru. receive-installment DELTA API hai: pichhli give dobara seed karte to
         wo har agli installment me phir se `discount` ban kar chali jaati (2nd
         installment par received 0 aur sab discount me). Pichhli give challan ke
         detailRows.discount (withPersistedGiveDisc) me pehle se hai → h.net me shamil. */
      discSeed[h.name] = cfg.viewOnly ? hist : 0;
      /* Installment 1 ke baad: Pay Now me SIRF remaining map ho (already paid − give).
         Input = KUL wasooli → seed = paid + remaining, taake recvNow = remaining. */
      if (!cfg.viewOnly) {
        if (owedSeed < 0) {
          /* Old Advance / credit: pehle consume ho chuka ho to paid; warna full owed. */
          seed[h.name] = paidSeed !== 0 ? paidSeed : owedSeed;
        } else {
          /* Challan ho to pichhli give h.net me fold hai — dobara mat ghatao. */
          const giveInRem = (cfg.challan || histFoldedSeed) ? 0 : hist;
          const paidPos = Math.max(0, paidSeed);
          const remainingNow = Math.max(0, owedSeed - giveInRem - paidPos);
          seed[h.name] = paidPos + remainingNow;
        }
      } else {
        seed[h.name] = paidSeed;
      }
    });
    /* Aggregate Previous Pending row (jab head-wise prev na ho) — remaining map. */
    if (!cfg.viewOnly && !useHeadPrevSeed && (+cfg.model.prev || 0) > 0) {
      const prevKey = cfg.model.prevName || 'Previous Pending';
      const prevPaidSeed = Math.max(0, +cfg.model.prevPaid || 0);
      const prevRem = Math.max(0, (+cfg.model.prev || 0) - prevPaidSeed);
      seed[prevKey] = prevPaidSeed + prevRem;
    }
    setPerHeadInput(seed);
    setGiveDiscInput(discSeed);
    setShowGiveDisc(priorGive);
    /* Fine: next installment me baqi fine hi map ho (paid + remaining). */
    if (!cfg.viewOnly) {
      const fineRowsInit = (cfg.challan?.detailRows || []).filter(feeService.isLateFineRow);
      const finePaidInit = fineRowsInit.reduce((a, r) => a + (+r.receivedAmount || 0), 0);
      const fineBilledInit = fineRowsInit.reduce((a, r) => a + (+r.challanAmount || 0), 0);
      const fineCalcInit = feeService.computeFine({
        dueDate: cfg.challan?.dueDate, receivingDate: localTodayISO(), settings: cfg.settings,
      });
      /* Bill na hui ho to apna late fine + pichhle challans ka carried fine (same Fine line). */
      const fineDueInit = fineBilledInit > 0 ? fineBilledInit : fineCalcInit + Math.max(0, +cfg.prevFine || 0);
      /* Pehle fine par di gayi discount (Give → recvDiscount, discount me fold) — baqaya se minus. */
      const fineDiscInit = fineRowsInit.reduce((a, r) => a + Math.max(0, +r.discount || 0), 0);
      const finePaidPos = Math.max(0, finePaidInit);
      const fineRem = Math.max(0, fineDueInit - fineDiscInit - finePaidPos);
      setFineRecvInput(finePaidPos + fineRem);
    } else {
      setFineRecvInput(null);
    }
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const { classMeta, student, model, payments, challan, period, monthIdx, viewOnly, settings } = cfg;

  /* Fee Settings → Advance Payment Receiving. Default ON (undefined/true) → koi
     tabdeeli nahi (over-receiving pehle ki tarah advance banata hai). OFF hone par
     har head ki Pay Now us head ke owed par cap ho jaati hai — naya advance nahi
     banta (niche rows.map me lagta hai). Sirf inputs/figures gate hote hain; save
     ka payload/challanFigures/advApplied math jyun ka tyun. */
  const advancePaymentReceivingOn = settings?.advancePaymentReceiving !== false;

  /* Per-head already-received. Session `payments` are lost on refresh, so when a
     real challan exists take each head's authoritative receivedAmount from its
     detailRows (matched by subHead) and keep the larger of the two. */
  const challanRecvByHead = {};
  (challan?.detailRows || []).forEach(r => {
    const n = r.subHead || r.head || '';
    challanRecvByHead[n] = (challanRecvByHead[n] || 0) + (+r.receivedAmount || 0);
  });
  const paymentsPerHead = {};
  (payments || []).forEach(p => {
    Object.entries(p.perHead || {}).forEach(([n, v]) => {
      paymentsPerHead[n] = (paymentsPerHead[n] || 0) + (+v || 0);
    });
  });
  /* Session payments se pehle di hui Give Discount (API disc ignore kare to bhi). */
  const histGiveByHead = {};
  (payments || []).forEach(p => {
    Object.entries(p.giveDisc || {}).forEach(([n, v]) => {
      histGiveByHead[n] = (histGiveByHead[n] || 0) + Math.max(0, +v || 0);
    });
  });
  const perHeadPaid = {};
  (model.heads || []).forEach(h => {
    const fromPay = +paymentsPerHead[h.name] || 0;
    const fromCh = +challanRecvByHead[h.name] || 0;
    /* Negative received (Old Advance −3000) Math.max se 0 na bane. */
    perHeadPaid[h.name] = challan
      ? (Math.abs(fromCh) >= Math.abs(fromPay) ? fromCh : fromPay)
      : fromPay;
  });

  /* Build display rows with live recompute */
  let totalChallan = 0, totalDisc = 0, totalAfter = 0;
  /* NOTE: Over-receiving allowed hai — head ke owed se zyada amount li ja sakti hai.
     Us case me Pending MINUS (negative) ho jaata hai = utna ADVANCE. Is liye yahan
     koi upper clamp nahi lagta (pehle lagta tha, jis se extra amount block ho jaata). */
  const useHeadPrev = !!model.headWisePrev;
  const rows = model.heads.map(h => {
    const paid = +perHeadPaid[h.name] || 0;
    const after = h.net;
    const headPrev = useHeadPrev ? (+h.prev || 0) : 0;   // us head ka previous (owed me shamil)
    const owed = after + headPrev;
    /* Head ka owed MINUS ho (advance/credit — this-month magar previous bara advance) to wo
       CREDIT head hai: yahan collect NAHI karte; credit total par advApplied se apply hota. */
    const isCredit = useHeadPrev && owed < 0;
    /* Input KUL wasooli hai (already + new); credit head par collect nahi (paid par rehta).
       Old-dues head bhi ab editable — bas default full seed hota hai (seed effect). */
    const rawIn = +perHeadInput[h.name] || 0;
    const totalRecv = (viewOnly || isCredit)
    ? paid
  : (owed < 0 ? rawIn : Math.max(0, rawIn));
    let recvNow = (viewOnly || isCredit) ? 0 : (totalRecv - paid);
    /* Give Discount: payments hist + live input.
       - viewOnly: hist dikhao; agar pehle se disc me fold hai to math me 0.
       - live: input hi source of truth (seed hist tab jab fold na ho). */
    const histGive = isCredit ? 0 : Math.max(0, +histGiveByHead[h.name] || 0);
    const remNoHist = owed - paid - recvNow;
    const remWithHist = owed - histGive - paid - recvNow;
    const histFolded = histGive > 0 && Math.abs(remNoHist) <= Math.abs(remWithHist);
    const typedGive = (!showGiveDisc || viewOnly || isCredit)
      ? 0
      : Math.max(0, Math.min(+giveDiscInput[h.name] || 0, Math.max(0, owed)));
    /* Challan withPersistedGiveDisc se aaya ho to pichhli installments ki Give Discount
       h.disc / owed me PEHLE se fold hai. Display ke liye usay wapas nikaal kar gross
       Net Payable dikhao, taake "Remaining after Inst. N" = Net − received − disc sahi
       aaye (warna disc do dafa katti thi). Math (owed/finalNet) jyun ka tyun. */
    const foldedGive = (!isCredit && challan?._isReceivingGive) ? histGive : 0;
    /* View: give owed me fold ho (foldedGive) to math me dobara mat ghatao —
       warna Final Net / Remaining me give do dafa katti thi. */
    const giveDisc = viewOnly
      ? ((foldedGive > 0 || histFolded) ? 0 : histGive)
      : typedGive;
    const giveDiscShow = viewOnly ? histGive : typedGive;
    /* Discount column: fold ho to original challan disc alag, give alag. */
    const discShow = foldedGive > 0
      ? Math.max(0, (+h.disc || 0) - foldedGive)
      : (showGiveDisc && histFolded && histGive > 0)
        ? Math.max(0, (+h.disc || 0) - histGive)
        : (+h.disc || 0);
    const finalNetPayable = isCredit ? owed : Math.max(0, owed - giveDisc);
    /* Advance Payment Receiving OFF → is head par owed se zyada NAYI wasooli mana:
       nayi raqam (recvNow) ko Final Net Payable − already-paid par cap karo taake
       koi over-payment→advance na bane. Default ON par ye branch chalta hi nahi,
       is liye maujooda behaviour (over-receiving allowed) bilkul barqarar. Credit/
       viewOnly heads ko haath nahi lagate. */
    if (!advancePaymentReceivingOn && !viewOnly && !isCredit) {
      recvNow = Math.min(recvNow, Math.max(0, finalNetPayable - paid));
    }
    const pending = owed - paid - recvNow;      // credit head par = owed (minus)
    /* Remaining Give Discount ke baad — finalNet se. */
    const remaining = finalNetPayable - paid - recvNow;
    /* ── Installment history (display only) ──
       Har PICHHLI receiving (payment) = ek installment. Is head ka us installment
       me received (perHead) + di gayi Give Discount (giveDisc) running Net Payable
       se ghata kar "Remaining after Inst. N" banti hai. Ye sirf columns dikhati
       hai — save/receive ka koi hisaab isse nahi badalta. */
    let instRun = owed + foldedGive;
    const installments = (payments || []).map(p => {
      const received = +(p.perHead?.[h.name]) || 0;
      const discGiven = Math.max(0, +(p.giveDisc?.[h.name]) || 0);
      /* Clamp NAHI — owed se zyada liya to MINUS = us head ka advance (sequence me dikhe). */
      instRun = instRun - received - discGiven;
      return { received, discGiven, remainingAfter: instRun };
    });
    totalChallan += h.std;
    totalDisc += discShow;
    totalAfter += after;
    /* Display-only: Net Payable gross (fold shuda give wapas), aur Pay Now (live) me
       Final Net Payable = pichhli installments ke BAAD ka baqaya − nayi give. */
    const netShow = owed + foldedGive;
    const finalShow = (viewOnly || isCredit) ? finalNetPayable : finalNetPayable - paid;
    return {
      ...h,
      disc: discShow,
      paid, totalRecv, recvNow, after, headPrev, owed, pending, isCredit,
      giveDisc, giveDiscShow, finalNetPayable, remaining, installments,
      netShow, finalShow,
    };
  });

  /* Prev Amount column — head-wise: >0 baqaya, <0 advance (minus), 0/na-ho → "—". */
  const prevDisp = (v) => (typeof v === 'number' && v !== 0) ? money(v) : '—';
  const totalPrev = rows.reduce((a, r) => a + (typeof r.prev === 'number' ? r.prev : 0), 0);

  /* Previous Pending bhi ab ek editable head ki tarah — uska apna received input.
     Heads ki tarah ye input bhi KUL wasooli rakhta hai (already + new). */
  const prevKey = model.prevName || 'Previous Pending';
  /* Head-wise me aggregate "Previous Pending" row use nahi hoti — sab 0. */
  const prevPaid = useHeadPrev ? 0 : (+model.prevPaid || 0);
  const prevTotalRecv = (viewOnly || useHeadPrev)
    ? prevPaid
    : Math.max(0, perHeadInput[prevKey] == null ? prevPaid : (+perHeadInput[prevKey] || 0));
  let prevRecv = (viewOnly || useHeadPrev) ? 0 : (prevTotalRecv - prevPaid);
  /* Advance Payment Receiving OFF → aggregate Previous Pending par bhi over-receiving
     mana: nayi wasooli baqaya (model.prev − prevPaid) par cap. Default ON par no-op. */
  if (!advancePaymentReceivingOn && !viewOnly && !useHeadPrev) {
    prevRecv = Math.min(prevRecv, Math.max(0, (+model.prev || 0) - prevPaid));
  }
  const prevPend = useHeadPrev ? 0 : (model.prev - prevPaid - prevRecv);   // negative = advance

  const headsRecv = rows.reduce((a, r) => a + r.recvNow, 0) + prevRecv;
  /* Head-wise credit — jin heads ka owed MINUS hai (advance) un ke |owed| ka jama. */
  const headAdvCredit = rows.reduce((a, r) => a + (r.owed < 0 ? -r.owed : 0), 0);
  /* BAAQI advance credit = kul advance − consume shuda (advPaid) + head-wise credit. */
  const advCredit = Math.max(0, (+model.advance || 0) - (+model.advPaid || 0)) + headAdvCredit;
  /* Pehle se CONSUME ho chuka advance — challan ki negative advance rows ke received (minus).
     viewOnly me naya advApplied 0 hota hai, is liye credit head yahin se settle hota (warna
     fully-received par bhi −550 atka reh jaata tha). */
  const advConsumed = useHeadPrev
    ? (challan?.detailRows || [])
      .filter(r => /previous|pending|arrear/i.test(String(r.subHead || r.head || '')) && (+r.challanAmount || 0) < 0)
      .reduce((a, r) => a + Math.abs(+r.receivedAmount || 0), 0)
    : 0;
  const advApplied = Math.min(advCredit, Math.max(0, headsRecv));
  /* Credit heads ka DISPLAYED Pending advance (naya + pehle consume shuda) ke hisaab se kam
     karo: jaise-jaise baaki heads receive hote (ya ho chuke) hain, credit consume ho kar
     Pending −550 → 0 ki taraf jaata hai (naya head banaye baghair). */
  const advTotalApplied = advApplied + advConsumed;
  if (useHeadPrev && advTotalApplied > 0) {
    let toApply = advTotalApplied;
    rows.forEach(r => {
      if (!r.isCredit) return;
      const credit = -r.owed;
      const applied = Math.min(credit, Math.max(0, toApply));
      toApply -= applied;
      r.pending = r.owed + applied;
    });
  }

  /* ── LATE FINE ──
     Challan ki due date ke BAAD wasool karne par jurmana. Base date wahi
     "Receiving Date" hai jo upar modal me chuni gayi (system ka aaj nahi), is
     liye date badalte hi fine live update hoti hai, aur receivable/total dono
     me jud'ti hai. Challan Amount baaki heads ki tarah read-only hai; cashier
     kam/zyada lena chahe (ya waive karna ho) to "Received" me karta hai —
     dekho `fineRecvInput`. View mode me actual receiving date ke hisaab se
     dikhti hai aur edit nahi hoti. */
  const fineBaseDate = viewOnly
    ? (String(payments?.[payments.length - 1]?.date || challan?.receivedDate || challan?.modifiedAt || '').slice(0, 10) || date)
    : date;
  const fineRows = (challan?.detailRows || []).filter(feeService.isLateFineRow);
  /* Ledger me pehle se mojood (freeze shuda) fine — aur uske khilaf wasooli. */
  const fineBilled = fineRows.reduce((a, r) => a + (+r.challanAmount || 0), 0);
  /* Wasool shuda fine SIRF row ke receivedAmount se. Pehle yahan
     max(receivedAmount, challanAmount) tha — us waqt fine ya poori jaati ya
     bilkul nahi, to "billed = paid" maan lena theek tha. Ab cashier fine
     partial le sakta hai (ya bilkul na le) magar wo phir bhi bill hoti hai,
     is liye billed ko paid maanna baqaya fine ko chupa deta tha. */
  const finePaid = fineRows.reduce((a, r) => a + (+r.receivedAmount || 0), 0);
  const fineCalc = feeService.computeFine({
    dueDate: challan?.dueDate, receivingDate: fineBaseDate, settings,
  });
  /* Jo fine ledger me likhi ja chuki hai WAHI authority hai — usay dobara compute
     na karo. Warna settings badalne par (ya view mode me doosri base date par)
     modal ki fine persisted row se mukhtalif nikalti thi: Total 4,400 magar
     Already Received 4,450, aur Remaining minus me chala jaata tha.
     Fine abhi tak billed nahi hui to computed hi lagti hai. */
  /* Pichhle mahino ka baqaya fine (carry) — same "Fine" line me. Bill ho chuki ho to wo pehle
     hi us me shamil hai (billed authority). */
  const prevFine = fineBilled > 0 ? 0 : Math.max(0, Math.round(+cfg.prevFine || 0));
  const fineDue = fineBilled > 0 ? fineBilled : fineCalc + prevFine;
  /* Fine par PEHLE di gayi discount (Give Discount → recvDiscount, discount me fold). */
  const fineDiscPrev = fineRows.reduce((a, r) => a + Math.max(0, +r.discount || 0), 0);
  const fineDueNet = Math.max(0, fineDue - fineDiscPrev);
  /* IS receiving ki fine Give Discount — sirf Give Discount tick ho aur live mode. */
  const fineGive = (showGiveDisc && !viewOnly)
    ? Math.max(0, Math.min(+fineGiveInput || 0, Math.max(0, fineDueNet - finePaid)))
    : 0;
  const setFineGive = (v) => {
    const g = Math.max(0, Math.min(Number(v) || 0, Math.max(0, fineDueNet - finePaid)));
    setFineGiveInput(g);
    /* Pay Now = baqi fine (Final Net) — heads ki Give Discount jaisa. */
    setFineRecvInput(Math.max(finePaid, fineDueNet - g));
  };
  const fineDays = feeService.daysLate(challan?.dueDate, fineBaseDate);
  /* Fine ki wasooli bilkul baaki heads jaisi: input KUL wasooli rakhta hai, aur
     ab ka naya paisa = input − pehle se paid. Seed sirf ALREADY PAID hai (banti
     hui fine nahi) — modal khulte hi fine PENDING me nazar aati hai aur Receiving
     Now 0 rehta hai, jab tak cashier khud raqam na daale. Baaki heads bhi isi
     tarah `paid` se shuru hote hain. */
  const fineTotalRecv = viewOnly
    ? finePaid
    : Math.max(0, fineRecvInput == null ? finePaid : fineRecvInput);
  /* Fine bhi baaki fee heads jaisa POORA editable: input KUL wasooli hai, naya paisa =
     input − pehle se paid. MINUS bhi ho sakta hai (cashier ne pehle zyada le liya tha,
     ab kam kar raha = correction), is liye yahan max(0) clamp NAHI — warna fine sirf
     barh sakti thi, ghata nahi (fee heads ki tarah edit nahi hoti thi). */
  let fineOwed = viewOnly ? 0 : (fineTotalRecv - finePaid);
  /* Advance Payment Receiving OFF → fine par bhi over-receiving mana: nayi wasooli
     baqaya fine (fineDue − finePaid) par cap. Upper cap sirf — MINUS (correction)
     phir bhi allow hai. Default ON par no-op. */
  if (!advancePaymentReceivingOn && !viewOnly) {
    fineOwed = Math.min(fineOwed, Math.max(0, fineDueNet - fineGive - finePaid));
  }
  const finePend = fineDueNet - fineGive - finePaid - fineOwed;

  const receivingNow = headsRecv - advApplied + fineOwed;   // fineOwed view mode me 0
  /* alreadyPaid me se pehle CONSUME ho chuka advance ghatao — heads ke received me wo cash
     shamil hai jise advance ne kam kiya tha (alag negative row me −advance), warna Already
     Received aur Remaining dono galat (−550) aate the. */
  const alreadyPaid = rows.reduce((a, r) => a + r.paid, 0) + prevPaid + finePaid - advConsumed;
  /* Give Discount (hist/typed) Total Net Payable se ghatao — warna Remaining After
     slip ke 0 ke bawajood discount jaisa baqaya dikhata hai. */
  const giveMathTotal = rows.reduce((a, r) => a + (r.giveDisc || 0), 0) + fineGive;
  const totalAmt = totalAfter + model.prev - model.advance + fineDueNet - giveMathTotal;
  /* Total se zyada wasool ho to ye MINUS me jaata hai = student ka advance. */
  const remainAfter = totalAmt - alreadyPaid - receivingNow;

  /* ── 9-column payment-flow table ke footer sums (sirf display) ──
     Previous Dues + This Month's Challan − Discount = Net Payable ·
     Net Payable − Give Discount = Final Net Payable · Final − Pay Now = Remaining.
     Give Discount UI-only hai. Special rows (aggregate Previous Pending / Advance /
     Late Fine) ko condition ke mutabiq shamil karta hai taake footer un ke saath mile. */
  const aggPrevShown = !useHeadPrev && model.prev > 0 && !(model.heads || []).some(h => /previous|pending|arrear/i.test(h.name));
  const advRowShown = !useHeadPrev && advCredit > 0;
  const flowSumHeadPrev = rows.reduce((a, r) => a + (r.headPrev || 0), 0);
  const flowPrevDues = flowSumHeadPrev + (aggPrevShown ? model.prev : 0);
  const flowChallan = totalChallan + fineDue;
  const flowNet = rows.reduce((a, r) => a + r.netShow, 0) + (aggPrevShown ? model.prev : 0) + (advRowShown ? -advCredit : 0) + fineDueNet;
  const flowGiveDisc = rows.reduce((a, r) => a + (r.giveDiscShow || r.giveDisc || 0), 0) + fineGive;
  /* Live Pay Now: Final = pichhli installments ke baad ka baqaya (paid minus). */
  const flowFinal = rows.reduce((a, r) => a + r.finalShow, 0)
    + (aggPrevShown ? model.prev - (viewOnly ? 0 : prevPaid) : 0)
    + (advRowShown ? -advCredit : 0)
    + fineDueNet - fineGive - (viewOnly ? 0 : finePaid);

  /* ── Installment columns (display only) ──
     N = ab tak ki receiving (payments) + 1 (ab wali). Har PICHHLI receiving apni
     "Installment k Received" + "Remaining after Inst. k" jori deti hai. Ye sirf
     ledger ki asli receiving history dikhati hain — koi save/receive hisaab inse
     nahi badalta. */
  const installmentCount = (payments || []).length;
  /* View (Transaction Details): "Last Received" column = SIRF aakhri receiving (save-time se
     pehchani, slip jaisa) — 3,000 pehle Inst 1 me dikh chuka, yahan sirf 1,000. */
  const lastRecvByHead = {};
  if (viewOnly) {
    (latestReceivingSlipRows(challan) || []).forEach(x => {
      lastRecvByHead[String(x.name).trim().toLowerCase()] = (lastRecvByHead[String(x.name).trim().toLowerCase()] || 0) + (x.recv || 0);
    });
  }
  const lastRecvOf = (name) => +lastRecvByHead[String(name || '').trim().toLowerCase()] || 0;
  const lastRecvTotal = Object.values(lastRecvByHead).reduce((a, v) => a + (+v || 0), 0);
  /* Fee Settings → Multiple Receiving. OFF hone par ek challan par sirf EK hi
     installment jaiz hai — jaise hi koi prior receipt maujood ho (session payments
     ya persist-shuda ledger wasooli, dono cover), doosri receiving round har jagah
     band. Sirf inputs/button gate hote hain + handleReceive guard; save/anyHeadRecv/
     challanFigures ka math jyun ka tyun. Default ON par ye hamesha false rehta hai. */
  const priorReceiptExists = installmentCount >= 1 || alreadyPaid > 0;
  const multipleReceivingBlocked = !viewOnly && settings?.multipleReceiving === false && priorReceiptExists;
  /* Aggregate "Previous Pending" row (jab head-wise prev na ho) ke installment cells. */
  let prevInstRun = +model.prev || 0;
  const prevInst = (payments || []).map(p => {
    const received = +(p.perHead?.[prevKey]) || 0;
    prevInstRun = Math.max(0, prevInstRun - received);
    return { received, discGiven: 0, remainingAfter: prevInstRun };
  });
  const renderInstCells = (list) => (list || []).map((x, i) => (
    <React.Fragment key={i}>
      <td className="fee-right flow-inst-col">
        {x && x.received !== 0 ? <span className="fee-paid-amt">{money(x.received)}</span> : money(0)}
        {x && x.discGiven > 0 && <span className="fee-sub-eq">disc {money(x.discGiven)}</span>}
      </td>
      {/* MINUS = advance (owed se zyada wasool). */}
      <td className={`fee-right flow-inst-col${x && x.remainingAfter < 0 ? ' fee-neg' : ''}`}>{x ? money(x.remainingAfter) : <span className="fee-recv-dash">—</span>}</td>
    </React.Fragment>
  ));
  const renderInstDash = () => (payments || []).map((p, i) => (
    <React.Fragment key={p.id || i}>
      <td className="fee-right flow-inst-col"><span className="fee-recv-dash">—</span></td>
      <td className="fee-right flow-inst-col"><span className="fee-recv-dash">—</span></td>
    </React.Fragment>
  ));

  const setHead = (name, v) => {
  const n = Number(v) || 0;
  const allowNeg = /old\s*advance|advance\s*till/i.test(String(name || ''));
  setPerHeadInput(prev => ({ ...prev, [name]: allowNeg ? n : Math.max(0, n) }));
};

  /* Give Discount change → Pay Now Final Net Payable par sync (Remaining 0),
     taake discount pending/minus na dikhe. */
  const setGiveDisc = (name, v) => {
    const giveRaw = Math.max(0, Number(v) || 0);
    const h = (model.heads || []).find(x => x.name === name);
    const headPrev = useHeadPrev ? (+(h?.prev) || 0) : 0;
    const owed = ((+h?.net || 0) + headPrev);
    const give = Math.min(giveRaw, Math.max(0, owed));
    const finalNet = Math.max(0, owed - give);
    const paid = +perHeadPaid[name] || 0;
    setGiveDiscInput(prev => ({ ...prev, [name]: give }));
    /* Kul wasooli = Final Net (pehle se paid se kam na ho). */
    setPerHeadInput(prev => ({ ...prev, [name]: Math.max(paid, finalNet) }));
  };

  /* Pending is the mirror of Received — the two always add up to the head's net,
     so typing either one drives the other. Both write to the same perHeadInput
     state; there is no second source of truth. Received KUL wasooli hai, is liye
     yahan `net` se ghatao (owed se nahi). */
  const setPendingFor = (row, v) => {
    /* Pending MINUS bhi ho sakta hai (advance) — clamp nahi. Received = owed − pending
       (owed = After Discount + head-wise Prev). */
    const pend = Number(v) || 0;
    const owed = (typeof row.owed === 'number') ? row.owed : row.net;
    const recv = owed - pend;
const allowNeg = owed < 0 || /old\s*advance|advance\s*till/i.test(String(row.name || ''));
setPerHeadInput(prev => ({ ...prev, [row.name]: allowNeg ? recv : Math.max(0, recv) }));
  };

  const fineTxt = settings?.fineEnabled
    ? `Rs. ${(+settings.fineAmt || 0).toLocaleString('en-PK')} ${settings.fineType === 'daily' ? '/ day' : '(fixed)'}`
    : '—';

  const handleReceive = () => {
    /* Multiple Receiving OFF + is challan par pehle se receipt maujood → doosri
       receiving round bilkul mana. Inputs/button already disabled hain; ye guard
       last line of defence hai. */
    if (multipleReceivingBlocked) {
      toast('Multiple Receiving is disabled in Fee Settings — this challan already has a payment recorded', 'error');
      return;
    }
    /* receivingNow MINUS bhi ho sakta hai jab cashier ne already-received ko neeche
       theek kiya — wo bhi ek valid save hai. Sirf "kuch bhi nahi badla" rokna hai.
       Sirf Give Discount (bina nayi cash) bhi valid receive hai. */
   const anyHeadRecv = rows.some(r => r.recvNow !== 0) || prevRecv !== 0 || fineOwed !== 0;
   const anyGiveDisc = showGiveDisc && (rows.some(r => (r.giveDisc || 0) > 0) || fineGive > 0);
if (!anyHeadRecv && !anyGiveDisc) {
  toast('Enter at least one head amount to receive', 'error');
  return;
}
    if (!date) { toast('Receiving date is required', 'error'); return; }
    /* Session-date guard: receiving date current session ki UTC window ke andar ho. */
    const recvChk = validateSessionDateFromStorage(date, 'receiving date');
    if (!recvChk.ok) { toast(recvChk.message, 'error'); return; }
    /* Build perHead snapshot of receivingNow values. Non-zero delta bhejo — MINUS
       wala bhi, warna correction save hi na hoti. */
    const perHead = {};
    rows.forEach(r => { if (r.recvNow !== 0) perHead[r.name] = r.recvNow; });
    /* Previous dues ki raqam bhi — ASLI subHead key par, taake API sahi row par lagaye. */
    if (prevRecv !== 0) perHead[prevKey] = (perHead[prevKey] || 0) + prevRecv;
    /* Jo heads challan ke detailRows me NAHI (e.g. Transport setup fallback) magar receive
       hue — inhe alag bhejo taake save unki NAYI ledger row bana kar wasooli persist kare. */
    const existingHeads = new Set((challan?.detailRows || []).map(r => String(r.subHead || r.head || '').toLowerCase().trim()));
    const newHeads = rows
      .filter(r => !r.isCredit && r.recvNow > 0 && !existingHeads.has(String(r.name).toLowerCase().trim()))
      .map(r => ({ name: r.name, std: r.std, disc: r.disc, recv: r.recvNow }));
    /* Receiving ke WAQT ka per-head previous (running-ledger se) — slip is se sahi Remaining
       nikalti hai (fully-paid head ka backend previousPendingorAdv baad me 0 ho jaata hai). */
    const prevByHead = {};
    (model.heads || []).forEach(h => { if (h.prev) prevByHead[h.name] = h.prev; });
    const payload = {
      reg: student.reg, monthIdx,
      studentName: student.name,
      date, method, ref, txn, remarks,
      amount: receivingNow,
      perHead,
      /* Correction (net minus) — receipt/slip aur history ise adjustment dikhayein,
         normal wasooli nahi. */
      isAdjustment: receivingNow < 0,
      /* Fine alag se — receipt/slip par apni line banti hai, aur `amount` me
         pehle se shamil hai (receivingNow me joda gaya). */
      fine: fineOwed,
      /* Kul waajib fine — ab wasool na bhi ho to ledger me bill zaroor honi hai,
         warna baqaya fine agli baar gayab mil jaati hai. */
      fineBilled: fineDue,
      /* Is receiving me laga pichhla ADVANCE credit. Save ise challan me ek negative
         "Previous Pending" row ke received (-advApplied) ke taur par record karta hai,
         warna advance sirf cash kam karta magar ledger me consume na hota → fee poora
         received ho kar remaining minus (over-payment) reh jaata. advName = us row ka
         subHead (agar pehle se ho), warna default 'Previous Pending'. */
      advApplied: advApplied,
      /* Old Advance Till Date chal rahi ho to usi subHead par consume karo —
         warna withAdvanceRow default "Previous Pending" naya row bana deta tha. */
      advName: model.advName
        || (challan?.detailRows || []).find(r =>
             /old\s*advance|advance\s*till/i.test(String(r.subHead || r.head || ''))
             && (+r.challanAmount || 0) < 0
           )?.subHead
        || (model.heads || []).find(h =>
             /old\s*advance|advance\s*till/i.test(String(h.name || ''))
             && (+h.net || 0) < 0
           )?.name
        || 'Previous Pending',
      /* Missing (fallback) heads jinki receiving persist honi hai — e.g. Transport. */
      newHeads,
      /* Slip ke liye receiving-time ka per-head previous. */
      prevByHead,
      /* Checkbox ON → isReceiving true; Give Discount per head → detailRows.discount. */
      isReceiving: !!showGiveDisc,
      giveDisc: showGiveDisc
        ? {
          ...Object.fromEntries(rows.filter(r => (r.giveDisc || 0) > 0).map(r => [r.name, r.giveDisc])),
          /* Fine par Give Discount — fine row ke naam ("Late Fine") par; request builder isay
             fine row ke `discount` me bhejta hai. */
          ...(fineGive > 0 ? { [fineRows[0]?.subHead || feeService.LATE_FINE_HEAD]: fineGive } : {}),
        }
        : {},
    };
    if (cfg.kind === 'child') payload.famKey = cfg.famKey;
    else payload.classKey = classMeta.key;
    onSave(payload);
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal xl fee-recv-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon"><i className="fa-solid fa-hand-holding-dollar"></i></div>
            <div>
              <div className="fee-modal-title">
                {viewOnly ? 'Transaction Details — ' : 'Receiving Fee of '}
                <em>{student.name}</em>
              </div>
              <div className="fee-modal-sub">
                {classMeta.cls} ({classMeta.sec}) · {period}
              </div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          {!viewOnly && (
            <div className="fee-recv-meta">
              <div className="fee-field">
                <span className="fee-label">Custom Reference #</span>
                <input className="fee-input" value={ref} onChange={e => setRef(e.target.value)} placeholder="Optional" />
              </div>
              <div className="fee-field">
                <span className="fee-label">Receiving Date</span>
                <input className="fee-input" type="date" value={date} onChange={e => setDate(e.target.value)} />
              </div>
              <div className="fee-field">
                <span className="fee-label">Payment Method</span>
                <div className="fee-select-wrap">
                  <select className="fee-select" value={method} onChange={e => setMethod(e.target.value)}>
                    <option>Cash</option>
                    <option>Bank Transfer</option>
                    <option>Cheque</option>
                    <option>Card</option>
                    <option>Online / App</option>
                  </select>
                  <i className="fa-solid fa-chevron-down"></i>
                </div>
              </div>
              <div className="fee-field">
                <span className="fee-label">Transaction #</span>
                <input className="fee-input" value={txn} onChange={e => setTxn(e.target.value)} placeholder="Optional" />
              </div>
            </div>
          )}

          {/* Remarks — backend not ready (README §10); hide until API stores it.
          {!viewOnly && (
            <div className="fee-field" style={{ marginBottom: 16 }}>
              <span className="fee-label">Remarks</span>
              <input className="fee-input" value={remarks} onChange={e => setRemarks(e.target.value)} placeholder="Optional note for this installment" />
            </div>
          )}
          */}

          <div className="fee-recv-info">
            <div className="fee-recv-info-item">
              <span className="fee-recv-info-lbl">Fine Type</span>
              <span className="fee-recv-info-val">{settings?.fineEnabled ? (settings.fineType === 'daily' ? 'Per day' : 'Fixed') : '—'}</span>
            </div>
            <div className="fee-recv-info-item">
              <span className="fee-recv-info-lbl">Due Date</span>
              <span className="fee-recv-info-val">
                {isMultiMonthChallan(challan) ? '—' : (fmtDMY(challan?.dueDate) || '—')}
              </span>
            </div>
            <div className="fee-recv-info-item">
              <span className="fee-recv-info-lbl">Fine After Due Date</span>
              {/* Rate ke saath is challan par ACTUAL banti fine bhi — receiving
                  date due se aage ho to hi. */}
              <span className="fee-recv-info-val">
                {fineTxt}
                {fineDue > 0 && (
                  <span className="fee-sub-eq fee-fine">
                    {fineCalc > 0 ? `${fineDays} day${fineDays === 1 ? '' : 's'} late = ${money(fineCalc)}` : ''}
                    {prevFine > 0 ? `${fineCalc > 0 ? ' + ' : ''}previous fine ${money(prevFine)}` : ''}
                    {prevFine > 0 && fineCalc > 0 ? ` = ${money(fineDue)}` : ''}
                  </span>
                )}
              </span>
            </div>
            <div className="fee-recv-info-item">
              <span className="fee-recv-info-lbl">Discount if any</span>
              <span className="fee-recv-info-val">{money(model.disc)}</span>
            </div>
          </div>

          {!viewOnly && (
            <label className="fee-recv-give-toggle" style={multipleReceivingBlocked ? { opacity: .55, cursor: 'not-allowed' } : undefined}>
              <input
                type="checkbox"
                checked={showGiveDisc}
                disabled={multipleReceivingBlocked}
                onChange={e => {
                  const on = e.target.checked;
                  setShowGiveDisc(on);
                  if (!on) {
                    setGiveDiscInput(prev => {
                      const z = {};
                      Object.keys(prev || {}).forEach(k => { z[k] = 0; });
                      return z;
                    });
                    setFineGiveInput(0);
                  }
                }}
              />
              <span>Give Discount</span>
              <em>Check to show Give Discount column</em>
            </label>
          )}

          {/* Multiple Receiving OFF + is challan par pehle se receipt — koi doosri
              receiving round (cash/discount) available nahi. */}
          {multipleReceivingBlocked && (
            <div className="fee-info fee-info--warn">
              <i className="fa-solid fa-ban"></i>
              <span><b>Multiple Receiving is disabled</b> in Fee Settings — this challan already has {installmentCount > 0 ? `${installmentCount} installment${installmentCount === 1 ? '' : 's'}` : 'a payment'} recorded, so no further receiving round is available here.</span>
            </div>
          )}

          {/* Advance Payment Receiving OFF — over-payment/advance banane ki ijazat
              nahi; har head ki Pay Now us ke owed par cap hai. */}
          {!viewOnly && !multipleReceivingBlocked && !advancePaymentReceivingOn && (
            <div className="fee-info fee-info--warn">
              <i className="fa-solid fa-piggy-bank"></i>
              <span><b>Advance Payment Receiving is disabled</b> in Fee Settings — Pay Now is capped at exactly what each head still owes, so no new advance balance can be created here.</span>
            </div>
          )}

          <div className="fee-stbl-wrap" style={{ marginTop: 14 }}>
            <table className="fee-stbl fee-recv-table flow">
              <thead>
                <tr>
                  <th className="flow-head-col">Fee Head</th>
                  <th className="fee-right">Previous Dues</th>
                  <th className="fee-right"><span className="flow-op">+</span> This Month&apos;s Challan</th>
                  <th className="fee-right"><span className="flow-op">−</span> Discount in This Month&apos;s Challan</th>
                  <th className="fee-right"><span className="flow-op">=</span> Net Payable</th>
                  {(payments || []).map((p, i) => (
                    <React.Fragment key={p.id || i}>
                      <th className="fee-right flow-inst-col">Installment {i + 1} Received</th>
                      <th className="fee-right flow-inst-col">Remaining after Inst. {i + 1}</th>
                    </React.Fragment>
                  ))}
                  {showGiveDisc && (
                    <th className="fee-center"><span className="flow-op">−</span> Give Discount</th>
                  )}
                  {showGiveDisc && (
                    <th className="fee-right"><span className="flow-op">=</span> Final Net Payable</th>
                  )}
                  {/* View mode me ye column naya payment nahi — sab installments ka JAMA hai. */}
                  <th className="fee-center"><span className="flow-op">−</span> {viewOnly ? 'Last Received' : `Pay Now (Installment ${installmentCount + 1})`}</th>
                  <th className="fee-right"><span className="flow-op">=</span> Remaining</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(r => (
                  <tr key={r.name}>
                    <td className="flow-head-col"><b>{r.name}</b></td>
                    {/* Previous Dues — us head ka pichhla baqaya (>0 tag, <0 advance, warna —). */}
                    <td className="fee-right">
                      {r.headPrev > 0
                        ? <span className="flow-prevtag">{money(r.headPrev)}</span>
                        : (r.headPrev < 0 ? money(r.headPrev) : <span className="fee-recv-dash">—</span>)}
                    </td>
                    <td className="fee-right">{money(r.std)}</td>
                    <td className="fee-right">{r.disc > 0 ? money(r.disc) : '0'}</td>
                    {/* Net Payable = After Discount + head-wise Previous (r.owed). */}
                    <td className="fee-right"><span className="fee-cell-grey">{money(r.netShow)}</span></td>
                    {renderInstCells(r.installments)}
                    {showGiveDisc && (
                      <td className="fee-center">
                        {viewOnly || r.isCredit ? (
                          (r.giveDiscShow || 0) > 0
                            ? money(r.giveDiscShow)
                            : <span className="fee-recv-dash">—</span>
                        ) : (
                          <input
                            className="flow-input flow-input--disc"
                            type="number"
                            min="0"
                            max={Math.max(0, r.owed)}
                            value={giveDiscInput[r.name] === 0 ? 0 : (giveDiscInput[r.name] || '')}
                            onChange={e => setGiveDisc(r.name, e.target.value)}
                            placeholder="0"
                            disabled={multipleReceivingBlocked}
                          />
                        )}
                      </td>
                    )}
                    {showGiveDisc && (
                      <td className="fee-right"><span className="flow-final">{money(r.finalShow)}</span></td>
                    )}
                    {/* Pay Now = SIRF is installment ki raqam (state me KUL wasooli = paid + ye).
                        Over-receiving default ON par allowed; Advance Payment Receiving OFF par
                        baqaya (Final − paid) par cap (max) hota hai. */}
                    <td className="fee-center">
                      {viewOnly ? (
                        <span className="fee-paid-amt">{money(lastRecvOf(r.name))}</span>
                      ) : r.isCredit ? (
                        /* Credit head — yahan collect nahi hota; credit total se apply hota. */
                        <span className="fee-cell-grey">—</span>
                      ) : (
                        <input
                          className="flow-input flow-input--pay"
                          type="number"
                          min="0"
                          max={!advancePaymentReceivingOn ? Math.max(0, r.finalNetPayable - r.paid) : undefined}
                          value={r.totalRecv - r.paid}
                          onChange={e => setHead(r.name, r.paid + (Number(e.target.value) || 0))}
                          placeholder="0"
                          disabled={multipleReceivingBlocked}
                        />
                      )}
                    </td>
                    {/* Remaining = Final Net Payable − paid − recvNow (minus = advance). */}
                    <td className="fee-right">
                      {viewOnly ? (
                        <span className="flow-remain">{money(r.remaining)}</span>
                      ) : r.isCredit ? (
                        /* Credit head ka baqaya (advance, minus) — baaki heads receive hote hi
                           consume ho kar 0 ki taraf jaata hai. */
                        <span className={r.pending < 0 ? 'fee-neg' : undefined}>{money(r.pending)}</span>
                      ) : (
                        <span className="flow-remain">{money(r.remaining)}</span>
                      )}
                    </td>
                  </tr>
                ))}
                {/* Family child ke model me "Previous Pending" pehle se ek head hota hai (upar
                    rows me apne input ke saath aata hai) — us case me ye row skip karo,
                    warna duplicate dikhega. */}
                {!useHeadPrev && model.prev > 0 && !(model.heads || []).some(h => /previous|pending|arrear/i.test(h.name)) && (
                  <tr>
                    <td className="flow-head-col"><b>Previous Pending</b></td>
                    <td className="fee-right"><span className="flow-prevtag">{money(model.prev)}</span></td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    <td className="fee-right"><span className="fee-cell-grey">{money(model.prev)}</span></td>
                    {renderInstCells(prevInst)}
                    {showGiveDisc && <td className="fee-center"><span className="fee-recv-dash">—</span></td>}
                    {showGiveDisc && <td className="fee-right"><span className="flow-final">{money(viewOnly ? model.prev : model.prev - prevPaid)}</span></td>}
                    <td className="fee-center">
                      {viewOnly ? (
                        <span className="fee-paid-amt">{money(prevPaid)}</span>
                      ) : (
                        <input
                          className="flow-input flow-input--pay"
                          type="number"
                          min="0"
                          max={!advancePaymentReceivingOn ? Math.max(0, (+model.prev || 0) - prevPaid) : undefined}
                          value={prevTotalRecv - prevPaid}
                          onChange={e => setHead(prevKey, prevPaid + (Number(e.target.value) || 0))}
                          placeholder="0"
                          disabled={multipleReceivingBlocked}
                        />
                      )}
                    </td>
                    <td className="fee-right">
                      {viewOnly ? (
                        money(Math.max(0, model.prev - prevPaid))
                      ) : (
                        <span className="flow-remain">{money(prevPend)}</span>
                      )}
                    </td>
                  </tr>
                )}
                {/* ADVANCE — non-head-wise me aggregate advance row. Head-wise me credit har
                    head ke Prev/owed me hota hai, is liye ye row nahi. */}
                {!useHeadPrev && advCredit > 0 && (
                  <tr>
                    <td className="flow-head-col"><b>Advance</b></td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    <td className="fee-right"><span className="fee-cell-grey">{money(-advCredit)}</span></td>
                    {renderInstDash()}
                    {showGiveDisc && <td className="fee-center"><span className="fee-recv-dash">—</span></td>}
                    {showGiveDisc && <td className="fee-right"><span className="fee-cell-grey">{money(-advCredit)}</span></td>}
                    <td className="fee-center fee-neg"><b>{money(-advApplied)}</b></td>
                    <td className="fee-right">{money(advCredit - advApplied)}</td>
                  </tr>
                )}
                {/* ── LATE FINE ── bilkul baaki heads jaisi row: Challan Amount
                    read-only (settings + din se khud banti hai, Receiving Date
                    badalne par live update), aur Received/Pending editable —
                    cashier partial fine le sakta hai ya Received 0 kar ke waive. */}
                {fineDue > 0 && (
                  <tr>
                    <td className="flow-head-col">
                      <b>Fine</b>
                      <span className="fee-sub-eq">
                        {fineCalc > 0 || prevFine === 0 ? (
                          <>
                            {fineDays} day{fineDays === 1 ? '' : 's'} late
                            {settings?.fineType === 'daily' ? ` × Rs. ${(+settings.fineAmt || 0).toLocaleString('en-PK')}` : ''}
                          </>
                        ) : null}
                        {/* Pichhle mahino ka fine isi Fine line me (naam nahi badalta). */}
                        {prevFine > 0 && <>{fineCalc > 0 ? <br /> : null}+ previous fine {money(prevFine)}</>}
                      </span>
                    </td>
                    <td className="fee-right"><span className="fee-recv-dash">—</span></td>
                    {/* This Month's Challan me late fine — settings + din se khud banti hai,
                        read-only. Kam/zyada lena ho to "Pay Now" me karta hai. */}
                    <td className="fee-right">{money(fineDue)}</td>
                    <td className="fee-right">0</td>
                    {/* Net = fine − pehle di gayi fine discount (agar ho). */}
                    <td className="fee-right"><span className="fee-cell-grey">{money(fineDueNet)}</span></td>
                    {renderInstDash()}
                    {/* Give Discount tick ho to FINE par bhi discount (fee heads jaisa). */}
                    {showGiveDisc && (
                      <td className="fee-center">
                        {viewOnly ? (
                          fineDiscPrev > 0 ? money(fineDiscPrev) : <span className="fee-recv-dash">—</span>
                        ) : (
                          <input
                            className="flow-input flow-input--disc"
                            id="recv-fine-give"
                            type="number"
                            min="0"
                            max={Math.max(0, fineDueNet - finePaid)}
                            value={fineGiveInput === 0 ? 0 : (fineGiveInput || '')}
                            onChange={e => setFineGive(e.target.value)}
                            placeholder="0"
                            aria-label="Fine discount"
                            disabled={multipleReceivingBlocked}
                          />
                        )}
                      </td>
                    )}
                    {showGiveDisc && <td className="fee-right"><span className="flow-final">{money(viewOnly ? fineDueNet : fineDueNet - fineGive - finePaid)}</span></td>}
                    {/* Pay Now EDITABLE — SIRF is installment ki fine (state me KUL = paid + ye). */}
                    <td className="fee-center">
                      {viewOnly ? (
                        <span className="fee-paid-amt">{money(finePaid)}</span>
                      ) : (
                        <input
                          className="flow-input flow-input--pay"
                          type="number"
                          min="0"
                          max={!advancePaymentReceivingOn ? Math.max(0, fineDueNet - fineGive - finePaid) : undefined}
                          value={fineTotalRecv - finePaid}
                          onChange={e => setFineRecvInput(Math.max(0, finePaid + (Number(e.target.value) || 0)))}
                          placeholder="0"
                          disabled={multipleReceivingBlocked}
                        />
                      )}
                    </td>
                    <td className="fee-right">
                      {viewOnly ? (
                        money(Math.max(0, fineDueNet - finePaid))
                      ) : (
                        <span className="flow-remain">{money(finePend)}</span>
                      )}
                    </td>
                  </tr>
                )}
              </tbody>
              <tfoot>
                <tr className="fee-recv-total">
                  <td className="flow-head-col">Total</td>
                  <td className="fee-right">{flowPrevDues !== 0 ? money(flowPrevDues) : '—'}</td>
                  <td className="fee-right">{money(flowChallan)}</td>
                  <td className="fee-right">{money(totalDisc)}</td>
                  <td className="fee-right">{money(flowNet)}</td>
                  {(payments || []).map((p, i) => {
                    const received = rows.reduce((a, r) => a + (r.installments[i] ? r.installments[i].received : 0), 0)
                      + (aggPrevShown && prevInst[i] ? prevInst[i].received : 0);
                    const remaining = rows.reduce((a, r) => a + (r.installments[i] ? r.installments[i].remainingAfter : 0), 0)
                      + (aggPrevShown && prevInst[i] ? prevInst[i].remainingAfter : 0);
                    return (
                      <React.Fragment key={p.id || i}>
                        <td className="fee-right flow-inst-col">{money(received)}</td>
                        <td className="fee-right flow-inst-col">{money(remaining)}</td>
                      </React.Fragment>
                    );
                  })}
                  {showGiveDisc && <td className="fee-center">{money(flowGiveDisc)}</td>}
                  {showGiveDisc && <td className="fee-right">{money(flowFinal)}</td>}
                  <td className="fee-center">{money(viewOnly ? lastRecvTotal : receivingNow)}</td>
                  <td className="fee-right">{money(remainAfter)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
          <div className="fee-recv-flow-hint">
            <i className="fa-solid fa-circle-info"></i>
            <span>
              Previous Dues + This Month&apos;s Challan − Discount = Net Payable
              {(() => {
                if (viewOnly) return ' · Last Received = latest receiving only · Remaining = balance after all installments';
                const payLbl = 'Pay Now';
                return showGiveDisc
                  ? ` · Net Payable − Give Discount = Final Net Payable · Final Net Payable − ${payLbl} = Remaining`
                  : ` · Net Payable − ${payLbl} = Remaining`;
              })()}
            </span>
          </div>

          <div className="fee-recv-paystrip">
            <div className="fee-recv-paycard">
              <span className="fee-recv-paylbl">Total Net Payable</span>
              <span className="fee-recv-payval">{money(totalAmt)}</span>
            </div>
            <div className="fee-recv-paycard">
              <span className="fee-recv-paylbl">Already Received</span>
              <span className="fee-recv-payval green">{money(alreadyPaid)}</span>
            </div>
            <div className="fee-recv-paycard">
              {/* MINUS = correction, wasooli nahi — label aur rang dono badal jaate hain. */}
              <span className="fee-recv-paylbl">{receivingNow < 0 ? 'Adjustment' : 'Receiving Now'}</span>
              <span className={`fee-recv-payval ${receivingNow < 0 ? 'red' : 'blue'}`}>{money(receivingNow)}</span>
            </div>
            <div className="fee-recv-paycard">
              <span className="fee-recv-paylbl">Remaining After</span>
              <span className="fee-recv-payval red">{money(remainAfter)}</span>
            </div>
          </div>

          {payments && payments.length > 0 && (
            <div style={{ marginTop: 18 }}>
              <div className="fee-recv-hist-title" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span><i className="fa-solid fa-clock-rotate-left"></i> Payment History</span>
                {onDownloadPayment && payments.length > 0 && (
                  <ReceiptDownloadButton
                    payments={payments}
                    onPick={(p, combinedFlag) => onDownloadPayment(p, combinedFlag)}
                  />
                )}
              </div>
              <div className="fee-stbl-wrap" style={{ marginTop: 8 }}>
                <table className="fee-stbl fee-recv-hist">
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Date &amp; Time</th>
                      <th>Method</th>
                      <th>Reference</th>
                      <th className="fee-right">Amount</th>
                      <th className="fee-center">Source</th>
                      {(onEditPayment || onDownloadPayment) && <th className="fee-center">Actions</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {payments.filter(p => !String(p.id || '').startsWith('stored-give-')).map((p, i) => {
                      /* OneLink / bank installments can't be re-allocated from here. */
                      const locked = p.source === 'onelink' || p.source === 'bank';
                      return (
                      <tr key={p.id || i}>
                        <td className="fee-num">{i + 1}</td>
                        <td>
                          {p.date}
                          {p.time && <span className="fee-sub-eq">{fmtTime12(p.time)}</span>}
                        </td>
                        <td>{p.method}</td>
                        <td>{p.ref || p.txn || '—'}</td>
                        <td className="fee-right"><b>{money(p.amount)}</b></td>
                        <td className="fee-center">
                          <span className={`fee-chip ${p.source === 'onelink' || p.source === 'bank' ? 'fee-chip-active' : ''}`}>
                            {p.source === 'onelink' || p.source === 'bank' ? 'OneLink' : 'Counter'}
                          </span>
                        </td>
                        {(onEditPayment || onDownloadPayment) && (
                          <td className="fee-center">
                            <div className="fee-recv-acts">
                              {onEditPayment && (
                                <Tooltip text={locked ? 'OneLink / bank payments cannot be edited here' : 'Edit this installment'}>
                                  <button type="button" className="fee-iconbtn tiny" disabled={locked} onClick={() => onEditPayment(p)}>
                                    <i className="fa-solid fa-pen"></i>
                                  </button>
                                </Tooltip>
                              )}
                              {onDownloadPayment && (
                                <Tooltip text="Download this installment's receipt">
                                  <button type="button" className="fee-iconbtn tiny" onClick={() => onDownloadPayment(p, false)}>
                                    <i className="fa-solid fa-download"></i>
                                  </button>
                                </Tooltip>
                              )}
                            </div>
                          </td>
                        )}
                      </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard and close">
            <button className="fee-btn fee-btn-ghost" onClick={onClose}>{viewOnly ? 'Close' : 'Cancel'}</button>
          </Tooltip>
          {!viewOnly && (
            <Tooltip text={multipleReceivingBlocked
              ? 'Multiple Receiving is disabled in Fee Settings — this challan already has a payment recorded'
              : (receivingNow < 0
                ? `Reduce recorded received amount by Rs. ${Math.abs(receivingNow).toLocaleString('en-PK')}`
                : `Record Rs. ${receivingNow.toLocaleString('en-PK')} as received`)}>
              <button
                className="fee-btn fee-btn-primary"
                onClick={handleReceive}
                disabled={multipleReceivingBlocked}
                style={multipleReceivingBlocked ? { opacity: .55, cursor: 'not-allowed' } : undefined}
              >
                {receivingNow < 0
                  ? <><i className="fa-solid fa-pen"></i> Update Received</>
                  : <><i className="fa-solid fa-check"></i> Pay Now (Installment {installmentCount + 1})</>}
              </button>
            </Tooltip>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   FEE REMINDER MODAL — push notification composer. 160-char limit
   with live counter, target description, send CTA.
   ═══════════════════════════════════════════════════════════════════ */
function FeeReminderModal({ cfg, onClose, toast }) {
  const DEFAULT_MSG = "Dear Parent, your child's fee for this month is pending. Please pay at your earliest convenience. — School Administration";
  const [msg, setMsg] = useState(DEFAULT_MSG);

  useEffect(() => {
    if (!cfg) return;
    setMsg(DEFAULT_MSG);
  }, [cfg]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const target = cfg.type === 'class'
    ? `${cfg.classMeta.cls} (${cfg.classMeta.sec}) — ${cfg.sm?.unpaid ?? 0} unpaid parent${(cfg.sm?.unpaid ?? 0) === 1 ? '' : 's'}`
    : `${cfg.student?.name} (${cfg.classMeta?.cls} / ${cfg.classMeta?.sec})`;

  const handleSend = async () => {
    if (!msg.trim()) { toast('Reminder message cannot be empty', 'error'); return; }
    await feeService.sendFeeReminder({ target, message: msg, period: cfg.period }).catch(() => { });
    toast('Fee reminder sent', 'success');
    onClose();
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal sm">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#F59E0B,#D97706)' }}>
              <i className="fa-solid fa-bell"></i>
            </div>
            <div>
              <div className="fee-modal-title">Send Fee Reminder</div>
              <div className="fee-modal-sub">Parent mobile app push notification</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-info">
            <i className="fa-solid fa-circle-info"></i>
            <span>
              This reminder will be sent to fee defaulters who have not paid their fee yet
              through parent mobile app push notification.
            </span>
          </div>

          <div className="fee-field" style={{ marginTop: 12 }}>
            <span className="fee-label">Notification Message</span>
            <textarea
              className="fee-input fee-textarea"
              maxLength={160}
              rows={4}
              value={msg}
              onChange={e => setMsg(e.target.value)}
            />
            <div className="fee-rem-counter">
              <span>{msg.length}</span> / <span>160</span> characters
            </div>
          </div>

          <div className="fee-rem-target">
            <i className="fa-solid fa-bullseye"></i> <strong>Target:</strong> {target}
          </div>
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard and close">
            <button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button>
          </Tooltip>
          <Tooltip text="Send reminder to parents">
            <button className="fee-btn fee-btn-primary" onClick={handleSend}>
              <i className="fa-solid fa-paper-plane"></i> Send Reminder
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   RECEIPT DOWNLOAD BUTTON — a single click when a student has 0/1
   installment (the caller's existing single-slip behaviour is kept
   intact there); a small dropdown (reuses the app's own .fee-ms-menu
   look) offering each individual installment plus "Combined Receipt"
   once there is more than one. onPick(payment, combined) — payment is
   the chosen installment (combined === false) or null (combined ===
   true, all installments together).
   ═══════════════════════════════════════════════════════════════════ */
function ReceiptDownloadButton({ payments, onPick, label = 'Download receipt slip' }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const onDown = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', onDown);
    return () => document.removeEventListener('mousedown', onDown);
  }, [open]);

  if (!payments || payments.length === 0) return null;

  if (payments.length === 1) {
    return (
      <Tooltip text={label}>
        <button type="button" className="fee-iconbtn tiny" onClick={() => onPick(payments[0], false)}>
          <i className="fa-solid fa-download"></i>
        </button>
      </Tooltip>
    );
  }

  return (
    <div className="fee-ms" ref={ref} style={{ display: 'inline-block' }}>
      <Tooltip text="Download receipt — choose an installment or combined">
        <button type="button" className="fee-iconbtn tiny" onClick={() => setOpen(o => !o)}>
          <i className="fa-solid fa-download"></i>
        </button>
      </Tooltip>
      {open && (
        <div className="fee-ms-menu" style={{ left: 'auto', right: 0, minWidth: 260 }}>
          {payments.map((p, i) => (
            <button key={p.id || i} type="button" className="fee-ms-opt" onClick={() => { onPick(p, false); setOpen(false); }}>
              <span className="fee-ms-name">
                Installment {i + 1} <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>({p.date} · {money(p.amount)})</span>
              </span>
            </button>
          ))}
          <button type="button" className="fee-ms-opt" onClick={() => { onPick(null, true); setOpen(false); }}>
            <span className="fee-ms-name"><b>Combined Receipt</b> <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>(all installments)</span></span>
          </button>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   FEE SLIP MODAL — receipt preview for a single payment, with A4 vs
   Small (thermal/80mm) size picker and a Download / print CTA.
   In `combined` mode (cfg.combined + cfg.allPayments) it instead builds
   one Combined Receipt covering EVERY installment for the student/month
   as a fee-head-wise pivot (one row per head, one column per
   installment + a total), reusing the exact same slip shell + CSS.
   ═══════════════════════════════════════════════════════════════════ */
/* Ek installment ki slip ke per-head rows:
     Std       = is installment se PEHLE us head ka baqaya
                 (challan − manager discount + head previous − pichhli installments ka received+give)
     Discount  = is installment me di gayi Give Discount
     Received  = is installment me wasool
     Remaining = Std − Discount − Received (MINUS = advance)
   Sirf wo heads jin par is installment me kuch hua. Challan na ho to null (purana fallback). */
function installmentSlipRows(challan, payments, payment) {
  const rows = challan && Array.isArray(challan.detailRows) ? challan.detailRows : null;
  if (!rows || !payment) return null;
  const list = payments || [];
  let idx = list.findIndex(p => p === payment || (p.id != null && p.id === payment.id));
  if (idx < 0) idx = list.length;
  const earlier = list.slice(0, idx);
  const norm = (s) => String(s || '').trim().toLowerCase();
  const pick = (obj, name) => {
    const k = Object.keys(obj || {}).find(x => norm(x) === norm(name));
    return k != null ? (+obj[k] || 0) : 0;
  };
  const out = [];
  rows.forEach(r => {
    const name = r.subHead || r.head || '';
    if ((+r.challanAmount || 0) < 0 && isLedgerCarryRow(r)) return;   // advance-consumption row
    const recv = pick(payment.perHead, name);
    const disc = Math.max(0, pick(payment.giveDisc, name));
    const mgr = r._mgrDisc != null ? +r._mgrDisc : (+r.discount || 0) - (r._recvFolded ? (+r.recvDiscount || 0) : 0);
    let before = (+r.challanAmount || 0) - mgr + (feeHeadPrev(r) || 0);
    let earlierPaid = 0;
    earlier.forEach(p => { earlierPaid += pick(p.perHead, name) + Math.max(0, pick(p.giveDisc, name)); });
    before -= earlierPaid;
    /* Is payment me kuch na liya ho magar baqaya ho to bhi head dikhe (Received "—",
       Remaining = baqaya). Poora ada shuda aur ab bhi kuch nahi → chhod do. */
    if (!recv && !disc && Math.round(before) <= 0) return;
    /* _mgr / _first: slip (toggle ON) is head ki PEHLI receiving par manager discount bhi
       dikhaye — Std gross, Discount = manager + give.
       Previous alag column me: is installment se pehle ka previous baqaya. Old-dues head
       par stored previous 0 ho (paid ke baad) to wasooli khud previous hai, advance nahi. */
    const prevNow = isPreviousDuesHead(name)
      ? Math.max(0, Math.round(before) - Math.max(0, Math.round((+r.challanAmount || 0) - mgr)))
      : 0;
    const prev = prevNow > 0 ? prevNow : 0;
    out.push({ name, std: Math.round(before) - prev, disc: Math.round(disc), recv: Math.round(recv), prev, _mgr: Math.round(mgr), _first: earlierPaid === 0 });
  });
  return out.length ? out : null;
}

/* AAKHRI RECEIVING ki slip (pichhle challan par — list ka Download). Installment NUMBER
   par nahi (server khaali purane slot me bhar deta hai, e.g. Others Inst 1 me) — ek receive
   call ke saare heads ek hi waqt save hote hain, is liye installment ka save-time
   (modifiedAt / createdAt, second tak) "ek receiving" pehchanta hai:
     Std       = us receiving se PEHLE ka baqaya (challan − manager disc + carried prev −
                 pehle ki receivings ka received + give)
     Discount  = us receiving ki Give Discount
     Received  = us receiving me liya
     Remaining = Std − Discount − Received (minus = advance)
   Installments na hon (purana record) to null (caller fallback). */
function latestReceivingSlipRows(challan) {
  const rows = challan && Array.isArray(challan.detailRows) ? challan.detailRows : null;
  if (!rows) return null;
  const tsOf = (inst) => String(inst.modifiedAt || inst.createdAt || '').slice(0, 19);
  const hit = (inst) => (+inst.receivedAmount || 0) !== 0 || (+inst.recvDiscount || 0) > 0;
  let latest = '';
  rows.forEach(r => (r.installments || []).forEach(inst => {
    if (!hit(inst)) return;
    const t = tsOf(inst);
    if (t > latest) latest = t;
  }));
  if (!latest) return null;
  const out = [];
  rows.forEach(r => {
    if ((+r.challanAmount || 0) < 0 && isLedgerCarryRow(r)) return;   // advance-consumption row
    let recvNow = 0, discNow = 0, before = 0;
    (r.installments || []).forEach(inst => {
      if (!hit(inst)) return;
      const t = tsOf(inst);
      const recv = +inst.receivedAmount || 0;
      const give = Math.max(0, +inst.recvDiscount || 0);
      if (t === latest) { recvNow += recv; discNow += give; }
      else if (t < latest) before += recv + give;
    });
    const mgr = r._mgrDisc != null ? +r._mgrDisc : (+r.discount || 0) - (r._recvFolded ? (+r.recvDiscount || 0) : 0);
    const std = (+r.challanAmount || 0) - mgr + (feeHeadPrev(r) || 0) - before;
    /* Is receiving me kuch na liya magar baqaya ho to bhi head dikhe (Received "—"). */
    if (!recvNow && !discNow && Math.round(std) <= 0) return;
    const headName = r.subHead || r.head || '';
    const prevNow = isPreviousDuesHead(headName)
      ? Math.max(0, Math.round(std) - Math.max(0, Math.round((+r.challanAmount || 0) - mgr - before)))
      : 0;
    const prev = prevNow > 0 ? prevNow : 0;
    out.push({ name: headName, std: Math.round(std) - prev, disc: Math.round(discNow), recv: Math.round(recvNow), prev, _mgr: Math.round(mgr), _first: before === 0 });
  });
  return out.length ? out : null;
}

function FeeSlipModal({ cfg, onClose, toast }) {
  const [size, setSize] = useState('a4');
  const [theme, setTheme] = useState('color'); // 'color' | 'bw'
  /* Show Discount on Challan (column choice) — installment slip par manager discount ke liye. */
  const { data: slipSettings } = useAsync(feeService.getFeeSettings, []);

  useEffect(() => { if (cfg) setSize(cfg.defaultSize || 'a4'); }, [cfg]);
  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const { classMeta, student, period, combined, allPayments } = cfg;
  /* combined mode me payment null hota hai — har jagah safe access ke liye {}. */
  const payment = cfg.payment || {};
  /* ── Combined Receipt (fee-head-wise pivot across all installments) ──
     Har installment ka apna perHead column, plus per-head total. Ye sirf
     combined===true par banti hai; warna khali reh kar niche ka pura
     single-slip hisaab jyun ka tyun chalta hai (koi behaviour change nahi). */
  const combinedRows  = combined ? (allPayments || []) : [];
  const combinedTotal = combinedRows.reduce((a, p) => a + (+p.amount || 0), 0);
  const headWiseNames = combined
    ? [...new Set(combinedRows.flatMap(p => Object.keys(p.perHead || {})))]
    : [];
  const headWiseRows = headWiseNames.map(name => ({
    name,
    perInstallment: combinedRows.map(p => +(p.perHead?.[name]) || 0),
    total: combinedRows.reduce((a, p) => a + (+(p.perHead?.[name]) || 0), 0),
  }));
  /* Challan ke detailRows se per-head Standard (net) / Discount / Received banao — taake
     slip me sirf received nahi, poora breakup dikhe. Challan na mile to fallback: sirf
     received (perHead). */
  const chRows = cfg.challan && Array.isArray(cfg.challan.detailRows) ? cfg.challan.detailRows : null;
  /* Stored "Previous Pending" GENERATION-time snapshot hai — pichhle mahine ki receiving
     baad me ho to stale (jaise 13,850 jabke asal 6,850). Receiving component live value
     (running-ledger) cfg.prevStd me bhejta hai; mile to prev row ka Std usse override. */
  const prevStdOverride = (typeof cfg.prevStd === 'number') ? Math.round(cfg.prevStd) : null;
  const isPrevLabel = (r) => /previous\s*pending|arrear/.test(String(r.subHead || r.head || '').toLowerCase());
  /* Per-head previous (previousPendingorAdv) available ho to slip HEAD-WISE: aggregate
     "Previous Pending" row hata kar har head ka previous "Pending" me jodte hain (challan jaisa). */
  const hasHeadPrev = !cfg.instRows && Array.isArray(chRows) && chRows.some(r => !isPrevLabel(r) && (feeHeadPrev(r) || 0) !== 0);
  /* Installment slip: rows pehle se bane hue (installmentSlipRows) — Std = pehle ka baqaya.
     "Show Discount on Challan" ON ho to head ki PEHLI receiving par Discount Manager wala
     discount bhi: Std = gross (4,000), Discount = manager + give (1,000 + 500). Baad ki
     receivings par manager pehle hi gin chuka — sirf give. */
  const showMgrDisc = (slipSettings || {}).showDiscount !== false;
  const baseRows = cfg.instRows
    ? cfg.instRows.map(r => ((showMgrDisc && r._first && (r._mgr || 0) > 0)
      ? { ...r, std: r.std + r._mgr, disc: r.disc + r._mgr }
      : { ...r }))
    : chRows
    ? chRows
      .filter(r => !(hasHeadPrev && isPrevLabel(r)))
      .map(r => {
        const isPrev = isPrevLabel(r);
        let std = Math.round(+r.challanAmount || 0);   // ORIGINAL standard fee (discount se pehle)
        if (isPrev && prevStdOverride != null) std = prevStdOverride;
        const disc = Math.round(+r.discount || 0);
        const recv = Math.round(+r.receivedAmount || 0);
        const prev = hasHeadPrev ? Math.round(+(feeHeadPrev(r)) || 0) : 0;
        return { name: r.subHead || r.head || '—', std, disc, recv, prev };
      })
    : Object.entries(payment.perHead || {}).map(([name, amt]) => ({ name, std: Math.round(+amt || 0), disc: 0, recv: Math.round(+amt || 0), prev: 0 }));

  /* Slip par per-head previous = challan ki apni `previousPendingorAdv` (feeHeadPrev) — ye
     RECEIPT hai, is liye jitna previous BILL hua tha (aur ab received me shamil) wahi sahi
     source hai. Running-ledger byHead post-receiving 0 ho jaati hai (previous pay ho gaya),
     is liye slip par use NAHI karte — warna Tuition/Transport ka Received me previous to hai
     magar Prev 0 ho kar Remaining ghalat minus (−3,000) dikhta tha. Phir credit heads
     (advance ne fee cover ki) ko "covered" + ek "Advance Applied" (minus) line. */
  if (hasHeadPrev && Array.isArray(chRows)) {
    /* Fully-paid head ka backend previousPendingorAdv 0 ho jaata hai, magar uska Received me
       previous (jo BILL hua tha) shamil hota hai → Remaining ghalat minus (−3,000). Is liye
       receiving ke WAQT ka original per-head previous (payment.prevByHead — save ke waqt model
       se store hua) mile to us head ka Prev usi se set karo. Jahan mile wahi override — warna
       feeHeadPrev jaisा hai waisा (kabhi zero nahi). */
    const srcByHead = (payment && payment.prevByHead && typeof payment.prevByHead === 'object' && Object.keys(payment.prevByHead).length)
      ? payment.prevByHead
      : ((cfg.prevByHead && typeof cfg.prevByHead === 'object') ? cfg.prevByHead : null);
    if (srcByHead) {
      const norm = (s) => String(s || '').toLowerCase().trim();
      const keys = Object.keys(srcByHead);
      baseRows.forEach(r => {
        const key = keys.find(k => norm(k) === norm(r.name));
        if (key != null) r.prev = Math.round(srcByHead[key]);   // mile → use; warna feeHeadPrev
      });
    }
    let hasCredit = false;
    baseRows.forEach(r => {
      if (((r.std - r.disc) + (r.prev || 0)) < 0 && (r.prev || 0) < 0) { r.recv = r.std - r.disc; hasCredit = true; }
    });
    if (hasCredit) {
      const coveredRecv = baseRows.reduce((a, r) => a + r.recv, 0);
      const feeCash = Math.round(+payment.amount || 0) - Math.max(0, Math.round(+payment.fine || 0));
      const advApplied = coveredRecv - feeCash;
      if (advApplied > 0) baseRows.push({ name: 'Advance Applied', std: 0, disc: 0, recv: -advApplied, prev: 0, isAdvance: true });
    }
  }

  /* ── LATE FINE ki alag line ──
     Backend fine ko ledger me persist nahi karta, is liye detailRows me nahi
     aati. Jo fine is receiving me li gayi wo `payment.fine` me hai; na ho to
     amount aur heads ke farq se nikaal lo — warna slip par "Amount Received"
     heads ke Total se zyada dikhta hai aur parent ko wajah samajh nahi aati.
     Agar challan me pehle se Late Fine row maujood ho to dobara na jodo. */
  const fineAlready = baseRows.some(r => {
    const n = String(r.name).trim().toLowerCase();
    return n === 'late fine' || n === 'fine';
  });
  const baseRecv = baseRows.reduce((a, r) => a + r.recv, 0);
  const slipFine = Math.max(0, Math.round(+payment.fine || 0) || (Math.round(+payment.amount || 0) - baseRecv));
  const headRows = (!fineAlready && slipFine > 0)
    ? [...baseRows, (() => {
      /* Fine par is payment ki Give Discount (agar di) — Std = fine, Disc = discount. */
      const fk = Object.keys(payment.giveDisc || {}).find(k => feeService.isLateFineRow({ subHead: k }));
      const fd = fk ? Math.max(0, Math.round(+payment.giveDisc[fk] || 0)) : 0;
      return { name: 'Fine', std: slipFine + fd, disc: fd, recv: slipFine, prev: 0 };
    })()]
    : baseRows;
  /* Previous-dues head (Old Dues Till Date, Previous Due, …) par challan amount 0 hota
     hai. Paid ke baad previous field bhi 0 ho jati hai, is liye Received poora
     Remaining me minus (advance) dikhta tha. Wo raqam Previous Dues hai. */
  headRows.forEach(r => {
    if (r.isAdvance) return;
    const challanNet = (r.std || 0) - (r.disc || 0);
    const gap = (r.recv || 0) - (challanNet + (r.prev || 0));
    /* Challan amount khali ho, ya head khud previous/old dues ho, to minus advance nahi —
       wo Previous Dues column me jaata hai. */
    if (gap > 0 && (challanNet <= 0 || isPreviousDuesHead(r.name))) r.prev = (r.prev || 0) + gap;
  });
  const totStd = headRows.reduce((a, r) => a + r.std, 0);
  const totPrev = headRows.reduce((a, r) => a + (r.prev || 0), 0);
  const totDisc = headRows.reduce((a, r) => a + r.disc, 0);
  const total = headRows.reduce((a, r) => a + r.recv, 0);
  /* "Amount Received": challan-wali (cumulative) slip par KUL wasooli (table ke Received
     total jaisi) — 2nd installment me full ho jaye to poori raqam dikhe, sirf is
     installment ki nahi. Installment slip / challan-less fallback par is payment ki raqam. */
  const slipAmount = (chRows && !cfg.instRows) ? total : (+payment.amount || 0);
  /* Pending per head = OWED − Received, jahan owed = (Std − Disc) + us head ka previous.
     > 0 → baqaya; = 0 → poora paid (current + previous dono); < 0 → owed se bhi zyada liya =
     ADVANCE. Pehle yahan galti thi: dueRem 0 (poora paid) par bhi neeche `overAdv` (−4,000)
     return ho jaata tha — is liye fully-paid head par galat minus dikhta tha. */
  const pendingOf = (r) => r.isAdvance ? 0 : ((r.std - r.disc) - r.recv + (r.prev || 0));
  const remaining = headRows.reduce((a, r) => a + pendingOf(r), 0);
  const rowRem = pendingOf;
  const remCell = (r) => { const x = pendingOf(r); return x !== 0 ? x.toLocaleString('en-PK') : '—'; };
  const totRemTxt = remaining !== 0 ? remaining.toLocaleString('en-PK') : '—';
  const sch = feeReportSchool(cfg.school);

  const doPrint = () => {
    const w = window.open('', '_blank');
    if (!w) { toast('Please allow pop-ups to download the slip', 'error'); return; }
    const slipHtml = combined ? `
      <div class="fee-slip-doc fee-slip-${size}">
        <span class="fee-slip-paid-stamp">Paid</span>
        <div class="fee-slip-brandhead">
          <div class="fee-slip-brand">
            <div class="fee-slip-logo">${feeReportLogoHtml(sch)}</div>
            <div>
              <div class="fee-slip-school">${escHtml(sch.name)}</div>
              <div class="fee-slip-tag">Combined Fee Receipt</div>
              ${sch.address ? `<div class="fee-slip-addr">${escHtml(sch.address)}</div>` : ''}
              ${sch.session ? `<div class="fee-slip-addr">Academic Session: ${escHtml(sch.session)}</div>` : ''}
            </div>
          </div>
          <div class="fee-slip-meta">Generated: ${escHtml(feeReportDate(sch))}<br/>By: ${escHtml(sch.generatedBy)}</div>
        </div>
        <div class="fee-slip-kv">
          <span class="k">Period</span><span class="v">${escHtml(period)}</span>
          <span class="k">Student</span><span class="v">${escHtml(student.name)}</span>
          <span class="k">Father</span><span class="v">${escHtml(student.father || '—')}</span>
          <span class="k">Class</span><span class="v">${escHtml(classMeta.cls)} (${escHtml(classMeta.sec)})</span>
          <span class="k">Reg No</span><span class="v">${escHtml(student.reg)}</span>
          <span class="k">Installments</span><span class="v">${combinedRows.length}</span>
        </div>
        <table class="fee-slip-tbl fee-slip-heads">
          <thead><tr><th>Fee Head</th>${combinedRows.map((p, i) => `<th>Inst. ${i + 1}</th>`).join('')}<th>Total</th></tr></thead>
          <tbody>
            ${headWiseRows.map(r => `<tr><td>${escHtml(headLabel(r.name))}</td>${r.perInstallment.map(v => `<td>${v.toLocaleString('en-PK')}</td>`).join('')}<td><b>${r.total.toLocaleString('en-PK')}</b></td></tr>`).join('')}
          </tbody>
        </table>
        <table class="fee-slip-tbl fee-slip-heads" style="margin-top:8px">
          <thead><tr><th>#</th><th>Date</th><th>Method</th><th>Amount</th></tr></thead>
          <tbody>
            ${combinedRows.map((p, i) => `<tr><td>${i + 1}</td><td>${escHtml(p.date)}${p.time ? '  ·  ' + escHtml(fmtTime12(p.time)) : ''}</td><td>${escHtml(p.method || 'Cash')}</td><td>${(+p.amount || 0).toLocaleString('en-PK')}</td></tr>`).join('')}
            <tr class="fee-slip-headtot"><td colspan="3">Total Received</td><td>${combinedTotal.toLocaleString('en-PK')}</td></tr>
          </tbody>
        </table>
        <div class="fee-slip-net">
          <span>Total Received</span><span>Rs. ${combinedTotal.toLocaleString('en-PK')}</span>
        </div>
        <div class="fee-slip-foot">Computer generated receipt — ${escHtml(sch.name)} · Combined Fee Receipt · ${escHtml(feeReportDate(sch))} · By: ${escHtml(sch.generatedBy)}</div>
      </div>` : `
      <div class="fee-slip-doc fee-slip-${size}">
        <span class="fee-slip-paid-stamp">Paid</span>
        <div class="fee-slip-brandhead">
          <div class="fee-slip-brand">
            <div class="fee-slip-logo">${feeReportLogoHtml(sch)}</div>
            <div>
              <div class="fee-slip-school">${escHtml(sch.name)}</div>
              <div class="fee-slip-tag">Fee Received Slip</div>
              ${sch.address ? `<div class="fee-slip-addr">${escHtml(sch.address)}</div>` : ''}
              ${sch.session ? `<div class="fee-slip-addr">Academic Session: ${escHtml(sch.session)}</div>` : ''}
            </div>
          </div>
          <div class="fee-slip-meta">Generated: ${escHtml(feeReportDate(sch))}<br/>By: ${escHtml(sch.generatedBy)}</div>
        </div>
        <div class="fee-slip-kv">
          <span class="k">Receipt No</span><span class="v">${escHtml(payment.id || `RCV-${Date.now()}`)}</span>
          <span class="k">Date</span><span class="v">${escHtml(payment.date)}${payment.time ? `  ·  ${escHtml(fmtTime12(payment.time))}` : ''}</span>
          <span class="k">Period</span><span class="v">${escHtml(period)}</span>
          <span class="k">Student</span><span class="v">${escHtml(student.name)}</span>
          <span class="k">Father</span><span class="v">${escHtml(student.father || '—')}</span>
          <span class="k">Class</span><span class="v">${escHtml(classMeta.cls)} (${escHtml(classMeta.sec)})</span>
          <span class="k">Reg No</span><span class="v">${escHtml(student.reg)}</span>
          <span class="k">Method</span><span class="v">${escHtml(payment.method)}</span>
          ${payment.ref ? `<span class="k">Reference</span><span class="v">${escHtml(payment.ref)}</span>` : ''}
          ${payment.txn ? `<span class="k">Transaction</span><span class="v">${escHtml(payment.txn)}</span>` : ''}
        </div>
        <table class="fee-slip-tbl fee-slip-heads">
          <thead><tr><th>Head</th><th>Previous Dues</th><th>Std. Amount</th><th>Discount</th><th>Received</th><th>Remaining</th></tr></thead>
          <tbody>
            ${headRows.map(r => `<tr><td>${escHtml(headLabel(r.name))}</td><td>${r.isAdvance ? '—' : ((r.prev || 0) ? (r.prev || 0).toLocaleString('en-PK') : '—')}</td><td>${r.isAdvance ? '—' : r.std.toLocaleString('en-PK')}</td><td>${r.isAdvance ? '—' : (r.disc ? r.disc.toLocaleString('en-PK') : '—')}</td><td>${r.recv ? r.recv.toLocaleString('en-PK') : '—'}</td><td>${remCell(r)}</td></tr>`).join('')}
            <tr class="fee-slip-headtot"><td>Total</td><td>${totPrev ? totPrev.toLocaleString('en-PK') : '—'}</td><td>${totStd.toLocaleString('en-PK')}</td><td>${totDisc ? totDisc.toLocaleString('en-PK') : '—'}</td><td>${total.toLocaleString('en-PK')}</td><td>${totRemTxt}</td></tr>
          </tbody>
        </table>
            <div class="fee-slip-net">
          <span>Amount Received</span><span>Rs. ${slipAmount.toLocaleString('en-PK')}</span>
        </div>
        <div class="fee-slip-foot">Computer generated receipt — ${escHtml(sch.name)} · Fee Received Slip · ${escHtml(feeReportDate(sch))} · By: ${escHtml(sch.generatedBy)}</div>
      </div>`;
    w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Fee Slip — ${escHtml(student.name)}</title>
<style>
  html,body,* { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; color-adjust:exact !important; }
  body { margin:0; font-family:'Plus Jakarta Sans','Segoe UI',Arial,sans-serif; background:#F1F3F8; padding:18px; }
  .fee-slip-doc { position:relative; background:#fff; color:#111; border:1px solid #93C5FD; border-radius:12px; padding:20px; max-width:420px; margin:0 auto; }
  .fee-slip-doc.fee-slip-small { max-width:302px; padding:14px 12px; font-size:11px; }
  .fee-slip-paid-stamp { position:absolute; top:14px; right:16px; border:3px double #16A34A; color:#16A34A; font-size:15px; font-weight:900; letter-spacing:2px; padding:4px 10px; border-radius:6px; transform:rotate(-12deg); opacity:.85; text-transform:uppercase; }
  .fee-slip-doc.fee-slip-small .fee-slip-paid-stamp { font-size:11px; padding:3px 7px; top:8px; right:8px; letter-spacing:1px; border-width:2px; }
  .fee-slip-brandhead { display:flex; justify-content:space-between; align-items:flex-start; gap:10px; border-bottom:2px solid #1E3A8A; background:linear-gradient(135deg,rgba(30,58,138,.06),transparent); padding:10px 8px; margin:-20px -20px 12px; border-radius:12px 12px 0 0; }
  .fee-slip-brand { display:flex; align-items:center; gap:10px; text-align:left; }
  .fee-slip-logo { width:38px; height:38px; border:1px solid #ddd; border-radius:10px; display:flex; align-items:center; justify-content:center; overflow:hidden; color:#1E3A8A; font-weight:800; background:#fff; flex-shrink:0; }
  .fee-slip-logo img { width:100%; height:100%; object-fit:contain; }
  .fee-slip-school { font-size:15px; font-weight:800; color:#1E3A8A; }
  .fee-slip-tag { font-size:10.5px; color:#1E40AF; letter-spacing:1px; text-transform:uppercase; margin-top:2px; font-weight:600; }
  .fee-slip-addr { font-size:10.5px; color:#666; margin-top:2px; }
  .fee-slip-meta { font-size:10px; color:#666; text-align:right; line-height:1.55; white-space:nowrap; }
  .fee-slip-kv { display:grid; grid-template-columns:auto 1fr; gap:4px 10px; font-size:12px; margin-bottom:12px; }
  .fee-slip-kv .k { color:#666; }
  .fee-slip-kv .v { text-align:right; font-weight:700; color:#111; }
  .fee-slip-tbl { width:100%; border-collapse:collapse; font-size:11.5px; margin-bottom:10px; }
  .fee-slip-tbl th, .fee-slip-tbl td { border-bottom:1px solid #DBEAFE; padding:5px 4px; text-align:right; }
  .fee-slip-tbl th:first-child, .fee-slip-tbl td:first-child { text-align:left; }
  .fee-slip-tbl th { background:#1E3A8A; color:#fff; border-bottom:none; }
  .fee-slip-headtot td { border-top:1.5px solid #1E3A8A; border-bottom:none; font-weight:800; background:#EFF6FF; color:#1E3A8A; }
  .fee-slip-net { display:flex; justify-content:space-between; align-items:center; background:linear-gradient(135deg,#1E3A8A,#1D4ED8); color:#fff; padding:8px 12px; border-radius:4px; font-weight:800; }
  .fee-slip-foot { margin-top:14px; text-align:center; font-size:9px; color:#999; border-top:1px solid #eee; padding-top:8px; }

  /* Small Receipt — 80mm par header side-by-side nahi samaata, is liye sab
     center me ek ke neeche ek (bilkul wahi jo preview me dikhta hai). */
  .fee-slip-small .fee-slip-brandhead { flex-direction:column; align-items:center; text-align:center; gap:6px; padding:8px 6px; margin:-14px -12px 10px; border-radius:8px 8px 0 0; }
  .fee-slip-small .fee-slip-brand { flex-direction:column; align-items:center; text-align:center; gap:6px; }
  .fee-slip-small .fee-slip-logo { width:34px; height:34px; border-radius:8px; }
  .fee-slip-small .fee-slip-school { font-size:13.5px; line-height:1.25; }
  .fee-slip-small .fee-slip-tag { font-size:9.5px; letter-spacing:.5px; margin-top:2px; }
  .fee-slip-small .fee-slip-addr { font-size:9.5px; line-height:1.35; }
  .fee-slip-small .fee-slip-meta { text-align:center; white-space:normal; font-size:9.5px; line-height:1.4; }
  .fee-slip-small .fee-slip-kv { font-size:10.5px; gap:3px 8px; margin-bottom:10px; }
  .fee-slip-small .fee-slip-tbl { font-size:9.5px; }
  .fee-slip-small .fee-slip-tbl th, .fee-slip-small .fee-slip-tbl td { padding:4px 2px; }
  .fee-slip-small .fee-slip-tbl th { font-size:8.5px; line-height:1.2; }
  .fee-slip-small .fee-slip-tbl td:first-child { word-break:break-word; }
  .fee-slip-small .fee-slip-net { padding:7px 10px; font-size:11.5px; }
  .fee-slip-small .fee-slip-foot { font-size:8px; margin-top:10px; padding-top:6px; }

  /* Colorless — genuine low-ink redesign, same convention as the fee
     challan (FEE_CHALLAN_CSS_SCOPED) and every report across the ERP. */
  body.fee-bw .fee-slip-doc { border-color:#ddd; }
  body.fee-bw .fee-slip-paid-stamp { border-color:#000; color:#000; }
  body.fee-bw .fee-slip-brandhead { border-bottom:1.5px solid #111; background:none; margin:0 0 12px; padding:0 0 10px; border-radius:0; }
  body.fee-bw .fee-slip-small .fee-slip-brandhead { margin:0 0 10px; padding:0 0 8px; }
  body.fee-bw .fee-slip-school { color:#111; }
  body.fee-bw .fee-slip-tag { color:#555; font-weight:500; }
  body.fee-bw .fee-slip-tbl th, body.fee-bw .fee-slip-tbl td { border-bottom-color:#eee; }
  body.fee-bw .fee-slip-tbl th { background:none; color:#333; border-bottom:1.5px solid #333; }
  body.fee-bw .fee-slip-headtot td { border-top-color:#333; background:#f5f7fb; color:#111; }
  body.fee-bw .fee-slip-net { background:#111; color:#fff; }

  /* Thermal roll par A4 page size receipt ko beech me chhota sa chhaap kar
     baaki safha zaya kar deta tha — 80mm par page bhi 80mm ka. */
  ${size === 'small'
        ? '@page { size:80mm auto; margin:0; }\n  @media print { body { background:#fff; padding:0; } .fee-slip-doc.fee-slip-small { max-width:none; width:80mm; border:0; border-radius:0; margin:0; padding:4mm 3mm; } body:not(.fee-bw) .fee-slip-doc.fee-slip-small .fee-slip-brandhead { margin:-4mm -3mm 10px; border-radius:0; } }'
        : '@page { size:A4; margin:14mm; }\n  @media print { body { background:#fff; padding:0; } }'}
</style></head><body${theme === 'bw' ? ' class="fee-bw"' : ''}>${slipHtml}</body></html>`);
    w.document.close();
    w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    toast('Slip ready — use your browser\'s Save as PDF.', 'success');
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#16A34A,#15803D)' }}>
              <i className="fa-solid fa-receipt"></i>
            </div>
            <div>
              <div className="fee-modal-title">{combined ? 'Combined Fee Receipt' : 'Fee Received Slip'}</div>
              <div className="fee-modal-sub">{student.name} · {classMeta.cls} ({classMeta.sec}) · {period}</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-dl-label">Slip Size</div>
          <div className="fee-dl-fmt-grid">
            <button type="button" className={`fee-dl-fmt${size === 'a4' ? ' sel' : ''}`} onClick={() => setSize('a4')}>
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(30,58,138,.1)', color: '#1E3A8A' }}>
                <i className="fa-solid fa-file-lines"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">A4 Size</div>
                <div className="fee-dl-desc">Full-page receipt</div>
              </div>
            </button>
            <button type="button" className={`fee-dl-fmt${size === 'small' ? ' sel' : ''}`} onClick={() => setSize('small')}>
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(22,163,74,.1)', color: '#16A34A' }}>
                <i className="fa-solid fa-receipt"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">Small Receipt</div>
                <div className="fee-dl-desc">Thermal / 80mm</div>
              </div>
            </button>
          </div>

          <div className="fee-dl-label" style={{ marginTop: 16 }}>Slip Theme</div>
          <div className="fee-dl-fmt-grid">
            <button type="button" className={`fee-dl-fmt${theme === 'color' ? ' sel' : ''}`} onClick={() => setTheme('color')}>
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(30,58,138,.1)', color: '#1E3A8A' }}>
                <i className="fa-solid fa-palette"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">Colorful</div>
                <div className="fee-dl-desc">Brand-colour receipt</div>
              </div>
            </button>
            <button type="button" className={`fee-dl-fmt${theme === 'bw' ? ' sel' : ''}`} onClick={() => setTheme('bw')}>
              <div className="fee-dl-fmt-ic" style={{ background: 'rgba(55,65,81,.1)', color: '#374151' }}>
                <i className="fa-solid fa-circle-half-stroke"></i>
              </div>
              <div>
                <div className="fee-dl-fmt-name">Colorless</div>
                <div className="fee-dl-desc">Low-ink printing</div>
              </div>
            </button>
          </div>

          <div className="fee-dl-label" style={{ marginTop: 16 }}>Preview</div>
          <div className={`fee-slip-doc fee-slip-${size}${theme === 'bw' ? ' fee-bw' : ''}`}>
            <span className="fee-slip-paid-stamp">Paid</span>
            <div className="fee-slip-brandhead">
              <div className="fee-slip-brand">
                <div className="fee-slip-logo">
                  {sch.logo
                    ? <img src={sch.logo} alt={`${sch.name} logo`} />
                    : sch.monogram}
                </div>
                <div>
                  <div className="fee-slip-school">{sch.name}</div>
                  <div className="fee-slip-tag">{combined ? 'Combined Fee Receipt' : 'Fee Received Slip'}</div>
                  {sch.address && <div className="fee-slip-addr">{sch.address}</div>}
                  {sch.session && <div className="fee-slip-addr">Academic Session: {sch.session}</div>}
                </div>
              </div>
              <div className="fee-slip-meta">Generated: {feeReportDate(sch)}<br />By: {sch.generatedBy}</div>
            </div>
            {combined ? (
              <>
                <div className="fee-slip-kv">
                  <span className="k">Period</span><span className="v">{period}</span>
                  <span className="k">Student</span><span className="v">{student.name}</span>
                  <span className="k">Father</span><span className="v">{student.father || '—'}</span>
                  <span className="k">Class</span><span className="v">{classMeta.cls} ({classMeta.sec})</span>
                  <span className="k">Reg No</span><span className="v">{student.reg}</span>
                  <span className="k">Installments</span><span className="v">{combinedRows.length}</span>
                </div>
                <table className="fee-slip-tbl fee-slip-heads">
                  <thead>
                    <tr>
                      <th>Fee Head</th>
                      {combinedRows.map((p, i) => <th key={p.id || i}>Inst. {i + 1}</th>)}
                      <th>Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {headWiseRows.map(r => (
                      <tr key={r.name}>
                        <td>{headLabel(r.name)}</td>
                        {r.perInstallment.map((v, i) => <td key={i}>{v.toLocaleString('en-PK')}</td>)}
                        <td><b>{r.total.toLocaleString('en-PK')}</b></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <table className="fee-slip-tbl fee-slip-heads" style={{ marginTop: 8 }}>
                  <thead>
                    <tr><th>#</th><th>Date</th><th>Method</th><th>Amount</th></tr>
                  </thead>
                  <tbody>
                    {combinedRows.map((p, i) => (
                      <tr key={p.id || i}><td>{i + 1}</td><td>{p.date}{p.time ? `  ·  ${fmtTime12(p.time)}` : ''}</td><td>{p.method || 'Cash'}</td><td>{(+p.amount || 0).toLocaleString('en-PK')}</td></tr>
                    ))}
                    <tr className="fee-slip-headtot"><td colSpan={3}>Total Received</td><td>{combinedTotal.toLocaleString('en-PK')}</td></tr>
                  </tbody>
                </table>
                <div className="fee-slip-net">
                  <span>Total Received</span>
                  <span>Rs. {combinedTotal.toLocaleString('en-PK')}</span>
                </div>
                <div className="fee-slip-foot">Computer generated receipt — {sch.name} · Combined Fee Receipt · {feeReportDate(sch)} · By: {sch.generatedBy}</div>
              </>
            ) : (
              <>
                <div className="fee-slip-kv">
                  <span className="k">Receipt No</span><span className="v">{payment.id || `RCV-${Date.now()}`}</span>
                  <span className="k">Date</span><span className="v">{payment.date}{payment.time ? `  ·  ${fmtTime12(payment.time)}` : ''}</span>
                  <span className="k">Period</span><span className="v">{period}</span>
                  <span className="k">Student</span><span className="v">{student.name}</span>
                  <span className="k">Father</span><span className="v">{student.father || '—'}</span>
                  <span className="k">Class</span><span className="v">{classMeta.cls} ({classMeta.sec})</span>
                  <span className="k">Reg No</span><span className="v">{student.reg}</span>
                  <span className="k">Method</span><span className="v">{payment.method}</span>
                  {payment.ref && <><span className="k">Reference</span><span className="v">{payment.ref}</span></>}
                  {payment.txn && <><span className="k">Transaction</span><span className="v">{payment.txn}</span></>}
                </div>
                <table className="fee-slip-tbl fee-slip-heads">
                  <thead>
                    <tr><th>Head</th><th>Previous Dues</th><th>Std. Amount</th><th>Discount</th><th>Received</th><th>Remaining</th></tr>
                  </thead>
                  <tbody>
                    {headRows.map(r => (
                      <tr key={r.name}><td>{r.name}</td><td>{r.isAdvance ? '—' : ((r.prev || 0) ? (r.prev || 0).toLocaleString('en-PK') : '—')}</td><td>{r.isAdvance ? '—' : r.std.toLocaleString('en-PK')}</td><td>{r.isAdvance ? '—' : (r.disc ? r.disc.toLocaleString('en-PK') : '—')}</td><td>{r.recv ? r.recv.toLocaleString('en-PK') : '—'}</td><td>{remCell(r)}</td></tr>
                    ))}
                    <tr className="fee-slip-headtot"><td>Total</td><td>{totPrev ? totPrev.toLocaleString('en-PK') : '—'}</td><td>{totStd.toLocaleString('en-PK')}</td><td>{totDisc ? totDisc.toLocaleString('en-PK') : '—'}</td><td>{total.toLocaleString('en-PK')}</td><td>{totRemTxt}</td></tr>
                  </tbody>
                </table>
                <div className="fee-slip-net">
                  <span>Amount Received</span>
                  <span>Rs. {slipAmount.toLocaleString('en-PK')}</span>
                </div>
                <div className="fee-slip-foot">Computer generated receipt — {sch.name} · Fee Received Slip · {feeReportDate(sch)} · By: {sch.generatedBy}</div>
              </>
            )}
          </div>
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Close preview">
            <button className="fee-btn fee-btn-ghost" onClick={onClose}>Close</button>
          </Tooltip>
          <Tooltip text="Download / print this slip">
            <button className="fee-btn fee-btn-primary" onClick={doPrint}>
              <i className="fa-solid fa-download"></i> Download Slip
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   FEE RECEIVING TAB — month/year filter, smart search, per-class
   expandable receiver table. Two sub-segments (Individual / Family).
   For Individual: each class row expands to a student-level table
   with previous dues / this-month dues / discount / received /
   remaining / status / action. Actions: "Fee Receive" link (opens
   the FeeReceivingModal), Receive More (partial), View transaction,
   Download Slip (opens FeeSlipModal), Delete manual receipt (confirm).
   ═══════════════════════════════════════════════════════════════════ */

/* Pichhle mahino ka LIVE baqaya/advance per student — RUNNING-LEDGER se (carry-forward
   de-dup, Fee History jaisa). "Latest prior challan ka net−received" wala tareeqa tab
   galat hota hai jab kisi purane mahine ki fee BAAD me receive ho: stored "Previous
   Pending" snapshot stale reh jaata hai aur agla mahina phantom baqaya dikhata hai. Yeh
   har prior mahine ke SIRF naye charges (non-prev rows) − received chalata hai, is liye
   October (September ki receiving ke baad) aur November (October me prev pay karne ke
   baad) dono me sahi baqaya nikalta hai. Returns { [studentID]: { dues, advance } }. */
/* Multi-month challan applied month ko COVER karta hai? Covering = current
   (e.g. Sep–Oct jab Oct view) — previous-dues me mat gino (warna Prev=Std double). */
function ledgerCoversMonth(rec, month, year) {
  if (!rec) return false;
  const m = Number(month) || 0;
  const y = Number(year) || 0;
  if (!m || !y) return false;
  const sm = Number(rec.startMonth) || Number(rec.month) || 0;
  const sy = Number(rec.startYear) || Number(rec.year) || 0;
  const em = Number(rec.endMonth) || Number(rec.month) || sm;
  const ey = Number(rec.endYear) || Number(rec.year) || sy;
  if (!sm || !sy) return false;
  const t = y * 12 + m;
  return t >= (sy * 12 + sm) && t <= (ey * 12 + em);
}

function isMultiMonthChallan(rec) {
  if (!rec) return false;
  if ((Number(rec.totalMonthChallan) || 0) > 1) return true;
  const sm = Number(rec.startMonth) || 0;
  const em = Number(rec.endMonth) || 0;
  const sy = Number(rec.startYear) || 0;
  const ey = Number(rec.endYear) || 0;
  return !!(sm && em && (sm !== em || sy !== ey));
}

/* Two Months+: start month → Current Fee; covered later months (dropdown) → Total Dues.
   e.g. Sep–Oct challan: Sep me Current, Oct me Dues. */
function isMultiMonthNonStartView(rec, month, year) {
  if (!isMultiMonthChallan(rec) || !ledgerCoversMonth(rec, month, year)) return false;
  const sm = Number(rec.startMonth) || Number(rec.month) || 0;
  const sy = Number(rec.startYear) || Number(rec.year) || 0;
  if (!sm || !sy) return false;
  return (Number(year) * 12 + Number(month)) > (sy * 12 + sm);
}

/* Regenerate button (multi-month challan ke covered mahine) — YELLOW, taake alag pehchana jaye. */
const REGEN_BTN_STYLE = { color: '#A16207', background: '#FEF3C7', borderColor: '#FACC15' };

/* Challan par koi RECEIVING hai? (wasooli ya receiving-time discount) — hai to challan delete
   band; pehle Fee Receiving se receiving delete karein, phir delete khulta hai. */
function challanHasReceiving(rec) {
  return (rec?.detailRows || []).some(r =>
    Math.abs(Number(r.receivedAmount) || 0) > 0 || Math.max(0, Number(r.recvDiscount) || 0) > 0);
}
const DEL_LOCKED_TIP = 'Delete disabled — this challan already has a receiving against it (partial or full). Delete the receiving in Fee Receiving first, then you can delete this challan.';

/* Challan Type dropdown — 1 se 12 mahine. */
const CHALLAN_TYPE_LABELS = [
  'One Month', 'Two Months', 'Three Months', 'Four Months', 'Five Months', 'Six Months',
  'Seven Months', 'Eight Months', 'Nine Months', 'Ten Months', 'Eleven Months', 'Twelve Months',
];

/* Ek student ke is mahine ke challans me se ASLI is-mahine wala chuno. Sep–Nov (3 months)
   challan Oct/Nov me bhi aata hai; Oct me alag challan ban jaye to wahi pehle — covering
   challan sirf tab jab koi apna na ho. */
function pickMonthChallan(rows, month, year) {
  const list = Array.isArray(rows) ? rows.filter(Boolean) : [];
  if (!list.length) return null;
  return list.find(r => !isMultiMonthNonStartView(r, month, year)) || list[0];
}

/* Running-ledger previous. viewMonth/viewYear: covering multi-month challans skip. */
function prevOutFromLedgerRows(prevRows, viewMonth = null, viewYear = null) {
  /* SIRF aggregate carry rows ("Previous Pending" / arrear) — Launch Setup /
     Update Student ka "Previous Due" / "Previous Dues" head yahan NAHI.
     Woh normal billable head hai: pehle regex `/previous|…/` usay skip kar
     deta tha, received minus ho jati thi magar billed running me add nahi —
     partial receive ke baad next month Advance (−ve) dikhta tha, Dues nahi. */
  const isPrev = (r) => /previous\s*pending|arrears?/i.test(String(r.subHead || r.head || ''));
  const byStudent = new Map();
  /* View mahine ko cover karne wale (Sep–Nov ka Nov) challans jo skip hue — student-wise. */
  const skippedCover = new Map();
  (prevRows || []).forEach(r => {
    if (viewMonth != null && viewYear != null && ledgerCoversMonth(r, viewMonth, viewYear)) {
      const sid = String(r.studentID);
      (skippedCover.get(sid) || skippedCover.set(sid, []).get(sid)).push(r);
      return;
    }
    const id = String(r.studentID);
    if (!byStudent.has(id)) byStudent.set(id, []);
    byStudent.get(id).push(r);
  });
  const out = {};
  byStudent.forEach((recs, id) => {
    const sorted = recs.slice().sort(
      (a, b) => (Number(a.year) * 12 + Number(a.month)) - (Number(b.year) * 12 + Number(b.month)));
    let running = 0, first = true;
    /* HEAD-WISE previous: har prior mahine ke non-previous heads ka (billed − disc − received)
       head ke naam se jama — pichhla baqaya apne asli heads me taqseem ho kar carry ho.
       Aggregate "Previous Pending" rows skip (warna double-count). Negative = advance. */
    const headNet = new Map();
    const startOf = (x) => Number(x.startYear || x.year) * 12 + Number(x.startMonth || x.month);
    /* Is student ke multi-month challans (skip hue + shamil dono) — jin ki range me baad wala
       challan ka mahina aata ho (Sep–Nov ke andar Oct) aur wo us ka baqaya carry kare. */
    const covers = [...(skippedCover.get(id) || []), ...recs].filter(isMultiMonthChallan);
    const endOf = (x) => Number(x.endYear || x.startYear || x.year) * 12 + Number(x.endMonth || x.startMonth || x.month);
    sorted.forEach(rec => {
      const rows = rec.detailRows || [];
      /* Skip hue covering challan (Sep–Nov) ka baqaya agar BAAD wala challan (Oct) head-wise
         previousPendingorAdv me CARRY karta hai, to us challan ka carry hi opening balance —
         warna Oct par us baqaye ki wasooli (5,000) bina bill ke gin kar phantom ADVANCE
         (−4,000) banta tha. Per-head bhi usi carry se shuru. */
      const hpOf = (r) => Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0;
      const hpSum = rows.filter(r => !isPrev(r)).reduce((a, r) => a + hpOf(r), 0);
      if (hpSum !== 0 && covers.some(cv => cv !== rec && startOf(cv) < startOf(rec) && startOf(rec) <= endOf(cv))) {
        running = hpSum;
        first = false;
        headNet.clear();
        rows.forEach(r => {
          if (isPrev(r)) return;
          const nm = String(r.subHead || r.head || '').trim();
          if (nm && hpOf(r)) headNet.set(nm, (headNet.get(nm) || 0) + hpOf(r));
        });
      }
      const carry = rows.filter(isPrev).reduce((a, r) => a + ((+r.challanAmount || 0) - (+r.discount || 0)), 0);
      const newBilled = rows.filter(r => !isPrev(r)).reduce((a, r) => a + ((+r.challanAmount || 0) - (+r.discount || 0)), 0);
      const received = rows.reduce((a, r) => a + (+r.receivedAmount || 0), 0);
      rows.forEach(r => {
        if (isPrev(r)) return;
        const nm = String(r.subHead || r.head || '').trim();
        if (!nm) return;
        const net = (+r.challanAmount || 0) - (+r.discount || 0) - (+r.receivedAmount || 0);
        headNet.set(nm, (headNet.get(nm) || 0) + net);
      });
      if (first) { running = carry; first = false; }   // sirf pehle mahine ka carry opening balance
      running += newBilled - received;
    });
    const byHead = {};
    headNet.forEach((v, k) => { const n = Math.round(v); if (n !== 0) byHead[k] = n; });
    /* HAMESHA emit karo (net 0 ho tab bhi) — kyunke ye student ke PRIOR challans hain. Aise
       students ke liye prevOverride = {dues:0, advance:0, byHead:{}} banta hai, jo agle mahine
       ke challan par AUTHORITY hai: agar previous poora pay ho chuka to backend ke STALE
       "Previous Pending" (gross snapshot) ko nazar-andaaz kar ke 0 dikhata hai. */
    out[id] = { dues: running > 0 ? running : 0, advance: running < 0 ? -running : 0, byHead };
  });
  return out;
}

/* ── Models / helpers ── */

/* Per-head PREVIOUS amount (us head ka pichhle periods se aaya baqaya) — API detailRow
   me jis bhi naam se aaye, yahan se defensive tareeqe se padhte hain. Jab tak backend
   ye field na bheje, `null` (UI me "—" dikhta hai). Advance/0 par bhi null → "—".
   NOTE: field ka asli naam API response se confirm hone par yahan pin kar denge. */
function feeHeadPrev(row) {
  if (!row || typeof row !== 'object') return null;
  /* Backend detailRow me per-head previous ka ASLI field: `previousPendingorAdv`
     (negative = us head ka advance). Baaki naam fallback ke taur par. */
  const v = row.previousPendingorAdv ?? row.previousPendingOrAdv
    ?? row.previousAmount ?? row.previousBalance ?? row.prevAmount ?? row.prevBalance
    ?? row.previousPending ?? row.prevPending ?? row.previousDue ?? row.previousDues
    ?? row.openingBalance ?? row.arrearAmount ?? null;
  if (v == null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

/* Head-wise previous DISTRIBUTE karta hai (challan/slip builders ke liye). Agar
   student.prevByHead ({ headName: baqaya }, running-ledger se) mile to har row ka Prev usi
   head ke asli baqaya se set hota hai (na ke poora lump ek head me). byHead ke wo heads jo
   is challan me nahi, apni row me aa jaate hain. Jo total phir bhi map na ho (opening
   aggregate) wo pehli row me. `whole` = builder ka rounding helper. Return true = laga. */
function applyPrevByHead(rows, student, whole) {
  /* Multi-month covering challan khud current hai — usi ke unpaid ko Prev me
     mat chipkao (Std 10,066 + Prev 10,066 = double). */
  if (isMultiMonthChallan(student && student._challan)) return false;
  const byHead = (student && student.prevByHead && typeof student.prevByHead === 'object') ? student.prevByHead : null;
  if (!byHead || !Object.keys(byHead).length) return false;
  const norm = (s) => String(s || '').toLowerCase().trim();
  const keys = Object.keys(byHead);
  const used = new Set();
  rows.forEach(r => {
    const key = keys.find(k => norm(k) === norm(r.name));
    const p = key != null ? Math.round(byHead[key]) : 0;
    if (key != null) used.add(key);
    r.prev = p;
    r.net = r.std - r.disc + p;
  });
  keys.forEach(k => {
    if (used.has(k)) return;
    const p = Math.round(byHead[k]);
    rows.push({ name: k, std: 0, disc: 0, prev: p, net: p });
    used.add(k);
  });
  const runningPrev = (student && (student.dues != null || student.advance != null))
    ? (whole(student.dues) - whole(student.advance)) : null;
  const mapped = keys.reduce((a, k) => a + Math.round(byHead[k] || 0), 0);
  const leftover = (runningPrev != null) ? (runningPrev - mapped) : 0;
  if (leftover > 0 && rows.length > 0) { rows[0].prev += leftover; rows[0].net += leftover; }
  return true;
}

function recStudentModel({ student, headsForClass, generated, classDisc, payments, challan = null, prevOverride = null }) {
  let heads, prev, advance, thisMonth, disc;
  /* Previous-dues row ka ASLI subHead (e.g. "Previous Pending") aur uske khilaf ab tak
     wasool hui raqam — receiving modal me us par bhi amount likhi ja sake, aur payment
     sahi detailRow par map ho (API perHead ko subHead se match karta hai). */
  let prevName = '', prevPaid = 0, advName = '', advPaid = 0, headWisePrev = false;
  if (challan && Array.isArray(challan.detailRows)) {
    /* Backend HAR head ke saath uska `previousPendingorAdv` (per-head previous) bhejta hai.
       Aise me previous HEAD-WISE dikhate/wasoolte hain aur aggregate "Previous Pending" row
       ko nazar-andaaz karte hain (challan jaisa). */
    headWisePrev = challan.detailRows.some(r => r.previousPendingorAdv != null || r.previousPendingOrAdv != null);
    heads = [];
    prev = 0; advance = 0;
    let prevRowTotal = 0;   // aggregate "Previous Pending" ka total (residual ke liye)
    challan.detailRows.forEach(r => {
      const amt = +r.challanAmount || 0;
      const d = +r.discount || 0;
      const label = String(r.subHead || r.head || '').toLowerCase();
      if (/previous\s*pending|arrear/.test(label)) {
        if (headWisePrev) {
          if (amt >= 0) prevRowTotal += Math.max(0, amt - Math.min(d, amt));
        } else if (amt >= 0) {
          prev += amt;
          if (!prevName) prevName = r.subHead || r.head || '';
          prevPaid += (+r.receivedAmount || 0);
        } else {
          advance += Math.abs(amt);
          if (!advName) advName = r.subHead || r.head || '';
          advPaid += Math.abs(+r.receivedAmount || 0);
        }
      } else if (feeService.isLateFineRow(r)) {
        /* Late Fine skip — modal apni alag line me dikhata hai. */
      } else {
        const disc = amt > 0 ? Math.min(d, amt) : 0;
        heads.push({
          name: r.subHead || r.head || '',
          std: amt,
          disc,
          net: amt - disc,
          prev: feeHeadPrev(r),
          /* Poori discount (Give Discount samet) — head-wise previous par bhi lag sakti hai
             (neeche std + prev tak cap hoti hai). */
          rawDisc: amt >= 0 ? Math.max(0, d) : 0,
        });
        /* Option A: Old Advance head table me rehti hai, magar save/withAdvanceRow
           ke liye asli subHead yahan pin karo (model.advance me double-count mat karo —
           headAdvCredit pehle se owed < 0 se cover karta hai). */
        if (/old\s*advance|advance\s*till/i.test(label) && amt < 0 && !advName) {
          advName = r.subHead || r.head || '';
        }
      }
    });
    /* Transport fallback — challan me na ho magar setup amount ho to add karo. */
    const hasTransport = challan.detailRows.some(r => String(r.subHead || r.head || '').toLowerCase().trim() === 'transport');
    if (!hasTransport && (+student.transport || 0) > 0) {
      const t = +student.transport || 0;
      heads.push({ name: 'Transport', std: t, disc: 0, net: t, prev: 0 });
    }
    thisMonth = heads.reduce((a, h) => a + h.std, 0);
    disc = heads.reduce((a, h) => a + h.disc, 0);
    if (headWisePrev) {
      /* Har head ka Prev running-ledger ke byHead se (na ke lump); byHead ke extra heads
         apni row me; leftover pehli head me. */
      const byHead = (prevOverride && prevOverride.byHead && typeof prevOverride.byHead === 'object') ? prevOverride.byHead : null;
      if (byHead && Object.keys(byHead).length) {
        const norm = (s) => String(s || '').toLowerCase().trim();
        const keys = Object.keys(byHead);
        const used = new Set();
        heads.forEach(h => {
          const key = keys.find(k => norm(k) === norm(h.name));
          h.prev = key != null ? Math.round(byHead[key]) : 0;
          if (key != null) used.add(key);
        });
        keys.forEach(k => { if (used.has(k)) return; heads.push({ name: k, std: 0, disc: 0, net: 0, prev: Math.round(byHead[k]) }); used.add(k); });
        const runningPrev = prevOverride ? (Math.round(+prevOverride.dues || 0) - Math.round(+prevOverride.advance || 0)) : null;
        const mapped = keys.reduce((a, k) => a + Math.round(byHead[k] || 0), 0);
        const leftover = (runningPrev != null) ? (runningPrev - mapped) : 0;
        if (leftover > 0 && heads.length > 0) heads[0].prev = (+heads[0].prev || 0) + leftover;
      } else {
        const sumHeadPrev = heads.reduce((a, h) => a + (+h.prev || 0), 0);
        const runningPrev = prevOverride ? (Math.round(+prevOverride.dues || 0) - Math.round(+prevOverride.advance || 0)) : null;
        const totalPrevTarget = (runningPrev != null) ? runningPrev : prevRowTotal;
        const residualPrev = Math.max(0, Math.round(totalPrevTarget - sumHeadPrev));
        if (residualPrev > 0) {
          if (heads.length > 0) heads[0].prev = (+heads[0].prev || 0) + residualPrev;
          else heads.push({ name: 'Previous Pending', std: 0, disc: 0, net: 0, prev: residualPrev });
        }
      }
      prev = heads.reduce((a, h) => a + (+h.prev || 0), 0);
      advance = 0;
      /* Give Discount PREVIOUS baqaye par bhi di ja sakti hai (setup "Previous Due" head:
         is mahine 0, previous 33,600, Give Discount 13,400). Upar disc sirf is mahine ke
         amount tak cap hoti thi → 13,400 gum, list ka Discount/Remaining ghalat jabke slip
         sahi. Ab cap = is mahine + us head ka previous (slip jaisa). */
      heads.forEach(h => {
        if (!(h.rawDisc > h.disc)) return;
        const cap = Math.max(0, +h.std || 0) + Math.max(0, +h.prev || 0);
        h.disc = Math.min(h.rawDisc, cap);
        h.net = h.std - h.disc;
      });
      disc = heads.reduce((a, h) => a + h.disc, 0);
    } else if (prevOverride) {
      /* Non-head-wise: LIVE prior-outstanding (running-ledger) authority. */
      prev = Math.max(0, +prevOverride.dues || 0);
      advance = Math.max(0, +prevOverride.advance || 0);
      if (prev > 0 && !prevName) prevName = 'Previous Pending';
    }
  } else {
    heads = (headsForClass || []).map(h => {
      const std = +h.amt || 0;
      const d = +(classDisc?.[h.name]) || 0;
      return { name: h.name, std, disc: Math.min(d, std), net: std - Math.min(d, std), prev: feeHeadPrev(h) };
    });
    prev = +student.dues || 0;
    advance = +student.advance || 0;
    thisMonth = generated ? heads.reduce((a, h) => a + h.std, 0) : 0;
    disc = generated ? heads.reduce((a, h) => a + h.disc, 0) : 0;
  }
  /* Ledger par bill ho chuki LATE FINE. `heads` me ye shamil nahi (receiving modal
     usay apni alag line me dikhata hai), magar `paid` niche saari detailRows se
     banta hai — yani fine ki wasooli us me aati hai. Is liye fine ko payable me
     bhi jodna zaroori hai, warna dono taraf bay-mail ho jaati thi: 12,000 payable
     magar 12,400 paid → Remaining −400 (poora receive karne ke bawajood). */
  /* Fine row ki bill − us par di gayi Give Discount (discount me fold). */
  const billedFine = (challan && Array.isArray(challan.detailRows))
    ? challan.detailRows.filter(feeService.isLateFineRow)
      .reduce((a, r) => a + (+r.challanAmount || 0) - Math.max(0, +r.discount || 0), 0)
    : 0;
  /* Paid must survive a page refresh. The local `payments` array is session-only
     (getReceipts is mock), so when a real challan exists take the authoritative
     received total straight from its detailRows' receivedAmount. Math.max keeps
     the figure correct in the brief window after a payment, before loadChallans
     re-fetches the updated challan. */
  const paidFromChallan = (challan && Array.isArray(challan.detailRows))
    ? challan.detailRows.reduce((a, r) => a + (+r.receivedAmount || 0), 0)
    : 0;
  const paidFromPayments = (payments || []).reduce((a, p) => a + (+p.amount || 0), 0);
  const paid = challan ? Math.max(paidFromChallan, paidFromPayments) : paidFromPayments;
  /* Receiving-time Give Discount — list ke Discount column me add, Remaining se
     hatao. Payments session-only hain; tab switch ke baad localStorage (ledgerId)
     se bhi padho. Agar API/optimistic update pehle se detailRows.discount me
     fold kar chuka ho to dobara na jodo (warna Remaining −ve). */
  let giveFromPays = (payments || []).reduce((sum, p) => {
    if (!p?.giveDisc) return sum;
    return sum + Object.values(p.giveDisc).reduce((a, v) => a + Math.max(0, +v || 0), 0);
  }, 0);
  if (giveFromPays <= 0 && challan?._giveDisc) {
    giveFromPays = Object.values(challan._giveDisc).reduce((a, v) => a + Math.max(0, +v || 0), 0);
  }
  if (giveFromPays <= 0 && challan?.id) {
    giveFromPays = feeService.getStoredGiveDiscTotal(challan.id) || 0;
  }
  /* paymentMethod ka |#GD#… marker sirf tab padho jab receiving BAQI ho.
     delete-receiving marker ko row par chhod jaata hai (receivedAmount aur
     discount palat kar bhi), to warna delete ki hui Give Discount list ke
     Discount column me hamesha ke liye chipak jaati thi. */
  if (giveFromPays <= 0 && challan?.paymentMethod && feeService.hasLiveReceiving(challan)) {
    const parsed = feeService.parseGiveDiscFromPaymentMethod(challan.paymentMethod);
    giveFromPays = Object.values(parsed.giveDisc || {}).reduce((a, v) => a + Math.max(0, +v || 0), 0);
  }
  /* Challan withPersistedGiveDisc se guzar chuka ho (_isReceivingGive) to Give
     Discount pehle se detailRows.discount (→ disc) me hai. Partial (2nd installment)
     par neeche wala heuristic dobara jod deta tha → list ke Discount column me double. */
  if (challan?._isReceivingGive) giveFromPays = 0;
  if (giveFromPays > 0) {
    const remNo = (Math.max(0, prev + thisMonth - disc - advance) + billedFine) - paid;
    const remWith = (Math.max(0, prev + thisMonth - (disc + giveFromPays) - advance) + billedFine) - paid;
    if (Math.abs(remNo) > Math.abs(remWith)) disc += giveFromPays;
  }
  const payable = Math.max(0, prev + thisMonth - disc - advance) + billedFine;
  const remaining = payable - paid;   /* MINUS = advance (total se zyada wasool) */
 let status = 'none';
const hasRecvActivity = (challan && Array.isArray(challan.detailRows))
  ? challan.detailRows.some(r => (Number(r.receivedAmount) || 0) !== 0)
  : (paidFromPayments !== 0);
if (generated && (paid > 0 || hasRecvActivity)) {
  status = remaining <= 0 ? 'full' : 'partial';
}
  /* Only payments explicitly tagged as OneLink/bank-pull are protected
     from manual deletion. A "Bank Transfer" entered at the counter
     stays deletable — same as the HTML reference (which keys off the
     `source` field, not the method). */
  const onelink = (payments || []).some(p => p.source === 'onelink' || p.source === 'bank');
  /* Per-head ab tak wasool hui raqam (challan ke receivedAmount se) — Bulk modal isi se
     "Already Received" aur seeding nikaalta hai, warna paid heads dobara seed ho jate the. */
  const paidPerHead = {};
  if (challan && Array.isArray(challan.detailRows)) {
    challan.detailRows.forEach(r => {
      const n = r.subHead || r.head || '';
      paidPerHead[n] = (paidPerHead[n] || 0) + (+r.receivedAmount || 0);
    });
  }
  return { heads, generated, prev, prevName, prevPaid, paidPerHead, advance, advName, advPaid, thisMonth, disc, payable, paid, remaining, status, onelink, headWisePrev };
}

function statusBadge(status) {
  if (status === 'full') return <span className="fee-stat-badge fee-stat-full"><i className="fa-solid fa-circle-check"></i> Fully Received</span>;
  if (status === 'partial') return <span className="fee-stat-badge fee-stat-partial"><i className="fa-solid fa-circle-half-stroke"></i> Partial</span>;
  return <span className="fee-stat-badge fee-stat-none"><i className="fa-solid fa-circle-exclamation"></i> Not Received</span>;
}

function summaryChips({ total, paid, unpaid, onelink = 0 }) {
