  </div>`;
  }).join('');

  return `<style>${HIST_REPORT_CSS}</style><body>
  <div class="hist-page">
    ${histHeadHtml(meta, 'Old ERP Ledger', [
    `Classes: ${blocks.filter(b => b.rows.length).length}`,
