/* The (month, year) pairs a report spans, oldest first. Capped so a wide date
   range can't fan out into an unbounded number of requests. */
/* Aggregate carry rows ("Previous Pending"/arrear) — prevOutFromLedgerRows jaisa. */
const isLedgerCarryRow = (r) => isAggregateCarryRow(r);

/* Ek challan ki ASLI wasooli receipts (installment-wise) — Collection & Advance
   Adjustment reports ke liye. Har installment = ek receipt: date, time, cash amount,
   receiving-time discount (recvDiscount) aur kis user ne liya (createdBy).
   Negative advance-consumption rows (challanAmount < 0, received −X) cash nahi —
   skip. Installments na hon (purana record) to ek synthetic receipt detail totals se. */
function ledgerInstallmentReceipts(rec) {
  if (!rec || !Array.isArray(rec.detailRows)) return [];
  const rows = rec.detailRows.filter(r => !((+r.challanAmount || 0) < 0 && isLedgerCarryRow(r)));
  const groups = new Map();
  rows.forEach(row => (row.installments || []).forEach(inst => {
    const recv = +inst.receivedAmount || 0;
    const give = Math.max(0, +inst.recvDiscount || 0);
    if (!recv && !give) return;
    const no = +inst.installmentNo || 0;
    const g = groups.get(no) || { no, date: '', time: '', amount: 0, give: 0, by: null };
    g.amount += recv;
    g.give += give;
    const d = String(inst.receivedDate || '').slice(0, 10);
    if (d) g.date = d;
    const t = String(inst.createdAt || '');
    if (t.length >= 16) g.time = t.slice(11, 16);
    if (inst.createdBy) g.by = inst.createdBy;
    groups.set(no, g);
  }));
  if (groups.size) {
    return [...groups.values()]
      .map(g => ({ ...g, date: g.date || String(rec.receivedDate || '').slice(0, 10) }))
      .sort((a, b) => a.no - b.no);
  }
  const amount = rows.reduce((a, r) => a + (+r.receivedAmount || 0), 0);
  const give = rows.reduce((a, r) => a + Math.max(0, +r.recvDiscount || 0), 0);
  if (!amount && !give) return [];
  return [{
    no: 1,
    date: String(rec.receivedDate || rec.modifiedAt || '').slice(0, 10),
    time: String(rec.modifiedAt || '').slice(11, 16),
    amount, give, by: rec.modifiedBy || null,
  }];
}

/* Kya challan pichhla baqaya CARRY karta hai — head ka previousPendingorAdv ya
   aggregate "Previous Pending" row. (API ka isCarried reliable nahi, is liye khud dekhte.) */
function challanCarriesPrev(rec) {
  return (rec?.detailRows || []).some(r => {
    if (feeService.isLateFineRow(r)) return false;
    if (isLedgerCarryRow(r)) return (+r.challanAmount || 0) !== 0;
    return (Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0) !== 0;
  });
}

/* Is mahine challan na ho (e.g. December, Sep–Nov challan ke baad) to KIS pichhle challan par
   wasooli ho. isCarried scenario skip — khud tay karte hain:
     - Aakhri (latest) pichhla challan agar purana baqaya carry karta hai (Oct challan me
       Sep–Nov ka 20,000 head-wise prev) → SIRF wahi; us ka Remaining sab samet (October
       jaisa). Purane challans (API unhe abhi bhi pending dikhati) ignore — warna double.
     - Carry nahi karta → /pending ki list ka sab se naya pending challan.
   priorList / pendList dono naya-pehle sorted. Returns { rec, pc } (pc = /pending item). */
function pickReceivableChallan(priorList, pendList) {
  const prior = priorList || [];
  const pend = pendList || [];
  const latest = prior[0] || null;
  if (latest && (challanCarriesPrev(latest) || !pend.some(x => Number(x.ledgerId) !== Number(latest.id)))) {
    return { rec: latest, pc: pend.find(x => Number(x.ledgerId) === Number(latest.id)) || null };
  }
  const pc = pend[0] || null;
  const rec = pc ? (prior.find(r => Number(r.id) === Number(pc.ledgerId)) || null) : latest;
  return { rec, pc };
}

/* PICHHLE challans ka baqaya FINE jo is challan me carry hua (Option 2). Jab ye challan
   pichhla baqaya carry karta hai (challanCarriesPrev), to us se pehle wale challan P ka fine:
     - P par "Late Fine" row ho → us ka baqaya (bill − discount − received) — us me P ka apna
       carried fine pehle hi shamil hai.
     - Na ho → P ki Due Date se IS challan ke banne ki tareekh tak ka fine (wahan freeze) +
       P me carry hua purana fine (recursive).
   Same "Fine" line me receiving popup isay is challan ke apne late fine ke saath jodta hai. */
function carriedFineInto(rec, priorList, settings, depth = 0) {
  if (!rec || !settings?.fineEnabled || depth > 24) return 0;
  if (!challanCarriesPrev(rec)) return 0;
  const startOf = (x) => Number(x.startYear || x.year) * 12 + Number(x.startMonth || x.month);
  const recStart = startOf(rec);
  const P = (priorList || [])
    .filter(p => p && Number(p.id) !== Number(rec.id) && startOf(p) < recStart)
    .sort((a, b) => (startOf(b) - startOf(a)) || (Number(b.id) - Number(a.id)))[0];
  if (!P) return 0;
  const pFineRows = (P.detailRows || []).filter(feeService.isLateFineRow);
  if (pFineRows.length) {
    return Math.max(0, Math.round(pFineRows.reduce((a, r) =>
      a + (+r.challanAmount || 0) - Math.max(0, +r.discount || 0) - (+r.receivedAmount || 0), 0)));
  }
  const issue = String(rec.dateofCreattion || rec.createdAt || '').slice(0, 10) || localTodayISO();
  const own = feeService.computeFine({ dueDate: P.dueDate, receivingDate: issue, settings });
  return Math.max(0, Math.round(own)) + carriedFineInto(P, priorList, settings, depth + 1);
}

/* Ledger-range rows → { [studentID]: [pichhle challans, naya-pehle] } (view mahine ko cover
   karne wale multi-month challans chhod kar). pickReceivableChallan isi list par chalta hai. */
function priorChallansByStudent(prevRows, viewMonth, viewYear) {
  const prior = {};
  const seenIds = new Set();
  (prevRows || []).forEach(r => {
    if (!r || seenIds.has(r.id)) return;
    seenIds.add(r.id);
    if (ledgerCoversMonth(r, viewMonth, Number(viewYear))) return;
    const k = String(r.studentID);
    (prior[k] = prior[k] || []).push(feeService.withPersistedGiveDisc(r));
  });
  Object.values(prior).forEach(list => list.sort((a, b) =>
    (Number(b.startYear || b.year) * 12 + Number(b.startMonth || b.month)) -
    (Number(a.startYear || a.year) * 12 + Number(a.startMonth || a.month)) || (Number(b.id) - Number(a.id))));
  return prior;
}

/* Challan ka mahina label — multi-month par "September – October 2026". */
function ledgerMonthLabel(rec) {
  const sm = Number(rec.startMonth || rec.month) || 0;
  const sy = Number(rec.startYear || rec.year) || 0;
  const em = Number(rec.endMonth) || sm;
  const ey = Number(rec.endYear) || sy;
  if (!sm) return '—';
  if (isMultiMonthChallan(rec) && (em !== sm || ey !== sy)) {
    return sy === ey
      ? `${FEE_MONTHS[sm - 1]} – ${FEE_MONTHS[em - 1]} ${ey}`
      : `${FEE_MONTHS[sm - 1]} ${sy} – ${FEE_MONTHS[em - 1]} ${ey}`;
  }
  return `${FEE_MONTHS[sm - 1]} ${sy}`;
}

/* Ek student ki ADVANCE movement — running-ledger (prevOutFromLedgerRows jaisa):
     running += challan ka naya bill (net, discount + give ke baad)
     running −= har receipt ki wasooli
   running < 0 = advance. Receipt se advance BARHE → "received" event (us receipt ki
   date); naya challan bill ho kar advance GHATE → "adjusted" event (challan ki issue
   date, us challan ke mahine ke khilaf). Pehle challan ka carry = opening balance. */
export function ledgerAdvanceEvents(recs) {
  const list = (recs || []).slice().sort((a, b) =>
    ((Number(a.startYear || a.year) * 12 + Number(a.startMonth || a.month)) -
     (Number(b.startYear || b.year) * 12 + Number(b.startMonth || b.month))));
  const events = [];
  let running = 0, first = true, openingDate = '';
  list.forEach(rec => {
    const rows = rec.detailRows || [];
    const net = (r) => (+r.challanAmount || 0) - (+r.discount || 0);
    const billDate = String(rec.dateofCreattion || rec.createdAt || '').slice(0, 10);
    if (first) {
      running = rows.filter(isLedgerCarryRow).reduce((a, r) => a + net(r), 0);
      openingDate = billDate;
      if (running < 0) events.push({ type: 'recv', date: '', amount: -running, opening: true });
      first = false;
    }
    const newBilled = rows.filter(r => !isLedgerCarryRow(r)).reduce((a, r) => a + net(r), 0);
    let before = Math.max(0, -running);
    running += newBilled;
    let after = Math.max(0, -running);
    if (after < before) events.push({ type: 'adj', date: billDate, amount: before - after, against: ledgerMonthLabel(rec) });
    ledgerInstallmentReceipts(rec).forEach(p => {
      before = Math.max(0, -running);
      running -= p.amount;
      after = Math.max(0, -running);
      if (after > before) events.push({ type: 'recv', date: p.date || billDate, amount: after - before });
      else if (after < before) events.push({ type: 'adj', date: p.date || billDate, amount: before - after, against: ledgerMonthLabel(rec) });
    });
  });
  return { events, openingDate, balance: Math.max(0, -running) };
}

/* Login user id → employee naam (Fee History jaisa), ek dafa resolve. */
function useEmpNames(ids) {
  const [names, setNames] = useState({});
  const key = [...new Set((ids || []).filter(Boolean).map(String))].sort().join(',');
  useEffect(() => {
    const missing = key ? key.split(',').filter(id => !(id in names)) : [];
    if (!missing.length) return undefined;
    let alive = true;
    Promise.all(missing.map(id => feeService.getEmployeeNameByLoginUser(id).then(n => [id, n]).catch(() => [id, null])))
      .then(pairs => { if (alive) setNames(prev => ({ ...prev, ...Object.fromEntries(pairs) })); });
    return () => { alive = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  return names;
}

function ledgerPeriods(fromM, fromY, toM, toY) {
  const out = [];
  let y = fromY, m = fromM;
  while ((y < toY || (y === toY && m <= toM)) && out.length < 36) {
    out.push({ month: m, year: y });
    m += 1;
    if (m > 12) { m = 1; y += 1; }
  }
  return out;
}

/* Roll one student's challan records into the figures the panels and the A4
   builders expect. `heads` carries one row per fee head across all periods —
   unpaid heads land wholly in `pend`, partly-paid ones only for the shortfall. */
/* `settings` late fine ke liye — backend abhi fine ko apni detailRow me persist
   nahi karta, is liye jo challan due date ke BAAD receive hua uski fine yahan
   dobara compute kar ke payable/paid + Head-Wise me shaamil ki jaati hai. Jis din
   backend row bhejne lage, isLateFineRow match ho jaayegi aur ye reconstruction
   apne aap skip ho jaayegi (double-count nahi hoga). */
const isOldDuesName = (r) => /old\s*dues|dues\s*till/i.test(String(r?.subHead || r?.head || ''));

export function ledgerModel(recs, settings = null) {
  const isPrev = (r) => !isOldDuesName(r)
    && /previous|pending|arrear/i.test(String(r.subHead || r.head || ''));
  const headPrevOf = (r) => +r.previousPendingorAdv || +r.previousPendingOrAdv || 0;
  /* Mahine-wise sort — running-ledger sahi chalne ke liye. */
  const list = (recs || []).slice().sort(
    (a, b) => (Number(a.year) * 12 + Number(a.month)) - (Number(b.year) * 12 + Number(b.month)),
  );

  const heads = new Map();
  let payable = 0, paid = 0, disc = 0;
  /* fineTotal = kul late fine (wasool + baqaya); fineRecv = jo wasool ho chuki. */
  let fineTotal = 0, fineRecv = 0;
  /* CARRY-FORWARD ke double-count se bachne ke liye running-ledger (Fee History jaisa):
     "Previous Pending" line pichle mahine ka hi baqaya hota hai — agar hum har mahine ka
     pending jod dein to wahi raqam do-do baar ginn jaati thi (e.g. 15,500 + 15,500 = 31,000).
     Is liye sirf PEHLE mahine ka carry opening balance, baaki running me already shaamil. */
  let running = 0, seen = false, advApplied = 0, prevDuesAgg = 0;
  list.forEach((rec, recIdx) => {
    const rows = rec.detailRows || [];
    /* Head-wise previousPendingorAdv (jaise Admission par −1000 advance) — aggregate
       "Previous Pending" row SKIP, warna dues double / advance miss. */
    const hasHeadPrev = rows.some(r => !isPrev(r) && !feeService.isLateFineRow(r) && headPrevOf(r) !== 0);
    const feeRows = rows.filter(r => !feeService.isLateFineRow(r) && !(hasHeadPrev && isPrev(r)));
    const carrySigned = hasHeadPrev
      ? feeRows.reduce((a, r) => a + headPrevOf(r), 0)   // opening = head-wise prev (minus = advance)
      : rows.filter(isPrev).reduce((a, r) => a + ((+r.challanAmount || 0) - (+r.discount || 0)), 0);
    const newBilled = feeRows
      .filter(r => hasHeadPrev || !isPrev(r))
      .reduce((a, r) => a + ((+r.challanAmount || 0) - (+r.discount || 0)), 0);
    /* Received: fine row alag; head-wise me aggregate prev row skip. */
    const received = (hasHeadPrev ? feeRows : rows.filter(r => !feeService.isLateFineRow(r)))
      .reduce((a, r) => a + ledgerRowRecv(r), 0);
    /* BILL ho chuki "Late Fine" row (Option 2 me pichhla fine bhi isi me) — bill (− fine discount)
       jodo aur us ki wasooli ghatao. Pehle wasooli ghatti thi magar bill kabhi nahi judta tha. */
    const lateRows = rows.filter(feeService.isLateFineRow);
    const billedFineNet = lateRows.reduce((a, r) => a + (+r.challanAmount || 0) - Math.max(0, +r.discount || 0), 0);
    const billedFineRecv = lateRows.reduce((a, r) => a + ledgerRowRecv(r), 0);
    const isFirst = !seen;
    if (isFirst) { running = carrySigned; seen = true; }
    const openDebt = isFirst ? Math.max(0, carrySigned) : 0;   // sirf pehle mahine ka pichla baqaya
    prevDuesAgg += openDebt;   // dashboard: Previous Dues split (current = payable − prevDues)
    /* Is mahine laga pichla ADVANCE credit (running < 0 tha) — total advance me jodo. */
    if (running < 0) advApplied += Math.min(-running, newBilled);
    payable += newBilled + openDebt + billedFineNet;
    paid += received + billedFineRecv;
    fineTotal += billedFineNet;
    fineRecv += billedFineRecv;
    disc += rows.reduce((a, r) => a + (+r.discount || 0), 0);
    /* Head-wise: pehle mahine ka carrySigned (= Σ headPrev) pehle se running me
       hai — yahan sirf is mahine ka bill − received. */
    running += newBilled - received + billedFineNet - billedFineRecv;

    /* Per-head aggregation (Head-Wise report ke liye) — waisa hi. */
    rows.forEach(r => {
      if (hasHeadPrev && isPrev(r)) return;
      const sub = r.subHead || r.head || '—';
      const k = `${r.head || ''}|${sub}`;
      const agg = heads.get(k) || { head: r.head || 'Account Payable', sub, total: 0, disc: 0, recv: 0, pend: 0 };
      const hp = hasHeadPrev ? headPrevOf(r) : 0;
      agg.total += (+r.challanAmount || 0);
      agg.disc += (+r.discount || 0);
      agg.recv += ledgerRowRecv(r);
      /* Pending = (challan − disc + headPrev) − received. Advance (hp minus) yahan
         settle hota hai — Defaulter Remaining Receiving jaisa. */
      agg.pend += ((+r.challanAmount || 0) - (+r.discount || 0) + hp) - ledgerRowRecv(r);
      heads.set(k, agg);
    });

    /* ── LATE FINE (reconstructed) ──
       Backend fine ko apni detailRow me persist nahi karta, is liye yahan dobara
       banti hai. Do surtein:
         a) Challan due date ke BAAD receive hua → fine WASOOL ho chuki. Base date
            ASLI receiving date (receivedDate) hai, aaj nahi — warna purane challan
            ki fine roz barhti rehti. payable + paid dono me (net asar 0).
         b) Challan abhi tak unpaid hai aur due date guzar chuki → fine AAJ tak
            accrue ho chuki aur ABHI BAQAYA hai. payable + running me (paid me
            nahi) — isi se Defaulter report ka "Total Outstanding" sahi banta hai.
       Backend ne apni Late Fine row bhej di ho to kuch na karo (double-count nahi). */
    /* Option 2 — agla challan is ka baqaya CARRY kare to is ka fine us challan ke "Fine" me
       chala jata hai: (a) agle par Late Fine row ho → fine wahan bill (yahan skip, double nahi);
       (b) na ho → fine SIRF agle challan ke banne ki tareekh tak (freeze), aaj tak nahi. */
    const carriedBy = list[recIdx + 1] && challanCarriesPrev(list[recIdx + 1]) ? list[recIdx + 1] : null;
    const fineInLater = !!(carriedBy && (carriedBy.detailRows || []).some(feeService.isLateFineRow));
    if (settings?.fineEnabled && !rows.some(feeService.isLateFineRow) && !fineInLater) {
      const collected = received > 0;
      const base = collected
        ? String(rec.receivedDate || rec.modifiedAt || rec.dateofCreattion || '').slice(0, 10)
        : carriedBy
          ? (String(carriedBy.dateofCreattion || carriedBy.createdAt || '').slice(0, 10) || localTodayISO())
          : localTodayISO();
      const fine = feeService.computeFine({ dueDate: rec.dueDate, receivingDate: base, settings });
      if (fine > 0) {
        fineTotal += fine;
        payable += fine;
        if (collected) { paid += fine; fineRecv += fine; }
        else { running += fine; }      // baqaya fine outstanding me
        const k = `Account Payable|${feeService.LATE_FINE_HEAD}`;
        const agg = heads.get(k)
          || { head: 'Account Payable', sub: feeService.LATE_FINE_HEAD, total: 0, disc: 0, recv: 0, pend: 0 };
        agg.total += fine;
        if (collected) agg.recv += fine;
        else agg.pend += fine;
        heads.set(k, agg);
      }
    }
  });
  /* CURRENT outstanding. Head-wise latest challan par (amt − disc + hp − recv)
     authority — multi-month me running kabhi-kabhi headPrev miss/double karti;
     aakhri challan Receiving Remaining se match karta hai. */
  let remaining = Math.max(0, running);
  const latest = list[list.length - 1];
  if (latest && Array.isArray(latest.detailRows)) {
    const lrows = latest.detailRows;
    const latestHeadPrev = lrows.some(r => !isPrev(r) && !feeService.isLateFineRow(r) && headPrevOf(r) !== 0);
    if (latestHeadPrev) {
      let out = 0;
      lrows.forEach(r => {
        if (feeService.isLateFineRow(r) || isPrev(r)) return;
        out += ((+r.challanAmount || 0) - (+r.discount || 0) + headPrevOf(r)) - ledgerRowRecv(r);
      });
      /* Projected / billed fine pending bhi outstanding me. */
      out += Math.max(0, fineTotal - fineRecv);
      remaining = Math.max(0, Math.round(out));
    }
  }
  /* ADVANCE = pichhle overpay se aaya credit jo aage ke challans par laga (running < 0
     wale mahino se). Head-Wise report is se pending me se minus dikhati hai. */
  const advance = advApplied;

  /* Unpaid heads — aakhri challan; partial baqaya (pend > 0) bhi dikhao, sirf
     receivedAmount==null nahi (warna Give/partial ke baad "—" aa jata tha). */
  const unpaidHeads = latest
    ? Array.from(new Set(
      (latest.detailRows || [])
        .filter(r => {
          if (feeService.isLateFineRow(r)) return false;
          /* Aggregate "Previous Pending" skip — warna wahi baqaya head ke saath do dafa.
             Previous Due / Pending Due / Old Dues Till Date yahan rehte hain. */
          if (isAggregateCarryRow(r)) return false;
          const hp = headPrevOf(r);
          const pend = ((+r.challanAmount || 0) - (+r.discount || 0) + hp) - ledgerRowRecv(r);
          return pend > 0;
        })
        .map(r => r.subHead || r.head || '—'),
    ))
    : [];

    /* Old Dues Till Date ka baqaya (aakhri challan se) */
  let oldDues = 0;
  if (latest && Array.isArray(latest.detailRows)) {
    latest.detailRows.forEach(r => {
      if (!isOldDuesName(r)) return;
      const hp = headPrevOf(r);
      const pend = (+r.challanAmount || 0) - (+r.discount || 0) + hp - ledgerRowRecv(r);
      if (pend > 0) oldDues += pend;
    });
  }
  oldDues = Math.round(oldDues);
  const dueISO = latest ? challanDueISO(latest) : '';

  return {
    billed: list.length > 0,
    payable, paid, remaining, disc, advance,
    /* Dashboard Fee Analytics split — prevDues = pehle mahine ka opening baqaya,
       currBilled = is period ka naya bill (payable − prevDues, taake Curr + Prev
       hamesha Net Receivable ke barabar rahe). Reports extra fields ignore karti hain. */
    prevDues: prevDuesAgg,
    currBilled: Math.max(0, payable - prevDuesAgg),
    /* Late fine alag se bhi — KPI tiles aur report footers is se "Fine Collected"
       / "Fine Outstanding" dikhate hain. */
    fine: fineTotal, fineRecv, finePend: Math.max(0, fineTotal - fineRecv),
    heads: Array.from(heads.values()),
    recs: list,
    unpaidHeads,
    oldDues, dueISO,
  };
}

/* Pulls the given periods' challans and joins them onto the class roster.
   Returns the same { classes, studentsMap, allStudents, totals } shape the
   panels already consume, so the A4 builders keep working untouched. */
export function useLedgerReportData(periods) {
  const { data: classes = [] } = useAsync(feeService.getFeeClasses, []);
  const { data: studentsMap = {} } = useAsync(feeService.getTransportFee, []);
  /* Late fine reports me dikhane ke liye settings chahiye (rate + on/off). */
  const { data: settings = {} } = useAsync(feeService.getFeeSettings, []);
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /* Serialised so the effect re-runs on value, not identity, of `periods`. */
  const periodKey = JSON.stringify(periods || []);
  useEffect(() => {
    let alive = true;
    const list = JSON.parse(periodKey);
    if (!list.length) { setRecords([]); setLoading(false); return undefined; }
    setLoading(true);
    setError(null);
    Promise.all(list.map(p => feeService.getMonthChallans(p.month, p.year).catch(() => null)))
      .then(res => {
        if (!alive) return;
        if (res.every(r => r === null)) setError('Could not load challans from the ledger');
        /* Give Discount (paymentMethod|#GD#) fold — Defaulter Remaining Receiving jaisa.
           Multi-month (Sep–Oct) challan dono mahino ki call me aata hai — id se ek hi
           dafa rakho, warna reports me wo do dafa gina jaata tha. */
        const seenIds = new Set();
        const uniq = res.filter(Boolean).flat().filter(r => {
          if (!r || r.id == null) return true;
          if (seenIds.has(r.id)) return false;
          seenIds.add(r.id);
          return true;
        });
        setRecords(uniq.map(r => feeService.withPersistedGiveDisc(r)));
        setLoading(false);
      });
    return () => { alive = false; };
  }, [periodKey]);

  const allStudents = useMemo(() => {
    const byStudent = new Map();
    records.forEach(rec => {
      const k = String(rec.studentID);
      if (!byStudent.has(k)) byStudent.set(k, []);
      byStudent.get(k).push(rec);
    });
    const out = [];
    classes.forEach(c => {
      (studentsMap[c.key] || []).forEach(s => {
        const recs = byStudent.get(String(s.studentID)) || byStudent.get(String(s.applicantsID)) || [];
        out.push({ c, s, m: ledgerModel(recs, settings) });
      });
    });
    return out;
  }, [classes, studentsMap, records, settings]);

  /* Only billed students count — a student with no challan isn't a defaulter. */
  const totals = useMemo(() => {
    let exp = 0, recv = 0, pend = 0, disc = 0, def = 0, paid = 0, n = 0;
    let fine = 0, fineRecv = 0, finePend = 0;
    allStudents.forEach(({ m }) => {
      if (!m.billed) return;
      n += 1;
      exp += m.payable; recv += m.paid; pend += m.remaining; disc += m.disc;
      fine += (m.fine || 0); fineRecv += (m.fineRecv || 0); finePend += (m.finePend || 0);
      if (m.remaining > 0) def += 1; else paid += 1;
    });
    return { exp, recv, pend, disc, adv: 0, def, paid, n, fine, fineRecv, finePend };
  }, [allStudents]);

  return { classes, studentsMap, allStudents, totals, records, loading, error };
}

/* Per-head breakdown for one student. Head-Wise shows every head — paid,
   partly paid and unpaid alike; the receivedAmount === null filter belongs to
   the Defaulter report, not here. */
function ledgerHeadRows(m, headFilter) {
  const rows = m ? m.heads : [];
  if (headFilter && headFilter !== 'All Heads') return rows.filter(r => r.sub === headFilter);
  return rows;
}

/* Small inline banner for the ledger fetch state. */
function RepLoadState({ loading, error, empty, emptyText }) {
  if (loading) return <div className="fee-info"><i className="fa-solid fa-circle-notch fa-spin"></i> <span>Loading challans from the ledger…</span></div>;
  if (error) return <div className="fee-info" style={{ color: '#B91C1C' }}><i className="fa-solid fa-triangle-exclamation"></i> <span>{error}</span></div>;
  if (empty) return <div className="fee-info"><i className="fa-solid fa-circle-info"></i> <span>{emptyText}</span></div>;
  return null;
}

