/* ════════════ 4. AGING / OUTSTANDING ════════════ */
function ReportPanelAging({ toast }) {
  const school = useContext(FeeReportBranchContext);
  /* REAL ledger (sample data nahi): As-of date tak ka baqaya, challan ki due date se kitne din
     purana — ledgerAgingAsOf. As-of se 12 mahine pehle tak ke challans load. */
  const [asOf, setAsOf] = useState(localTodayISO());
  const [clsFilter, setClsFilter] = useState('all');
  const periods = useMemo(() => {
    const d = new Date(`${asOf}T00:00:00`);
    if (isNaN(d.getTime())) return [];
    const back = new Date(d.getFullYear(), d.getMonth() - 12, 1);
    return ledgerPeriods(back.getMonth() + 1, back.getFullYear(), d.getMonth() + 1, d.getFullYear());
  }, [asOf]);
  const { classes, allStudents, loading, error } = useLedgerReportData(periods);
  const list = useMemo(() => allStudents
    .filter(x => clsFilter === 'all' || x.c.key === clsFilter)
    .map(x => {
      const a = ledgerAgingAsOf(x.m.recs || [], asOf);
      return { ...x, a, m: { ...x.m, remaining: a.total } };
    })
    .filter(x => x.a.total > 0), [allStudents, asOf, clsFilter]);
  const tot = list.reduce((o, x) => ({ cur: o.cur + x.a.cur, d30: o.d30 + x.a.d30, d60: o.d60 + x.a.d60, d90: o.d90 + x.a.d90 }), { cur: 0, d30: 0, d60: 0, d90: 0 });

  const reportTitle = 'Aging / Outstanding Analysis';
  const downloadReport = (style, format) => {
    const html = buildRepAgingHTML({ list, tot, asOf, isBW: style === 'bw', school });
    openPrintReport(html, reportTitle, toast, format);
  };

  return (
    <>
      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span><strong>Aging analysis</strong> buckets outstanding fee by how long it's overdue (Current, 1–30, 31–60, 61–90+ days) — the standard for recovery-risk and follow-up prioritisation.</span>
      </div>

      <RepLoadState loading={loading} error={error} />

      {repKpiStrip([
        ['k-green', 'fa-circle-dot', 'Current', fmtRs(tot.cur), ''],
        ['k-amber', 'fa-clock', '1–30 Days', fmtRs(tot.d30), ''],
        ['k-amber', 'fa-clock-rotate-left', '31–60 Days', fmtRs(tot.d60), ''],
        ['k-red', 'fa-triangle-exclamation', '61–90+ Days', fmtRs(tot.d90), ''],
      ])}

      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field">
              <span className="fee-label">As of Date</span>
              <input className="fee-input" type="date" value={asOf} onChange={e => setAsOf(e.target.value || localTodayISO())} style={{ minWidth: 170 }} />
            </div>
            <div className="fee-field">
              <span className="fee-label">Class</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={clsFilter} onChange={e => setClsFilter(e.target.value)}>
                  <option value="all">All Classes</option>
                  {classes.map(c => <option key={c.key} value={c.key}>{c.cls} {c.sec}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <RepActions title={reportTitle} onGenerate={downloadReport} />
          </div>
        </div>
      </div>

      <div className="fee-section">
        <div className="fee-section-body">
          <div className="age-legend">
            <span><i className="age-dot age-cur"></i> Current</span>
            <span><i className="age-dot age-30"></i> 1–30</span>
            <span><i className="age-dot age-60"></i> 31–60</span>
            <span><i className="age-dot age-90"></i> 61–90+</span>
          </div>
          <div className="fee-stbl-wrap">
            <table className="fee-stbl">
              <thead>
                <tr>
                  <th>Sn.</th><th>Student</th><th>Class/Sec</th>
                  <th className="fee-right">Current</th>
                  <th className="fee-right">1–30</th>
                  <th className="fee-right">31–60</th>
                  <th className="fee-right">61–90+</th>
                  <th className="fee-right">Total Due</th>
                  <th style={{ width: 150 }}>Aging</th>
                </tr>
              </thead>
              <tbody>
                {list.length === 0 ? (
                  <tr><td colSpan="9" className="fee-stbl-empty">No outstanding dues.</td></tr>
                ) : list.map((x, j) => {
                  const tt = (x.a.cur + x.a.d30 + x.a.d60 + x.a.d90) || 1;
                  return (
                    <tr key={`${x.c.key}-${x.s.reg}`}>
                      <td className="fee-num">{j + 1}</td>
                      <td>
                        <b>{x.s.name}</b>
                        <span className="fee-sub-eq">s/o {x.s.father || '—'}</span>
                      </td>
                      <td>{x.c.cls} / {x.c.sec}</td>
                      <td className="fee-right">{money(x.a.cur)}</td>
                      <td className="fee-right" style={{ color: '#D97706', fontWeight: 700 }}>{money(x.a.d30)}</td>
                      <td className="fee-right" style={{ color: '#D97706', fontWeight: 700 }}>{money(x.a.d60)}</td>
                      <td className="fee-right fee-neg">{money(x.a.d90)}</td>
                      <td className="fee-right"><b>{money(x.m.remaining)}</b></td>
                      <td>
                        <div className="age-bar">
                          {x.a.cur > 0 && (
                            <Tooltip text={`Current — ${fmtRs(x.a.cur)} (${((x.a.cur / tt) * 100).toFixed(1)}%)`}>
                              <i className="age-cur" style={{ width: `${(x.a.cur / tt) * 100}%` }} />
                            </Tooltip>
                          )}
                          {x.a.d30 > 0 && (
                            <Tooltip text={`1–30 Days — ${fmtRs(x.a.d30)} (${((x.a.d30 / tt) * 100).toFixed(1)}%)`}>
                              <i className="age-30" style={{ width: `${(x.a.d30 / tt) * 100}%` }} />
                            </Tooltip>
                          )}
                          {x.a.d60 > 0 && (
                            <Tooltip text={`31–60 Days — ${fmtRs(x.a.d60)} (${((x.a.d60 / tt) * 100).toFixed(1)}%)`}>
                              <i className="age-60" style={{ width: `${(x.a.d60 / tt) * 100}%` }} />
                            </Tooltip>
                          )}
                          {x.a.d90 > 0 && (
                            <Tooltip text={`61–90+ Days — ${fmtRs(x.a.d90)} (${((x.a.d90 / tt) * 100).toFixed(1)}%)`}>
                              <i className="age-90" style={{ width: `${(x.a.d90 / tt) * 100}%` }} />
                            </Tooltip>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr style={{ background: 'var(--bg-muted)', fontWeight: 800 }}>
                  <td colSpan="3" className="fee-right">GRAND TOTAL</td>
                  <td className="fee-right">{money(tot.cur)}</td>
                  <td className="fee-right">{money(tot.d30)}</td>
                  <td className="fee-right">{money(tot.d60)}</td>
                  <td className="fee-right">{money(tot.d90)}</td>
                  <td className="fee-right">{money(tot.cur + tot.d30 + tot.d60 + tot.d90)}</td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      </div>
    </>
  );
}

/* ════════════ 5. COLLECTION vs EXPECTED ════════════ */
function ReportPanelSummary({ toast }) {
  const school = useContext(FeeReportBranchContext);
  /* REAL ledger (sample data nahi) — chune hue mahine ke liye:
       Expected    = us mahine BANE challans ka bill (discount ke baad)
       Collected   = us mahine ki receipts (installment date se, kisi bhi challan par)
       Discount    = us mahine ke challans ka discount (manager + receiving)
       Outstanding = mahine ke aakhir tak ka baqaya (ledgerPendingAsOf), defaulters = baqaya > 0 */
  const [selMonth, setSelMonth] = useState(FEE_MONTHS[new Date().getMonth()]);
  const [selYear, setSelYear] = useState(String(new Date().getFullYear()));
  const selM = FEE_MONTHS.indexOf(selMonth) + 1;
  const selY = Number(selYear) || new Date().getFullYear();
  const periods = useMemo(() => {
    const back = new Date(selY, selM - 13, 1);
    return ledgerPeriods(back.getMonth() + 1, back.getFullYear(), selM, selY);
  }, [selM, selY]);
  const { classes, studentsMap, allStudents, loading, error } = useLedgerReportData(periods);
  const data = useMemo(() => {
    const ym = `${selY}-${String(selM).padStart(2, '0')}`;
    const monthKey = selY * 12 + selM;
    const cutoff = `${ym}-${String(new Date(selY, selM, 0).getDate()).padStart(2, '0')}`;
    const startOf = (x) => Number(x.startYear || x.year) * 12 + Number(x.startMonth || x.month);
    const byClass = {};
    const receipts = [];
    let exp = 0, recv = 0, disc = 0, pend = 0, def = 0, paid = 0, n = 0;
    allStudents.forEach(({ c, s, m }) => {
      const recs = m.recs || [];
      if (!recs.length) return;
      n += 1;
      let e = 0, r = 0;
      recs.forEach(rec => {
        if (startOf(rec) === monthKey) {
          (rec.detailRows || []).forEach(row => {
            if (isLedgerCarryRow(row)) return;
            e += (+row.challanAmount || 0) - (+row.discount || 0);
            disc += (+row.discount || 0);
          });
        }
        const method = feeService.paymentMethodDisplay(rec.paymentMethod) || 'Cash';
        ledgerInstallmentReceipts(rec).forEach(p => {
          if (String(p.date || '').slice(0, 7) !== ym || !p.amount) return;
          r += p.amount;
          receipts.push({ name: s.name, father: s.father, cls: `${c.cls}/${c.sec}`, reg: s.reg, date: p.date, time: p.time, method, ref: `CH-${rec.id}/${p.no}`, amt: p.amount });
        });
      });
      const net = [...ledgerPendingAsOf(recs, monthKey, cutoff).values()].reduce((a2, v) => a2 + v, 0);
      if (net > 0) { pend += Math.round(net); def += 1; } else if (r > 0) paid += 1;
      exp += e; recv += r;
      const k = c.key;
      byClass[k] = byClass[k] || { label: `${c.cls} ${c.sec}`, e: 0, r: 0 };
      byClass[k].e += e; byClass[k].r += r;
    });
    const modes = repPayModesFromReceipts([{ payments: receipts.map(x => ({ method: x.method, amount: x.amt })) }]);
    return {
      totals: { exp, recv, pend, disc, adv: 0, def, paid, n },
      modes, receipts,
      sectionsData: classes.filter(c => (studentsMap[c.key] || []).length).map(c => byClass[c.key] || { label: `${c.cls} ${c.sec}`, e: 0, r: 0 }),
    };
  }, [allStudents, classes, studentsMap, selM, selY]);
  const totals = data.totals;
  const real = totals.exp ? Math.round(totals.recv / totals.exp * 100) : 0;
  const modes = data.modes;
  const modeTot = modes.reduce((a, m) => a + m.amt, 0) || 1;
  const sectionsData = data.sectionsData;
  const maxE = Math.max(...sectionsData.map(s => s.e), 1);

  const reportTitle = 'Collection vs Expected';
  const downloadReport = (style, format) => {
    const html = buildRepSummaryHTML({ totals, real, modes, modeTot, sectionsData, isBW: style === 'bw', school });
    openPrintReport(html, reportTitle, toast, format);
  };
  const [modePicker, setModePicker] = useState(null); // { mode: string } | null
  const downloadByMode = (mode, style, format) => {
    const rows = data.receipts.filter(x => (x.method || 'Cash') === mode);
    const html = buildRepPayModeHTML({ method: mode, rows, isBW: style === 'bw', school });
    openPrintReport(html, `${mode} Collections`, toast, format);
  };

  return (
    <>
      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span>The <strong>collection summary</strong> compares expected (billed) revenue against actual receipts, shows realisation %, and breaks receipts down by payment mode.</span>
      </div>

      <RepLoadState loading={loading} error={error} />

      {repKpiStrip([
        ['k-blue', 'fa-file-invoice-dollar', 'Expected Revenue', fmtRs(totals.exp), ''],
        ['k-green', 'fa-sack-dollar', 'Collected', fmtRs(totals.recv), <span><b className="up">{real}%</b> realised</span>],
        ['k-amber', 'fa-percent', 'Discount / Waiver', fmtRs(totals.disc), ''],
        ['k-red', 'fa-clock', 'Outstanding', fmtRs(totals.pend), `${totals.def} defaulters`],
      ])}

      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field">
              <span className="fee-label">Month</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={selMonth} onChange={e => setSelMonth(e.target.value)}>
                  {FEE_MONTHS.map(m => <option key={m}>{m}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Year</span>
              <input className="fee-input" type="number" value={selYear} onChange={e => setSelYear(e.target.value)} style={{ width: 110 }} />
            </div>
            <RepActions title={reportTitle} onGenerate={downloadReport} />
          </div>
        </div>
      </div>

      <div className="fee-section">
        <div className="fee-section-header">
          <div className="fee-section-title">
            <div className="fee-section-icon"><i className="fa-solid fa-chart-column"></i></div>
            <div>
              <div className="fee-section-name">Expected vs Collected by Section</div>
              <div className="fee-section-sub">Billed (blue) against actual receipts (green)</div>
            </div>
          </div>
        </div>
        <div className="fee-section-body">
          <div className="rep-bars">
            {sectionsData.map(c => {
              const pend = Math.max(c.e - c.r, 0);
              const pct = c.e > 0 ? Math.round(c.r / c.e * 100) : 0;
              return (
                <div key={c.label} className="rep-bar-col">
                  <div className="rep-bar-pair">
                    <Tooltip text={`${c.label} · Expected — ${fmtRs(c.e)}  ·  Pending ${fmtRs(pend)}`}>
                      <div className="rep-bar" style={{ height: `${(c.e / maxE) * 100}%` }} />
                    </Tooltip>
                    <Tooltip text={`${c.label} · Collected — ${fmtRs(c.r)}  (${pct}% realised)`}>
                      <div className="rep-bar green" style={{ height: `${(c.r / maxE) * 100}%` }} />
                    </Tooltip>
                  </div>
                  <Tooltip text={`${c.label} — Expected ${fmtRs(c.e)} · Collected ${fmtRs(c.r)} · Pending ${fmtRs(pend)}`}>
                    <div className="rep-bar-lbl">{c.label}</div>
                  </Tooltip>
                </div>
              );
            })}
          </div>
          <div className="age-legend" style={{ margin: '14px 0 0' }}>
            <span><i className="age-dot" style={{ background: '#1E3A8A' }}></i> Expected</span>
            <span><i className="age-dot" style={{ background: '#16A34A' }}></i> Collected</span>
          </div>
        </div>
      </div>

      <div className="fee-section">
        <div className="fee-section-header">
          <div className="fee-section-title">
            <div className="fee-section-icon"><i className="fa-solid fa-money-bill-transfer"></i></div>
            <div>
              <div className="fee-section-name">Collection by Payment Mode</div>
              <div className="fee-section-sub">How {fmtRs(modeTot)} received this period was paid</div>
            </div>
          </div>
        </div>
        <div className="fee-section-body">
          <div className="mode-grid">
            {modes.length === 0 ? (
              <div style={{ color: 'var(--text-muted)', fontSize: 12.5 }}>No payments recorded yet.</div>
            ) : modes.map(m => {
              const pct = Math.round(m.amt / modeTot * 100);
              return (
                <div key={m.name} className="mode-card">
                  <div className="mode-card-top">
                    <div className="mode-ic" style={{ background: m.col }}><i className={`fa-solid ${m.ic}`}></i></div>
                    <div className="mode-name">{m.name}</div>
                    <div className="mode-actions">
                      <Tooltip text={`Download ${m.name} report`}>
                        <button className="mode-act-btn" onClick={() => setModePicker({ mode: m.name })}>
                          <i className="fa-solid fa-download"></i>
                        </button>
                      </Tooltip>
                    </div>
                  </div>
                  <div className="mode-amt">{fmtRs(m.amt)}</div>
                  <div className="mode-pct">{pct}% of receipts</div>
                  <div className="mode-track"><i style={{ width: `${pct}%`, background: m.col }} /></div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {modePicker && (
        <StandardReportPicker
          open
          title={`${modePicker.mode} Collections`}
          subtitle="Choose style and format, then generate."
          formats={['pdf', 'word', 'excel']}
          onClose={() => setModePicker(null)}
          onGenerate={(style, format) => { downloadByMode(modePicker.mode, style, format); setModePicker(null); }}
        />
      )}
    </>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   PORTED FEE REPORTS (read-only) — wired to the ERP's real fee data
   (BranchLedger challans via useLedgerReportData/ledgerModel, the
   transport roster via useReportData, and preEnrollmentService).
   Each report reuses the shared FeeReportBranchContext /
   repWrap / repKpiStrip / RepActions machinery so it matches the six
   original reports. Where the ERP genuinely has no data source yet
   (advance ledger history, partial-challan store, pre-enroll payment
   API) the report still renders with a clear empty state instead of
   fabricated numbers.
   ═══════════════════════════════════════════════════════════════════ */

function headsLabelFor(mode, heads) {
  return mode === 'all' ? 'All Heads' : (heads && heads.length ? heads.join(', ') : 'None');
}

/* Ek student ka per-head PENDING, chune hue mahine ke AAKHIR tak (as-of):
     - Sirf wo challans jin ka start mahina <= selected mahina.
     - Naye se purane ki taraf: challan shamil; agar wo purana baqaya CARRY karta hai
       (head prev / "Previous Pending" row) to us se purane chhod do (warna double).
     - Per head: challan − manager discount − give (cutoff tak) + carried prev − received
       (cutoff tak, installment ki receiving date se). Baad me hui wasooli nahi ginti —
       purane mahine ka report us waqt ka asal baqaya dikhata hai.
   Returns Map(head → pending). */
export function ledgerPendingAsOf(recs, monthKey, cutoffISO) {
  const startOf = (x) => Number(x.startYear || x.year) * 12 + Number(x.startMonth || x.month);
  const list = (recs || [])
    .filter(r => startOf(r) <= monthKey)
    .sort((a, b) => (startOf(b) - startOf(a)) || (Number(b.id) - Number(a.id)));
  const use = [];
  for (const rec of list) {
    use.push(rec);
    if (challanCarriesPrev(rec)) break;
  }
  const out = new Map();
  const hpOf = (r) => Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0;
  use.forEach(rec => {
    /* Heads par head-wise prev ho to aggregate "Previous Pending" row skip (wahi baqaya do
       dafa) — receiving/challanFigures jaisa. Carry row ki apni previousPendingorAdv kabhi
       nahi jodte (505: row 13,850 + us par 6,850 = 20,700 double tha). */
    const rows = rec.detailRows || [];
    const headWise = rows.some(r => !isLedgerCarryRow(r) && !feeService.isLateFineRow(r) && hpOf(r) !== 0);
    rows.forEach(r => {
    if (isLedgerCarryRow(r) && headWise) return;
    if ((+r.challanAmount || 0) < 0 && isLedgerCarryRow(r)) return;   // advance-consumption row
    const mgr = r._mgrDisc != null ? +r._mgrDisc : (+r.discount || 0) - (r._recvFolded ? (+r.recvDiscount || 0) : 0);
    let recv = 0, give = 0;
    const insts = Array.isArray(r.installments) ? r.installments : [];
    if (insts.length) {
      insts.forEach(i => {
        const d = String(i.receivedDate || '').slice(0, 10);
        if (d && d > cutoffISO) return;
        recv += +i.receivedAmount || 0;
        give += Math.max(0, +i.recvDiscount || 0);
      });
    } else {
      const d = String(rec.receivedDate || '').slice(0, 10);
      if (!d || d <= cutoffISO) { recv = +r.receivedAmount || 0; give = Math.max(0, +r.recvDiscount || 0); }
    }
    const hp = isLedgerCarryRow(r) ? 0 : (feeHeadPrev(r) || 0);
    const pend = (+r.challanAmount || 0) - mgr - give + hp - recv;
    const name = r.subHead || r.head || '—';
    out.set(name, (out.get(name) || 0) + pend);
    });
  });
  return out;
}

/* Challan ki due date — na ho (multi-month) to issue date + 10 din. */
function challanDueISO(rec) {
  const d = String(rec?.dueDate || '').slice(0, 10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(d)) return d;
  const c = String(rec?.dateofCreattion || rec?.createdAt || '').slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(c)) return '';
  const dt = new Date(`${c}T00:00:00`);
  dt.setDate(dt.getDate() + 10);
  return localDateISO(dt);
}

/* AGING (asOf tak): ledgerPendingAsOf wala challan-chain, magar har challan ka baqaya do
   hisson me — carried (purana, pehle wasool hota hai) aur apna (is challan ka bill).
   Apna hissa is challan ki due date se, carried hissa us se purane challan ki due date se
   (na ho to 30 din pehle) purana gina jata hai. Buckets: Current (due nahi guzri) / 1–30 /
   31–60 / 61+ din. Returns { cur, d30, d60, d90, total }. */
function ledgerAgingAsOf(recs, asOfISO) {
  const out = { cur: 0, d30: 0, d60: 0, d90: 0, total: 0 };
  const [ay, am] = String(asOfISO || '').split('-').map(Number);
  if (!ay || !am) return out;
  const monthKey = ay * 12 + am;
  const startOf = (x) => Number(x.startYear || x.year) * 12 + Number(x.startMonth || x.month);
  const list = (recs || [])
    .filter(r => startOf(r) <= monthKey)
    .sort((a, b) => (startOf(b) - startOf(a)) || (Number(b.id) - Number(a.id)));
  const hpOf = (r) => Number(r.previousPendingorAdv ?? r.previousPendingOrAdv) || 0;
  const asOfMs = new Date(`${asOfISO}T00:00:00`).getTime();
  const put = (amt, dueISO) => {
    if (amt <= 0) return;
    const days = dueISO ? Math.floor((asOfMs - new Date(`${dueISO}T00:00:00`).getTime()) / 86400000) : 0;
    if (days <= 0) out.cur += amt; else if (days <= 30) out.d30 += amt; else if (days <= 60) out.d60 += amt; else out.d90 += amt;
    out.total += amt;
  };
  for (let i = 0; i < list.length; i++) {
    const rec = list[i];
    const rows = rec.detailRows || [];
    const headWise = rows.some(r => !isLedgerCarryRow(r) && !feeService.isLateFineRow(r) && hpOf(r) !== 0);
    let own = 0, carried = 0, recv = 0;
    rows.forEach(r => {
      if ((+r.challanAmount || 0) < 0 && isLedgerCarryRow(r)) return;
      const mgr = r._mgrDisc != null ? +r._mgrDisc : (+r.discount || 0) - (r._recvFolded ? (+r.recvDiscount || 0) : 0);
      let rv = 0, give = 0;
      const insts = Array.isArray(r.installments) ? r.installments : [];
      if (insts.length) {
        insts.forEach(x => {
          const d = String(x.receivedDate || '').slice(0, 10);
          if (d && d > asOfISO) return;
          rv += +x.receivedAmount || 0;
          give += Math.max(0, +x.recvDiscount || 0);
        });
      } else {
        const d = String(rec.receivedDate || '').slice(0, 10);
        if (!d || d <= asOfISO) { rv = +r.receivedAmount || 0; give = Math.max(0, +r.recvDiscount || 0); }
      }
      recv += rv;
      if (isLedgerCarryRow(r)) { if (!headWise) carried += (+r.challanAmount || 0) - mgr - give; return; }
      own += (+r.challanAmount || 0) - mgr - give;
      if (headWise) carried += hpOf(r);
    });
    const carriedOut = Math.max(0, carried - recv);
    const ownOut = Math.max(0, own - Math.max(0, recv - carried));
    const ownDue = challanDueISO(rec);
    const olderDue = list[i + 1] ? challanDueISO(list[i + 1]) : (() => {
      if (!ownDue) return '';
      const d = new Date(`${ownDue}T00:00:00`); d.setDate(d.getDate() - 30); return localDateISO(d);
    })();
    put(Math.round(ownOut), ownDue);
    put(Math.round(carriedOut), olderDue);
    if (challanCarriesPrev(rec)) break;   // purane challans ka baqaya isi me carry
  }
  return out;
}

/* Per-head outstanding per student AS OF selected month ke aakhir tak (ledgerPendingAsOf) —
   challan us mahine bana ho ya nahi, purana baqaya bhi aata hai. One group per student. */
function buildPendingDuesGroups({ classes, studentsMap, allStudents, headMode, selectedHeads, monthKey, cutoffISO }) {
  const keep = (name) => headMode === 'all' || selectedHeads.includes(name);
  const groups = [];
  classes.forEach(c => {
    (studentsMap[c.key] || []).forEach(s => {
      const m = allStudents.find(x => x.c.key === c.key && x.s.reg === s.reg)?.m;
      if (!m) return;
      const perHead = ledgerPendingAsOf(m.recs || [], monthKey, cutoffISO);
      const entries = [...perHead.entries()]
        .map(([head, amt]) => ({ head, amount: Math.round(+amt || 0) }))
        .filter(e => e.amount > 0 && keep(e.head));
      if (!entries.length) return;
      const total = entries.reduce((a, e) => a + e.amount, 0);
      groups.push({ classKey: c.key, reg: s.reg, name: s.name, father: s.father, cls: c.cls, sec: c.sec, entries, total });
    });
  });
  const summary = {
    totalAmount: groups.reduce((a, g) => a + g.total, 0),
    totalStudents: groups.length,
    totalEntries: groups.reduce((a, g) => a + g.entries.length, 0),
  };
  return { groups, summary };
}

/* ════════════ PENDING DUES REPORT ════════════ */
function ReportPanelPendingDues({ toast }) {
  const school = useContext(FeeReportBranchContext);
  const [month, setMonth] = useState(FEE_MONTHS[new Date().getMonth()]);
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [headMode, setHeadMode] = useState('all');
  const [selectedHeads, setSelectedHeads] = useState([]);

  /* Selected mahina + us se PEHLE ke 12 mahine — purana baqaya (challan is mahine na ho tab
     bhi) as-of hisaab me aa sake. Cutoff = selected mahine ki aakhri taareekh. */
  const selM = FEE_MONTHS.indexOf(month) + 1;
  const selY = Number(year) || new Date().getFullYear();
  const monthKey = selY * 12 + selM;
  const cutoffISO = `${selY}-${String(selM).padStart(2, '0')}-${String(new Date(selY, selM, 0).getDate()).padStart(2, '0')}`;
  const periods = useMemo(() => {
    const back = new Date(selY, selM - 13, 1);
    return ledgerPeriods(back.getMonth() + 1, back.getFullYear(), selM, selY);
  }, [selM, selY]);
  const { classes, studentsMap, allStudents, loading, error } = useLedgerReportData(periods);

  const allHeads = useMemo(() => {
    const set = new Set();
    /* As-of pending wale heads (selected mahine tak). */
    allStudents.forEach(({ m }) => ledgerPendingAsOf(m.recs || [], monthKey, cutoffISO).forEach((v, k) => { if (v > 0) set.add(k); }));
    return Array.from(set).sort((a, b) => String(a).localeCompare(String(b)));
  }, [allStudents, monthKey, cutoffISO]);
  const toggleHead = (h) => setSelectedHeads(prev => prev.includes(h) ? prev.filter(x => x !== h) : [...prev, h]);

  const { groups, summary } = useMemo(
    () => buildPendingDuesGroups({ classes, studentsMap, allStudents, headMode, selectedHeads, monthKey, cutoffISO }),
    [classes, studentsMap, allStudents, headMode, selectedHeads, monthKey, cutoffISO],
  );
  const asOfLabel = `${month} ${year}`;

  const reportTitle = `Pending Dues — ${asOfLabel}`;
  const downloadReport = (style, format) => {
    const html = buildRepPendingDuesHTML({ groups, summary, asOfDate: asOfLabel, headMode, selectedHeads, isBW: style === 'bw', school });
    openPrintReport(html, reportTitle, toast, format);
  };

  return (
    <>
      <div className="fee-seg">
        <button className={`fee-seg-btn${headMode === 'all' ? ' active' : ''}`} onClick={() => setHeadMode('all')}>
          <i className="fa-solid fa-layer-group"></i> All Heads
        </button>
        <button className={`fee-seg-btn${headMode === 'selected' ? ' active' : ''}`} onClick={() => setHeadMode('selected')}>
          <i className="fa-solid fa-list-check"></i> Select Fee Heads
        </button>
      </div>

      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span>Outstanding balance by fee head <b>as of the end of the selected month</b> — every unpaid due up to that month (even if no challan was generated in it), with only the payments received up to that date deducted.</span>
      </div>

      <RepLoadState loading={loading} error={error} />

      {repKpiStrip([
        ['k-red', 'fa-triangle-exclamation', 'Total Pending', fmtRs(summary.totalAmount), ''],
        ['k-blue', 'fa-user-graduate', 'Students', `${summary.totalStudents}`, ''],
        ['k-amber', 'fa-list-ul', 'Pending Entries', `${summary.totalEntries}`, ''],
        ['k-green', 'fa-layer-group', 'Selected Heads', headsLabelFor(headMode, selectedHeads), ''],
      ])}

      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field">
              <span className="fee-label">Select Month</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={month} onChange={e => setMonth(e.target.value)}>
                  {FEE_MONTHS.map(m => <option key={m}>{m}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Year</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={year} onChange={e => setYear(e.target.value)}>
                  <option>2025</option><option>2026</option><option>2027</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <RepActions title={reportTitle} onGenerate={downloadReport} />
          </div>

          {headMode === 'selected' && (
            <div className="fee-field" style={{ marginTop: 14 }}>
              <span className="fee-label">Fee Heads{selectedHeads.length ? ` — ${selectedHeads.length} selected` : ''}</span>
              <div className="fee-headchip-row">
                {allHeads.length === 0 ? (
                  <span style={{ color: 'var(--text-muted)', fontSize: 12.5 }}>No fee heads with dues in this month.</span>
                ) : allHeads.map(h => (
                  <button type="button" key={h} className={`fee-headchip${selectedHeads.includes(h) ? ' active' : ''}`} onClick={() => toggleHead(h)}>
                    {selectedHeads.includes(h) && <i className="fa-solid fa-check"></i>} {h}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="fee-section">
        <div className="fee-section-body">
          <div className="fee-detail-title">
            <i className="fa-solid fa-triangle-exclamation"></i> Pending Dues — {asOfLabel}
          </div>
          <div className="fee-stbl-wrap">
            <table className="fee-stbl">
              <thead>
                <tr>
                  <th>Sr#</th><th>Student Name</th><th>Admission No</th><th>Class</th><th>Section</th>
                  <th>Fee Head</th><th className="fee-right">Pending Amount</th>
                </tr>
              </thead>
              <tbody>
                {groups.length === 0 ? (
                  <tr><td colSpan="7" className="fee-stbl-empty">No pending dues for the selected month / fee head(s).</td></tr>
                ) : groups.map((g, gi) => (
                  <React.Fragment key={`${g.classKey}-${g.reg}`}>
                    {g.entries.map((e, ei) => (
                      <tr key={`${g.reg}-${ei}`}>
                        {ei === 0 && (
                          <>
                            <td className="fee-num" rowSpan={g.entries.length}>{gi + 1}</td>
                            <td rowSpan={g.entries.length}><b>{g.name}</b><span className="fee-sub-eq">s/o {g.father || '—'}</span></td>
                            <td rowSpan={g.entries.length}>{g.reg}</td>
                            <td rowSpan={g.entries.length}>{g.cls}</td>
                            <td rowSpan={g.entries.length}>{g.sec}</td>
                          </>
                        )}
                        <td>{e.head}</td>
                        <td className="fee-right"><span className="fee-neg">{money(e.amount)}</span></td>
                      </tr>
                    ))}
                    {g.entries.length > 1 && (
                      <tr className="fee-recv-total">
                        <td colSpan="6" style={{ textAlign: 'right', fontWeight: 800 }}>Total — {g.name}</td>
                        <td className="fee-right"><span className="fee-neg">{money(g.total)}</span></td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
}

/* ════════════ ONELINK PAYMENT REPORT ════════════
   Real OneLink / bank transactions from the ledger: any challan whose
   paymentMethod resolves to OneLink / 1Link / Bank and that has a
   received amount, within the selected period. */
function ReportPanelOneLink({ toast }) {
  const school = useContext(FeeReportBranchContext);
  const [seg, setSeg] = useState('month');
  const [openKey, setOpenKey] = useState(null);
  const today = localTodayISO();
  const [date, setDate] = useState(today);
  const [month, setMonth] = useState(FEE_MONTHS[new Date().getMonth()]);
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [from, setFrom] = useState(today.slice(0, 8) + '01');
  const [to, setTo] = useState(today);

  const periods = useMemo(() => {
    const y = Number(year) || new Date().getFullYear();
    if (seg === 'daily') { const [yy, mm] = String(date || '').split('-'); return [{ month: Number(mm) || 1, year: Number(yy) || y }]; }
    if (seg === 'range') {
      const [fy, fm] = String(from || '').split('-'); const [ty, tm] = String(to || '').split('-');
      return ledgerPeriods(Number(fm) || 1, Number(fy) || y, Number(tm) || 12, Number(ty) || y);
    }
    return [{ month: FEE_MONTHS.indexOf(month) + 1, year: y }];
  }, [seg, date, from, to, month, year]);

  const { classes, allStudents, loading, error } = useLedgerReportData(periods);

  const txByClass = useMemo(() => {
    const isOnelink = (raw) => /one\s*link|1\s*link|bank/i.test(feeService.paymentMethodDisplay(raw));
    const inPeriod = (d) => {
      if (!d) return false;
      if (seg === 'daily') return d === date;
      if (seg === 'range') return d >= from && d <= to;
      const dd = new Date(d);
      return dd.getMonth() === FEE_MONTHS.indexOf(month) && dd.getFullYear() === (Number(year) || dd.getFullYear());
    };
    const map = {};
    allStudents.forEach(({ c, s, m }) => {
      (m.recs || []).forEach(rec => {
        if (!isOnelink(rec.paymentMethod)) return;
        const received = (rec.detailRows || []).reduce((a, r) => a + Math.max(0, +r.receivedAmount || 0), 0);
        if (received <= 0) return;
        const d = String(rec.receivedDate || rec.modifiedAt || rec.dateofCreattion || '').slice(0, 10);
        if (!inPeriod(d)) return;
        (map[c.key] ||= []).push({ s, p: { amount: received, date: d, time: '', method: feeService.paymentMethodDisplay(rec.paymentMethod), source: 'onelink', txn: feeService.psidOf(rec) } });
      });
    });
    return map;
  }, [allStudents, seg, date, from, to, month, year]);

  const allTx = useMemo(() => Object.values(txByClass).flat(), [txByClass]);
  const totalTx = allTx.length;
  const totalAmt = allTx.reduce((a, x) => a + (+x.p.amount || 0), 0);
  const modeBreak = useMemo(() => {
    const map = {};
    allTx.forEach(x => { const k = x.p.method || 'Bank Transfer'; map[k] = (map[k] || 0) + (+x.p.amount || 0); });
    return Object.keys(map).map(k => ({ name: k, amt: map[k] }));
  }, [allTx]);
  const periodLabel = seg === 'daily' ? date : seg === 'range' ? `${from} – ${to}` : `${month} ${year}`;

  const reportTitle = `OneLink Payment Report — ${periodLabel}`;
  const downloadReport = (style, format) => {
    const html = buildRepOneLinkHTML({ classes, txByClass, seg, date, month, year, from, to, totalTx, totalAmt, modeBreak, isBW: style === 'bw', school });
    openPrintReport(html, reportTitle, toast, format);
  };

  return (
    <>
      <div className="fee-seg">
        <button className={`fee-seg-btn${seg === 'month' ? ' active' : ''}`} onClick={() => setSeg('month')}>
          <i className="fa-solid fa-calendar-week"></i> Month
        </button>
        <button className={`fee-seg-btn${seg === 'range' ? ' active' : ''}`} onClick={() => setSeg('range')}>
          <i className="fa-solid fa-calendar-days"></i> Date Range
        </button>
        <button className={`fee-seg-btn${seg === 'daily' ? ' active' : ''}`} onClick={() => setSeg('daily')}>
          <i className="fa-solid fa-calendar-day"></i> Single Date
        </button>
      </div>

      <div className="fee-info">
        <i className="fa-solid fa-circle-info"></i>
        <span>All payments received through <strong>OneLink / Bank</strong> — read from the ledger and filtered by month, date range or a single date.</span>
