/* Filesystem-safe report file name — strips punctuation, collapses spaces. */
const reportFileName = (title) => (title || 'Report').replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-');

/* Trigger a real .xlsx file download from an in-memory ExcelJS workbook —
   real column widths, bold headers, native number formats (none of which
   the HTML-table-as-.xls trick can do). */
async function feeDownloadWorkbook(wb, filename) {
  const buffer = await wb.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/* DD-Mon-YYYY formatter for the Generated Challans export — full 4-digit
   year (reads/sorts better in Excel than a 2-digit slip date). */
const fmtGenChallanDate = (iso) => {
  const m = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const [y, mo, d] = iso.split('-');
  return `${d}-${m[(+mo - 1) || 0]}-${y}`;
};

/* Excel export for Fee Challans → Generated Challans. `rows` is every
   already-generated { c: classMeta, s: student, payable, genISO, dueISO }
   pair for the applied month/year — the complete generated-challan dataset,
   built by the caller from the full class/student roster, not from whatever
   "Search Student" happens to be filtering to on screen. Contact Number
   reuses studentPhone(); payable + genISO/dueISO are precomputed by the
   caller from the real BranchLedger challan record. */
function buildGeneratedChallansWorkbook({ rows, monthIdx, appliedMonth, appliedYear, school }) {
  const wb = new ExcelJS.Workbook();
  wb.creator = 'School Mentor';
  wb.created = new Date();
  const ws = wb.addWorksheet('Generated Challans');

  /* ── Discover the dynamic fee-head columns from the actual challan data ──
     Each row carries s.headAmounts (per-head net = challanAmount − discount,
     built from the challan's detailRows in the handler) and s.arrears (the
     folded previous/pending/arrear bucket). Head columns = the union of head
     names across every exported challan, in first-seen order; an "Arrears"
     column is appended only when at least one challan carries a prev/arrears
     amount. */
  const headNamesOrder = [];
  const headNamesSeen = new Set();
  rows.forEach(({ s }) => {
    Object.keys(s.headAmounts || {}).forEach(name => {
      if (!headNamesSeen.has(name)) { headNamesSeen.add(name); headNamesOrder.push(name); }
    });
  });
  const anyArrears = rows.some(({ s }) => Math.abs(Number(s.arrears) || 0) > 0);
  const dynamicHeadCols = [...headNamesOrder, ...(anyArrears ? ['Arrears'] : [])];

  const fixedCols = [
    { header: 'Sr. No',                  width: 8  },
    { header: 'Class',                   width: 16 },
    { header: 'Section',                 width: 12 },
    { header: 'Admission No.',           width: 16 },
    { header: 'Student Name',            width: 24 },
    { header: 'Father Name / Guardian',  width: 24 },
    { header: 'Address',                 width: 26 },
    { header: 'Contact Number',          width: 16 },
    { header: 'Challan Generation Date', width: 20 },
    { header: 'Due Date',                width: 16 },
  ];
  const cols = [
    ...fixedCols,
    ...dynamicHeadCols.map(name => ({ header: name, width: Math.max(14, Math.min(22, name.length + 4)) })),
    { header: 'Total Payable Amount', width: 20 },
  ];
  const FIXED_N = fixedCols.length;
  const TOTAL_CI = cols.length;
  ws.columns = cols.map(cc => ({ width: cc.width }));

  ws.mergeCells(1, 1, 1, cols.length);
  const title = ws.getCell(1, 1);
  title.value = `${(school && (school.name || school.branchName)) || 'School'} — Generated Fee Challans Report`;
  title.font = { bold: true, size: 13, color: { argb: 'FFFFFFFF' } };
  title.alignment = { horizontal: 'center', vertical: 'middle' };
  title.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
  ws.getRow(1).height = 24;

  ws.mergeCells(2, 1, 2, cols.length);
  const meta = ws.getCell(2, 1);
  meta.value = `${appliedMonth} ${appliedYear}   ·   ${rows.length} challan${rows.length === 1 ? '' : 's'}   ·   Generated: ${fmtGenChallanDate(new Date().toISOString().slice(0, 10))}`;
  meta.font = { italic: true, size: 10, color: { argb: 'FF64748B' } };
  meta.alignment = { horizontal: 'center' };
  ws.getRow(2).height = 18;

  const headerRow = ws.getRow(3);
  cols.forEach((cc, i) => {
    const cell = headerRow.getCell(i + 1);
    cell.value = cc.header;
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 10 };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
    cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
  });
  headerRow.height = 30;

  const fallbackGen = `${appliedYear}-${String(monthIdx + 1).padStart(2, '0')}-01`;
  const fallbackDue = `${appliedYear}-${String(monthIdx + 1).padStart(2, '0')}-14`;

  /* Per-head cell value for a row: the head's net challan amount, or the folded
     Arrears bucket. Total stays the ERP's payable (prev dues/advance/paid
     aware) — deliberately NOT a naive sum of the head columns. */
  const headCellAmount = (s, headName) =>
    headName === 'Arrears'
      ? (Number(s.arrears) || 0)
      : (Number((s.headAmounts || {})[headName]) || 0);

  rows.forEach(({ c, s, payable, genISO, dueISO }, i) => {
    const row = ws.getRow(4 + i);
    row.getCell(1).value = i + 1;
    row.getCell(2).value = c.cls;
    row.getCell(3).value = c.sec;
    row.getCell(4).value = s.reg || '—';
    row.getCell(5).value = s.name;
    row.getCell(6).value = s.father || '—';
    row.getCell(7).value = s.address || '—';
    row.getCell(8).value = studentPhone(s);
    row.getCell(9).value = fmtGenChallanDate(genISO || fallbackGen);
    row.getCell(10).value = fmtGenChallanDate(dueISO || fallbackDue);

    dynamicHeadCols.forEach((headName, hi) => {
      const cell = row.getCell(FIXED_N + 1 + hi);
      cell.value = headCellAmount(s, headName);
      cell.numFmt = '"Rs. "#,##0';
      cell.alignment = { horizontal: 'right' };
    });

    const totalCell = row.getCell(TOTAL_CI);
    totalCell.value = Number(payable) || 0;
    totalCell.numFmt = '"Rs. "#,##0';
    totalCell.font = { bold: true };
    totalCell.alignment = { horizontal: 'right' };

    for (let ci = 1; ci <= cols.length; ci++) {
      const cell = row.getCell(ci);
      if (ci === 1 || ci === 3) cell.alignment = { horizontal: 'center' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE2E8F0' } }, left: { style: 'thin', color: { argb: 'FFE2E8F0' } },
        bottom: { style: 'thin', color: { argb: 'FFE2E8F0' } }, right: { style: 'thin', color: { argb: 'FFE2E8F0' } },
      };
    }
  });

  ws.views = [{ state: 'frozen', ySplit: 3 }];
  return wb;
}

function feeReportSchool(school) {
  const name = school?.branchName || school?.name || FEE_SCHOOL.name;
  const words = String(name).split(/\s+/).filter(Boolean);
  return {
    name,
    monogram: school?.monogram || words.map(w => w[0]).slice(0, 2).join('').toUpperCase() || FEE_SCHOOL.monogram,
    address: school?.address || '',
    logo: school?.branchLogo || school?.logo || '',
    session: school?.academicSession || school?.session || '',
    generatedDate: school?.generatedDate || null,
    generatedBy: school?.generatedBy || sessionStorage.getItem('displayName') || sessionStorage.getItem('userName') || 'Fee',
    branchBankName:      school?.branchBankName,
    branchAccountTitle:  school?.branchAccountTitle,
    branchAccountNumber: school?.branchAccountNumber,
    branchIBAN:          school?.branchIBAN,
    branchbankCity:      school?.branchbankCity,
    branchAccountDesc:   school?.branchAccountDesc,
  };
}

function feeBankDetails(school) {
  if (!school || typeof school !== 'object') return null;
  const bankName = school.branchBankName    || school.bankName      || '';
  const title    = school.branchAccountTitle|| school.accountTitle  || '';
  const acctNo   = school.branchAccountNumber|| school.accountNumber || '';
  const iban     = school.branchIBAN        || school.iban          || '';
  const city     = school.branchbankCity    || school.branchBankCity || school.bankCity || '';
  const desc     = school.branchAccountDesc || '';
  if (!(bankName || title || acctNo || iban || city || desc)) return null;
  return { bankName, title, acctNo, iban, city, desc };
}
function feeBankBlockHtml(school, { thermal = false } = {}) {
  const b = feeBankDetails(school);
  if (!b) return '';
  const rows = [['Bank', b.bankName],['Title', b.title],['Account #', b.acctNo],['IBAN', b.iban],['Branch', b.city]].filter(([, v]) => v);
  if (!rows.length) return '';
  if (thermal) {
    return `
  <div class="th-psid" style="margin-top:5px;">
    <div class="th-psid-top">Bank Transfer Details</div>
    <div style="display:grid;grid-template-columns:auto 1fr;column-gap:6px;row-gap:1px;font-size:9.5px;">
      ${rows.map(([k, v]) => `<span style="color:#666;">${escHtml(k)}</span><span style="text-align:right;font-weight:700;color:#111;">${escHtml(String(v))}</span>`).join('')}
    </div>
    ${b.desc ? `<div style="font-size:8.5px;color:#555;margin-top:3px;">${escHtml(b.desc)}</div>` : ''}
  </div>`;
  }
  return `
    <div class="psid-block" style="margin-top:5px;">
      <div class="psid-top"><div class="psid-dot"></div><span class="psid-tag">Bank Account Details</span></div>
      <div style="display:grid;grid-template-columns:auto 1fr;column-gap:10px;row-gap:2px;font-size:10.5px;margin-top:4px;">
        ${rows.map(([k, v]) => `<span style="color:#666;">${escHtml(k)}</span><span style="text-align:right;font-weight:700;color:#111;">${escHtml(String(v))}</span>`).join('')}
      </div>
      ${b.desc ? `<div style="font-size:9.5px;color:#555;margin-top:4px;">${escHtml(b.desc)}</div>` : ''}
    </div>`;
}

function feeReportDate(school) {
  const d = school?.generatedDate ? new Date(school.generatedDate) : new Date();
  return Number.isNaN(d.getTime()) ? new Date().toLocaleDateString('en-GB') : d.toLocaleDateString('en-GB');
}

function feeReportLogoHtml(school) {
  return school.logo
    ? `<img src="${escHtml(school.logo)}" alt="${escHtml(school.name)} logo" />`
    : escHtml(school.monogram);
}

/* Live school name for the kit header — the report-header API's branch
   name when loaded; otherwise undefined so reportKit falls back to the
   live current branch (never the hard-coded FEE_SCHOOL constant). */
const feeKitSchoolName = (school) => (school && (school.branchName || school.name)) || undefined;

function repWrap(title, filters, body, isBW = false, school = null) {
  const meta = feeReportSchool(school);
  const isColor = !isBW;
  const bodyHtml = `<style>${REP_A4_CSS(isColor)}</style>
    <div class="rep-filters">${filters}</div>
    ${body}
    <div class="rep-genby">Computer generated report · By: ${escHtml(meta.generatedBy)}</div>`;
  return buildStandardReportHtml({ title: escHtml(title), format: 'pdf', isColor, bodyHtml, schoolName: feeKitSchoolName(school) && escHtml(feeKitSchoolName(school)) });
}


function buildRepDefaulterHTML({ groups, totals, month, year, scope = 'all', isBW = false, school = null }) {
  const fmt = (n) => (+n || 0).toLocaleString('en-PK');
  const blocks = (groups || []).map(({ c, list }) => {
    if (!list.length) return '';
    const sub = list.reduce((a, x) => a + x.rem, 0);
    const subFine = list.reduce((a, x) => a + x.finePend, 0);
    return `<div class="rep-secttl">${escHtml(c.cls)} — Section ${escHtml(c.sec)} · ${list.length} defaulter(s)</div>
      <table class="rep-tbl">
        <thead><tr><th>Sn.</th><th>Student</th><th>Father</th><th>Reg No</th><th>Contact</th><th>Unpaid Heads</th><th>Due Date</th><th class="r">Fine</th><th class="r">Pending</th></tr></thead>
        <tbody>${list.map((x, j) => `<tr><td>${j + 1}</td><td><b>${escHtml(x.s.name)}</b></td><td>${escHtml(x.s.father || '—')}</td><td>${escHtml(x.s.reg)}</td><td>${escHtml(studentPhone(x.s))}</td><td>${escHtml(x.heads.join(', ') || '—')}</td><td>${escHtml(fmtDMY(x.due) || '—')}</td><td class="r ${x.finePend > 0 ? 'neg' : ''}">${fmt(x.finePend)}</td><td class="r neg">${fmt(x.rem)}</td></tr>`).join('')}</tbody>
        <tfoot><tr class="rep-tot"><td colspan="7">${escHtml(c.cls)}/${escHtml(c.sec)} Subtotal</td><td class="r">${fmt(subFine)}</td><td class="r">${fmt(sub)}</td></tr></tfoot>
