          <tbody>${list.map((x, j) => `<tr>
            <td>${j + 1}</td>
            <td><b>${escHtml(x.s.name)}</b></td>
            <td>${escHtml(x.s.father || '—')}</td>
            <td>${escHtml(x.s.reg)}</td>
            <td>${escHtml(studentPhone(x.s))}</td>
            <td>${escHtml(ledgerMonthLabel(x.rec))}</td>
