    `<table class="rep-tbl"><thead><tr><th>Sn.</th><th>Student</th><th>Class/Sec</th><th>Reg No</th><th>Date &amp; Time</th><th>Reference</th><th class="r">Amount</th></tr></thead>
      <tbody>${trs || `<tr><td colspan="7" style="text-align:center;color:#94A3B8">No payments via ${escHtml(method)}.</td></tr>`}</tbody>
      <tfoot><tr class="rep-tot"><td colspan="6">Total</td><td class="r">${total.toLocaleString('en-PK')}</td></tr></tfoot>
    </table>`, isBW, school);
}

/* Kit subtitle for the standalone Fee Heads / Transport Fee reports —
   keeps the live academic session (previously in the bespoke header)
   alongside the report's own count line. */
const feeKitSubtitle = (meta, extra) => [
  meta.session ? `Academic Session: ${escHtml(meta.session)}` : reportAcademicYear(),
  extra,
].filter(Boolean).join(' · ');

function buildTransportReportHTML({ cls, sec, rows, isBW = false, school = null }) {
  const meta = feeReportSchool(school);
  const charged = rows.filter(r => +r.transport > 0);
  const subtotal = rows.reduce((s, r) => s + (+r.transport || 0), 0);
  const trs = rows.map((s, i) => `
    <tr>
      <td style="padding:8px 10px;border-bottom:1px solid #E5E7EB">${i + 1}</td>
      <td style="padding:8px 10px;border-bottom:1px solid #E5E7EB">${escHtml(s.reg)}</td>
      <td style="padding:8px 10px;border-bottom:1px solid #E5E7EB"><b>${escHtml(s.name)}</b></td>
      <td style="padding:8px 10px;border-bottom:1px solid #E5E7EB">${escHtml(s.father)}</td>
      <td style="padding:8px 10px;border-bottom:1px solid #E5E7EB;text-align:right;font-variant-numeric:tabular-nums">${+s.transport > 0 ? `Rs. ${(+s.transport).toLocaleString('en-PK')}` : '<span style="color:#94A3B8">—</span>'}</td>
    </tr>`).join('');

  const bodyHtml = `<style>
    table { width:100%; border-collapse:collapse; margin-top:8px; }
    thead th { background:#EFF6FF; color:#1E3A5F; font-weight:800; text-align:left; padding:10px; border-bottom:2px solid #BFDBFE; font-size:11px; text-transform:uppercase; letter-spacing:.4px; }
    thead th.right { text-align:right; }
    tfoot td { padding:10px; font-weight:800; background:#F8FAFF; border-top:2px solid #1E3A8A; }
    tfoot td.right { text-align:right; }
    .rep-genby { margin-top:14px; text-align:right; font-size:11px; color:#64748B; }
  </style>
  <table>
    <thead>
      <tr>
        <th style="width:48px">#</th>
        <th style="width:130px">Reg No</th>
        <th>Name</th>
        <th>Father Name</th>
        <th class="right" style="width:140px">Transport Fee</th>
      </tr>
    </thead>
    <tbody>${trs || `<tr><td colspan="5" style="text-align:center;padding:18px;color:#64748B">No students enrolled.</td></tr>`}</tbody>
    ${rows.length > 0 ? `<tfoot><tr><td colspan="4">Monthly transport collection</td><td class="right">Rs. ${subtotal.toLocaleString('en-PK')}</td></tr></tfoot>` : ''}
  </table>
  <div class="rep-genby">By: ${escHtml(meta.generatedBy)}</div>`;

  return buildStandardReportHtml({
    title: escHtml(`Transport Fee — ${cls} (${sec})`),
    format: 'pdf',
    isColor: !isBW,
    bodyHtml,
    subtitleLine: feeKitSubtitle(meta, `${charged.length} of ${rows.length} student${rows.length === 1 ? '' : 's'} using transport`),
    schoolName: feeKitSchoolName(school) && escHtml(feeKitSchoolName(school)),
  });
}

/* Vehicle-wise transport report — shared repWrap header/footer (report-header API). */
function buildVehicleReportHTML({ vehicles = [], students = [], school = null, isBW = false }) {
  const cell = 'padding:8px 10px;border-bottom:1px solid #E5E7EB';
  const rowsFor = (list) => list.map((s, i) => `
    <tr>
      <td style="${cell}">${i + 1}</td>
      <td style="${cell}">${escHtml(s.reg)}</td>
      <td style="${cell}"><b>${escHtml(s.name)}</b></td>
      <td style="${cell}">${escHtml(s.route || '—')}</td>
      <td style="${cell};text-align:right;font-variant-numeric:tabular-nums">${+s.transport > 0 ? `Rs. ${(+s.transport).toLocaleString('en-PK')}` : '<span style="color:#94A3B8">—</span>'}</td>
    </tr>`).join('');

  const withVeh = students.filter(s => s.vehicleId);
  const unassigned = students.filter(s => !s.vehicleId && +s.transport > 0);

  const blocks = vehicles.map(v => {
    const list = withVeh.filter(s => String(s.vehicleId) === String(v.id));
    const subtotal = list.reduce((a, s) => a + (+s.transport || 0), 0);
    return `
    <div class="rep-secttl">${escHtml(v.name)} — ${escHtml(v.regNo)}${v.route ? ` · ${escHtml(v.route)}` : ''} · ${list.length} student${list.length === 1 ? '' : 's'}</div>
    <table class="rep-tbl"><thead><tr>
      <th style="width:48px">#</th><th style="width:130px">Reg No</th><th>Name</th><th>Route / Area</th><th class="r" style="width:140px">Transport Fee</th>
    </tr></thead>
    <tbody>${rowsFor(list) || `<tr><td colspan="5" style="text-align:center;color:#94A3B8">No students assigned to this vehicle.</td></tr>`}</tbody>
    ${list.length ? `<tfoot><tr><td colspan="4">Monthly collection</td><td class="r">Rs. ${subtotal.toLocaleString('en-PK')}</td></tr></tfoot>` : ''}
    </table>`;
  }).join('');

  const unassignedBlock = unassigned.length ? `
    <div class="rep-secttl">No vehicle assigned · ${unassigned.length} student${unassigned.length === 1 ? '' : 's'}</div>
    <table class="rep-tbl"><thead><tr>
      <th style="width:48px">#</th><th style="width:130px">Reg No</th><th>Name</th><th>Route / Area</th><th class="r" style="width:140px">Transport Fee</th>
    </tr></thead><tbody>${rowsFor(unassigned)}</tbody></table>` : '';

  const grand = withVeh.concat(unassigned).reduce((a, s) => a + (+s.transport || 0), 0);
  const filters = `<b>Vehicles:</b> ${vehicles.length} &nbsp;·&nbsp; <b>Students:</b> ${withVeh.length + unassigned.length} &nbsp;·&nbsp; <b>Total monthly:</b> Rs. ${grand.toLocaleString('en-PK')}`;
  const body = (vehicles.length === 0 && unassigned.length === 0)
    ? '<div style="text-align:center;color:#94A3B8;padding:20px">No vehicles or transport students yet.</div>'
    : `${blocks}${unassignedBlock}
    <div style="margin-top:14px;padding:10px 12px;border:2px solid #1E3A8A;border-radius:8px;font-weight:800;display:flex;justify-content:space-between;">
      <span>Total monthly transport collection</span><span>Rs. ${grand.toLocaleString('en-PK')}</span>
    </div>`;

  return repWrap('Vehicle-wise Transport Report', filters, body, isBW, school);
}

