/* ─── Fee Receiving tab ─── */
.fee-recind-row { grid-template-columns: 70px 1.1fr 1.4fr 220px 70px; }
.fee-recfam-row { grid-template-columns: 60px 1fr 1.3fr 130px 220px 70px; }
.fee-hist-row   { grid-template-columns: 70px 1.4fr 150px 110px 70px; }
/* Old ERP Ledger — wahi row, magar Download column ke baghair (4 cells). */
.fee-hist-row--nodl { grid-template-columns: 70px 1.4fr 150px 70px; }
.fee-rep-clsrow-grid { grid-template-columns: 60px 1fr 1fr 150px 80px; }

/* Reports tab — category chips */
.fee-rep-chips {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}
/* Page-level Colorful / Colorless toggle for the Reports tab */
.fee-rep-style-row {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin: 4px 0 14px;
  padding: 10px 14px;
  background: var(--bg-card);
  border: 1.5px solid var(--border-light);
  border-radius: 12px;
  box-shadow: var(--shadow-xs, 0 1px 2px rgba(15,23,42,.04));
}
.fee-rep-style-lbl {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .5px;
  color: var(--text-muted);
}
.fee-rep-style-seg {
  display: inline-flex;
  background: var(--bg-muted);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 3px;
  gap: 3px;
}
.fee-rep-style-btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 13px;
  border: none;
  background: transparent;
  border-radius: 7px;
  cursor: pointer;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
  transition: all .18s ease;
}
.fee-rep-style-btn i { font-size: 10px; }
.fee-rep-style-btn:hover { color: var(--brand-primary, #1E40AF); }
.fee-rep-style-btn.on {
  background: var(--bg-card);
  color: var(--brand-primary, #1E40AF);
  box-shadow: 0 1px 3px rgba(15,23,42,.10);
}
.fee-rep-style-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(30,64,175,.22);
}
[data-theme="dark"] .fee-rep-style-row { background: var(--bg-card); border-color: var(--border-light); }
[data-theme="dark"] .fee-rep-style-seg { background: var(--bg-muted); border-color: var(--border-light); }
[data-theme="dark"] .fee-rep-style-btn.on { background: var(--bg-card); color: #93C5FD; }
[data-theme="dark"] .fee-rep-style-btn:focus-visible { box-shadow: 0 0 0 3px rgba(59,130,246,.32); }
.fee-rep-chip {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  text-align: left;
  padding: 13px 15px;
  border: 1.5px solid var(--border-light);
  border-radius: 12px;
  background: var(--bg-card);
  cursor: pointer;
  transition: all .2s ease;
  font-family: var(--font-body);
  width: 100%;
}
.fee-rep-chip:has(.fee-rep-chip-info) { padding-right: 36px; }
.fee-rep-chip-info {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #1E3A8A;
  background: rgba(30,58,138,.08);
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}
.fee-rep-chip-info:hover,
.fee-rep-chip-info:focus-visible {
  background: rgba(30,58,138,.16);
  outline: none;
}
.fee-rep-chip-info:focus-visible {
  box-shadow: 0 0 0 3px rgba(30,58,138,.22);
}
.fee-rep-chip:hover {
  border-color: #1E3A8A;
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(30,58,138,.15);
}
.fee-rep-chip-ic { transition: transform .25s ease, box-shadow .25s ease; }
.fee-rep-chip:hover .fee-rep-chip-ic {
  transform: scale(1.08) rotate(-6deg);
  box-shadow: 0 6px 14px rgba(30,58,138,.35);
}
.fee-rep-chip.active {
  border-color: #1E3A8A;
  background: linear-gradient(135deg, rgba(30,58,138,.06), transparent);
  box-shadow: 0 0 0 3px rgba(30,58,138,.1);
}
.fee-rep-chip-ic {
  width: 38px; height: 38px;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; color: #fff;
  flex-shrink: 0;
  background: linear-gradient(135deg, #1E3A8A, #2563EB);
}
.fee-rep-chip-name { font-size: 13px; font-weight: 800; color: var(--text-primary); line-height: 1.2; }
.fee-rep-chip-desc { font-size: 10.5px; color: var(--text-muted); margin-top: 3px; line-height: 1.35; }

/* KPI strip (used across reports) */
.fee-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}
.fee-kpi {
  border: 1.5px solid var(--border-light);
  border-radius: 14px;
  padding: 14px 16px;
  background: var(--bg-card);
  position: relative;
  overflow: hidden;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
  cursor: default;
}
.fee-kpi:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(15,23,42,.10);
  border-color: var(--border-med);
}
.fee-kpi.k-blue:hover  { border-color: #2563EB; box-shadow: 0 12px 28px rgba(30,58,138,.18); }
.fee-kpi.k-green:hover { border-color: #16A34A; box-shadow: 0 12px 28px rgba(22,163,74,.18); }
.fee-kpi.k-amber:hover { border-color: #D97706; box-shadow: 0 12px 28px rgba(217,119,6,.18); }
.fee-kpi.k-red:hover   { border-color: #DC2626; box-shadow: 0 12px 28px rgba(220,38,38,.18); }
.fee-kpi-ic { transition: transform .25s ease; }
.fee-kpi:hover .fee-kpi-ic { transform: scale(1.1) rotate(-4deg); }
.fee-kpi::before {
  content: '';
  position: absolute;
  inset: 0 0 auto 0;
  height: 4px;
  border-radius: 14px 14px 0 0;
}
.fee-kpi.k-blue::before  { background: linear-gradient(90deg, #1E3A8A, #2563EB); }
.fee-kpi.k-green::before { background: linear-gradient(90deg, #16A34A, #22C55E); }
.fee-kpi.k-amber::before { background: linear-gradient(90deg, #D97706, #F59E0B); }
.fee-kpi.k-red::before   { background: linear-gradient(90deg, #DC2626, #EF4444); }
.fee-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.fee-kpi-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .3px;
  text-transform: uppercase;
  color: var(--text-muted);
}
.fee-kpi-ic {
  width: 30px; height: 30px;
  border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px;
}
.fee-kpi.k-blue  .fee-kpi-ic { background: rgba(30,58,138,.10);  color: #1E3A8A; }
.fee-kpi.k-green .fee-kpi-ic { background: rgba(22,163,74,.10);  color: #16A34A; }
.fee-kpi.k-amber .fee-kpi-ic { background: rgba(217,119,6,.10);  color: #D97706; }
.fee-kpi.k-red   .fee-kpi-ic { background: rgba(220,38,38,.10);  color: #DC2626; }
.fee-kpi-val {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  margin-top: 10px;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
}
.fee-kpi-meta {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 3px;
}
.fee-kpi-meta b.up   { color: #16A34A; }
.fee-kpi-meta b.down { color: #DC2626; }

/* Aging bar + legend */
.age-legend {
  display: flex; flex-wrap: wrap; gap: 14px;
  font-size: 11.5px; color: var(--text-secondary);
  font-weight: 700; align-items: center;
  margin-bottom: 12px;
}
.age-legend span { display: inline-flex; align-items: center; gap: 7px; }
.age-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.age-cur, .age-dot.age-cur { background: #16A34A; }
.age-30,  .age-dot.age-30  { background: #F59E0B; }
.age-60,  .age-dot.age-60  { background: #D97706; }
.age-90,  .age-dot.age-90  { background: #DC2626; }
.age-bar {
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--bg-muted);
  border: 1px solid var(--border-light);
  display: flex;
}
.age-bar > i {
  height: 100%;
  display: block;
  cursor: pointer;
  transition: filter .15s ease, transform .15s ease;
}
.age-bar > i:hover { filter: brightness(1.15); transform: scaleY(1.15); }
.rep-bar { cursor: pointer; }
.rep-bar:hover { filter: brightness(1.1); }

/* Summary tab bars */
.rep-bars {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(60px, 1fr);
  align-items: end;
  gap: 8px;
  height: 180px;
  padding: 10px 6px 0;
  border-bottom: 1.5px solid var(--border-light);
}
.rep-bar-col {
  display: flex; flex-direction: column;
  justify-content: flex-end; align-items: center;
  height: 100%; gap: 6px;
  cursor: pointer;
}
.rep-bar-pair {
  display: flex; gap: 4px; align-items: flex-end;
  width: 100%; height: 100%; justify-content: center;
}
.rep-bar {
  width: 18px; min-height: 4px;
  background: #1E3A8A;
  border-radius: 4px 4px 0 0;
  transition: transform .2s ease;
}
.rep-bar.green { background: #16A34A; }
.rep-bar-col:hover .rep-bar { transform: scaleY(1.04); transform-origin: bottom; }
.rep-bar-lbl {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-muted);
  text-align: center;
  margin-top: 4px;
}

/* Payment-mode mini cards */
.mode-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}
.mode-card {
  border: 1.5px solid var(--border-light);
  border-radius: 14px;
  padding: 14px 16px;
  background: var(--bg-card);
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
  cursor: default;
}
.mode-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(15,23,42,.10);
  border-color: var(--border-med);
}
.mode-ic { transition: transform .25s ease; }
.mode-card:hover .mode-ic { transform: scale(1.1) rotate(-4deg); }

/* Method chip — used in collection tables to colour-code payment channel */
.fee-method-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  border: 1px solid transparent;
  white-space: nowrap;
}
.mode-card-top {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 12px;
}
.mode-ic {
  width: 36px; height: 36px;
  border-radius: 10px;
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  flex-shrink: 0;
}
.mode-name {
  flex: 1; min-width: 0;
  font-size: 13.5px;
  font-weight: 800;
  color: var(--text-primary);
}
.mode-actions { display: inline-flex; gap: 6px; flex-shrink: 0; }
.mode-act-btn {
  width: 30px; height: 30px;
  border-radius: 8px;
  border: 1.5px solid var(--border-light);
  background: var(--bg-card);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 11px;
  display: inline-flex; align-items: center; justify-content: center;
  transition: all .15s ease;
}
.mode-act-btn:hover { color: #1E3A8A; border-color: #1E3A8A; }
.mode-amt {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.mode-pct {
  font-size: 11.5px;
  color: var(--text-muted);
  font-weight: 700;
  margin-top: 2px;
}
.mode-track {
  margin-top: 10px;
  height: 6px;
  border-radius: 999px;
  background: var(--bg-muted);
  border: 1px solid var(--border-light);
  overflow: hidden;
}
.mode-track > i { display: block; height: 100%; border-radius: 999px; }

/* Dark mode */
[data-theme="dark"] .fee-rep-chip,
[data-theme="dark"] .fee-kpi,
[data-theme="dark"] .mode-card {
  background: var(--bg-card);
  border-color: var(--border-light);
}
[data-theme="dark"] .fee-rep-chip:hover,
[data-theme="dark"] .mode-card:hover { border-color: var(--border-med); }
[data-theme="dark"] .fee-rep-chip.active {
  background: linear-gradient(135deg, rgba(59,130,246,.08), transparent);
  border-color: #3B82F6;
  box-shadow: 0 0 0 3px rgba(59,130,246,.15);
}
[data-theme="dark"] .fee-rep-chip-name,
[data-theme="dark"] .fee-kpi-val,
[data-theme="dark"] .mode-name,
[data-theme="dark"] .mode-amt { color: var(--text-primary); }
[data-theme="dark"] .fee-rep-chip-desc,
[data-theme="dark"] .fee-kpi-label,
[data-theme="dark"] .fee-kpi-meta,
[data-theme="dark"] .mode-pct,
[data-theme="dark"] .age-legend { color: var(--text-muted); }
[data-theme="dark"] .age-bar,
[data-theme="dark"] .mode-track {
  background: var(--bg-muted);
  border-color: var(--border-light);
}
[data-theme="dark"] .rep-bars { border-color: var(--border-light); }
[data-theme="dark"] .mode-act-btn {
  background: var(--bg-card);
  border-color: var(--border-light);
  color: var(--text-muted);
}
[data-theme="dark"] .mode-act-btn:hover { color: #93C5FD; border-color: #3B82F6; }

/* Fee History — overall school reports band */
.fee-hist-overall {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 14px 18px;
  margin-bottom: 16px;
  border: 1.5px solid var(--border-light);
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(30,58,138,.05), rgba(29,184,138,.04));
  box-shadow: var(--shadow-sm);
}
.fee-hist-overall-info { display: flex; align-items: center; gap: 13px; }
.fee-hist-overall-info > i {
  width: 42px; height: 42px;
  border-radius: 12px;
  background: linear-gradient(135deg, #1E3A8A, #1E40AF);
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
}
.fee-hist-overall-title { font-size: 14px; font-weight: 800; color: var(--text-primary); }
.fee-hist-overall-sub   { font-size: 12px; color: var(--text-muted); margin-top: 1px; }
.fee-hist-overall-btns  { display: flex; gap: 10px; flex-wrap: wrap; }

/* View button used in history student rows */
.fee-hist-vbtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 10px;
  border: 1.5px solid #1E3A8A;
  background: var(--bg-card);
  color: #1E3A8A;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all .2s ease;
}
.fee-hist-vbtn:hover {
  background: linear-gradient(135deg, #1E3A8A, #1E40AF);
  color: #fff;
  border-color: transparent;
}

/* Meta-card strip inside the history modal */
.fee-hist-ledger-meta {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}
.fee-hist-metacard {
  border: 1.5px solid var(--border-light);
  border-radius: 10px;
  padding: 12px 14px;
  background: var(--bg-muted);
}
.fee-hist-metacard .l {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .3px;
}
.fee-hist-metacard .v {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  margin-top: 3px;
  font-variant-numeric: tabular-nums;
}
.fee-hist-metacard .v.green { color: #16A34A; }
.fee-hist-metacard .v.red   { color: #DC2626; }

/* Detailed-history month card (accordion-style block) */
.fee-month-card {
  border: 1.5px solid var(--border-light);
  border-radius: 14px;
  overflow: hidden;
  margin-bottom: 14px;
  box-shadow: var(--shadow-sm);
}
.fee-month-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  background: linear-gradient(135deg, rgba(30,58,138,.05), transparent);
  border-bottom: 1px solid var(--border-light);
  flex-wrap: wrap;
}
.fee-month-title { font-size: 13.5px; font-weight: 800; color: var(--text-primary); display: flex; align-items: center; gap: 10px; }
.fee-month-title .mm {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1E3A8A, #1E40AF);
  color: #fff;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .4px;
}
.fee-month-body { display: grid; grid-template-columns: 1fr 1fr; }
.fee-month-col  { padding: 14px 16px; }
.fee-month-col + .fee-month-col { border-left: 1px solid var(--border-light); }
.fee-month-col h5 {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .4px;
  text-transform: uppercase;
  color: #1E3A8A;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.fee-month-col h5 > span { display: inline-flex; align-items: center; gap: 7px; }

.fee-kv {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 6px 12px;
  font-size: 12.5px;
}
.fee-kv .k { color: var(--text-muted); font-weight: 600; }
.fee-kv .v { text-align: right; font-weight: 700; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.fee-kv .v.green { color: #16A34A; }
.fee-kv .v.red   { color: #DC2626; }

/* Dark mode */
[data-theme="dark"] .fee-hist-overall {
  background: linear-gradient(135deg, rgba(59,130,246,.10), rgba(34,197,94,.06));
  border-color: var(--border-light);
}
[data-theme="dark"] .fee-hist-overall-title { color: var(--text-primary); }
[data-theme="dark"] .fee-hist-overall-sub   { color: var(--text-muted); }
[data-theme="dark"] .fee-hist-vbtn {
  background: var(--bg-card);
  color: #93C5FD;
  border-color: #3B82F6;
}
[data-theme="dark"] .fee-hist-vbtn:hover {
  background: linear-gradient(135deg, #2563EB, #1D4ED8);
  color: #fff;
}
[data-theme="dark"] .fee-hist-metacard {
  background: var(--bg-muted);
  border-color: var(--border-light);
}
[data-theme="dark"] .fee-hist-metacard .l { color: var(--text-muted); }
[data-theme="dark"] .fee-hist-metacard .v { color: var(--text-primary); }
[data-theme="dark"] .fee-hist-metacard .v.green { color: #86EFAC; }
[data-theme="dark"] .fee-hist-metacard .v.red   { color: #FCA5A5; }
[data-theme="dark"] .fee-month-card,
[data-theme="dark"] .fee-month-head { border-color: var(--border-light); }
[data-theme="dark"] .fee-month-head { background: linear-gradient(135deg, rgba(59,130,246,.08), transparent); }
[data-theme="dark"] .fee-month-col + .fee-month-col { border-left-color: var(--border-light); }
[data-theme="dark"] .fee-month-col h5 { color: #93C5FD; }
[data-theme="dark"] .fee-kv .k { color: var(--text-muted); }
[data-theme="dark"] .fee-kv .v { color: var(--text-primary); }
[data-theme="dark"] .fee-kv .v.green { color: #86EFAC; }
[data-theme="dark"] .fee-kv .v.red   { color: #FCA5A5; }

/* Bulk Fee Receiving modal — child list + expandable per-child card */
.fee-recv-summary-title {
  text-align: center;
  font-size: 14px;
  font-weight: 800;
  color: #1E3A8A;
  margin-bottom: 14px;
  letter-spacing: .2px;
}
.fee-bulk-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 6px; }
.fee-bulk-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border: 1.5px solid var(--border-light);
  border-radius: 12px;
  background: var(--bg-card);
  cursor: pointer;
  transition: all .2s ease;
  font-family: var(--font-body);
  text-align: left;
  width: 100%;
}
.fee-bulk-row:hover  { border-color: #1E3A8A; background: var(--bg-muted); }
.fee-bulk-row.sel {
  border-color: #1E3A8A;
  box-shadow: 0 0 0 3px rgba(30,58,138,.1);
  background: linear-gradient(135deg, rgba(30,58,138,.04), transparent);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.fee-bulk-av {
  width: 38px; height: 38px;
  border-radius: 10px;
  background: linear-gradient(135deg, #DBEAFE, #EEF4FF);
  color: #1E3A8A;
  font-weight: 800;
  font-size: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.fee-bulk-main { flex: 1; min-width: 0; }
.fee-bulk-name { font-size: 13.5px; font-weight: 800; color: var(--text-primary); }
.fee-bulk-meta { font-size: 11.5px; color: var(--text-muted); margin-top: 1px; }
.fee-bulk-status { display: inline-flex; align-items: center; flex-shrink: 0; }
.fee-bulk-chev   { color: var(--text-muted); font-size: 12px; flex-shrink: 0; transition: all .2s; }
.fee-bulk-row.sel .fee-bulk-chev { color: #1E3A8A; }
.fee-bulk-card {
  border: 1.5px solid #1E3A8A;
  border-top: none;
  border-radius: 0 0 12px 12px;
  background: var(--bg-card);
  padding: 16px;
  margin: -6px 0 4px;
  animation: feeBulkCardIn .2s ease;
}
@keyframes feeBulkCardIn { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

.fee-recv-band {
  background: linear-gradient(135deg, #1E3A8A, #1E40AF);
  color: #fff;
  text-align: center;
  font-weight: 800;
  font-size: 14px;
  padding: 12px;
  border-radius: 10px;
}
.fee-onelink-note {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 14px;
  margin-bottom: 12px;
  border-radius: 10px;
  background: rgba(124,58,237,.08);
  border: 1px solid rgba(124,58,237,.25);
  color: #6D28D9;
  font-size: 12.5px;
  font-weight: 600;
}
.fee-onelink-note i { color: #7C3AED; font-size: 13px; }

[data-theme="dark"] .fee-recv-summary-title { color: #93C5FD; }
[data-theme="dark"] .fee-bulk-row {
  background: var(--bg-card);
  border-color: var(--border-light);
}
[data-theme="dark"] .fee-bulk-row:hover { background: var(--bg-muted); border-color: #3B82F6; }
[data-theme="dark"] .fee-bulk-row.sel   { border-color: #3B82F6; box-shadow: 0 0 0 3px rgba(59,130,246,.15); }
[data-theme="dark"] .fee-bulk-av {
  background: rgba(59,130,246,.16);
  color: #93C5FD;
}
[data-theme="dark"] .fee-bulk-name { color: var(--text-primary); }
[data-theme="dark"] .fee-bulk-meta { color: var(--text-muted); }
[data-theme="dark"] .fee-bulk-card { background: var(--bg-card); border-color: #3B82F6; }
[data-theme="dark"] .fee-onelink-note {
  background: rgba(124,58,237,.18);
  border-color: rgba(124,58,237,.35);
  color: #C4B5FD;
}
[data-theme="dark"] .fee-onelink-note i { color: #C4B5FD; }
.fee-recv-clssec { display: flex; flex-direction: column; gap: 2px; }
.fee-recv-clssec b { font-weight: 800; color: var(--text-primary); }
.fee-recv-clssec span { font-size: 11px; color: var(--text-muted); font-weight: 600; }

.fee-recv-sumchips { display: flex; gap: 6px; flex-wrap: wrap; justify-content: center; }
.fee-recv-sumchip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  border: 1px solid transparent;
  white-space: nowrap;
}
.fee-recv-sumchip .n { font-size: 12px; }
.fee-recv-sumchip.total   { background: rgba(30,64,175,.08); color: #1E40AF; border-color: rgba(30,64,175,.18); }
.fee-recv-sumchip.paid    { background: rgba(22,163,74,.1);  color: #16A34A; border-color: rgba(22,163,74,.22); }
.fee-recv-sumchip.unpaid  { background: rgba(220,38,38,.08); color: #DC2626; border-color: rgba(220,38,38,.2); }
.fee-recv-sumchip.onelink { background: rgba(124,58,237,.10); color: #7C3AED; border-color: rgba(124,58,237,.25); }

.fee-reminder-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border-radius: 10px;
  border: none;
  background: linear-gradient(135deg, #1E3A8A, #1E40AF);
  color: #fff;
  font-family: var(--font-body);
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all .2s ease;
  white-space: nowrap;
  box-shadow: 0 3px 10px rgba(30,58,138,.25);
}
.fee-reminder-btn:hover { transform: translateY(-1px); box-shadow: 0 6px 16px rgba(30,58,138,.35); }

.fee-recv-link {
  color: #1E3A8A;
  font-weight: 800;
  font-size: 12.5px;
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font-body);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all .15s ease;
}
.fee-recv-link:hover { text-decoration: underline; }
/* Action-cell wrapper — keeps the link + 3 icon buttons on ONE row.
   white-space:nowrap + flex-wrap:nowrap stop the icons spilling onto
   a second line; the parent .fee-stbl-wrap handles horizontal scroll
   if a narrow viewport ever forces overflow. */
.fee-recv-acts {
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
}
.fee-recv-acts .fee-recv-link {
  padding: 4px 10px;
  border-radius: 8px;
  background: rgba(30,58,138,.06);
  border: 1px solid rgba(30,58,138,.15);
  white-space: nowrap;
  flex-shrink: 0;
}
.fee-recv-acts .fee-recv-link:hover {
  background: rgba(30,58,138,.12);
  text-decoration: none;
}
.fee-recv-acts .fee-iconbtn { flex-shrink: 0; }
[data-theme="dark"] .fee-recv-acts .fee-recv-link {
  background: rgba(59,130,246,.10);
  border-color: rgba(59,130,246,.25);
  color: #93C5FD;
}
[data-theme="dark"] .fee-recv-acts .fee-recv-link:hover {
  background: rgba(59,130,246,.18);
}
.fee-recv-notice { color: #DC2626; font-weight: 700; font-size: 11.5px; text-align: center; line-height: 1.5; }
.fee-recv-notice b { font-weight: 800; }
.fee-iconbtn.tiny { width: 28px; height: 28px; font-size: 11px; }
.fee-this-dues { color: #DC2626; font-weight: 700; }
.fee-this-dues.zero { color: #DC2626; }
.fee-sub-eq { display: block; font-size: 10.5px; color: var(--text-muted); font-weight: 600; margin-top: 1px; }
.fee-disc-amt { color: #D97706; font-weight: 700; }
.fee-paid-amt { color: #16A34A; font-weight: 700; }

.fee-stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}
.fee-stat-full    { background: rgba(22,163,74,.12);  color: #16A34A; border: 1px solid rgba(22,163,74,.25); }
.fee-stat-partial { background: rgba(217,119,6,.12);  color: #D97706; border: 1px solid rgba(217,119,6,.28); }
.fee-stat-none    { background: rgba(220,38,38,.08);  color: #DC2626; border: 1px solid rgba(220,38,38,.2); }
.fee-onelink-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  background: rgba(124,58,237,.1);
  color: #7C3AED;
  border: 1px solid rgba(124,58,237,.25);
}
.fee-recv-status {
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
}
.fee-recv-status .fee-stat-badge,
.fee-recv-status .fee-onelink-tag { flex-shrink: 0; }

/* ─── Fee Receiving Modal ─── */
.fee-recv-meta {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 14px;
  margin-bottom: 16px;
}
.fee-recv-info {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 14px;
  padding: 14px 16px;
  background: var(--bg-muted);
  border: 1px solid var(--border-light);
  border-radius: 10px;
}
.fee-recv-info-item { display: flex; flex-direction: column; gap: 3px; }
.fee-recv-info-lbl  { font-size: 11px; font-weight: 700; color: var(--text-muted); letter-spacing: .2px; }
.fee-recv-info-val  { font-size: 13.5px; font-weight: 800; color: var(--text-primary); }
.fee-recv-give-toggle {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  margin: 12px 0 0; padding: 10px 14px;
  border: 1px solid var(--border); border-radius: 10px;
  background: var(--surface, #fff); cursor: pointer; user-select: none;
}
.fee-recv-give-toggle input { width: 16px; height: 16px; accent-color: #1E3A8A; cursor: pointer; }
.fee-recv-give-toggle > span { font-size: 13.5px; font-weight: 800; color: var(--text-primary); }
.fee-recv-give-toggle > em {
  font-style: normal; font-size: 11.5px; font-weight: 600; color: var(--text-muted);
}
.fee-recv-table th  { white-space: nowrap; }
.fee-recv-table input {
  width: 110px;
  height: 34px;
  border: 1.5px solid var(--border-light);
  border-radius: 8px;
  padding: 0 10px;
  font-family: var(--font-body);
  font-size: 12.5px;
  font-weight: 600;
  text-align: right;
  background: var(--bg-card);
  color: var(--text-primary);
  outline: none;
  transition: all .15s ease;
}
.fee-recv-table input:focus { border-color: #1E3A8A; box-shadow: 0 0 0 3px rgba(30,58,138,.08); }
.fee-recv-table .fee-recv-total td {
  background: var(--bg-muted);
  font-weight: 800;
  border-bottom: none;
  border-top: 1.5px solid var(--border-light);
}
.fee-recv-table .fee-cell-grey {
  background: var(--bg-muted);
  border-radius: 6px;
  padding: 6px 10px;
  display: inline-block;
  min-width: 80px;
  text-align: right;
  font-weight: 600;
}

/* ─── Fee-head payment-flow table (Individual Fee Receiving) ───
   Scoped to .fee-recv-table.flow so the plain (Bulk/Family) receiving
   table is unaffected. Ported from the sibling app's payment-flow design.
   Rules are scoped under .fee-recv-table.flow so they win over the base
   .fee-recv-table input rule above. */
.fee-recv-table.flow th { white-space: normal; line-height: 1.35; vertical-align: bottom; }
.fee-recv-table.flow .fee-center { text-align: center; }
.fee-recv-table.flow thead th.fee-center { text-align: center; }
.fee-recv-table.flow .flow-op {
  display: inline-block;
  color: var(--text-muted);
  font-weight: 900;
  margin-right: 2px;
}
/* Fee Head stays visible while the rest of the table scrolls horizontally. */
.fee-recv-table.flow .flow-head-col {
  position: sticky;
  left: 0;
  background: var(--bg-card);
  z-index: 1;
  box-shadow: 1px 0 0 var(--border-light);
}
.fee-recv-table.flow thead th.flow-head-col { background: var(--bg-muted); }
.fee-recv-table.flow tr.fee-recv-total td.flow-head-col { background: var(--bg-muted); }

/* Previous Dues — flagged as an older, carried-forward amount. */
.fee-recv-table.flow .flow-prevtag {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 6px;
  background: rgba(217,119,6,.1);
  color: #B45309;
  font-weight: 700;
}
[data-theme="dark"] .fee-recv-table.flow .flow-prevtag { background: rgba(217,119,6,.18); color: #FBBF24; }

/* Prior-installment history columns (Installment N Received / Remaining after
   Inst. N) — narrow, no-wrap headers with a faint tint so they read apart from
   the current live receiving columns. Purely visual. */
.fee-recv-table.flow th.flow-inst-col { white-space: nowrap; background: rgba(30,58,138,.04); }
.fee-recv-table.flow td.flow-inst-col { background: rgba(30,58,138,.02); }
[data-theme="dark"] .fee-recv-table.flow th.flow-inst-col { background: rgba(59,130,246,.08); }
[data-theme="dark"] .fee-recv-table.flow td.flow-inst-col { background: rgba(59,130,246,.05); }

/* Editable cells (Give Discount / Pay Now) — subtly highlighted so they
   read as different from the plain calculated columns around them. */
.fee-recv-table.flow .flow-input {
  width: 92px;
  height: 34px;
  border: 1.5px solid var(--border-light);
  border-radius: 8px;
  padding: 0 8px;
  font-family: var(--font-body);
  font-size: 12.5px;
  font-weight: 700;
  text-align: center;
  background: rgba(30,58,138,.045);
  color: var(--text-primary);
  outline: none;
  transition: all .15s ease;
}
.fee-recv-table.flow .flow-input:focus { border-color: #1E3A8A; box-shadow: 0 0 0 3px rgba(30,58,138,.1); background: var(--bg-card); }
.fee-recv-table.flow .flow-input--pay { background: rgba(22,163,74,.06); }
.fee-recv-table.flow .flow-input--pay:focus { border-color: #16A34A; box-shadow: 0 0 0 3px rgba(22,163,74,.12); }
[data-theme="dark"] .fee-recv-table.flow .flow-input { background: rgba(59,130,246,.1); border-color: var(--border-light); }
[data-theme="dark"] .fee-recv-table.flow .flow-input--pay { background: rgba(34,197,94,.1); }
[data-theme="dark"] .fee-recv-table.flow .flow-input:focus { background: var(--bg-card); }

/* Key outcome cells — Final Net Payable and Remaining are the two
   numbers a cashier actually needs to read at a glance. */
.fee-recv-table.flow .flow-final  { font-weight: 800; color: #1E3A8A; }
.fee-recv-table.flow .flow-remain { font-weight: 800; color: #B91C1C; }
[data-theme="dark"] .fee-recv-table.flow .flow-final  { color: #93C5FD; }
[data-theme="dark"] .fee-recv-table.flow .flow-remain { color: #FCA5A5; }

.fee-recv-table.flow .fee-recv-dash { color: var(--text-muted); }

.fee-recv-flow-hint {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  background: var(--bg-muted);
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.5;
}
.fee-recv-flow-hint i { color: #1E3A8A; margin-top: 1px; flex-shrink: 0; }

@media (max-width: 640px) {
  /* Touch-friendly inputs; table itself scrolls via .fee-stbl-wrap. */
  .fee-recv-table.flow .flow-input { width: 84px; height: 38px; font-size: 13px; }
  .fee-recv-flow-hint { font-size: 11px; }
}

.fee-recv-paystrip {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 12px;
  margin-top: 18px;
}
.fee-recv-paycard {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px 16px;
  border: 1.5px solid var(--border-light);
  border-radius: 12px;
  background: var(--bg-card);
}
.fee-recv-paylbl { font-size: 11px; font-weight: 700; color: var(--text-muted); letter-spacing: .3px; text-transform: uppercase; }
.fee-recv-payval {
  font-size: 18px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--text-primary);
}
.fee-recv-payval.green { color: #16A34A; }
.fee-recv-payval.blue  { color: #1E3A8A; }
.fee-recv-payval.red   { color: #DC2626; }

.fee-recv-hist-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  font-weight: 800;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: .5px;
}
.fee-recv-hist-title i { color: #1E3A8A; }

/* ─── Reminder Modal ─── */
.fee-textarea {
  min-height: 90px;
  resize: vertical;
  padding: 10px 12px;
  line-height: 1.55;
}
.fee-rem-counter {
  text-align: right;
  font-size: 11.5px;
  color: var(--text-muted);
  font-weight: 600;
  margin-top: 4px;
}
.fee-rem-counter span { font-variant-numeric: tabular-nums; }
.fee-rem-target {
  margin-top: 12px;
  padding: 11px 14px;
  border-radius: 10px;
  background: rgba(30,58,138,.05);
  border: 1px solid rgba(30,58,138,.15);
  font-size: 12.5px;
  color: var(--text-secondary);
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}
.fee-rem-target i { color: #1E3A8A; }

/* ─── Slip Modal preview ─── */
.fee-slip-doc {
  position: relative;
  background: #fff;
  color: #111;
  border: 1px solid #93C5FD;
  border-radius: 10px;
  padding: 20px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  max-width: 420px;
  margin: 0 auto;
}
.fee-slip-head { text-align: center; border-bottom: 2px solid #1E3A8A; background: linear-gradient(135deg,rgba(30,58,138,.06),transparent); padding: 10px 8px; margin: -20px -20px 12px; border-radius: 10px 10px 0 0; }
.fee-slip-doc.fee-slip-small .fee-slip-head { margin: -14px -14px 10px; padding: 8px 6px; border-radius: 8px 8px 0 0; }
.fee-slip-brandhead { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; border-bottom: 2px solid #1E3A8A; background: linear-gradient(135deg,rgba(30,58,138,.06),transparent); padding: 10px 8px; margin: -20px -20px 12px; border-radius: 10px 10px 0 0; }
.fee-slip-brand { display: flex; align-items: center; gap: 10px; text-align: left; }
.fee-slip-logo { width: 38px; height: 38px; border: 1px solid #ddd; border-radius: 10px; display: flex; align-items: center; justify-content: center; overflow: hidden; color: #1E3A8A; font-weight: 800; background: #fff; flex-shrink: 0; }
.fee-slip-logo img { width: 100%; height: 100%; object-fit: contain; }
.fee-slip-meta { font-size: 10px; color: #666; text-align: right; line-height: 1.55; white-space: nowrap; }
.fee-slip-foot { margin-top: 14px; text-align: center; font-size: 9px; color: #999; border-top: 1px solid #eee; padding-top: 8px; }
.fee-slip-addr { font-size: 10.5px; color: #666; margin-top: 2px; }
.fee-slip-school { font-size: 16px; font-weight: 800; color: #1E3A8A; }
.fee-slip-tag { font-size: 11px; color: #1E40AF; letter-spacing: 1px; text-transform: uppercase; margin-top: 3px; font-weight: 600; }
.fee-slip-paid-stamp { position: absolute; top: 14px; right: 16px; border: 3px double #16A34A; color: #16A34A; font-size: 15px; font-weight: 900; letter-spacing: 2px; padding: 4px 10px; border-radius: 6px; transform: rotate(-12deg); opacity: .85; text-transform: uppercase; }
.fee-slip-doc.fee-slip-small .fee-slip-paid-stamp { font-size: 11px; padding: 3px 7px; top: 8px; right: 8px; letter-spacing: 1px; border-width: 2px; }
.fee-slip-kv {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 10px;
  font-size: 12px;
  margin-bottom: 12px;
  color: #111;
}
.fee-slip-kv .k { color: #666; }
.fee-slip-kv .v { text-align: right; font-weight: 700; }
.fee-slip-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; margin-bottom: 10px; color: #111; }
.fee-slip-tbl th,
.fee-slip-tbl td { border-bottom: 1px solid #DBEAFE; padding: 5px 4px; text-align: right; }
.fee-slip-tbl th:first-child,
.fee-slip-tbl td:first-child { text-align: left; }
.fee-slip-tbl th { background: #1E3A8A; color: #fff; border-bottom: none; }
.fee-slip-headtot td { border-top: 1.5px solid #1E3A8A; border-bottom: none; font-weight: 800; background: #EFF6FF; color: #1E3A8A; }
.fee-slip-net {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: linear-gradient(135deg,#1E3A8A,#1D4ED8);
  color: #fff;
  padding: 8px 12px;
  border-radius: 4px;
  font-weight: 800;
}

/* ── Small Receipt (thermal / 80mm) ──
   80mm me side-by-side header ki jagah hai hi nahi: brand aur "Generated"
   block ek doosre ko nichor dete the, jis se school ka naam ek-ek lafz par
   toot jaata tha aur logo naam ke neeche chala jaata tha. Asli counter
   receipt ki tarah ab sab kuch center me, ek ke neeche ek — aur andar ka
   type size 80mm ke mutabiq. */
.fee-slip-doc.fee-slip-small { max-width: 302px; padding: 14px 12px; font-size: 11px; }
.fee-slip-small .fee-slip-brandhead {
  flex-direction: column; align-items: center; text-align: center;
  gap: 6px; padding: 8px 6px; margin: -14px -12px 10px; border-radius: 8px 8px 0 0;
}
.fee-slip-small .fee-slip-brand { flex-direction: column; align-items: center; text-align: center; gap: 6px; }
.fee-slip-small .fee-slip-logo { width: 34px; height: 34px; border-radius: 8px; }
.fee-slip-small .fee-slip-school { font-size: 13.5px; line-height: 1.25; }
.fee-slip-small .fee-slip-tag { font-size: 9.5px; letter-spacing: .5px; margin-top: 2px; }
.fee-slip-small .fee-slip-addr { font-size: 9.5px; line-height: 1.35; }
/* nowrap yahan zaroori nahi — center me do lines me aa jaye to behtar hai. */
.fee-slip-small .fee-slip-meta { text-align: center; white-space: normal; font-size: 9.5px; line-height: 1.4; }
.fee-slip-small .fee-slip-kv { font-size: 10.5px; gap: 3px 8px; margin-bottom: 10px; }
.fee-slip-small .fee-slip-tbl { font-size: 9.5px; }
.fee-slip-small .fee-slip-tbl th,
.fee-slip-small .fee-slip-tbl td { padding: 4px 2px; }
.fee-slip-small .fee-slip-tbl th { font-size: 8.5px; line-height: 1.2; }
.fee-slip-small .fee-slip-tbl td:first-child { word-break: break-word; }
.fee-slip-small .fee-slip-net { padding: 7px 10px; font-size: 11.5px; }
.fee-slip-small .fee-slip-foot { font-size: 8px; margin-top: 10px; padding-top: 6px; }
/* Colorless — same low-ink redesign as the print version (FeeSlipModal
   doPrint / FEE_CHALLAN_CSS_SCOPED) applied live to the in-modal preview
   too, since this preview sits right next to the Slip Theme picker. */
.fee-slip-doc.fee-bw { border-color: #ddd; }
.fee-slip-doc.fee-bw .fee-slip-paid-stamp { border-color: #000; color: #000; }
.fee-slip-doc.fee-bw .fee-slip-head,
.fee-slip-doc.fee-bw .fee-slip-brandhead { border-bottom: 1.5px solid #111; background: none; margin: 0 0 12px; padding: 0 0 10px; border-radius: 0; }
.fee-slip-doc.fee-bw.fee-slip-small .fee-slip-brandhead { margin: 0 0 10px; padding: 0 0 8px; }
.fee-slip-doc.fee-bw .fee-slip-school { color: #111; }
.fee-slip-doc.fee-bw .fee-slip-tag { color: #555; font-weight: 500; }
.fee-slip-doc.fee-bw .fee-slip-tbl th,
.fee-slip-doc.fee-bw .fee-slip-tbl td { border-bottom-color: #eee; }
.fee-slip-doc.fee-bw .fee-slip-tbl th { background: none; color: #333; border-bottom: 1.5px solid #333; }
.fee-slip-doc.fee-bw .fee-slip-headtot td { border-top-color: #333; background: #f5f7fb; color: #111; }
.fee-slip-doc.fee-bw .fee-slip-net { background: #111; color: #fff; }

/* Multi-select + progress — dark */
[data-theme="dark"] .fee-ms-toggle {
  background: var(--input-bg, var(--bg-card));
