  /* Fee top-level tabs — horizontal scroll strip */
  .fee-subtabs {
    overflow-x: auto;
    flex-wrap: nowrap;
    scrollbar-width: none;
    -ms-overflow-style: none;
    padding: 4px;
    gap: 4px;
    border-radius: 12px;
  }
  .fee-subtabs::-webkit-scrollbar { display: none; }
  .fee-subtab {
    flex: 0 0 auto;
    white-space: nowrap;
    padding: 10px 14px;
    font-size: 12.5px;
